def _env(name, default=None):
    v = os.environ.get(name)
    return v if (v is not None and str(v).strip() != "") else default

def _env_int(name, default):
    v = os.environ.get(name)
    try:
        return int(v) if v is not None and str(v).strip() != "" else int(default)
    except:
        return int(default)

