def _codigo_produto_chave(valor):
    bruto = _as_str(valor).strip().upper()
    if not bruto:
        return ""
    if re.fullmatch(r"\d+", bruto):
        return bruto.lstrip("0") or "0"
    return re.sub(r"\s+", "", bruto)

def _codigo_produto_nfe_saida(valor):
    bruto = re.sub(r"\D+", "", _as_str(valor))
    if not bruto:
        return _as_str(valor).strip()
    if len(bruto) >= 6:
        return bruto
    return bruto.zfill(6)

def _produto_nome_normalizado(valor):
    texto = _as_str(valor)
    if not texto:
        return ""
    texto = re.sub(r"^\s*0*[A-Z0-9]+\s*[-–]\s*", "", texto, flags=re.I)
    texto = unicodedata.normalize("NFKD", texto)
    texto = "".join(ch for ch in texto if not unicodedata.combining(ch))
    texto = texto.upper()
    texto = re.sub(r"[^A-Z0-9]+", " ", texto)
    return re.sub(r"\s+", " ", texto).strip()

_ESTOQUE_GRUPOS_ORDEM = {
    "GFA": 0,
    "PET": 1,
    "AGUA": 2,
    "OUTROS": 3,
}

def _estoque_grupo_normalizado(valor):
    bruto = _as_str(valor).strip().upper()
    if not bruto:
        return ""
    aliases = {
        "GF": "GFA",
        "GFA": "GFA",
        "GRF": "GFA",
        "GARRAFA": "GFA",
        "GARRAFA RETORNAVEL": "GFA",
        "RETORNAVEL": "GFA",
        "RETORNAVEIS": "GFA",
        "VIDRO": "GFA",
        "PET": "PET",
        "DESCARTAVEL": "PET",
        "DESCARTAVEIS": "PET",
        "AGUA": "AGUA",
        "AGUAS": "AGUA",
        "AGUA MINERAL": "AGUA",
        "OUTRO": "OUTROS",
        "OUTROS": "OUTROS",
        "MATERIA PRIMA": "OUTROS",
        "MATERIA-PRIMA": "OUTROS",
        "MATERIA PRIMA E INSUMOS": "OUTROS",
        "EXPEDIENTE": "OUTROS",
    }
    return aliases.get(bruto, bruto if bruto in _ESTOQUE_GRUPOS_ORDEM else "")

def _estoque_grupo_ordem(valor):
    return _ESTOQUE_GRUPOS_ORDEM.get(_estoque_grupo_normalizado(valor), 99)

def _estoque_classificacao_operacional(item):
    item = item or {}
    grupo = _estoque_grupo_normalizado(item.get("grupo_estoque")) or _estoque_grupo_inferido(
        nome_produto=item.get("produto_base_nome") or item.get("nome_produto"),
        codigo_produto_nfe=item.get("codigo_produto_nfe"),
    )
    if grupo in {"GFA", "PET", "AGUA"}:
        return {
            "estoque_area": "PRODUCAO",
            "estoque_subgrupo": "PRODUTOS",
            "exibir_dashboard": True,
        }

    categorias = {
        _as_str(valor).strip().lower()
        for valor in (item.get("fornecedor_categorias") or [])
        if _as_str(valor)
    }
    texto = _produto_nome_normalizado(
        " ".join(
            [
                _as_str(item.get("produto_base_nome")),
                _as_str(item.get("nome_produto")),
                _as_str(item.get("grupo_estoque")),
            ]
        )
    )
    termos_formula = (
        "ACUCAR", "CONCENTRADO", "AROMA", "EXTRATO", "XAROPE",
        "ACIDO", "ACIDULANTE", "CONSERVANTE", "CORANTE",
        "EDULCORANTE", "ANTIOXIDANTE", "GAS CARBONICO", "CO2",
    )
    if "materia_prima" in categorias or any(termo in texto for termo in termos_formula):
        return {
            "estoque_area": "PRODUCAO",
            "estoque_subgrupo": "MATERIA_PRIMA",
            "exibir_dashboard": False,
        }
    return {
        "estoque_area": "ALMOXARIFADO_GERAL",
        "estoque_subgrupo": "GERAL",
        "exibir_dashboard": False,
    }

def _estoque_grupo_inferido(nome_produto="", codigo_produto_nfe="", grupo_estoque=""):
    grupo_exp = _estoque_grupo_normalizado(grupo_estoque)
    if grupo_exp:
        return grupo_exp
    texto = " ".join([
        _as_str(nome_produto).upper(),
        _as_str(codigo_produto_nfe).upper(),
    ]).strip()
    if not texto:
        return "OUTROS"
    if re.search(r"\bAGUA\b", texto):
        return "AGUA"
    if re.search(r"\bPREFORMA\b", texto) or re.search(r"\bPRE\s*-?\s*FORMA\b", texto):
        return "OUTROS"
    if re.search(r"\bPET\b", texto) or re.search(r"\bDESCART", texto) or re.search(r"\bRECICLAV", texto):
        return "PET"
    if re.search(r"\bGFA\b", texto) or re.search(r"\bGRF\b", texto) or re.search(r"\bGARRAFA\b", texto) or re.search(r"\bVIDRO\b", texto):
        return "GFA"
    return "OUTROS"

def _estoque_apresentacao_normalizada(*valores):
    texto = " ".join(_as_str(v).upper() for v in valores if _as_str(v)).strip()
    if not texto:
        return ""
    if "PALLET" in texto or re.search(r"\bPAL\b", texto):
        return "PALLET"
    if "CX48" in texto:
        return "CX48"
    if "CX24" in texto:
        return "CX24"
    if "CAIXA" in texto or re.search(r"\bCX\b", texto):
        return "CX"
    if "DUZIA" in texto or "DUZIAS" in texto or re.search(r"\bDZ\b", texto):
        return "DZ"
    if "PACOTE" in texto or "PACOTES" in texto or re.search(r"\bPCT\b", texto) or re.search(r"\bPAC\b", texto) or re.search(r"\bPT\b", texto):
        return "PCT"
    if "FARDO" in texto or "FARDOS" in texto or re.search(r"\bFD\b", texto):
        return "FD"
    if "UNIDADE" in texto or "UNIDADES" in texto or re.search(r"\bUND\b", texto) or re.search(r"\bUN\b", texto):
        return "UN"
    return ""

def _estoque_extrair_multiplicador(texto):
    bruto = _as_str(texto).upper()
    if not bruto:
        return 0.0
    for pattern in (
        r"\b(?:C\/|COM|X)\s*0*([1-9]\d{0,2})\b",
        r"\b(?:PCT|PAC|PACOTE|PACOTES|FD|FARDO|FARDOS|CX|CAIXA|CAIXAS)\s*0*([1-9]\d{0,2})\b",
        r"\b0*([1-9]\d{0,2})\s*(?:UN|UND|UNIDADES|GARRAFAS|PACOTES|CAIXAS)\b",
    ):
        match = re.search(pattern, bruto)
        if match:
            return _as_float(match.group(1), 0.0)
    return 0.0

def _estoque_base_nome_inferido(nome_produto="", grupo_estoque="", produto_base_nome=""):
    base_exp = _as_str(produto_base_nome).strip()
    nome = _as_str(nome_produto).strip() or base_exp
    grupo = _estoque_grupo_inferido(nome_produto=nome, grupo_estoque=grupo_estoque)
    texto = nome.upper()
    texto_norm = _produto_nome_normalizado(nome)
    if grupo == "AGUA" or re.search(r"\bAGUA\b", texto_norm):
        gas = "SEM GAS" if re.search(r"\bSEM GAS\b", texto_norm) else (
            "COM GAS" if re.search(r"\b(?:COM GAS|C GAS)\b", texto_norm) else ""
        )
        volume = next(
            (
                rotulo
                for padrao, rotulo in (
                    (r"\b2\s*L(?:T)?\b|\b2L\b", "2L"),
                    (r"\b600\s*ML\b", "600ML"),
                    (r"\b510\s*ML\b", "510ML"),
                    (r"\b500\s*ML\b", "500ML"),
                    (r"\b200\s*ML\b", "200ML"),
                )
                if re.search(padrao, texto_norm)
            ),
            "",
        )
        return " ".join(parte for parte in ("AGUA", gas, volume) if parte)

    sabores = (
        (r"\bLARANJINHA\b", "LARANJINHA"),
        (r"\bLARANJA\b", "LARANJA"),
        (r"\bLIMAO\b|\bSODA\b", "LIMAO (SODA)"),
        (r"\bFRAMBOESA\b", "FRAMBOESA"),
        (r"\bABACAXI\b", "ABACAXI"),
        (r"\bASTUBA\b", "ASTUBA"),
        (r"\bCITRUS\b", "CITRUS"),
        (r"\bTUBAINA\b", "TUBAINA"),
        (r"\bGUARANA\b", "GUARANA"),
        (r"\bUVA\b", "UVA"),
        (r"\bCOLA\b", "COLA"),
    )
    sabor = next(
        (rotulo for padrao, rotulo in sabores if re.search(padrao, texto_norm)),
        "",
    )
    volume = next(
        (
            rotulo
            for padrao, rotulo in (
                (r"\b2\s*L(?:T)?\b|\b2L\b", "2L"),
                (r"\b600\s*ML\b", "600ML"),
                (r"\b200\s*ML\b", "200ML"),
            )
            if re.search(padrao, texto_norm)
        ),
        "",
    )
    if sabor and volume:
        prefixo = "RETORNAVEL" if grupo == "GFA" else (
            "RECICLAVEL" if re.search(r"\bRECICLAV", texto_norm) else ""
        )
        return " ".join(parte for parte in (prefixo, sabor, volume) if parte)
    if base_exp:
        return base_exp
    if grupo == "PET":
        if re.search(r"\b2\s*L(T)?\b|\b2LT\b", texto):
            return "PET 2L"
        if re.search(r"\b600\s*ML\b|\bPET\s*600\b", texto):
            return "PET 600ML"
        if re.search(r"\b200\s*ML\b|\bPET\s*200\b", texto):
            return "PET 200ML"
    if grupo == "GFA":
        if re.search(r"\b600\s*ML\b|\bGFA\s*600\b|\bGRF\s*600\b", texto):
            return "GFA 600ML"
        if re.search(r"\b200\s*ML\b|\bGFA\s*200\b|\bGRF\s*200\b", texto):
            return "GFA 200ML"
    if grupo == "AGUA":
        if re.search(r"\b510\s*ML\b", texto):
            return "AGUA 510ML"
        return "AGUA"

    tokens = _produto_nome_normalizado(nome).split()
    remover = {
        "UN", "UND", "UNIDADE", "UNIDADES",
        "DZ", "DUZIA", "DUZIAS",
        "CX", "CX24", "CX48", "CAIXA", "CAIXAS",
        "PCT", "PAC", "PACOTE", "PACOTES",
        "FD", "FARDO", "FARDOS",
        "PAL", "PALLET", "PALLETS",
    }
    remover_numeros = {"9", "12", "24", "35", "48", "80"}
    tokens = [tok for tok in tokens if tok not in remover and tok not in remover_numeros]
    base = " ".join(tokens).strip()
    return base or nome or "PRODUTO"

def _estoque_produto_meta(row):
    fator_padrao = _as_float(row.get("fator_embalagem_padrao"), 1.0)
    if fator_padrao <= 0:
        fator_padrao = 1.0
    grupo_exp = _estoque_grupo_normalizado(row.get("grupo_estoque"))
    grupo = grupo_exp or _estoque_grupo_inferido(
        nome_produto=row.get("nome_produto"),
        codigo_produto_nfe=row.get("codigo_produto_nfe"),
    )
    base_exp = _as_str(row.get("produto_base_nome")).strip()
    base_nome = _estoque_base_nome_inferido(
        nome_produto=row.get("nome_produto"),
        grupo_estoque=grupo,
        produto_base_nome=row.get("produto_base_nome"),
    )
    base_key_raw = _produto_nome_normalizado(base_nome) or _produto_nome_normalizado(row.get("nome_produto"))
    if not base_key_raw:
        base_key_raw = _codigo_produto_chave(row.get("codigo_produto_nfe")) or _normalizar_codigo_barras(row.get("codigo_barras")) or "PRODUTO"
    return {
        "grupo_estoque": grupo or "OUTROS",
        "produto_base_nome": base_nome or _as_str(row.get("nome_produto")) or "Produto",
        "produto_base_key": f"{grupo or 'OUTROS'}:{base_key_raw}",
        "cadastro_explicitado": bool(grupo_exp and base_exp and fator_padrao > 0),
    }

def _extrair_codigo_produto_texto(valor):
    texto = _as_str(valor).strip()
    if not texto:
        return ""
    match = re.match(r"^\s*0*([A-Z0-9]+)\s*[-–]\s*", texto, re.I)
    if match:
        return _codigo_produto_chave(match.group(1))
    return ""

def _fator_base_produto(nome_produto="", embalagem="", unidade_ref="", grupo_produto=""):
    grupo = _estoque_grupo_inferido(nome_produto=nome_produto, grupo_estoque=grupo_produto)
    unidade = _estoque_apresentacao_normalizada(unidade_ref, embalagem, nome_produto)
    texto = " ".join([
        _as_str(nome_produto).upper(),
        _as_str(embalagem).upper(),
        _as_str(grupo_produto).upper(),
    ]).strip()
    multiplicador = _estoque_extrair_multiplicador(texto)
    eh_2l = bool(re.search(r"\b2\s*L(?:T)?\b|\b2L\b", texto))
    eh_200ml = bool(re.search(r"\b200\s*ML\b", texto))

    if unidade == "UN":
        return 1.0
    if unidade == "DZ":
        return 12.0
    if grupo == "GFA":
        if unidade == "PALLET":
            return 35.0 * 24.0
        if unidade in ("CX", "CX24", "CX48"):
            return multiplicador or (48.0 if eh_200ml else 24.0)
        return 12.0 if multiplicador <= 0 else multiplicador
    if grupo == "PET":
        pacote = multiplicador or (
            6.0 if eh_2l
            else (12.0 if re.search(r"\b12\b", texto) else (9.0 if re.search(r"\b9\b", texto) else 0.0))
        )
        if unidade == "PALLET":
            return (pacote if pacote > 0 else 12.0) * 80.0
        if unidade in ("PCT", "FD"):
            return pacote if pacote > 0 else 12.0
        if unidade in ("CX", "CX24", "CX48"):
            return multiplicador if multiplicador > 0 else pacote
        return 1.0
    if grupo == "AGUA":
        if unidade == "PALLET":
            return multiplicador if multiplicador > 0 else 0.0
        if unidade in ("PCT", "FD", "CX", "CX24", "CX48"):
            return multiplicador if multiplicador > 0 else 12.0
        return 1.0
    if grupo == "OUTROS" and multiplicador > 0:
        return multiplicador

    match = re.search(r"\b(\d{1,2})\s*[Xx]\s*\d+(?:[.,]\d+)?\s*(?:ML|L|LT|LITROS?)\b", texto)
    if match:
        try:
            return float(match.group(1))
        except Exception:
            pass

    match = re.search(r"\b(\d{1,2})\s*[Xx]\s*\d{2,4}\b", texto)
    if match:
        try:
            return float(match.group(1))
        except Exception:
            pass

    if "GFA" in texto or "510ML" in texto or "200ML" in texto:
        return 12.0
    return 1.0


def _estoque_pallet_meta(item):
    """Capacidade logistica; o saldo canonico continua sempre em unidades."""
    item = item or {}
    grupo = _estoque_grupo_normalizado(item.get("grupo_estoque")) or _estoque_grupo_inferido(
        nome_produto=item.get("produto_base_nome") or item.get("nome_produto"),
        grupo_estoque=item.get("grupo_estoque"),
    )
    texto = _produto_nome_normalizado(" ".join([
        _as_str(item.get("produto_base_nome")), _as_str(item.get("nome_produto")),
        _as_str(item.get("embalagem_tipo_padrao")), _as_str(item.get("unidade")),
    ]))
    volumes = unidades = 0
    rotulo = ""
    regra = ""
    if grupo == "AGUA":
        volumes, unidades, rotulo, regra = 150, 12, "pacotes", "agua_150x12"
    elif grupo == "PET" and re.search(r"\b2\s*L(?:T)?\b|\b2L\b", texto):
        volumes, unidades, rotulo, regra = 80, 6, "pacotes", "pet_2l_80x6"
    elif grupo == "PET" and re.search(r"\b600\s*ML\b|\bPET\s*600\b", texto):
        volumes, unidades, rotulo, regra = 132, 12, "pacotes", "pet_600_132x12"
    elif grupo == "PET" and re.search(r"\b200\s*ML\b|\bPET\s*200\b", texto):
        volumes, unidades, rotulo, regra = 304, 12, "pacotes", "pet_200_304x12"
    elif grupo == "GFA" and re.search(r"\b600\s*ML\b|\bGFA\s*600\b|\bGRF\s*600\b", texto):
        volumes, unidades, rotulo, regra = 35, 24, "caixas", "gfa_600_35x24"
    elif grupo == "GFA" and re.search(r"\b200\s*ML\b|\bGFA\s*200\b|\bGRF\s*200\b", texto):
        fatores = {_as_int(valor, 0) for valor in (item.get("fatores_embalagem_origem") or [])}
        if "CX24" in texto or re.search(r"\b(?:CX|CAIXA)\s*24\b", texto) or fatores == {24}:
            volumes, unidades, rotulo, regra = 60, 24, "caixas", "gfa_200_cx24_60x24"
        elif "CX48" in texto or re.search(r"\b(?:CX|CAIXA)\s*48\b", texto) or fatores == {48}:
            volumes, unidades, rotulo, regra = 48, 48, "caixas", "gfa_200_cx48_48x48"
    return {
        "identificado": bool(volumes and unidades),
        "volumes_por_pallet": volumes,
        "unidades_por_volume": unidades,
        "unidades_por_pallet": volumes * unidades,
        "rotulo_volume": rotulo,
        "regra": regra,
    }

def _valor_numerico_token(texto):
    return _as_float_br(_as_str(texto), _as_float(_as_str(texto), 0.0))

def _parse_token_qtd_unidade(texto):
    match = re.fullmatch(r"\s*(\d+(?:[.,]\d+)?)\s+([A-Z]{2,4})\s*", _as_str(texto).upper())
    if not match:
        return 0.0, ""
    return _valor_numerico_token(match.group(1)), _as_str(match.group(2)).upper()

def _coletar_cidades_resumo_pdf(lines):
    cidades = []
    em_resumo = False
    for raw in lines:
        linha = _as_str(raw).strip()
        up = linha.upper()
        if "RESUMO DAS CIDADES ATENDIDAS" in up:
            em_resumo = True
            continue
        if not em_resumo:
            continue
        if up.startswith("CIDADE") or up.startswith("UF ") or up.startswith("MAPAS"):
            continue
        match = re.match(r"^([A-ZÀ-Ú0-9 ./-]+?)\s+[A-Z]{2}\s+\d[\d.,]*\s+\d+\s+\d[\d.,]*\s*$", linha, re.I)
        if not match:
            continue
        cidade = _normalizar_nome_local(match.group(1))
        if cidade and cidade not in cidades:
            cidades.append(cidade)
    return cidades

def _parse_data_ptbr_extenso(texto):
    match = re.search(r"(\d{1,2})\s+de\s+([a-zç]+)\s+de\s+(\d{4})", _as_str(texto).lower())
    if not match:
        return None
    dia = _as_int(match.group(1), 0)
    mes = _MESES_PTBR.get(match.group(2))
    ano = _as_int(match.group(3), 0)
    if dia <= 0 or not mes or ano <= 0:
        return None
    try:
        return datetime.date(ano, mes, dia)
    except Exception:
        return None

def _rota_pdf_limpa(raw_text):
    texto = _as_str(raw_text)
    if not texto:
        return ""
    texto = re.sub(r"\s+", " ", texto)
    texto = texto.replace(" / ", "/")
    return texto.strip(" ,")

def _parse_carga_pdf_page(page_text, source_name="", veiculo_override=""):
    bruto = _as_str(page_text)
    if not bruto:
        return None

    linhas = [linha.rstrip() for linha in bruto.splitlines() if _as_str(linha).strip()]
    mapa_match = re.search(r"Mapa:\s*([0-9A-Z/-]+)", bruto, re.I)
    mapa_numero = _as_str(mapa_match.group(1)) if mapa_match else ""
    rota_match = re.search(r"Rota:\s*(.*?)\s+Separação Grupo(?: Carregamento)?", bruto, re.I | re.S)
    rota = _rota_pdf_limpa(rota_match.group(1) if rota_match else "")
    data_carga = _parse_data_ptbr_extenso(linhas[0] if linhas else "")
    cidades = _coletar_cidades_resumo_pdf(linhas)
    cidade_principal = cidades[0] if cidades else ""
    veiculo_numero = _csv_veiculo_numero({}, veiculo_override)
    if not veiculo_numero:
        placa_match = re.search(r"Placa:\s*([A-Z0-9-]{5,10})", bruto, re.I)
        veiculo_numero = _csv_veiculo_numero({"veiculo": placa_match.group(1) if placa_match else ""})

    numero_entregas = _as_int(re.search(r"Número Entregas:\s*([0-9]+)", bruto, re.I).group(1), 0) if re.search(r"Número Entregas:\s*([0-9]+)", bruto, re.I) else 0
    peso_total = _valor_numerico_token(re.search(r"Peso Total:\s*([0-9.,]+)", bruto, re.I).group(1)) if re.search(r"Peso Total:\s*([0-9.,]+)", bruto, re.I) else 0.0
    volumes_total = _valor_numerico_token(re.search(r"Total dos Volumes:\s*([0-9.,]+)", bruto, re.I).group(1)) if re.search(r"Total dos Volumes:\s*([0-9.,]+)", bruto, re.I) else 0.0
    valor_bonificacao = _valor_numerico_token(re.search(r"Valor Bonificação:\s*([0-9.,]+)", bruto, re.I).group(1)) if re.search(r"Valor Bonificação:\s*([0-9.,]+)", bruto, re.I) else 0.0
    valor_liquido = _valor_numerico_token(re.search(r"Valor Total Liquido:\s*([0-9.,]+)", bruto, re.I).group(1)) if re.search(r"Valor Total Liquido:\s*([0-9.,]+)", bruto, re.I) else 0.0

    grupo_atual = ""
    itens = []
    for raw in linhas:
        linha = _as_str(raw).strip()
        up = linha.upper()
        if up.startswith("GRUPO C.:"):
            grupo_atual = _as_str(linha.split(":", 1)[1]).strip()
            continue
        if not re.match(r"^\d{4,6}\s+", linha):
            continue

        colunas = [parte.strip() for parte in re.split(r"\s{2,}", linha) if _as_str(parte).strip()]
        if len(colunas) < 2:
            continue
        codigo_produto = _codigo_produto_chave(colunas[0])
        resto = colunas[1:]
        tokens_qtd = []
        while resto and re.fullmatch(r"\d+(?:[.,]\d+)?\s+[A-Z]{2,4}", resto[-1].upper()):
            tokens_qtd.insert(0, resto.pop())

        if not resto:
            continue

        embalagem = ""
        if len(resto) >= 2:
            nome_produto = " ".join(resto[:-1]).strip()
            embalagem = resto[-1]
        else:
            nome_produto = resto[0]

        qtd_embalagem = 0.0
        unidade_embalagem = ""
        qtd_solta = 0.0
        unidade_solta = ""
        if len(tokens_qtd) == 1:
            qtd_tmp, und_tmp = _parse_token_qtd_unidade(tokens_qtd[0])
            if und_tmp in ("DZ", "UN"):
                qtd_solta, unidade_solta = qtd_tmp, und_tmp
            else:
                qtd_embalagem, unidade_embalagem = qtd_tmp, und_tmp
        elif len(tokens_qtd) >= 2:
            qtd_embalagem, unidade_embalagem = _parse_token_qtd_unidade(tokens_qtd[0])
            qtd_solta, unidade_solta = _parse_token_qtd_unidade(tokens_qtd[1])

        fator_embalagem = _fator_base_produto(
            nome_produto=nome_produto,
            embalagem=embalagem,
            unidade_ref=unidade_embalagem or unidade_solta,
            grupo_produto=grupo_atual,
        )
        fator_solta = _fator_base_produto(
            nome_produto=nome_produto,
            embalagem=embalagem,
            unidade_ref=unidade_solta,
            grupo_produto=grupo_atual,
        )
        quantidade_total = round((qtd_embalagem * fator_embalagem) + (qtd_solta * fator_solta), 3)
        itens.append({
            "item_seq": len(itens) + 1,
            "grupo_produto": grupo_atual,
            "codigo_produto": codigo_produto,
            "nome_produto": nome_produto,
            "embalagem": embalagem,
            "unidade_embalagem": unidade_embalagem,
            "quantidade_embalagem": qtd_embalagem,
            "unidade_solta": unidade_solta,
            "quantidade_solta": qtd_solta,
            "fator_embalagem": fator_embalagem,
            "quantidade_total": quantidade_total,
            "dados_json": json.dumps({
                "linha_bruta": linha,
                "grupo_produto": grupo_atual,
                "tokens_qtd": tokens_qtd,
            }, ensure_ascii=False),
        })

    if not itens:
        return None

    nome_carga = rota or (f"Mapa {mapa_numero}" if mapa_numero else cidade_principal or "Carga PDF")
    if mapa_numero and mapa_numero not in nome_carga:
        nome_carga = f"Mapa {mapa_numero} - {nome_carga}"
    quantidade_total = round(sum(_as_float(item.get("quantidade_total"), 0.0) for item in itens), 3)

    return {
        "mapa_numero": mapa_numero,
        "nome_carga": nome_carga,
        "cidade": cidade_principal,
        "cidades": cidades,
        "rota": rota,
        "veiculo_numero": veiculo_numero,
        "arquivo_origem": source_name,
        "data_carga": data_carga or datetime.date.today(),
        "numero_entregas": numero_entregas,
        "peso_total": peso_total,
        "volumes_total": volumes_total,
        "valor_bonificacao": valor_bonificacao,
        "valor_total": valor_liquido,
        "quantidade_total": quantidade_total,
        "itens": itens,
    }

def _parse_cargas_pdf_bytes(pdf_bytes, source_name="", veiculo_override=""):
    texto = _extrair_texto_pdf_bytes(pdf_bytes)
    if not _as_str(texto):
        raise RuntimeError("Nao foi possivel extrair texto do PDF de cargas.")
    paginas = []
    for page_text in re.split(r"\f+", texto):
        pagina = _parse_carga_pdf_page(page_text, source_name=source_name, veiculo_override=veiculo_override)
        if pagina:
            paginas.append(pagina)
    if not paginas:
        raise RuntimeError("O PDF informado nao trouxe cargas reconheciveis.")
    return paginas

def _carregar_arquivo_por_extensao(dirs, extensoes):
    candidatos = []
    for pasta in dirs:
        if not pasta or not os.path.isdir(pasta):
            continue
        try:
            for nome in os.listdir(pasta):
                if any(nome.lower().endswith(ext.lower()) for ext in extensoes):
                    candidatos.append(os.path.join(pasta, nome))
        except Exception:
            continue
    if not candidatos:
        raise FileNotFoundError("Nenhum arquivo encontrado para importacao.")
    candidatos.sort(key=lambda p: os.path.getmtime(p), reverse=True)
    caminho = candidatos[0]
    with open(caminho, "rb") as f:
        return f.read(), os.path.basename(caminho), caminho

def _carregar_pdf_cargas_fonte(file_storage=None):
    if file_storage and getattr(file_storage, "filename", ""):
        dados = file_storage.read()
        if not dados:
            raise FileNotFoundError("Arquivo PDF vazio.")
        return dados, secure_filename(file_storage.filename or "cargas.pdf"), ""
    return _carregar_arquivo_por_extensao(CARGAS_IMPORT_PDF_DIRS, [".pdf"])

def _carregar_xml_fabrica_fonte(file_storage=None):
    if file_storage and getattr(file_storage, "filename", ""):
        dados = file_storage.read()
        if not dados:
            raise FileNotFoundError("Arquivo XML vazio.")
        return dados, secure_filename(file_storage.filename or "transferencia.xml"), ""
    return _carregar_arquivo_por_extensao(CARGAS_IMPORT_XML_DIRS, [".xml"])

def _buscar_produto_cadastro_por_referencias(cur, codigo_produto="", codigo_barras="", nome_produto=""):
    codigo_barras = _normalizar_codigo_barras(codigo_barras)
    codigo_produto = _codigo_produto_chave(codigo_produto)
    nome_norm = _produto_nome_normalizado(nome_produto)
    if codigo_barras:
        cur.execute("""
            SELECT id, codigo_barras, codigo_produto_nfe, nome_produto, grupo_estoque, produto_base_nome, unidade,
                   embalagem_tipo_padrao, fator_embalagem_padrao, origem_cadastro, criado_em, atualizado_em
            FROM estoque_produtos
            WHERE codigo_barras=%s
            ORDER BY id DESC
            LIMIT 1
        """, (codigo_barras,))
        row = cur.fetchone()
        if row:
            return row
    if codigo_produto:
        cur.execute("""
            SELECT id, codigo_barras, codigo_produto_nfe, nome_produto, unidade,
                   embalagem_tipo_padrao, fator_embalagem_padrao, origem_cadastro, criado_em, atualizado_em
            FROM estoque_produtos
            WHERE TRIM(LEADING '0' FROM COALESCE(codigo_produto_nfe, ''))=%s
            ORDER BY id DESC
            LIMIT 1
        """, (codigo_produto,))
        row = cur.fetchone()
        if row:
            return row
    if nome_norm:
        cur.execute("""
            SELECT id, codigo_barras, codigo_produto_nfe, nome_produto, unidade,
                   embalagem_tipo_padrao, fator_embalagem_padrao, origem_cadastro, criado_em, atualizado_em
            FROM estoque_produtos
            ORDER BY id DESC
        """)
        for row in (cur.fetchall() or []):
            if _produto_nome_normalizado(row.get("nome_produto")) == nome_norm:
                return row
    return None

def _saldo_atual_produto_estoque(cur, codigo_barras="", codigo_produto_nfe="", nome_produto=""):
    referencia = {
        "codigo_barras": _normalizar_codigo_barras(codigo_barras),
        "codigo_produto_nfe": _codigo_produto_nfe_saida(codigo_produto_nfe),
        "nome_produto": _as_str(nome_produto),
    }
    if not (referencia["codigo_barras"] or referencia["codigo_produto_nfe"] or referencia["nome_produto"]):
        return 0.0

    meta_ref = _estoque_produto_meta(referencia)
    payload = _estoque_resumo_produtos_data()
    for item in (payload.get("rows") or []):
        if _as_str(item.get("produto_base_key")) and _as_str(item.get("produto_base_key")) == _as_str(meta_ref.get("produto_base_key")):
            return _as_float(item.get("quantidade_atual"), 0.0)
        if referencia["codigo_barras"] and _normalizar_codigo_barras(item.get("codigo_barras")) == referencia["codigo_barras"]:
            return _as_float(item.get("quantidade_atual"), 0.0)
        if referencia["codigo_produto_nfe"] and _codigo_produto_chave(item.get("codigo_produto_nfe")) == _codigo_produto_chave(referencia["codigo_produto_nfe"]):
            return _as_float(item.get("quantidade_atual"), 0.0)
        if referencia["nome_produto"] and _produto_nome_normalizado(item.get("produto_base_nome") or item.get("nome_produto")) == _produto_nome_normalizado(referencia["nome_produto"]):
            return _as_float(item.get("quantidade_atual"), 0.0)
    return 0.0

def _listar_itens_carga_estoque(cur, carga_id):
    cur.execute("""
        SELECT
            id,
            carga_id,
            produto_id,
            item_seq,
            grupo_produto,
            codigo_produto,
            codigo_barras,
            nome_produto,
            embalagem,
            unidade_embalagem,
            quantidade_embalagem,
            unidade_solta,
            quantidade_solta,
            fator_embalagem,
            quantidade_total,
            estoque_movimento_id,
            baixado_em,
            dados_json,
            criado_em
        FROM cargas_estoque_itens
        WHERE carga_id=%s
        ORDER BY item_seq ASC, id ASC
    """, (carga_id,))
    return cur.fetchall() or []

def _baixar_estoque_carga(cur, carga_id, usuario="desconhecido"):
    carga_id = _as_int(carga_id, 0)
    if carga_id <= 0:
        return {"ok": False, "motivo": "carga_invalida"}

    cur.execute("""
        SELECT id, nome, veiculo_numero, mapa_numero, estoque_baixado_em
        FROM cargas
        WHERE id=%s
        LIMIT 1
    """, (carga_id,))
    carga = cur.fetchone() or {}
    if not carga:
        return {"ok": False, "motivo": "carga_nao_encontrada"}
    if carga.get("estoque_baixado_em"):
        return {
            "ok": True,
            "ja_baixada": True,
            "carga_id": carga_id,
            "nome": _as_str(carga.get("nome")),
        }

    itens = _listar_itens_carga_estoque(cur, carga_id)
    if not itens:
        return {"ok": False, "motivo": "sem_itens"}

    total_itens = 0
    insuficiencias = []
    produtos_criados = 0
    destino_setor = _as_str(carga.get("veiculo_numero")) or _as_str(carga.get("nome")) or "Caminhao"
    numero_nota = f"CARGA-{_as_str(carga.get('mapa_numero')) or carga_id}"

    for item in itens:
        quantidade_total = _as_float(item.get("quantidade_total"), 0.0)
        if quantidade_total <= 0:
            quantidade_total = round(
                (_as_float(item.get("quantidade_embalagem"), 0.0) * _as_float(item.get("fator_embalagem"), 1.0))
                + (_as_float(item.get("quantidade_solta"), 0.0) * _fator_base_produto(
                    nome_produto=item.get("nome_produto"),
                    embalagem=item.get("embalagem"),
                    unidade_ref=item.get("unidade_solta"),
                    grupo_produto=item.get("grupo_produto"),
                )),
                3,
            )
        if quantidade_total <= 0:
            continue

        produto = _buscar_produto_cadastro_por_referencias(
            cur,
            codigo_produto=item.get("codigo_produto"),
            codigo_barras=item.get("codigo_barras"),
            nome_produto=item.get("nome_produto"),
        )
        produto_criado = False
        if not produto:
            produto, produto_criado = _obter_ou_criar_produto_estoque(
                cur,
                codigo_barras=item.get("codigo_barras"),
                codigo_produto_nfe=_codigo_produto_nfe_saida(item.get("codigo_produto")),
                nome_produto=item.get("nome_produto"),
                unidade=item.get("embalagem") or item.get("unidade_embalagem") or item.get("unidade_solta"),
                origem_cadastro="carga_pdf",
            )
        if produto_criado:
            produtos_criados += 1

        saldo_antes = _saldo_atual_produto_estoque(
            cur,
            codigo_barras=produto.get("codigo_barras") or item.get("codigo_barras"),
            codigo_produto_nfe=produto.get("codigo_produto_nfe") or item.get("codigo_produto"),
            nome_produto=produto.get("nome_produto") or item.get("nome_produto"),
        )
        saldo_depois = round(saldo_antes - quantidade_total, 3)
        if saldo_depois < 0:
            insuficiencias.append({
                "produto": _as_str(produto.get("nome_produto") or item.get("nome_produto")),
                "saldo_antes": round(saldo_antes, 3),
                "quantidade_baixada": round(quantidade_total, 3),
                "saldo_depois": saldo_depois,
            })

        cur.execute("""
            INSERT INTO estoque_movimentos
                (
                    codigo_barras, codigo_produto_nfe, numero_nota, nome_produto, quantidade, valor_unitario, tipo_movimento,
                    origem_setor, destino_setor, referencia_tipo, referencia_id, usuario_registro
                )
            VALUES
                (%s, %s, %s, %s, %s, %s, 'saida', %s, %s, 'carga_pdf', %s, %s)
        """, (
            _normalizar_codigo_barras(produto.get("codigo_barras") or item.get("codigo_barras")),
            _codigo_produto_nfe_saida(produto.get("codigo_produto_nfe") or item.get("codigo_produto")),
            numero_nota,
            _as_str(produto.get("nome_produto") or item.get("nome_produto")),
            quantidade_total,
            0.0,
            "Almoxarifado",
            destino_setor,
            carga_id,
            usuario or "desconhecido",
        ))
        movimento_id = _as_int(cur.lastrowid, 0)
        cur.execute("""
            UPDATE cargas_estoque_itens
            SET produto_id=%s,
                codigo_barras=%s,
                estoque_movimento_id=%s,
                baixado_em=NOW()
            WHERE id=%s
        """, (
            _as_int(produto.get("id"), 0) or None,
            _normalizar_codigo_barras(produto.get("codigo_barras") or item.get("codigo_barras")),
            movimento_id or None,
            _as_int(item.get("id"), 0),
        ))
        total_itens += 1

    if total_itens <= 0:
        return {"ok": False, "motivo": "sem_movimentos"}

    cur.execute("""
        UPDATE cargas
        SET estoque_baixado_em=NOW(), estoque_baixado_por=%s
        WHERE id=%s
    """, (usuario or "desconhecido", carga_id))

    return {
        "ok": True,
        "carga_id": carga_id,
        "nome": _as_str(carga.get("nome")),
        "itens_baixados": total_itens,
        "produtos_criados": produtos_criados,
        "insuficiencias": insuficiencias,
        "ja_baixada": False,
    }

def _status_frete_gera_baixa_estoque(status):
    return _as_str(status).lower() in ("carregado", "entregando", "retornando", "paradoCarregado".lower())

def _sincronizar_baixa_estoque_frete(cur, antes, depois, usuario="desconhecido"):
    carga_id = _as_int((depois or {}).get("carga_id"), 0)
    if carga_id <= 0:
        return None
    status_antes = _as_str((antes or {}).get("status")).lower()
    status_depois = _as_str((depois or {}).get("status")).lower()
    if _status_frete_gera_baixa_estoque(status_depois) and not _status_frete_gera_baixa_estoque(status_antes):
        return _baixar_estoque_carga(cur, carga_id, usuario=usuario)
    return None

def _importar_cargas_pdf_bytes(pdf_bytes, source_name="", veiculo_override="", usuario="desconhecido") -> dict:
    paginas = _parse_cargas_pdf_bytes(pdf_bytes, source_name=source_name, veiculo_override=veiculo_override)
    conn = get_conn()
    cur = conn.cursor(dictionary=True)
    criadas = 0
    atualizadas = 0
    fretes_criados = 0
    fretes_atualizados = 0
    cargas_baixadas = 0
    try:
        for pagina in paginas:
            mapa_numero = _as_str(pagina.get("mapa_numero"))
            cur.execute("""
                SELECT *
                FROM cargas
                WHERE tipo_importacao='pdf'
                  AND mapa_numero=%s
                ORDER BY id DESC
                LIMIT 1
            """, (mapa_numero,))
            existente = cur.fetchone()
            if existente and existente.get("estoque_baixado_em"):
                raise RuntimeError(f"A carga do mapa {mapa_numero or existente.get('id')} ja teve baixa no estoque e nao pode ser sobrescrita.")

            payload = (
                pagina.get("nome_carga"),
                pagina.get("cidade"),
                pagina.get("rota"),
                pagina.get("veiculo_numero"),
                source_name,
                len(pagina.get("itens") or []),
                0,
                pagina.get("quantidade_total"),
                0.0,
                pagina.get("peso_total"),
                pagina.get("valor_total"),
                source_name,
                "pdf",
                mapa_numero,
                pagina.get("data_carga"),
                pagina.get("numero_entregas"),
                pagina.get("volumes_total"),
                pagina.get("valor_bonificacao"),
            )

            if existente:
                carga_id = _as_int(existente.get("id"), 0)
                cur.execute("""
                    UPDATE cargas
                    SET nome=%s,
                        cidade=%s,
                        rota=%s,
                        veiculo_numero=%s,
                        origem_csv=%s,
                        registros_importados=%s,
                        clientes_distintos=%s,
                        quantidade_total=%s,
                        litros_total=%s,
                        peso_total=%s,
                        valor_total=%s,
                        arquivo_origem=%s,
                        tipo_importacao=%s,
                        mapa_numero=%s,
                        data_carga=%s,
                        numero_entregas=%s,
                        volumes_total=%s,
                        valor_bonificacao=%s,
                        atualizado_em=NOW(),
                        estoque_baixado_em=NULL,
                        estoque_baixado_por=''
                    WHERE id=%s
                """, payload + (carga_id,))
                atualizadas += 1
            else:
                cur.execute("""
                    INSERT INTO cargas
                        (
                            nome, cidade, rota, veiculo_numero, origem_csv, registros_importados, clientes_distintos,
                            quantidade_total, litros_total, peso_total, valor_total, arquivo_origem, tipo_importacao,
                            mapa_numero, data_carga, numero_entregas, volumes_total, valor_bonificacao
                        )
                    VALUES
                        (%s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s)
                """, payload)
                carga_id = _as_int(cur.lastrowid, 0)
                criadas += 1

            if carga_id <= 0:
                continue

            cur.execute("DELETE FROM cargas_estoque_itens WHERE carga_id=%s", (carga_id,))
            for item in (pagina.get("itens") or []):
                produto = _buscar_produto_cadastro_por_referencias(
                    cur,
                    codigo_produto=item.get("codigo_produto"),
                    codigo_barras=item.get("codigo_barras"),
                    nome_produto=item.get("nome_produto"),
                )
                if not produto:
                    produto, _produto_criado = _obter_ou_criar_produto_estoque(
                        cur,
                        codigo_barras=item.get("codigo_barras"),
                        codigo_produto_nfe=_codigo_produto_nfe_saida(item.get("codigo_produto")),
                        nome_produto=item.get("nome_produto"),
                        unidade=item.get("embalagem") or item.get("unidade_embalagem") or item.get("unidade_solta"),
                        origem_cadastro="carga_pdf",
                    )
                fator_embalagem = _as_float(produto.get("fator_embalagem_padrao"), 0.0) or _as_float(item.get("fator_embalagem"), 1.0)
                if fator_embalagem <= 0:
                    fator_embalagem = _fator_base_produto(
                        nome_produto=item.get("nome_produto"),
                        embalagem=item.get("embalagem"),
                        unidade_ref=item.get("unidade_embalagem") or item.get("unidade_solta"),
                        grupo_produto=item.get("grupo_produto"),
                    )
                quantidade_total = round(
                    (_as_float(item.get("quantidade_embalagem"), 0.0) * fator_embalagem)
                    + (_as_float(item.get("quantidade_solta"), 0.0) * _fator_base_produto(
                        nome_produto=item.get("nome_produto"),
                        embalagem=item.get("embalagem"),
                        unidade_ref=item.get("unidade_solta"),
                        grupo_produto=item.get("grupo_produto"),
                    )),
                    3,
                )
                cur.execute("""
                    INSERT INTO cargas_estoque_itens
                        (
                            carga_id, produto_id, item_seq, grupo_produto, codigo_produto, codigo_barras,
                            nome_produto, embalagem, unidade_embalagem, quantidade_embalagem,
                            unidade_solta, quantidade_solta, fator_embalagem, quantidade_total, dados_json
                        )
                    VALUES
                        (%s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s)
                """, (
                    carga_id,
                    _as_int(produto.get("id"), 0) or None,
                    _as_int(item.get("item_seq"), 0),
                    _as_str(item.get("grupo_produto")),
                    _codigo_produto_nfe_saida(item.get("codigo_produto")),
                    _normalizar_codigo_barras(produto.get("codigo_barras") or item.get("codigo_barras")),
                    _as_str(produto.get("nome_produto") or item.get("nome_produto")),
                    _as_str(item.get("embalagem")),
                    _as_str(item.get("unidade_embalagem")),
                    _as_float(item.get("quantidade_embalagem"), 0.0),
                    _as_str(item.get("unidade_solta")),
                    _as_float(item.get("quantidade_solta"), 0.0),
                    fator_embalagem,
                    quantidade_total,
                    _as_str(item.get("dados_json")),
                ))

            veiculo_id_resolvido = _resolver_veiculo_id_por_numero(cur, pagina.get("veiculo_numero"))
            km_atual_veiculo = _buscar_km_atual_veiculo(cur, veiculo_id_resolvido)
            cur.execute("SELECT id FROM fretes WHERE carga_id=%s ORDER BY id ASC LIMIT 1", (carga_id,))
            frete_existente = cur.fetchone()
            observacao = f"Mapa {mapa_numero or '-'} | {pagina.get('numero_entregas') or 0} entrega(s) | {round(_as_float(pagina.get('peso_total'), 0.0), 3)} kg"
            if frete_existente:
                frete_id = _as_int(frete_existente.get("id"), 0)
                antes_frete = _buscar_frete_detalhado(cur, frete_id)
                cur.execute("""
                    UPDATE fretes
                    SET nome=%s,
                        cidade=%s,
                        data_carga=%s,
                        veiculo_id=%s,
                        km_atual=CASE
                            WHEN COALESCE(km_atual, 0) <= 0 THEN %s
                            ELSE km_atual
                        END,
                        observacao=%s,
                        peso=%s,
                        qtd_entregas=%s
                    WHERE id=%s
                """, (
                    pagina.get("nome_carga"),
                    pagina.get("cidade"),
                    pagina.get("data_carga"),
                    veiculo_id_resolvido,
                    km_atual_veiculo,
                    observacao,
                    pagina.get("peso_total"),
                    pagina.get("numero_entregas"),
                    frete_id,
                ))
                depois_frete = _buscar_frete_detalhado(cur, frete_id)
                fretes_atualizados += 1
                baixa = _sincronizar_baixa_estoque_frete(cur, antes_frete, depois_frete, usuario=usuario)
                if baixa and baixa.get("ok") and not baixa.get("ja_baixada"):
                    cargas_baixadas += 1
            else:
                cur.execute("""
                    INSERT INTO fretes
                        (nome, cidade, data_carga, status, veiculo_id, carga_id, observacao, km_atual, peso, qtd_entregas)
                    VALUES
                        (%s, %s, %s, 'liberado', %s, %s, %s, %s, %s, %s)
                """, (
                    pagina.get("nome_carga"),
                    pagina.get("cidade"),
                    pagina.get("data_carga"),
                    veiculo_id_resolvido,
                    carga_id,
                    observacao,
                    km_atual_veiculo,
                    pagina.get("peso_total"),
                    pagina.get("numero_entregas"),
                ))
                fretes_criados += 1

        conn.commit()
    except Exception:
        conn.rollback()
        raise
    finally:
        cur.close()
        conn.close()

    return {
        "ok": True,
        "arquivo": source_name,
        "paginas_importadas": len(paginas),
        "cargas_criadas": criadas,
        "cargas_atualizadas": atualizadas,
        "fretes_criados": fretes_criados,
        "fretes_atualizados": fretes_atualizados,
        "cargas_baixadas": cargas_baixadas,
    }

def _importar_cargas_csv_texto(texto, source_name="", veiculo_override="") -> dict:
    leitor = csv.DictReader(io.StringIO(texto), delimiter=";")
    if not leitor.fieldnames:
        raise RuntimeError("CSV sem cabecalho.")

    grupos = {}
    for linha_num, linha in enumerate(leitor, start=2):
        cidade_raw = _as_str(linha.get("Cidade"))
        if not cidade_raw:
            cidade_raw = _as_str(linha.get("cidade"))
        cidade_key = _normalizar_chave_texto(cidade_raw) or "sem-cidade"
        cidade_label = _normalizar_nome_local(cidade_raw) or "Sem cidade"
        rota = _as_str(linha.get("Rota"))
        rota_key = _normalizar_chave_texto(rota) or "sem-rota"
        veiculo_numero = _csv_veiculo_numero(linha, veiculo_override)
        veiculo_key = _normalizar_chave_texto(veiculo_numero) or "sem-veiculo"
        grupo_key = veiculo_key if veiculo_numero else (rota_key if rota_key != "sem-rota" else cidade_key)
        grupo = grupos.setdefault(grupo_key, {
            "cidade": "",
            "cidades": [],
            "veiculo_numero": veiculo_numero,
            "rotas": Counter(),
            "clientes": set(),
            "linhas": 0,
            "data_carga": None,
            "quantidade": 0.0,
            "litros": 0.0,
            "peso": 0.0,
            "valor": 0.0,
            "itens": [],
        })
        if cidade_label and cidade_label not in grupo["cidades"]:
            grupo["cidades"].append(cidade_label)
        if not _as_str(grupo.get("cidade")) and cidade_label:
            grupo["cidade"] = cidade_label

        cliente = _as_str(linha.get("Cliente"))
        if rota:
            grupo["rotas"][rota] += 1
        if cliente:
            grupo["clientes"].add(cliente)
        grupo["linhas"] += 1
        data_linha = _csv_date(linha.get("Data"))
        if data_linha and grupo["data_carga"] is None:
            grupo["data_carga"] = data_linha
        grupo["quantidade"] += _csv_numero(linha.get("Quantidade"), 0.0)
        grupo["litros"] += _csv_numero(linha.get("Litro"), 0.0)
        grupo["peso"] += _csv_numero(linha.get("Peso"), 0.0)
        grupo["valor"] += _csv_numero(linha.get("Valor Venda"), 0.0)
        grupo["itens"].append({
            "linha_num": linha_num,
            "cliente": cliente,
            "cidade": cidade_label,
            "rota": rota,
            "veiculo_numero": veiculo_numero,
            "numero_nf": _as_str(linha.get("Número nf")) or _as_str(linha.get("Numero nf")),
            "produto": _as_str(linha.get("Produto")),
            "quantidade": _csv_numero(linha.get("Quantidade"), 0.0),
            "litro": _csv_numero(linha.get("Litro"), 0.0),
            "peso": _csv_numero(linha.get("Peso"), 0.0),
            "valor_venda": _csv_numero(linha.get("Valor Venda"), 0.0),
            "dados_json": json.dumps(linha, ensure_ascii=False, default=str),
        })

    if not grupos:
        raise RuntimeError("CSV nao possui registros validos.")

    conn = get_conn()
    cur = conn.cursor(dictionary=True)
    criadas = 0
    atualizadas = 0
    fretes_criados = 0
    fretes_atualizados = 0
    linhas_importadas = 0

    try:
        for grupo in grupos.values():
            cidade = _as_str(grupo["cidade"]) or (_as_str(grupo["cidades"][0]) if grupo.get("cidades") else "")
            veiculo_numero = _as_str(grupo.get("veiculo_numero"))
            rota = grupo["rotas"].most_common(1)[0][0] if grupo["rotas"] else ""
            data_carga = grupo.get("data_carga") or datetime.date.today()
            if veiculo_numero:
                nome_carga = _montar_nome_frete_exibicao(grupo.get("cidades"), veiculo_numero, cidade) or "Carga importada"
            else:
                nome_carga = _montar_nome_frete_exibicao(grupo.get("cidades"), rota, cidade) or rota or cidade or "Carga importada"
            rota_lookup = rota if not veiculo_numero else ""
            cidade_lookup = cidade if not veiculo_numero and not rota_lookup else ""
            existente = None

            if source_name:
                if veiculo_numero:
                    cur.execute(
                        """
                        SELECT id, nome, cidade, veiculo_numero
                        FROM cargas
                        WHERE LOWER(TRIM(COALESCE(origem_csv, ''))) = LOWER(%s)
                          AND LOWER(TRIM(COALESCE(veiculo_numero, ''))) = LOWER(%s)
                        ORDER BY id ASC
                        LIMIT 1
                        """,
                        (source_name, veiculo_numero),
                    )
                    existente = cur.fetchone()
                else:
                    cur.execute(
                        """
                        SELECT id, nome, cidade, veiculo_numero
                        FROM cargas
                        WHERE LOWER(TRIM(COALESCE(origem_csv, ''))) = LOWER(%s)
                          AND LOWER(TRIM(COALESCE(rota, ''))) = LOWER(%s)
                          AND LOWER(TRIM(COALESCE(veiculo_numero, ''))) = ''
                        ORDER BY id ASC
                        LIMIT 1
                        """,
                        (source_name, rota_lookup),
                    )
                    existente = cur.fetchone()
                    if not existente and cidade_lookup:
                        cur.execute(
                            """
                            SELECT id, nome, cidade, veiculo_numero
                            FROM cargas
                            WHERE LOWER(TRIM(COALESCE(origem_csv, ''))) = LOWER(%s)
                              AND LOWER(TRIM(COALESCE(cidade, ''))) = LOWER(%s)
                              AND LOWER(TRIM(COALESCE(veiculo_numero, ''))) = ''
                            ORDER BY id ASC
                            LIMIT 1
                            """,
                            (source_name, cidade_lookup),
                        )
                        existente = cur.fetchone()
            else:
                cur.execute(
                    """
                    SELECT id, nome, cidade, veiculo_numero
                    FROM cargas
                    WHERE LOWER(TRIM(nome)) = LOWER(%s)
                      AND LOWER(TRIM(COALESCE(veiculo_numero, ''))) = LOWER(%s)
                    ORDER BY id ASC
                    LIMIT 1
                    """,
                    (nome_carga, veiculo_numero),
                )
                existente = cur.fetchone()

            payload = (
                nome_carga,
                cidade,
                rota,
                veiculo_numero,
                source_name,
                int(grupo["linhas"]),
                int(len(grupo["clientes"])),
                round(float(grupo["quantidade"]), 3),
                round(float(grupo["litros"]), 3),
                round(float(grupo["peso"]), 3),
                round(float(grupo["valor"]), 2),
                source_name,
            )

            if existente:
                carga_id = _as_int(existente.get("id"), 0)
                cur.execute(
                    """
                    UPDATE cargas
                    SET nome=%s,
                        cidade=%s,
                        rota=%s,
                        veiculo_numero=%s,
                        origem_csv=%s,
                        registros_importados=%s,
                        clientes_distintos=%s,
                        quantidade_total=%s,
                        litros_total=%s,
                        peso_total=%s,
                        valor_total=%s,
                        arquivo_origem=%s,
                        tipo_importacao='csv',
                        atualizado_em=NOW()
                    WHERE id=%s
                    """,
                    payload + (carga_id,),
                )
                atualizadas += 1
            else:
                cur.execute(
                    """
                    INSERT INTO cargas
                        (
                            nome, cidade, rota, veiculo_numero, origem_csv, registros_importados, clientes_distintos,
                            quantidade_total, litros_total, peso_total, valor_total, arquivo_origem, tipo_importacao
                        )
                    VALUES
                        (%s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, 'csv')
                    """,
                    payload,
                )
                criadas += 1
                carga_id = _as_int(cur.lastrowid, 0)

            if not carga_id:
                continue

            veiculo_id_resolvido = _resolver_veiculo_id_por_numero(cur, veiculo_numero)
            km_atual_veiculo = _buscar_km_atual_veiculo(cur, veiculo_id_resolvido)

            cur.execute("DELETE FROM cargas_import_linhas WHERE carga_id=%s", (carga_id,))
            if grupo["itens"]:
                cur.executemany(
                    """
                    INSERT INTO cargas_import_linhas
                        (carga_id, linha_num, cliente, cidade, rota, veiculo_numero, numero_nf, produto, quantidade, litro, peso, valor_venda, dados_json)
                    VALUES
                        (%s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s)
                    """,
                    [
                        (
                            carga_id,
                            item["linha_num"],
                            item["cliente"],
                            item["cidade"],
                            item["rota"],
                            item["veiculo_numero"],
                            item["numero_nf"],
                            item["produto"],
                            item["quantidade"],
                            item["litro"],
                            item["peso"],
                            item["valor_venda"],
                            item["dados_json"],
                        )
                        for item in grupo["itens"]
                    ],
                )
                linhas_importadas += len(grupo["itens"])

            cur.execute(
                "SELECT id FROM fretes WHERE carga_id=%s ORDER BY id ASC LIMIT 1",
                (carga_id,),
            )
            frete_existente = cur.fetchone()
            nome_frete = nome_carga or "Carga importada"
            if frete_existente:
                cur.execute(
                    """
                    UPDATE fretes
                    SET nome=%s,
                        cidade=%s,
                        carga_id=%s,
                        veiculo_id=COALESCE(veiculo_id, %s),
                        km_atual=CASE
                            WHEN COALESCE(km_atual, 0) <= 0 THEN %s
                            ELSE km_atual
                        END,
                        data_carga=COALESCE(data_carga, %s)
                    WHERE id=%s
                    """,
                    (
                        nome_frete,
                        cidade,
                        carga_id,
                        veiculo_id_resolvido,
                        km_atual_veiculo,
                        data_carga,
                        _as_int(frete_existente.get("id"), 0),
                    ),
                )
                fretes_atualizados += 1
            else:
                cur.execute(
                    """
                    INSERT INTO fretes
                        (nome, cidade, data_carga, status, carga_id, observacao, km_atual, peso, qtd_entregas)
                    VALUES
                        (%s, %s, %s, %s, %s, %s, %s, %s, %s)
                    """,
                    (
                        nome_frete,
                        cidade,
                        data_carga,
                        "liberado",
                        carga_id,
                        f"Importado de {source_name}" if source_name else "Importado de CSV",
                        km_atual_veiculo,
                        round(float(grupo["peso"]), 3),
                        int(grupo["linhas"]),
                    ),
                )
                if veiculo_id_resolvido:
                    frete_id = _as_int(cur.lastrowid, 0)
                    if frete_id > 0:
                        cur.execute(
                            "UPDATE fretes SET veiculo_id=%s WHERE id=%s",
                            (veiculo_id_resolvido, frete_id),
                        )
                fretes_criados += 1

        conn.commit()
    except Exception:
        conn.rollback()
        raise
    finally:
        cur.close()
        conn.close()

    return {
        "ok": True,
        "arquivo": source_name,
        "cargas_criadas": criadas,
        "cargas_atualizadas": atualizadas,
        "fretes_criados": fretes_criados,
        "fretes_atualizados": fretes_atualizados,
        "cidades_total": len(grupos),
        "linhas_total": sum(int(g["linhas"]) for g in grupos.values()),
        "linhas_importadas": linhas_importadas,
    }

def _nz(v):
    return _as_float(v, 0.0)

def _calc_comissao_lancamento(row):
    base_gf = _nz(row.get("v_gf")) - _nz(row.get("d_gf")) - _nz(row.get("icms_gf"))
    base_pet = _nz(row.get("v_pet")) - _nz(row.get("d_pet")) - _nz(row.get("icms_pet"))
    base_agua = _nz(row.get("v_agua")) - _nz(row.get("d_agua"))
    base_vendedor_total = base_gf + base_pet + base_agua

    com_vendedor = (
        (base_gf * _nz(row.get("pct_vend_gf"))) +
        (base_pet * _nz(row.get("pct_vend_pet"))) +
        (base_agua * _nz(row.get("pct_vend_agua")))
    )

    base_ent_gf = _nz(row.get("gf_600")) + _nz(row.get("gf_200")) + _nz(row.get("gf_300")) - _nz(row.get("dev_gf"))
    base_ent_pet = _nz(row.get("pet_2l")) + _nz(row.get("pet_600")) - _nz(row.get("dev_pet"))
    base_ent_agua = _nz(row.get("agua_vol")) - _nz(row.get("dev_agua"))
    base_ent_acucar = _nz(row.get("acucar_qtd"))
    taxa_acucar = _nz(row.get("taxa_ent_acucar"))
    if taxa_acucar <= 0:
        taxa_acucar = _nz(row.get("t_acucar"))

    com_entregador = (
        (base_ent_gf * _nz(row.get("pct_ent_gf"))) +
        (base_ent_pet * _nz(row.get("pct_ent_pet"))) +
        (base_ent_agua * _nz(row.get("pct_ent_agua"))) +
        (base_ent_acucar * taxa_acucar)
    )

    return {
        "base_gf": base_gf,
        "base_pet": base_pet,
        "base_agua": base_agua,
        "base_vendedor_total": base_vendedor_total,
        "comissao_vendedor": com_vendedor,
        "base_ent_gf": base_ent_gf,
        "base_ent_pet": base_ent_pet,
        "base_ent_agua": base_ent_agua,
        "base_ent_acucar": base_ent_acucar,
        "comissao_entregador": com_entregador,
    }

def _fmt_dt(v):
    if not v:
        return None
    if isinstance(v, (datetime.datetime, datetime.date)):
        return v.strftime("%Y-%m-%d %H:%M:%S")
    return str(v)

def _fmt_date(v):
    if not v:
        return None
    if isinstance(v, datetime.datetime):
        return v.date().strftime("%Y-%m-%d")
    if isinstance(v, datetime.date):
        return v.strftime("%Y-%m-%d")
    return _as_str(v)[:10] or None

def _json_list_or_empty(s):
    try:
        return json.loads(s) if s else []
    except:
        return []

def _json_obj_or_empty(s):
    try:
        obj = json.loads(s) if s else {}
        return obj if isinstance(obj, dict) else {}
    except:
        return {}

def _normalizar_item_manutencao_payload(item, index=0):
    if not isinstance(item, dict):
        return None
    nome_produto = _as_str(item.get("nome_produto") or item.get("descricao") or item.get("item") or item.get("tipo"))
    codigo_produto = _as_str(item.get("codigo_produto_nfe") or item.get("codigo") or item.get("codigo_barras"))
    codigo_barras = _as_str(item.get("codigo_barras"))
    unidade = _as_str(item.get("unidade"))
    observacao = _as_str(item.get("observacao") or item.get("obs"))
    quantidade = _as_float(item.get("quantidade"), 0.0)
    valor_unitario = _as_float(item.get("valor_unitario"), 0.0)
    valor_total = _as_float(item.get("valor_total"), 0.0)
    if valor_total <= 0 and quantidade > 0 and valor_unitario > 0:
        valor_total = quantidade * valor_unitario
    if not any([
        nome_produto,
        codigo_produto,
        codigo_barras,
        observacao,
        quantidade > 0,
        valor_unitario > 0,
        valor_total > 0,
    ]):
        return None
    return {
        "item_seq": _as_str(item.get("item_seq") or str(index + 1)),
        "codigo_produto_nfe": codigo_produto,
        "codigo_barras": codigo_barras,
        "nome_produto": nome_produto,
        "unidade": unidade,
        "quantidade": quantidade,
        "valor_unitario": valor_unitario,
        "valor_total": valor_total,
        "observacao": observacao,
    }

def _normalizar_itens_manutencao_payload(lista):
    if not isinstance(lista, list):
        return []
    itens = []
    for index, item in enumerate(lista):
        normalizado = _normalizar_item_manutencao_payload(item, index)
        if normalizado:
            itens.append(normalizado)
    return itens

def _resumir_itens_manutencao(itens):
    nomes = []
    for item in _normalizar_itens_manutencao_payload(itens):
        nome = _as_str(item.get("nome_produto"))
        if nome and nome not in nomes:
            nomes.append(nome)
    if not nomes:
        return ""
    if len(nomes) == 1:
        return nomes[0]
    base = ", ".join(nomes[:3])
    return f"{len(nomes)} itens: {base}{'...' if len(nomes) > 3 else ''}"

def _load_json_file(path, default=None):
    try:
        with open(path, "r", encoding="utf-8") as f:
            data = json.load(f)
        if default is None:
            return data
        return data if isinstance(data, type(default)) else default
    except Exception:
        return default

def _save_json_file(path, data):
    tmp_path = f"{path}.tmp"
    with open(tmp_path, "w", encoding="utf-8") as f:
        json.dump(data, f, ensure_ascii=False, indent=2)
    os.replace(tmp_path, path)

def _normalizar_codbar_modo(v):
    modo = _as_str(v).lower()
    return "camera" if modo == "camera" else "bip"

def _normalizar_codigo_barras(v):
    codigo = _as_str(v)
    if codigo.upper() in ("SEM GTIN", "SEMGTIN", "NO GTIN"):
        return ""
    return codigo

def _normalizar_chave_acesso_nfe(v):
    return re.sub(r"\D+", "", _as_str(v))

COMBUSTIVEL_TIPOS = (
    "diesel_s10",
    "diesel_500",
    "gasolina",
    "etanol",
    "arla",
)
COMBUSTIVEL_PADRAO_VEICULO_TIPOS = (
    "diesel_s10",
    "diesel_500",
    "gasolina",
    "etanol",
    "flex",
)
COMBUSTIVEL_TIPO_ALIASES = {
    "diesel_s10": "diesel_s10",
    "diesel s10": "diesel_s10",
    "diesel s-10": "diesel_s10",
    "diesels10": "diesel_s10",
    "diesel10": "diesel_s10",
    "s10": "diesel_s10",
    "s-10": "diesel_s10",
    "diesel": "diesel_s10",
    "diesel_500": "diesel_500",
    "diesel_s500": "diesel_500",
    "diesel 500": "diesel_500",
    "diesel s500": "diesel_500",
    "diesel s-500": "diesel_500",
    "diesel500": "diesel_500",
    "diesels500": "diesel_500",
    "s500": "diesel_500",
    "s-500": "diesel_500",
    "gasolina": "gasolina",
    "gasolina comum": "gasolina",
    "gasolina c": "gasolina",
    "gasolina c comum": "gasolina",
    "etanol": "etanol",
    "etanol comum": "etanol",
    "etanol hidratado": "etanol",
    "etanol hidratado comum": "etanol",
    "alcool": "etanol",
    "álcool": "etanol",
    "arla": "arla",
    "arla32": "arla",
    "arla 32": "arla",
}
COMBUSTIVEL_PADRAO_VEICULO_ALIASES = {
    **COMBUSTIVEL_TIPO_ALIASES,
    "flex": "flex",
    "gasolina/etanol": "flex",
    "gasolina e etanol": "flex",
    "etanol/gasolina": "flex",
    "etanol e gasolina": "flex",
}
VEICULO_MODELOS_FLEX = ("gol", "polo", "saveiro")

def _normalizar_combustivel_tipo(v):
    tipo = re.sub(r"\s+", " ", _as_str(v).strip().lower())
    return COMBUSTIVEL_TIPO_ALIASES.get(tipo, "diesel_s10")

def _validar_combustivel_tipo(v):
    tipo = re.sub(r"\s+", " ", _as_str(v).strip().lower())
    if tipo not in COMBUSTIVEL_TIPO_ALIASES:
        raise ValueError(
            "combustivel_tipo deve ser Diesel S10, Diesel 500, Gasolina, Etanol ou Arla"
        )
    return COMBUSTIVEL_TIPO_ALIASES[tipo]

def _normalizar_combustivel_padrao_veiculo(v):
    tipo = re.sub(r"\s+", " ", _as_str(v).strip().lower())
    normalizado = COMBUSTIVEL_PADRAO_VEICULO_ALIASES.get(tipo, "diesel_500")
    return (
        normalizado
        if normalizado in COMBUSTIVEL_PADRAO_VEICULO_TIPOS
        else "diesel_500"
    )

def _validar_combustivel_padrao_veiculo(v):
    tipo = re.sub(r"\s+", " ", _as_str(v).strip().lower())
    if tipo not in COMBUSTIVEL_PADRAO_VEICULO_ALIASES:
        raise ValueError(
            "combustivel_padrao do veiculo deve ser Diesel S10, Diesel 500, "
            "Gasolina, Etanol ou Flex"
        )
    normalizado = COMBUSTIVEL_PADRAO_VEICULO_ALIASES[tipo]
    if normalizado not in COMBUSTIVEL_PADRAO_VEICULO_TIPOS:
        raise ValueError(
            "combustivel_padrao do veiculo deve ser Diesel S10, Diesel 500, "
            "Gasolina, Etanol ou Flex"
        )
    return normalizado

def _modelo_veiculo_e_flex(modelo):
    texto = re.sub(r"[^a-z0-9]+", " ", _as_str(modelo).strip().lower())
    tokens = set(texto.split())
    return any(modelo_flex in tokens for modelo_flex in VEICULO_MODELOS_FLEX)

def _combustivel_padrao_para_modelo(modelo, combustivel_padrao):
    if _modelo_veiculo_e_flex(modelo):
        return "flex"
    return _validar_combustivel_padrao_veiculo(combustivel_padrao)

def _combustiveis_permitidos_veiculo(combustivel_padrao):
    padrao = _normalizar_combustivel_padrao_veiculo(combustivel_padrao)
    if padrao == "diesel_s10":
        return ("diesel_s10", "arla")
    if padrao == "flex":
        return ("gasolina", "etanol")
    return (padrao,)

def _combustivel_padrao_veiculo_cur(cur, veiculo_id):
    cur.execute(
        "SELECT combustivel_padrao FROM veiculos WHERE id=%s",
        (_as_int(veiculo_id, 0),),
    )
    row = cur.fetchone()
    if not row:
        raise ValueError("veiculo nao encontrado")
    valor = row.get("combustivel_padrao") if isinstance(row, dict) else row[0]
    return _normalizar_combustivel_padrao_veiculo(valor)

def _validar_combustivel_para_veiculo(cur, veiculo_id, combustivel_tipo=""):
    padrao = _combustivel_padrao_veiculo_cur(cur, veiculo_id)
    tipo_informado = _as_str(combustivel_tipo).strip()
    tipo = (
        _validar_combustivel_tipo(tipo_informado)
        if tipo_informado
        else ("gasolina" if padrao == "flex" else padrao)
    )
    permitidos = _combustiveis_permitidos_veiculo(padrao)
    if tipo not in permitidos:
        if padrao == "diesel_500":
            raise ValueError("este veiculo usa Diesel 500 e nao permite abastecimento com Arla ou Diesel S10")
        if padrao == "diesel_s10":
            raise ValueError("este veiculo permite somente Diesel S10 ou Arla")
        if padrao == "flex":
            raise ValueError("este veiculo e Flex e permite somente Gasolina ou Etanol")
        raise ValueError(
            f"este veiculo permite somente {_combustivel_tipo_label(padrao)}"
        )
    return tipo

def _combustivel_tipo_label(v):
    return {
        "diesel_s10": "Diesel S10",
        "diesel_500": "Diesel 500",
        "gasolina": "Gasolina",
        "etanol": "Etanol",
        "arla": "Arla",
    }[_normalizar_combustivel_tipo(v)]

def _combustivel_move_veiculo(v):
    return _normalizar_combustivel_tipo(v) in (
        "diesel_s10",
        "diesel_500",
        "gasolina",
        "etanol",
    )

def _valor_litro_abastecimento(valor, quantidade_litros):
    litros = _as_float(quantidade_litros, 0.0)
    if litros <= 0:
        return None
    return _as_float(valor, 0.0) / litros

def _calcular_metricas_abastecimentos(rows):
    metricas = {}
    prev_km_by_veiculo = {}
    rows_ordenadas = sorted(
        rows or [],
        key=lambda r: (
            _as_int(r.get("veiculo_id"), 0),
            _as_int(r.get("km"), 0),
            _as_int(r.get("id"), 0),
        )
    )
    for row in rows_ordenadas:
        rid = _as_int(row.get("id"), 0)
        vid = _as_int(row.get("veiculo_id"), 0)
        km_atual = _as_int(row.get("km"), 0)
        qtd = _as_float(row.get("quantidade_litros"), 0.0)
        status = _as_str(row.get("status")).lower()
        combustivel_tipo = _normalizar_combustivel_tipo(row.get("combustivel_tipo"))
        item = {
            "km_inicial": None,
            "km_atual": km_atual,
            "km_rodado": None,
            "km_l": None,
            "valor_litro": _valor_litro_abastecimento(row.get("valor"), qtd),
        }

        if status == "abastecido" and _combustivel_move_veiculo(combustivel_tipo):
            prev_km = prev_km_by_veiculo.get(vid)
            if prev_km is not None:
                item["km_inicial"] = prev_km
                km_rodado = km_atual - prev_km
                item["km_rodado"] = km_rodado
                if km_rodado > 0:
                    if qtd > 0:
                        item["km_l"] = km_rodado / qtd
            prev_km_by_veiculo[vid] = km_atual

        metricas[rid] = item
    return metricas

def _detectar_combustivel_tipo_item(nome_produto):
    nome = _as_str(nome_produto).upper()
    if not nome:
        return ""
    if "ARLA" in nome:
        return "arla"
    if "ETANOL" in nome or "ALCOOL" in nome or "ÁLCOOL" in nome:
        return "etanol"
    if "GASOLINA" in nome:
        return "gasolina"
    if any(token in nome for token in ("S500", "S-500", "DIESEL 500")):
        return "diesel_500"
    if any(token in nome for token in ("DIESEL", "S10", "S-10")):
        return "diesel_s10"
    return ""

def _xml_local_name(tag):
    return str(tag or "").split("}", 1)[-1]

def _xml_child(node, tag_name):
    if node is None:
        return None
    for child in list(node):
        if _xml_local_name(child.tag) == tag_name:
            return child
    return None

def _xml_children(node, tag_name):
    if node is None:
        return []
    return [child for child in list(node) if _xml_local_name(child.tag) == tag_name]

def _xml_text(node, *path):
    current = node
    for tag_name in path:
        current = _xml_child(current, tag_name)
        if current is None:
            return ""
    return _as_str(current.text)

def _parse_nfe_xml_text(xml_text):
    try:
        root = ET.fromstring(xml_text)
    except Exception as exc:
        raise ValueError(f"XML da NF-e invalido: {exc}") from exc

    root_name = _xml_local_name(root.tag)
    nfe_node = root if root_name == "NFe" else _xml_child(root, "NFe")
    if nfe_node is None:
        raise ValueError("Nao foi encontrado o bloco NFe no XML informado.")

    inf_nfe = _xml_child(nfe_node, "infNFe")
    if inf_nfe is None:
        raise ValueError("Nao foi encontrado o bloco infNFe no XML informado.")

    ide = _xml_child(inf_nfe, "ide")
    emit = _xml_child(inf_nfe, "emit")
    dest = _xml_child(inf_nfe, "dest")
    prot = _xml_child(root, "protNFe")
    inf_prot = _xml_child(prot, "infProt") if prot is not None else None

    chave_acesso = _xml_text(inf_prot, "chNFe")
    if not chave_acesso:
        raw_id = _as_str((inf_nfe.attrib or {}).get("Id"))
        chave_acesso = raw_id[3:] if raw_id.startswith("NFe") else raw_id

    itens = []
    for idx, det in enumerate(_xml_children(inf_nfe, "det"), start=1):
        prod = _xml_child(det, "prod")
        if prod is None:
            continue
        codigo_barras = _normalizar_codigo_barras(_xml_text(prod, "cEAN") or _xml_text(prod, "cEANTrib"))
        codigo_produto = _as_str(_xml_text(prod, "cProd"))
        nome_produto = _as_str(_xml_text(prod, "xProd"))
        unidade = _as_str(_xml_text(prod, "uCom") or _xml_text(prod, "uTrib"))
        quantidade = _as_float(_xml_text(prod, "qCom") or _xml_text(prod, "qTrib"), 0.0)
        valor_unitario = _as_float(_xml_text(prod, "vUnCom") or _xml_text(prod, "vUnTrib"), 0.0)
        valor_total = _as_float(_xml_text(prod, "vProd"), quantidade * valor_unitario)
        itens.append({
            "item_seq": _as_str((det.attrib or {}).get("nItem")) or str(idx),
            "codigo_produto_nfe": codigo_produto,
            "codigo_barras": codigo_barras,
            "nome_produto": nome_produto,
            "unidade": unidade,
            "quantidade": quantidade,
            "valor_unitario": valor_unitario,
            "valor_total": valor_total,
        })

    if not itens:
        raise ValueError("A NF-e nao possui itens validos para importar.")

    return _aplicar_cadastro_embalagem_preview({
        "numero_nota": _xml_text(ide, "nNF"),
        "serie": _xml_text(ide, "serie"),
        "chave_acesso": chave_acesso,
        "data_emissao": _xml_text(ide, "dhEmi") or _xml_text(ide, "dEmi"),
        "emitente_nome": _xml_text(emit, "xNome"),
        "emitente_fantasia": _xml_text(emit, "xFant"),
        "emitente_cnpj": _xml_text(emit, "CNPJ") or _xml_text(emit, "CPF"),
        "destinatario_nome": _xml_text(dest, "xNome"),
        "destinatario_cnpj": _xml_text(dest, "CNPJ") or _xml_text(dest, "CPF"),
        "itens": itens,
    })

def _ler_xml_nfe_requisicao():
    arquivo_origem = ""
    xml_text = ""
    file_storage = request.files.get("xml")
    if file_storage:
        arquivo_origem = secure_filename(file_storage.filename or "")
        xml_bytes = file_storage.read() or b""
        if not xml_bytes:
            raise ValueError("arquivo XML vazio")
        try:
            xml_text = xml_bytes.decode("utf-8-sig")
        except Exception:
            xml_text = xml_bytes.decode("latin-1", errors="ignore")
    else:
        data = request.get_json(silent=True) or {}
        xml_text = _as_str(data.get("xml_text") or data.get("xml"))
        arquivo_origem = _as_str(data.get("arquivo_origem"))
    return xml_text, arquivo_origem

def _ler_arquivo_nfe_requisicao():
    arquivo_origem = ""
    conteudo = b""
    mimetype = ""
    file_storage = request.files.get("arquivo") or request.files.get("xml") or request.files.get("pdf")
    if file_storage:
        arquivo_origem = secure_filename(file_storage.filename or "")
        mimetype = _as_str(file_storage.mimetype).lower()
        conteudo = file_storage.read() or b""
        if not conteudo:
            raise ValueError("arquivo enviado vazio")
        return conteudo, arquivo_origem, mimetype

    data = request.get_json(silent=True) or {}
    xml_text = _as_str(data.get("xml_text") or data.get("xml"))
    if xml_text:
        arquivo_origem = _as_str(data.get("arquivo_origem")) or "nfe.xml"
        return xml_text.encode("utf-8"), arquivo_origem, "application/xml"
    html_text = _as_str(data.get("html_text") or data.get("html"))
    if html_text:
        arquivo_origem = _as_str(data.get("arquivo_origem")) or "consulta_nfe.html"
        return html_text.encode("utf-8"), arquivo_origem, "text/html"
    return b"", "", ""

def _detectar_tipo_arquivo_nfe(conteudo, arquivo_origem="", mimetype=""):
    nome = _as_str(arquivo_origem).lower()
    tipo = _as_str(mimetype).lower()
    prefixo = (conteudo or b"")[:16].lstrip()
    prefixo_texto = _decode_xml_bytes((conteudo or b"")[:2048]).lower() if conteudo else ""
    if (
        nome.endswith(".html")
        or nome.endswith(".htm")
        or tipo == "text/html"
        or "<html" in prefixo_texto
        or "xsltnferesumida" in prefixo_texto
        or "tabnfe" in prefixo_texto
    ):
        return "html"
    if nome.endswith(".xml") or tipo in ("text/xml", "application/xml") or prefixo.startswith(b"<"):
        return "xml"
    if nome.endswith(".pdf") or tipo == "application/pdf" or prefixo.startswith(b"%PDF"):
        return "pdf"
    return ""

def _decode_xml_bytes(xml_bytes):
    try:
        return (xml_bytes or b"").decode("utf-8-sig")
    except Exception:
        return (xml_bytes or b"").decode("latin-1", errors="ignore")

def _normalizar_data_documento(v):
    s = _as_str(v)
    if not s:
        return ""
    if re.match(r"^\d{4}-\d{2}-\d{2}$", s[:10]):
        return s[:10]
    for fmt in ("%d/%m/%Y", "%d-%m-%Y", "%Y/%m/%d"):
        try:
            return datetime.datetime.strptime(s[:10], fmt).date().isoformat()
        except Exception:
            pass
    try:
        return datetime.datetime.fromisoformat(s.replace("Z", "+00:00")).date().isoformat()
    except Exception:
        return ""

def _pdf_literal_to_text(data):
    out = bytearray()
    i = 0
    data = data or b""
    while i < len(data):
        b = data[i]
        if b == 92 and i + 1 < len(data):  # backslash
            nxt = data[i + 1]
            mapa = {
                ord("n"): 10,
                ord("r"): 13,
                ord("t"): 9,
                ord("b"): 8,
                ord("f"): 12,
                ord("("): ord("("),
                ord(")"): ord(")"),
                ord("\\"): ord("\\"),
            }
            if nxt in mapa:
                out.append(mapa[nxt])
                i += 2
                continue
            if 48 <= nxt <= 55:
                octal = bytes([nxt])
                j = i + 2
                while j < min(i + 4, len(data)) and 48 <= data[j] <= 55:
                    octal += bytes([data[j]])
                    j += 1
                out.append(int(octal, 8))
                i = j
                continue
            out.append(nxt)
            i += 2
            continue
        out.append(b)
        i += 1
    return out.decode("latin-1", errors="ignore")

def _extrair_texto_stream_pdf(stream_bytes):
    segmentos = []
    for match in re.finditer(rb"\((?:\\.|[^\\()])*\)\s*Tj", stream_bytes or b""):
        bloco = match.group(0)
        fim = bloco.rfind(b")")
        if fim > 0:
            segmentos.append(_pdf_literal_to_text(bloco[1:fim]))
    for match in re.finditer(rb"\[(.*?)\]\s*TJ", stream_bytes or b"", re.S):
        partes = []
        for literal in re.finditer(rb"\((?:\\.|[^\\()])*\)", match.group(1)):
            partes.append(_pdf_literal_to_text(literal.group(0)[1:-1]))
        if partes:
            segmentos.append("".join(partes))
    for match in re.finditer(rb"\((?:\\.|[^\\()])*\)\s*[\"']", stream_bytes or b""):
        bloco = match.group(0)
        fim = bloco.rfind(b")")
        if fim > 0:
            segmentos.append(_pdf_literal_to_text(bloco[1:fim]))
    return "\n".join([_as_str(seg) for seg in segmentos if _as_str(seg)])

def _descompactar_stream_pdf(stream_bytes):
    candidatos = [stream_bytes or b"", (stream_bytes or b"").rstrip(b"\r\n")]
    for candidato in candidatos:
        if not candidato:
            continue
        try:
            return zlib.decompress(candidato)
        except Exception:
            try:
                return zlib.decompress(candidato, -15)
            except Exception:
                pass
    return b""

def _extrair_texto_pdf_bytes(pdf_bytes):
    textos = []
    if shutil.which("pdftotext"):
        tmp_pdf_path = os.path.join("/tmp", f"nfe_pdf_{uuid.uuid4().hex}.pdf")
        tmp_txt_path = os.path.join("/tmp", f"nfe_pdf_{uuid.uuid4().hex}.txt")
        try:
            with open(tmp_pdf_path, "wb") as f:
                f.write(pdf_bytes or b"")
            proc = subprocess.run(
                ["pdftotext", "-layout", "-enc", "UTF-8", tmp_pdf_path, tmp_txt_path],
                capture_output=True,
                text=True,
                errors="ignore",
                timeout=20,
                check=False,
            )
            if proc.returncode == 0 and os.path.exists(tmp_txt_path):
                with open(tmp_txt_path, "r", encoding="utf-8", errors="ignore") as f:
                    texto_extraido = f.read()
                if _as_str(texto_extraido):
                    textos.append(texto_extraido)
        except Exception:
            pass
        finally:
            for path in (tmp_pdf_path, tmp_txt_path):
                try:
                    if os.path.exists(path):
                        os.remove(path)
                except Exception:
                    pass

    for match in re.finditer(rb"<<(.*?)>>\s*stream\r?\n(.*?)\r?\nendstream", pdf_bytes or b"", re.S):
        header = match.group(1) or b""
        stream = match.group(2) or b""
        if b"/FlateDecode" in header:
            payload = _descompactar_stream_pdf(stream)
        else:
            payload = stream
        texto = _extrair_texto_stream_pdf(payload)
        if _as_str(texto):
            textos.append(texto)

    if not textos and shutil.which("strings"):
        tmp_path = os.path.join("/tmp", f"nfe_pdf_{uuid.uuid4().hex}.pdf")
        try:
            with open(tmp_path, "wb") as f:
                f.write(pdf_bytes or b"")
            proc = subprocess.run(
                ["strings", "-n", "4", tmp_path],
                capture_output=True,
                text=True,
                errors="ignore",
                timeout=20,
                check=False,
            )
            if _as_str(proc.stdout):
                textos.append(proc.stdout)
        except Exception:
            pass
        finally:
            try:
                os.remove(tmp_path)
            except Exception:
                pass

    return "\n".join([t for t in textos if _as_str(t)])

def _linhas_pdf_normalizadas(texto):
    vistos = set()
    linhas = []
    for raw in re.split(r"[\r\n]+", texto or ""):
        linha = re.sub(r"\s+", " ", _as_str(raw))
        if not linha:
            continue
        chave = linha.upper()
        if chave in vistos:
            continue
        vistos.add(chave)
        linhas.append(linha)
    return linhas

def _limpar_numero_nota(v):
    digits = re.sub(r"\D+", "", _as_str(v))
    if not digits or len(digits) > 15:
        return ""
    return digits.lstrip("0") or digits

def _primeira_linha_com_rotulo(linhas, rotulos):
    rotulos = [r.upper() for r in (rotulos or []) if _as_str(r)]
    for idx, linha in enumerate(linhas or []):
        up = linha.upper()
        if not any(rotulo in up for rotulo in rotulos):
            continue
        for prox in (linhas or [])[idx + 1: idx + 4]:
            prox_up = prox.upper()
            if any(rotulo in prox_up for rotulo in rotulos):
                continue
            if re.search(r"[A-Z]", prox_up):
                return prox
    return ""

def _extrair_itens_pdf_linhas(linhas):
    itens = []
    vistos = set()
    skip_terms = (
        "CHAVE DE ACESSO",
        "CONTROLE DO FISCO",
        "NOTA FISCAL",
        "DANFE",
        "CALCULO DO IMPOSTO",
        "BASE DE CALCULO",
        "VALOR DO ICMS",
        "VALOR TOTAL",
        "TRANSPORTADOR",
        "PESO BRUTO",
        "PESO LIQUIDO",
        "DADOS ADICIONAIS",
        "RESERVADO AO FISCO",
        "PROTOCOLO",
        "NATUREZA DA OPERACAO",
        "FATURA",
        "DESCONTO",
        "FRETE",
    )
    item_re = re.compile(
        r"^(?P<prefixo>.+?)\s+(?P<unidade>[A-Z]{1,4})\s+(?P<quantidade>\d[\d.,]*)\s+"
        r"(?P<valor_unitario>\d[\d.,]*)\s+(?P<valor_total>\d[\d.,]*)(?:\s+.*)?$"
    )
    for linha in linhas or []:
        up = linha.upper()
        if any(term in up for term in skip_terms):
            continue
        match = item_re.match(linha)
        if not match:
            continue
        prefixo = re.sub(r"\s+", " ", _as_str(match.group("prefixo")))
        partes = prefixo.split()
        item_seq = ""
        codigo_produto = ""
        if partes and re.fullmatch(r"\d{1,4}", partes[0]):
            item_seq = partes.pop(0)
        if partes and re.fullmatch(r"[A-Z0-9./-]{2,20}", partes[0]) and not re.search(r"[a-z]", partes[0]):
            codigo_produto = partes.pop(0)
        nome = " ".join(partes).strip()
        if not nome or not re.search(r"[A-Za-z]", nome):
            continue
        chave = (
            nome.upper(),
            match.group("unidade"),
            match.group("quantidade"),
            match.group("valor_unitario"),
        )
        if chave in vistos:
            continue
        vistos.add(chave)
        itens.append({
            "item_seq": item_seq or str(len(itens) + 1),
            "codigo_produto_nfe": codigo_produto,
            "codigo_barras": "",
            "nome_produto": nome,
            "unidade": match.group("unidade"),
            "quantidade": _as_float_br(match.group("quantidade"), 0.0),
            "valor_unitario": _as_float_br(match.group("valor_unitario"), 0.0),
            "valor_total": _as_float_br(match.group("valor_total"), 0.0),
        })
    return itens

def _extrair_itens_ocr_linhas(linhas):
    itens = []
    vistos = set()
    skip_terms = (
        "CHAVE DE ACESSO",
        "CONTROLE DO FISCO",
        "NOTA FISCAL",
        "DANFE",
        "VALOR TOTAL",
        "TOTAL DA NOTA",
        "CALCULO DO IMPOSTO",
        "DADOS ADICIONAIS",
        "RESERVADO AO FISCO",
        "PROTOCOLO",
        "DESCONTO",
        "FRETE",
        "ICMS",
        "IPI",
        "CNPJ",
        "EMITENTE",
        "DESTINATARIO",
    )
    patterns = [
        re.compile(
            r"^(?:(?P<seq>\d{1,4})\s+)?(?P<codigo>[A-Z0-9./-]{2,30})\s+(?P<nome>.+?)\s+"
            r"(?P<quantidade>\d[\d.,]*)\s+(?P<valor_unitario>\d[\d.,]*)$",
            re.I,
        ),
        re.compile(
            r"^(?:(?P<seq>\d{1,4})\s+)?(?P<codigo>[A-Z0-9./-]{2,30})\s+(?P<nome>.+?)\s+"
            r"(?P<unidade>[A-Z]{1,4})\s+(?P<quantidade>\d[\d.,]*)\s+(?P<valor_unitario>\d[\d.,]*)"
            r"(?:\s+(?P<valor_total>\d[\d.,]*))?$",
            re.I,
        ),
    ]
    for linha in linhas or []:
        linha = re.sub(r"\s+", " ", _as_str(linha)).strip()
        if not linha:
            continue
        up = linha.upper()
        if any(term in up for term in skip_terms):
            continue
        if not re.search(r"\d", linha) or not re.search(r"[A-Z]", up):
            continue

        match = None
        for pattern in patterns:
            match = pattern.match(linha)
            if match:
                break
        if not match:
            continue

        codigo = _as_str(match.group("codigo")).strip()
        nome = _as_str(match.group("nome")).strip(" -")
        if not codigo or not nome or not re.search(r"[A-Za-z]", nome):
            continue

        quantidade = _as_float_br(match.group("quantidade"), 0.0)
        valor_unitario = _as_float_br(match.group("valor_unitario"), 0.0)
        if quantidade <= 0 or valor_unitario < 0:
            continue

        chave = (codigo.upper(), nome.upper(), round(quantidade, 3), round(valor_unitario, 2))
        if chave in vistos:
            continue
        vistos.add(chave)

        itens.append({
            "item_seq": _as_str(match.groupdict().get("seq")) or str(len(itens) + 1),
            "codigo_produto_nfe": codigo,
            "codigo_barras": "",
            "nome_produto": nome,
            "unidade": _as_str(match.groupdict().get("unidade")),
            "quantidade": quantidade,
            "valor_unitario": valor_unitario,
            "valor_total": _as_float_br(match.groupdict().get("valor_total"), quantidade * valor_unitario),
        })
    return itens

def _normalizar_item_preview_nfe(item, idx=1):
    item = item or {}
    quantidade = _as_float_br(item.get("quantidade"), _as_float(item.get("quantidade"), 0.0))
    unidade = _as_str(item.get("unidade"))
    if re.fullmatch(r"\d[\d.,]*", unidade or ""):
        unidade = ""
    quantidade_embalagem = _as_float_br(item.get("quantidade_embalagem"), _as_float(item.get("quantidade_embalagem"), quantidade))
    fator_embalagem = _as_float_br(item.get("fator_embalagem"), _as_float(item.get("fator_embalagem"), 1.0))
    if fator_embalagem <= 0:
        fator_embalagem = 1.0
    fator_inferido = 1 if item.get("fator_inferido") in (True, 1, "1", "true", "True") else 0
    quantidade_unidades = _as_float_br(item.get("quantidade_unidades"), _as_float(item.get("quantidade_unidades"), quantidade))
    valor_unitario = _as_float_br(item.get("valor_unitario"), _as_float(item.get("valor_unitario"), 0.0))
    valor_total = _as_float_br(item.get("valor_total"), quantidade * valor_unitario)
    return {
        "item_seq": _as_str(item.get("item_seq")) or str(idx),
        "codigo_produto_nfe": _as_str(item.get("codigo_produto_nfe")),
        "codigo_barras": _normalizar_codigo_barras(item.get("codigo_barras")),
        "nome_produto": _as_str(item.get("nome_produto")),
        "unidade": unidade,
        "embalagem_tipo": _as_str(item.get("embalagem_tipo")) or unidade,
        "quantidade_embalagem": quantidade_embalagem,
        "fator_embalagem": fator_embalagem,
        "fator_inferido": fator_inferido,
        "quantidade_unidades": quantidade_unidades,
        "quantidade": quantidade,
        "valor_unitario": valor_unitario,
        "valor_total": valor_total,
    }

def _normalizar_preview_nfe(data):
    data = data or {}
    warnings = data.get("warnings") if isinstance(data.get("warnings"), list) else []
    itens_brutos = data.get("itens") if isinstance(data.get("itens"), list) else []
    itens = []
    for idx, item in enumerate(itens_brutos, start=1):
        norm = _normalizar_item_preview_nfe(item, idx)
        if not (
            _as_str(norm.get("nome_produto"))
            or _as_str(norm.get("codigo_produto_nfe"))
            or _as_str(norm.get("codigo_barras"))
            or norm.get("quantidade")
            or norm.get("valor_unitario")
        ):
            continue
        itens.append(norm)

    chave_acesso = _normalizar_chave_acesso_nfe(data.get("chave_acesso"))
    if chave_acesso and len(chave_acesso) != 44:
        warnings.append("Chave de acesso com tamanho incompleto. Revise antes de importar.")
    preview_tipo = "parcial" if _as_str(data.get("preview_tipo")).lower() == "parcial" else "completo"
    limitation_message = _as_str(data.get("limitation_message"))
    valor_total = _as_float_br(data.get("valor_total"), _as_float(data.get("valor_total"), 0.0))

    return {
        "source_type": _as_str(data.get("source_type")).lower() or "xml",
        "preview_tipo": preview_tipo,
        "limitation_message": limitation_message,
        "arquivo_origem": _as_str(data.get("arquivo_origem")),
        "numero_nota": _limpar_numero_nota(data.get("numero_nota")) or _as_str(data.get("numero_nota")),
        "serie": _as_str(data.get("serie")),
        "chave_acesso": chave_acesso,
        "data_emissao": _normalizar_data_documento(data.get("data_emissao")),
        "emitente_nome": _as_str(data.get("emitente_nome")),
        "emitente_cnpj": _normalizar_chave_acesso_nfe(data.get("emitente_cnpj")),
        "destinatario_nome": _as_str(data.get("destinatario_nome")),
        "destinatario_cnpj": _normalizar_chave_acesso_nfe(data.get("destinatario_cnpj")),
        "valor_total": valor_total,
        "itens": itens,
        "warnings": [w for w in warnings if _as_str(w)],
    }


class _HtmlTableCollector(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.tables = []
        self._table_stack = []
        self._current_row = None
        self._current_cell = None

    def handle_starttag(self, tag, attrs):
        nome = str(tag or "").lower()
        attrs_map = {str(k or "").lower(): str(v or "") for k, v in (attrs or [])}
        if nome == "table":
            self._table_stack.append({"class": attrs_map.get("class", ""), "rows": []})
            return
        if not self._table_stack:
            return
        if nome == "tr":
            self._current_row = []
            return
        if nome in ("td", "th") and self._current_row is not None:
            self._current_cell = []

    def handle_endtag(self, tag):
        nome = str(tag or "").lower()
        if nome in ("td", "th"):
            if self._current_row is not None and self._current_cell is not None:
                texto = re.sub(r"\s+", " ", "".join(self._current_cell or [])).strip()
                self._current_row.append(texto)
            self._current_cell = None
            return
        if nome == "tr":
            if self._table_stack and isinstance(self._current_row, list):
                row = [col for col in self._current_row if _as_str(col)]
                if row:
                    self._table_stack[-1]["rows"].append(row)
            self._current_row = None
            self._current_cell = None
            return
        if nome == "table" and self._table_stack:
            self.tables.append(self._table_stack.pop())

    def handle_data(self, data):
        if self._current_cell is not None:
            self._current_cell.append(str(data or ""))


def _html_linhas_limpa(texto):
    bruto = _as_str(texto)
    bruto = re.sub(r"(?is)<(script|style)\b.*?>.*?</\1>", " ", bruto)
    bruto = re.sub(r"(?i)</?(tr|p|div|li|h\d)\b[^>]*>", "\n", bruto)
    bruto = re.sub(r"(?i)<br\s*/?>", "\n", bruto)
    bruto = re.sub(r"(?s)<[^>]+>", " ", bruto)
    linhas = []
    for linha in html_lib.unescape(bruto).splitlines():
        limpa = re.sub(r"\s+", " ", linha).strip()
        if limpa:
            linhas.append(limpa)
    return linhas


def _portal_match_header(header, *termos):
    base = re.sub(r"[^a-z0-9]+", "", _as_str(header).lower())
    return any(re.sub(r"[^a-z0-9]+", "", _as_str(termo).lower()) in base for termo in termos if _as_str(termo))


def _portal_find_col(headers, *grupos):
    for idx, header in enumerate(headers):
        for grupo in grupos:
            termos = grupo if isinstance(grupo, (list, tuple)) else [grupo]
            if _portal_match_header(header, *termos):
                return idx
    return -1


def _portal_get_value_from_rows(rows, *labels):
    labels_norm = [re.sub(r"[^a-z0-9]+", "", _as_str(label).lower()) for label in labels if _as_str(label)]
    for row in rows or []:
        cols = [_as_str(col).strip() for col in row if _as_str(col).strip()]
        if len(cols) < 2:
            continue
        for idx in range(len(cols) - 1):
            left_norm = re.sub(r"[^a-z0-9]+", "", cols[idx].lower())
            if any(label in left_norm for label in labels_norm):
                return cols[idx + 1]
    return ""


def _portal_get_value_from_text(lines, *labels):
    labels_norm = [re.sub(r"[^a-z0-9]+", "", _as_str(label).lower()) for label in labels if _as_str(label)]
    for idx, linha in enumerate(lines or []):
        linha_norm = re.sub(r"[^a-z0-9]+", "", linha.lower())
        for label in labels_norm:
            if label and label in linha_norm:
                match = re.search(r":\s*(.+)$", linha)
                if match and _as_str(match.group(1)):
                    return _as_str(match.group(1))
                if idx + 1 < len(lines):
                    prox = _as_str(lines[idx + 1])
                    if prox:
                        return prox
    return ""


def _parse_nfe_portal_html(html_text, arquivo_origem=""):
    html_text = _as_str(html_text)
    if not html_text:
        raise ValueError("envie o HTML salvo da consulta publica da NF-e")
    if "XSLTNFeResumida" not in html_text and "tabNFe" not in html_text:
        raise ValueError("o HTML enviado nao parece ser a pagina resumida oficial da NF-e")

    parser = _HtmlTableCollector()
    try:
        parser.feed(html_text)
    except Exception:
        pass

    tabelas = parser.tables or []
    todas_rows = []
    tabelas_itens = []
    for tabela in tabelas:
        rows = tabela.get("rows") or []
        todas_rows.extend(rows)
        if "tabnfe" in _as_str(tabela.get("class")).lower():
            tabelas_itens.append(rows)

    linhas = _html_linhas_limpa(html_text)
    texto_plano = "\n".join(linhas)
    chave_match = re.search(r"((?:\d[\s.-]?){44})", texto_plano)
    chave_acesso = _normalizar_chave_acesso_nfe(chave_match.group(1) if chave_match else "")
    chave_meta = _nfe_resumo_chave_acesso(chave_acesso)

    numero_nota = (
        _portal_get_value_from_rows(todas_rows, "numero", "número", "nnf")
        or _portal_get_value_from_text(linhas, "numero", "número", "nnf")
        or chave_meta.get("numero_nota")
    )
    serie = (
        _portal_get_value_from_rows(todas_rows, "serie", "série")
        or _portal_get_value_from_text(linhas, "serie", "série")
        or chave_meta.get("serie")
    )
    data_emissao = (
        _portal_get_value_from_rows(todas_rows, "data de emissao", "data emissao", "emissao", "emissão")
        or _portal_get_value_from_text(linhas, "data de emissao", "data emissao", "emissao", "emissão")
    )
    emitente_nome = (
        _portal_get_value_from_rows(todas_rows, "nome / razao social", "nome/razao social", "razao social", "emitente")
        or _portal_get_value_from_text(linhas, "nome / razao social", "nome/razao social", "razao social", "emitente")
    )
    emitente_cnpj = (
        _portal_get_value_from_rows(todas_rows, "cnpj", "cpf")
        or _portal_get_value_from_text(linhas, "cnpj", "cpf")
        or chave_meta.get("emitente_cnpj")
    )
    valor_total = (
        _portal_get_value_from_rows(todas_rows, "valor total da nota fiscal", "valor total", "valor da nota", "vnf")
        or _portal_get_value_from_text(linhas, "valor total da nota fiscal", "valor total", "valor da nota", "vnf")
    )

    itens = []
    for rows in tabelas_itens:
        if len(rows) < 2:
            continue
        headers = [re.sub(r"\s+", " ", _as_str(col)).strip() for col in rows[0]]
        idx_codigo = _portal_find_col(headers, ["codigo", "código", "codprod"], ["cod"])
        idx_descricao = _portal_find_col(headers, ["descricao", "descrição", "produto", "xprod"])
        idx_unidade = _portal_find_col(headers, ["unidade", "un", "und", "ucom"])
        idx_quantidade = _portal_find_col(headers, ["quantidade", "qtd", "qtde", "qcom"])
        idx_vunit = _portal_find_col(headers, ["valor unitario", "valor unitário", "vl unit", "vuncom"])
        idx_vtotal = _portal_find_col(headers, ["valor total", "vprod", "valor produto"])
        for row in rows[1:]:
            cols = [_as_str(col).strip() for col in row]
            if not any(cols):
                continue
            descricao = cols[idx_descricao] if 0 <= idx_descricao < len(cols) else ""
            codigo = cols[idx_codigo] if 0 <= idx_codigo < len(cols) else ""
            if not re.search(r"[A-Za-zÀ-ÿ]", descricao or ""):
                ignorar = {idx for idx in (idx_codigo, idx_unidade, idx_quantidade, idx_vunit, idx_vtotal) if idx >= 0}
                for idx_col, valor_col in enumerate(cols):
                    if idx_col in ignorar:
                        continue
                    valor_limpo = _as_str(valor_col).strip()
                    if re.search(r"[A-Za-zÀ-ÿ]", valor_limpo):
                        descricao = valor_limpo
                        break
            if not descricao and not codigo:
                continue
            if _portal_match_header(descricao, "total", "base de calculo", "valor aproximado dos tributos"):
                continue
            quantidade_raw = cols[idx_quantidade] if 0 <= idx_quantidade < len(cols) else ""
            valor_unitario_raw = cols[idx_vunit] if 0 <= idx_vunit < len(cols) else ""
            valor_total_raw = cols[idx_vtotal] if 0 <= idx_vtotal < len(cols) else ""
            quantidade = _as_float_br(quantidade_raw, _as_float(quantidade_raw, 0.0))
            valor_unitario = _as_float_br(valor_unitario_raw, _as_float(valor_unitario_raw, 0.0))
            valor_total_item = _as_float_br(valor_total_raw, quantidade * valor_unitario)
            itens.append({
                "item_seq": str(len(itens) + 1),
                "codigo_produto_nfe": codigo,
                "codigo_barras": "",
                "nome_produto": descricao,
                "unidade": cols[idx_unidade] if 0 <= idx_unidade < len(cols) else "",
                "quantidade": quantidade,
                "valor_unitario": valor_unitario,
                "valor_total": valor_total_item,
            })

    warnings = [
        "Dados extraidos do HTML resumido da consulta publica da NF-e. Revise antes de confirmar a importacao.",
    ]
    if not itens:
        warnings.append("Nenhum item foi localizado automaticamente na tabela tabNFe do HTML. Ajuste manualmente se necessario.")

    return _aplicar_cadastro_embalagem_preview({
        "source_type": "portal",
        "preview_tipo": "completo" if itens else "parcial",
        "limitation_message": "" if itens else "Consulta publica encontrada, mas a tabela de itens nao foi reconhecida por completo.",
        "arquivo_origem": arquivo_origem or "consulta_nfe.html",
        "numero_nota": numero_nota,
        "serie": serie,
        "chave_acesso": chave_acesso or chave_meta.get("chave_acesso"),
        "data_emissao": data_emissao,
        "emitente_nome": emitente_nome,
        "emitente_cnpj": emitente_cnpj,
        "valor_total": valor_total,
        "itens": itens,
        "warnings": warnings,
    })

def _parse_nfe_pdf_bytes(pdf_bytes, arquivo_origem=""):
    texto = _extrair_texto_pdf_bytes(pdf_bytes)
    if not _as_str(texto):
        raise ValueError("Nao foi possivel ler o PDF da NF-e. Envie o XML oficial ou revise manualmente os dados.")

    linhas = _linhas_pdf_normalizadas(texto)
    digits = re.findall(r"(?:\d[\s.-]?){44}", texto)
    chave_acesso = ""
    for candidato in digits:
        normalizado = _normalizar_chave_acesso_nfe(candidato)
        if len(normalizado) == 44:
            chave_acesso = normalizado
            break

    numero_nota = ""
    serie = ""
    data_emissao = ""
    for linha in linhas:
        up = linha.upper()
        if not numero_nota and ("NOTA" in up or "NUMERO" in up or "NRO" in up):
            for match in re.finditer(r"(\d[\d./-]{2,18})", linha):
                candidato = _limpar_numero_nota(match.group(1))
                if candidato:
                    numero_nota = candidato
                    break
        if not serie and "SERIE" in up:
            match = re.search(r"SERIE\s*[:\-]?\s*([A-Z0-9.-]+)", linha, re.I)
            if match:
                serie = _as_str(match.group(1))
        if not data_emissao and ("EMISSAO" in up or "EMISSAO" in up):
            match = re.search(r"(\d{2}/\d{2}/\d{4})", linha)
            if match:
                data_emissao = _normalizar_data_documento(match.group(1))

    if not data_emissao:
        match = re.search(r"\b(\d{2}/\d{2}/\d{4})\b", texto)
        if match:
            data_emissao = _normalizar_data_documento(match.group(1))

    cnpjs = re.findall(r"\d{2}\.?\d{3}\.?\d{3}/\d{4}-?\d{2}", texto)
    emitente_nome = _primeira_linha_com_rotulo(linhas, ["EMITENTE", "EMISSOR", "RAZAO SOCIAL"])
    if not emitente_nome:
        for linha in linhas[:12]:
            up = linha.upper()
            if re.search(r"[A-Z]", up) and not any(
                termo in up for termo in ("DANFE", "NOTA FISCAL", "CHAVE DE ACESSO", "CONTROLE DO FISCO")
            ):
                emitente_nome = linha
                break
    destinatario_nome = _primeira_linha_com_rotulo(linhas, ["DESTINATARIO", "REMETENTE"])

    warnings = [
        "Leitura de PDF em modo assistido. Revise os campos e os itens antes de confirmar a importacao."
    ]
    itens = _extrair_itens_pdf_linhas(linhas)
    if not itens:
        warnings.append("Nenhum item foi identificado automaticamente no PDF. Adicione ou ajuste os itens manualmente.")

    return _normalizar_preview_nfe({
        "source_type": "pdf",
        "arquivo_origem": arquivo_origem,
        "numero_nota": numero_nota,
        "serie": serie,
        "chave_acesso": chave_acesso,
        "data_emissao": data_emissao,
        "emitente_nome": emitente_nome,
        "emitente_cnpj": cnpjs[0] if len(cnpjs) >= 1 else "",
        "destinatario_nome": destinatario_nome,
        "destinatario_cnpj": cnpjs[1] if len(cnpjs) >= 2 else "",
        "itens": itens,
        "warnings": warnings,
    })

def _ler_arquivo_imagem_requisicao():
    arquivo = request.files.get("arquivo")
    if not arquivo or not getattr(arquivo, "filename", ""):
        raise ValueError("envie uma foto da nota para leitura OCR")
    conteudo = arquivo.read()
    if not conteudo:
        raise ValueError("a foto enviada esta vazia")
    return conteudo, secure_filename(arquivo.filename or "nota.jpg"), _as_str(getattr(arquivo, "mimetype", "")) or "image/jpeg"

def _normalizar_valor_brasileiro(valor_texto):
    bruto = _as_str(valor_texto)
    if not bruto:
        return None, ""
    match = re.search(r"(\d{1,3}(?:\.\d{3})*,\d{2}|\d+\.\d{2}|\d+,\d{2})", bruto)
    if not match:
        return None, ""
    token = match.group(1).strip()
    normalizado = token.replace(".", "").replace(",", ".")
    try:
        valor = round(float(normalizado), 2)
    except (TypeError, ValueError):
        return None, ""
    return valor, token

def _extrair_campo_rotulado_ocr(linhas, rotulos):
    rotulos_upper = [r.upper() for r in (rotulos or []) if _as_str(r)]
    for linha in linhas:
        up = linha.upper()
        if not any(rotulo in up for rotulo in rotulos_upper):
            continue
        partes = re.split(r"[:\-]", linha, maxsplit=1)
        if len(partes) == 2 and _as_str(partes[1]):
            return _as_str(partes[1])
        tokens = [tok for tok in re.split(r"\s{2,}", linha) if _as_str(tok)]
        if len(tokens) >= 2:
            return _as_str(tokens[-1])
    return ""

def _extrair_numero_nota_ocr(linhas, texto=""):
    candidatos = []
    for linha in linhas or []:
        atual = _as_str(linha)
        if not atual:
            continue
        up = atual.upper()
        if not any(rotulo in up for rotulo in ("NF", "NF-E", "NOTA", "NUMERO", "NRO", "NR.")):
            continue
        patterns = [
            r"(?:NF(?:-E)?|NOTA\s+FISCAL)\D{0,12}(\d{3,9})\b",
            r"(?:NUMERO|NRO|NR\.?)\D{0,8}(\d{3,9})\b",
            r"\b(\d{3,9})\b\D{0,8}(?:SERIE|S[ÉE]RIE)\b",
        ]
        for pattern in patterns:
            match = re.search(pattern, up, re.I)
            if not match:
                continue
            numero = _limpar_numero_nota(match.group(1))
            if numero:
                candidatos.append(numero)

    if not candidatos and texto:
        texto_upper = _as_str(texto).upper()
        for pattern in (
            r"(?:NF(?:-E)?|NOTA\s+FISCAL)\D{0,16}(\d{3,9})\b",
            r"(?:NUMERO|NRO|NR\.?)\D{0,10}(\d{3,9})\b",
        ):
            match = re.search(pattern, texto_upper, re.I)
            if not match:
                continue
            numero = _limpar_numero_nota(match.group(1))
            if numero:
                candidatos.append(numero)

    if not candidatos:
        campo_numero = _extrair_campo_rotulado_ocr(linhas, ["NUMERO", "NRO", "NF-E", "NOTA"])
        match = re.search(r"\b(\d{3,9})\b", campo_numero)
        if match:
            numero = _limpar_numero_nota(match.group(1))
            if numero:
                candidatos.append(numero)

    if not candidatos:
        return ""

    candidatos_unicos = []
    for item in candidatos:
        if item and item not in candidatos_unicos:
            candidatos_unicos.append(item)
    candidatos_unicos.sort(key=lambda value: (len(value), value), reverse=True)
    return candidatos_unicos[0]

def _extrair_secao_dados_produtos_ocr(texto):
    linhas = [_as_str(l).strip() for l in _as_str(texto).splitlines() if _as_str(l).strip()]
    if not linhas:
        return []

    inicio = -1
    for idx, linha in enumerate(linhas):
        up = linha.upper()
        if "DADOS DOS PRODUTOS" in up or "DADOS DOS SERV" in up:
            inicio = idx
            break
    if inicio < 0:
        return []

    fim = len(linhas)
    marcadores_fim = (
        "CALCULO DO IMPOSTO",
        "CÁLCULO DO IMPOSTO",
        "DADOS ADICIONAIS",
        "RESERVADO AO FISCO",
        "TRANSPORTADOR",
        "FATURA",
        "TOTAL DA NOTA",
    )
    for idx in range(inicio + 1, len(linhas)):
        up = linhas[idx].upper()
        if any(marker in up for marker in marcadores_fim):
            fim = idx
            break

    return linhas[inicio + 1:fim]

def _linha_parece_cabecalho_secao_produtos_ocr(linha):
    up = _as_str(linha).upper().strip()
    if not up:
        return True
    marcadores = (
        "COD", "CÓD", "DESCR", "NCM", "SH", "CST", "CFOP", "UN",
        "QTD", "QTDE", "QUANT", "V.UNIT", "V. UNIT", "VALOR UNIT",
        "V.TOTAL", "V. TOTAL", "VALOR TOTAL", "BC ICMS", "ICMS", "IPI", "ALIQ",
    )
    hits = sum(1 for marcador in marcadores if marcador in up)
    if hits >= 3 and not _detectar_combustivel_tipo_item(up):
        return True
    return False

def _tokens_numericos_linha_ocr(texto):
    tokens = []
    for match in re.finditer(r"\d+(?:[.,]\d+)?", _as_str(texto)):
        bruto = match.group(0)
        valor = _as_float_br(bruto, None)
        if valor is None or valor <= 0:
            continue
        tokens.append({
            "raw": bruto,
            "value": valor,
            "start": match.start(),
            "end": match.end(),
            "decimal": ("," in bruto or "." in bruto),
        })
    return tokens

def _extrair_qtd_total_bloco_produto_ocr(bloco_texto):
    tokens = _tokens_numericos_linha_ocr(bloco_texto)
    if len(tokens) < 2:
        return {}

    melhor = None
    melhor_score = float("-inf")

    for idx_total, token_total in enumerate(tokens):
        total = token_total["value"]
        if total <= 0 or total > 100000:
            continue

        for idx_qtd in range(0, idx_total):
            token_qtd = tokens[idx_qtd]
            qtd = token_qtd["value"]
            if qtd <= 0 or qtd > 5000 or qtd >= total:
                continue
            if idx_total - idx_qtd > 4:
                continue

            ratio = total / max(qtd, 1.0)
            if ratio <= 0 or ratio > 25:
                continue

            score = 0.0
            score += 0.9 if token_qtd["decimal"] else -0.5
            score += 0.4 if token_total["decimal"] else -0.2
            if idx_total == len(tokens) - 1:
                score += 0.6
            if idx_qtd >= max(0, idx_total - 3):
                score += 0.3
            if qtd >= 5:
                score += 0.2

            valor_unitario = None
            melhor_diff = None
            for idx_unit in range(idx_qtd + 1, idx_total):
                unit = tokens[idx_unit]["value"]
                if unit <= 0 or unit > 25:
                    continue
                esperado = qtd * unit
                if esperado <= 0:
                    continue
                diff = abs(esperado - total) / max(total, esperado, 1.0)
                if diff > 0.12:
                    continue
                if melhor_diff is None or diff < melhor_diff:
                    melhor_diff = diff
                    valor_unitario = unit
            if melhor_diff is not None:
                score += 1.4 - melhor_diff
            elif idx_total - idx_qtd > 2:
                continue
            else:
                score -= 0.2

            if score > melhor_score:
                melhor = {
                    "quantidade_litros": round(qtd, 3),
                    "valor": round(total, 2),
                    "valor_unitario": round(valor_unitario, 3) if valor_unitario is not None else round(ratio, 3),
                }
                melhor_score = score

    return melhor or {}

def _extrair_resumo_nota_amarela_ocr(linhas, combustivel_tipo=""):
    tipo_forcado = _as_str(combustivel_tipo).strip()
    tipo_forcado = _validar_combustivel_tipo(tipo_forcado) if tipo_forcado else ""
    candidatos = []

    for idx, linha_total in enumerate(linhas or []):
        up_total = _as_str(linha_total).upper()
        if "TOTAL R$" not in up_total and "TOTALRS" not in re.sub(r"\s+", "", up_total):
            continue

        valor, _valor_label = _normalizar_valor_brasileiro(linha_total)
        if valor is None:
            continue

        inicio = max(0, idx - 3)
        for pos in range(inicio, idx):
            linha_item = _as_str(linhas[pos]).strip()
            up_item = linha_item.upper()
            tipo_item = _detectar_combustivel_tipo_item(up_item)
            if tipo_forcado and tipo_item and tipo_item != tipo_forcado:
                continue
            if not tipo_item and not tipo_forcado:
                continue

            qtd = None
            match_lt = re.search(r"\b(?:LT|LTS|LITROS?)\s*[:\-]?\s*(\d[\d.,]*)", linha_item, re.I)
            if match_lt:
                qtd = _as_float_br(match_lt.group(1), None)
            if qtd in (None, "", 0, 0.0):
                match_lt = re.search(r"(\d[\d.,]*)\s*(?:LT|LTS|LITROS?)\b", linha_item, re.I)
                if match_lt:
                    qtd = _as_float_br(match_lt.group(1), None)
            if qtd in (None, "", 0, 0.0):
                continue

            tipo_final = tipo_item or tipo_forcado or ""
            score = 2.0
            if tipo_item:
                score += 0.3
            if "LT" in up_item or "LTS" in up_item or "LITRO" in up_item:
                score += 0.2
            if pos == idx - 1:
                score += 0.2
            candidatos.append((
                score,
                {
                    "combustivel_tipo": tipo_final,
                    "quantidade_litros": round(_as_float(qtd, 0.0), 3),
                    "valor": round(_as_float(valor, 0.0), 2),
                    "valor_unitario": round(_as_float(valor, 0.0) / max(_as_float(qtd, 1.0), 1.0), 3),
                }
            ))

    if not candidatos:
        return {}

    candidatos.sort(key=lambda item: item[0], reverse=True)
    return candidatos[0][1]

def _extrair_resumo_combustivel_secao_ocr(texto, combustivel_tipo=""):
    linhas = _extrair_secao_dados_produtos_ocr(texto)
    if not linhas:
        linhas = [_as_str(l).strip() for l in _as_str(texto).splitlines() if _as_str(l).strip()]
    if not linhas:
        return {}

    tipo_forcado = _as_str(combustivel_tipo).strip()
    tipo_forcado = _validar_combustivel_tipo(tipo_forcado) if tipo_forcado else ""
    header_idx = -1
    for idx, linha in enumerate(linhas):
        up = _as_str(linha).upper()
        if any(token in up for token in ("QTD", "QTDE", "QUANT")) and any(token in up for token in ("V.TOTAL", "V. TOTAL", "VALOR TOTAL")):
            header_idx = idx
            break

    linhas_analise = linhas[header_idx + 1:] if header_idx >= 0 else linhas
    candidatos = []
    amarelo = _extrair_resumo_nota_amarela_ocr(linhas_analise, combustivel_tipo=tipo_forcado)
    if amarelo:
        candidatos.append((2.4, amarelo))

    for idx, linha in enumerate(linhas_analise):
        if _linha_parece_cabecalho_secao_produtos_ocr(linha):
            continue

        bloco_linhas = []
        for pos in range(idx, min(idx + 2, len(linhas_analise))):
            atual = linhas_analise[pos]
            if _linha_parece_cabecalho_secao_produtos_ocr(atual):
                continue
            bloco_linhas.append(atual)
        bloco = " ".join(bloco_linhas).strip()
        if not bloco:
            continue

        extraido = _extrair_qtd_total_bloco_produto_ocr(bloco)
        if extraido:
            score = 1.0
            if header_idx >= 0 and idx <= 2:
                score += 0.4
            if any(ch.isalpha() for ch in bloco):
                score += 0.1
            candidatos.append((
                score,
                {
                    "combustivel_tipo": tipo_forcado or "",
                    "quantidade_litros": extraido.get("quantidade_litros"),
                    "valor": extraido.get("valor"),
                    "valor_unitario": extraido.get("valor_unitario"),
                }
            ))

    if not candidatos:
        bloco_total = " ".join(
            _as_str(linha).strip()
            for linha in linhas_analise
            if not _linha_parece_cabecalho_secao_produtos_ocr(linha)
        ).strip()
        extraido = _extrair_qtd_total_bloco_produto_ocr(bloco_total)
        if extraido:
            candidatos.append((
                0.4,
                {
                    "combustivel_tipo": tipo_forcado or "",
                    "quantidade_litros": extraido.get("quantidade_litros"),
                    "valor": extraido.get("valor"),
                    "valor_unitario": extraido.get("valor_unitario"),
                }
            ))

    if not candidatos:
        return {}

    candidatos.sort(key=lambda item: item[0], reverse=True)
    return candidatos[0][1]

def _selecionar_resumo_combustivel_ocr_textos(textos, combustivel_tipo=""):
    grupos = {}

    for idx, texto in enumerate(textos or []):
        resumo = _extrair_resumo_combustivel_secao_ocr(texto, combustivel_tipo=combustivel_tipo)
        qtd = resumo.get("quantidade_litros")
        valor = resumo.get("valor")
        if qtd in (None, "", 0, 0.0) or valor in (None, "", 0, 0.0):
            continue

        combustivel = _as_str(resumo.get("combustivel_tipo")).strip()
        chave = (
            combustivel,
            round(_as_float(qtd, 0.0), 3),
            round(_as_float(valor, 0.0), 2),
        )
        entry = grupos.get(chave)
        if entry is None:
            entry = {
                "count": 0,
                "first_idx": idx,
                "summary": dict(resumo),
            }
            grupos[chave] = entry
        entry["count"] += 1
        if not entry["summary"].get("valor_unitario") and resumo.get("valor_unitario"):
            entry["summary"] = dict(resumo)

    if not grupos:
        return {}, []

    ranked = sorted(
        grupos.values(),
        key=lambda item: (
            -item["count"],
            item["first_idx"],
            -_as_float(item["summary"].get("quantidade_litros"), 0.0),
            -_as_float(item["summary"].get("valor"), 0.0),
        ),
    )
    escolhido = dict(ranked[0]["summary"])
    escolhido["itens_encontrados"] = ranked[0]["count"]
    variantes = [
        {
            "combustivel_tipo": _as_str(item["summary"].get("combustivel_tipo")),
            "quantidade_litros": round(_as_float(item["summary"].get("quantidade_litros"), 0.0), 3),
            "valor": round(_as_float(item["summary"].get("valor"), 0.0), 2),
            "ocorrencias": item["count"],
        }
        for item in ranked
    ]
    return escolhido, variantes

def _extrair_dados_ocr_nfe(texto, arquivo_origem=""):
    texto = _as_str(texto)
    linhas = [_as_str(l).strip() for l in texto.splitlines() if _as_str(l).strip()]
    texto_upper = texto.upper()
    digits_all = re.sub(r"\D", "", texto)

    chave_acesso = ""
    match = re.search(r"CHAVE\s+DE\s+ACESSO(.{0,120})", texto_upper, re.S)
    if match:
        candidato = re.sub(r"\D", "", match.group(1))
        if len(candidato) >= 44:
            chave_acesso = candidato[:44]
    if len(chave_acesso) != 44:
        sequencias = re.findall(r"\d{44}", digits_all)
        if sequencias:
            chave_acesso = sequencias[0]

    numero_nota = ""
    serie = ""
    data_emissao = ""
    emitente_nome = ""
    destinatario_nome = ""
    emitente_cnpj = ""
    destinatario_cnpj = ""
    valor_total = None
    valor_total_label = ""

    for linha in linhas[:40]:
        up = linha.upper()
        if not serie and "SERIE" in up:
            match = re.search(r"SERIE\s*[:\-]?\s*([A-Z0-9.-]+)", linha, re.I)
            if match:
                serie = _as_str(match.group(1))
        if not data_emissao and any(rotulo in up for rotulo in ("EMISSAO", "DATA", "DT.")):
            match = re.search(r"(\d{2}/\d{2}/\d{4})", linha)
            if match:
                data_emissao = _normalizar_data_documento(match.group(1))
        if valor_total is None and any(rotulo in up for rotulo in ("VALOR TOTAL", "TOTAL DA NOTA", "VALOR A PAGAR")):
            valor_total, valor_total_label = _normalizar_valor_brasileiro(linha)

    if not data_emissao:
        match = re.search(r"\b(\d{2}/\d{2}/\d{4})\b", texto)
        if match:
            data_emissao = _normalizar_data_documento(match.group(1))

    cnpjs = re.findall(r"\d{2}\.?\d{3}\.?\d{3}/\d{4}-?\d{2}", texto)
    if cnpjs:
        emitente_cnpj = cnpjs[0]
    if len(cnpjs) >= 2:
        destinatario_cnpj = cnpjs[1]

    emitente_nome = _primeira_linha_com_rotulo(linhas, ["EMITENTE", "EMISSOR", "RAZAO SOCIAL"])
    destinatario_nome = _primeira_linha_com_rotulo(linhas, ["DESTINATARIO", "DESTINATARIO/REMETENTE", "REMETENTE"])

    if not emitente_nome:
        for linha in linhas[:12]:
            up = linha.upper()
            if re.search(r"[A-Z]", up) and not any(
                termo in up
                for termo in (
                    "DANFE",
                    "NOTA FISCAL",
                    "CHAVE DE ACESSO",
                    "CONTROLE DO FISCO",
                    "DOCUMENTO AUXILIAR",
                )
            ):
                emitente_nome = linha
                break

    if valor_total is None:
        for linha in reversed(linhas[-20:]):
            valor_total, valor_total_label = _normalizar_valor_brasileiro(linha)
            if valor_total is not None:
                break

    if not numero_nota:
        numero_nota = _extrair_numero_nota_ocr(linhas, texto)

    warnings = [
        "Leitura por OCR em modo assistido. Revise os campos antes de usar a chave ou concluir o lancamento."
    ]
    if len(chave_acesso) != 44:
        warnings.append("A chave de acesso nao foi localizada por completo na foto.")

    return {
        "source_type": "ocr",
        "arquivo_origem": arquivo_origem,
        "texto_bruto": texto,
        "chave_acesso": chave_acesso if len(chave_acesso) == 44 else "",
        "numero_nota": numero_nota,
        "serie": serie,
        "data_emissao": data_emissao,
        "emitente_nome": emitente_nome,
        "emitente_cnpj": emitente_cnpj,
        "destinatario_nome": destinatario_nome,
        "destinatario_cnpj": destinatario_cnpj,
        "valor_total": valor_total,
        "valor_total_label": valor_total_label,
        "warnings": warnings,
    }

def _preparar_candidatos_ocr_imagem(image):
    from PIL import Image, ImageOps

    base = ImageOps.exif_transpose(image).convert("RGB")
    max_lado = 1800
    if max(base.size) > max_lado:
        fator = max_lado / float(max(base.size) or 1)
        novo_tamanho = (
            max(1, int(base.width * fator)),
            max(1, int(base.height * fator)),
        )
        base = base.resize(novo_tamanho, Image.Resampling.LANCZOS)

    candidates = [base]
    cinza = ImageOps.grayscale(base)
    candidates.append(cinza)
    candidates.append(ImageOps.autocontrast(cinza))
    return candidates

def _coletar_textos_ocr_imagem(candidates, pytesseract):
    tentativas = []
    if candidates:
        tentativas.append((candidates[0], "por+eng", "--psm 6"))
    if len(candidates) >= 2:
        tentativas.append((candidates[1], "por+eng", "--psm 6"))
    if len(candidates) >= 3:
        tentativas.append((candidates[2], "por+eng", "--psm 11"))
    tentativas.append((candidates[-1], "eng", "--psm 6"))

    textos = []
    for img, lang, config in tentativas:
        try:
            texto = _as_str(pytesseract.image_to_string(img, lang=lang, config=config, timeout=20))
        except Exception:
            texto = ""
        if texto and texto not in textos:
            textos.append(texto)
    return textos

def _selecionar_melhor_dados_ocr_nfe_textos(textos, arquivo_origem=""):
    melhor = None
    melhor_score = -1

    for texto in textos or []:
        extraido = _extrair_dados_ocr_nfe(texto, arquivo_origem=arquivo_origem)
        score = 0
        if extraido.get("chave_acesso"):
            score += 10
        if extraido.get("numero_nota"):
            score += 2
        if extraido.get("emitente_nome"):
            score += 2
        if extraido.get("valor_total") is not None:
            score += 1
        if score > melhor_score:
            melhor = extraido
            melhor_score = score
        if extraido.get("chave_acesso"):
            return extraido

    if not melhor and textos:
        melhor = _extrair_dados_ocr_nfe("\n".join(textos), arquivo_origem=arquivo_origem)
    if not melhor:
        raise ValueError("nenhum texto foi identificado na foto da nota")
    return melhor

def _coletar_textos_ocr_itens_imagem(candidates, pytesseract):
    base = candidates[-1] if len(candidates) >= 3 else (candidates[1] if len(candidates) >= 2 else candidates[0])
    tentativas = [
        (base, "eng", "--oem 1 --psm 6 -c preserve_interword_spaces=1"),
        (base, "por+eng", "--oem 1 --psm 6 -c preserve_interword_spaces=1"),
    ]
    textos = []
    for img, lang, config in tentativas:
        try:
            texto = _as_str(pytesseract.image_to_string(img, lang=lang, config=config, timeout=8))
        except Exception:
            texto = ""
        if texto and texto not in textos:
            textos.append(texto)
        if texto and len(texto) > 80:
            break
    return textos

def _extrair_url_payload_barcode(raw):
    texto = unquote(_as_str(raw)).strip()
    if not texto:
        return ""
    match = re.search(r"https?://[^\s<>'\"]+", texto, re.I)
    if not match:
        return ""
    candidato = match.group(0).strip().rstrip(").,;")
    parsed = urlparse(candidato)
    if parsed.scheme not in ("http", "https") or not parsed.netloc:
        return ""
    return candidato

def _montar_url_consulta_nfe(base_url, chave_acesso=""):
    raw = _as_str(base_url).strip() or _nfe_consulta_url_default()
    chave = _normalizar_chave_acesso_nfe(chave_acesso)
    if len(chave) != 44:
        return raw
    try:
        separador = "&" if "?" in raw else "?"
        if re.search(r"([?&])nfe=", raw, re.I):
            return re.sub(r"([?&])nfe=[^&]*", rf"\1nfe={chave}", raw, flags=re.I)
        return f"{raw}{separador}nfe={chave}"
    except Exception:
        return raw

def _detectar_payload_barcode_imagem_bytes(image_bytes):
    BytesIO, Image, _pytesseract = _carregar_dependencias_ocr()
    try:
        from pyzbar.pyzbar import decode as zbar_decode
    except Exception:
        return {"raw": "", "url": "", "chave_acesso": ""}

    try:
        image = Image.open(BytesIO(image_bytes))
        image.load()
    except Exception:
        return {"raw": "", "url": "", "chave_acesso": ""}

    try:
        candidates = _preparar_candidatos_ocr_imagem(image)
    except Exception:
        candidates = [image]

    for candidate in candidates:
        try:
            resultados = zbar_decode(candidate)
        except Exception:
            resultados = []
        for resultado in resultados or []:
            raw = resultado.data.decode("utf-8", errors="ignore") if getattr(resultado, "data", None) else ""
            url = _extrair_url_payload_barcode(raw)
            digits = _normalizar_chave_acesso_nfe(raw)
            if url or len(digits) == 44:
                return {
                    "raw": raw,
                    "url": url,
                    "chave_acesso": digits if len(digits) == 44 else "",
                }
    return {"raw": "", "url": "", "chave_acesso": ""}

def _curl_fetch_html_text(url, timeout=30):
    url = _as_str(url).strip()
    if not url:
        raise ValueError("URL de consulta vazia para o scraping do codigo de barras.")
    try:
        proc = subprocess.run(
            [
                "curl",
                "-fsSL",
                "--compressed",
                "--max-time",
                str(int(timeout)),
                "--connect-timeout",
                "10",
                "-A",
                "Mozilla/5.0 (X11; Linux x86_64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/124.0 Safari/537.36",
                "-H",
                "Accept-Language: pt-BR,pt;q=0.9",
                url,
            ],
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
            text=True,
        )
    except FileNotFoundError as exc:
        raise RuntimeError("curl nao esta instalado neste ambiente.") from exc

    if proc.returncode != 0:
        detalhe = _as_str(proc.stderr).strip() or f"codigo {proc.returncode}"
        raise RuntimeError(f"curl nao conseguiu consultar a URL do codigo de barras: {detalhe}")

    html_text = _as_str(proc.stdout)
    if not html_text.strip():
        raise RuntimeError("curl retornou uma pagina vazia para a URL do codigo de barras.")
    return html_text

def _extrair_itens_html_generico(html_text):
    parser = _HtmlTableCollector()
    try:
        parser.feed(_as_str(html_text))
    except Exception:
        pass

    itens = []
    for tabela in parser.tables or []:
        rows = tabela.get("rows") or []
        if len(rows) < 2:
            continue

        headers = [re.sub(r"\s+", " ", _as_str(col)).strip() for col in rows[0]]
        idx_descricao = _portal_find_col(headers, ["descricao", "descrição", "produto", "xprod", "item"])
        idx_unidade = _portal_find_col(headers, ["unidade", "un", "und", "ucom"])
        idx_quantidade = _portal_find_col(headers, ["quantidade", "qtd", "qtde", "qcom"])
        idx_vunit = _portal_find_col(headers, ["valor unitario", "valor unitário", "vl unit", "vuncom"])
        idx_vtotal = _portal_find_col(headers, ["valor total", "v.total", "v total", "vprod", "valor produto"])
        if idx_quantidade < 0 or idx_vtotal < 0:
            continue

        for row in rows[1:]:
            cols = [_as_str(col).strip() for col in row]
            if not any(cols):
                continue
            descricao = cols[idx_descricao] if 0 <= idx_descricao < len(cols) else ""
            quantidade_raw = cols[idx_quantidade] if 0 <= idx_quantidade < len(cols) else ""
            valor_total_raw = cols[idx_vtotal] if 0 <= idx_vtotal < len(cols) else ""
            valor_unitario_raw = cols[idx_vunit] if 0 <= idx_vunit < len(cols) else ""
            quantidade = _as_float_br(quantidade_raw, _as_float(quantidade_raw, 0.0))
            valor_total = _as_float_br(valor_total_raw, _as_float(valor_total_raw, 0.0))
            valor_unitario = _as_float_br(valor_unitario_raw, _as_float(valor_unitario_raw, 0.0))
            if quantidade <= 0 or valor_total <= 0:
                continue
            itens.append({
                "item_seq": str(len(itens) + 1),
                "codigo_produto_nfe": "",
                "codigo_barras": "",
                "nome_produto": descricao,
                "unidade": cols[idx_unidade] if 0 <= idx_unidade < len(cols) else "",
                "quantidade": quantidade,
                "valor_unitario": valor_unitario,
                "valor_total": valor_total,
            })

    return itens

def _scrape_resumo_abastecimento_html(html_text, chave_acesso="", combustivel_tipo=""):
    itens = _extrair_itens_html_generico(html_text)
    if itens:
        resumo = _resumir_nfe_para_abastecimento({
            "itens": itens,
            "chave_acesso": chave_acesso,
        }, combustivel_tipo=combustivel_tipo)
        resumo["source_type"] = "barcode_scrape"
        return resumo

    texto = "\n".join(_html_linhas_limpa(html_text))
    extraido = _extrair_resumo_combustivel_secao_ocr(texto, combustivel_tipo=combustivel_tipo)
    if extraido.get("quantidade_litros") in (None, "", 0, 0.0) or extraido.get("valor") in (None, "", 0, 0.0):
        raise ValueError("Nao foi possivel localizar Quantidade e V.Total na pagina retornada pelo codigo de barras.")

    return {
        "source_type": "barcode_scrape",
        "combustivel_tipo": _normalizar_combustivel_tipo(extraido.get("combustivel_tipo") or combustivel_tipo),
        "quantidade_litros": _as_float(extraido.get("quantidade_litros"), 0.0),
        "valor": _as_float(extraido.get("valor"), 0.0),
        "chave_acesso_nfe": _normalizar_chave_acesso_nfe(chave_acesso),
        "emitente_nome": "",
        "numero_nota": "",
        "itens_encontrados": max(1, _as_int(extraido.get("itens_encontrados"), 0)),
    }

def _resumo_abastecimento_por_url_barcode(url, chave_acesso="", combustivel_tipo=""):
    html_text = _curl_fetch_html_text(url)
    return _scrape_resumo_abastecimento_html(
        html_text,
        chave_acesso=chave_acesso,
        combustivel_tipo=combustivel_tipo,
    )

def _barcode_preview_abastecimento_imagem_bytes(image_bytes, arquivo_origem="", combustivel_tipo=""):
    tipo_forcado = _as_str(combustivel_tipo).strip()
    tipo_forcado = _validar_combustivel_tipo(tipo_forcado) if tipo_forcado else ""
    payload_barcode = _detectar_payload_barcode_imagem_bytes(image_bytes)
    chave_barcode = _normalizar_chave_acesso_nfe(payload_barcode.get("chave_acesso"))
    if len(chave_barcode) != 44:
        raise ValueError("Nao foi possivel localizar uma chave NF-e valida no codigo de barras/QR da imagem.")

    meta = _nfe_resumo_chave_acesso(chave_barcode)
    warnings = ["Chave NF-e lida da imagem de codigo de barras/QR."]
    resumo = {
        "source_type": "barcode_scrape",
        "arquivo_origem": arquivo_origem,
        "texto_bruto": "",
        "chave_acesso_nfe": chave_barcode,
        "chave_acesso": chave_barcode,
        "numero_nota": _as_str(meta.get("numero_nota")),
        "serie": _as_str(meta.get("serie")),
        "data_emissao": "",
        "emitente_nome": "",
        "emitente_cnpj": _as_str(meta.get("emitente_cnpj")),
        "combustivel_tipo": tipo_forcado,
        "valor": None,
        "valor_total": None,
        "valor_total_label": "",
        "quantidade_litros": None,
        "itens_encontrados": 0,
        "warnings": warnings,
    }

    url_barcode = _as_str(payload_barcode.get("url")).strip()
    if not url_barcode:
        cfg = _carregar_nfe_config()
        url_barcode = _montar_url_consulta_nfe(
            _as_str(cfg.get("consulta_url")) or _nfe_consulta_url_default(),
            chave_barcode,
        )
        warnings.append("O codigo nao trouxe URL no payload. O sistema montou a URL de consulta a partir da chave lida.")

    try:
        resumo_scrape = _resumo_abastecimento_por_url_barcode(
            url_barcode,
            chave_acesso=chave_barcode,
            combustivel_tipo=tipo_forcado,
        )
        resumo.update({
            "numero_nota": _as_str(resumo_scrape.get("numero_nota")) or resumo["numero_nota"],
            "emitente_nome": _as_str(resumo_scrape.get("emitente_nome")) or resumo["emitente_nome"],
            "combustivel_tipo": _normalizar_combustivel_tipo(resumo_scrape.get("combustivel_tipo") or resumo.get("combustivel_tipo")),
            "valor": _as_float(resumo_scrape.get("valor"), 0.0) if resumo_scrape.get("valor") not in (None, "") else None,
            "valor_total": _as_float(resumo_scrape.get("valor"), 0.0) if resumo_scrape.get("valor") not in (None, "") else None,
            "quantidade_litros": _as_float(resumo_scrape.get("quantidade_litros"), 0.0) if resumo_scrape.get("quantidade_litros") not in (None, "") else None,
            "itens_encontrados": _as_int(resumo_scrape.get("itens_encontrados"), 0),
        })
        if resumo.get("quantidade_litros") not in (None, "", 0, 0.0) and resumo.get("valor") not in (None, "", 0, 0.0):
            warnings.append("Quantidade e V.Total foram extraidos por scraping da pagina retornada pelo QR code.")
    except Exception as exc:
        warnings.append(f"A chave foi lida, mas o scraping via curl nao concluiu ({_as_str(exc)}). Use Foto OCR se precisar de Quantidade e V.Total.")

    resumo["warnings"] = warnings
    return resumo

def _carregar_dependencias_ocr():
    try:
        from io import BytesIO
        from PIL import Image
        import pytesseract
    except Exception as exc:
        raise RuntimeError(
            "OCR de notas indisponivel nesta instalacao. Recrie o app com Pillow, pytesseract e tesseract-ocr."
        ) from exc
    return BytesIO, Image, pytesseract

def _get_rapidocr_engine():
    global _rapidocr_engine
    if _rapidocr_engine is not None:
        return _rapidocr_engine
    with _rapidocr_lock:
        if _rapidocr_engine is not None:
            return _rapidocr_engine
        try:
            from rapidocr import RapidOCR
        except Exception as exc:
            raise RuntimeError("RapidOCR indisponivel nesta instalacao.") from exc
        _rapidocr_engine = RapidOCR()
        return _rapidocr_engine

def _ocr_nfe_imagem_bytes(image_bytes, arquivo_origem=""):
    BytesIO, Image, pytesseract = _carregar_dependencias_ocr()

    try:
        image = Image.open(BytesIO(image_bytes))
        image.load()
    except Exception as exc:
        raise ValueError("nao foi possivel abrir a imagem enviada") from exc

    try:
        candidates = _preparar_candidatos_ocr_imagem(image)
    except Exception:
        candidates = [image]

    textos = _coletar_textos_ocr_imagem(candidates, pytesseract)
    return _selecionar_melhor_dados_ocr_nfe_textos(textos, arquivo_origem=arquivo_origem)

def _ocr_itens_nfe_imagem_bytes(image_bytes, arquivo_origem=""):
    BytesIO, Image, pytesseract = _carregar_dependencias_ocr()

    try:
        image = Image.open(BytesIO(image_bytes))
        image.load()
    except Exception as exc:
        raise ValueError("nao foi possivel abrir a imagem enviada") from exc

    try:
        candidates = _preparar_candidatos_ocr_imagem(image)
    except Exception:
        candidates = [image]

    melhor_itens = []

    try:
        import numpy as np
        rapid_engine = _get_rapidocr_engine()
        base_img = candidates[-1] if len(candidates) >= 3 else candidates[0]
        rapid_result = rapid_engine(np.array(base_img), use_cls=False)
        rapid_txts = []
        if rapid_result is not None:
            txts = getattr(rapid_result, "txts", None)
            if txts:
                rapid_txts = [_as_str(txt).strip() for txt in txts if _as_str(txt).strip()]
        if rapid_txts:
            itens_rapid = _extrair_itens_ocr_linhas(rapid_txts)
            if itens_rapid:
                return _normalizar_preview_nfe({
                    "source_type": "ocr",
                    "arquivo_origem": arquivo_origem,
                    "itens": itens_rapid,
                    "warnings": [
                        "OCR dos itens executado com RapidOCR. Revise codigo, descricao, quantidade e valor antes de confirmar a importacao.",
                        "Para melhor resultado, fotografe apenas a grade dos produtos.",
                    ],
                })
    except Exception:
        pass

    textos = _coletar_textos_ocr_itens_imagem(candidates, pytesseract)

    for texto in textos:
        linhas = [re.sub(r"\s+", " ", _as_str(l)).strip() for l in texto.splitlines() if _as_str(l).strip()]
        itens = _extrair_itens_ocr_linhas(linhas)
        if len(itens) > len(melhor_itens):
            melhor_itens = itens
        if len(itens) >= 2:
            break

    if not melhor_itens:
        raise ValueError("nenhum item foi identificado na foto. Tente enquadrar apenas a tabela dos produtos.")

    return _normalizar_preview_nfe({
        "source_type": "ocr",
        "arquivo_origem": arquivo_origem,
        "itens": melhor_itens,
        "warnings": [
            "OCR dos itens executado em modo de contingencia. Revise codigo, descricao, quantidade e valor antes de confirmar a importacao.",
            "Para melhor resultado, fotografe apenas a grade dos produtos.",
        ],
    })

def _azure_docint_value(field):
    field = field or {}
    if not isinstance(field, dict):
        return field
    for key in ("valueString", "valueNumber", "valueInteger", "valueDate", "content"):
        if field.get(key) not in (None, ""):
            return field.get(key)
    value_currency = field.get("valueCurrency")
    if isinstance(value_currency, dict) and value_currency.get("amount") not in (None, ""):
        return value_currency.get("amount")
    return ""

def _azure_docint_nfe_itens_preview(image_bytes, arquivo_origem=""):
    cfg = _carregar_nfe_config()
    if not cfg.get("azure_docint_habilitado"):
        raise ValueError("Azure Document Intelligence nao esta habilitado em Config > NF-e.")
    endpoint = _as_str(cfg.get("azure_docint_endpoint")).rstrip("/")
    api_key = _as_str(cfg.get("azure_docint_key"))
    model_id = _as_str(cfg.get("azure_docint_model_id")) or "prebuilt-invoice"
    api_version = _as_str(cfg.get("azure_docint_api_version")) or "2024-11-30"
    if not endpoint or not api_key:
        raise ValueError("Configure endpoint e chave do Azure Document Intelligence em Config > NF-e.")

    base_url = endpoint if endpoint.endswith("/documentintelligence") else f"{endpoint}/documentintelligence"
    analyze_url = f"{base_url}/documentModels/{model_id}:analyze?api-version={api_version}"
    headers = {
        "Ocp-Apim-Subscription-Key": api_key,
        "Content-Type": "application/octet-stream",
    }
    resp = requests.post(analyze_url, headers=headers, data=image_bytes, timeout=60)
    if resp.status_code not in (200, 202):
        try:
            detalhe = resp.json()
        except Exception:
            detalhe = resp.text
        raise RuntimeError(f"Azure Document Intelligence recusou a analise: {detalhe}")

    payload = resp.json() if resp.status_code == 200 else None
    operation_location = resp.headers.get("Operation-Location") or resp.headers.get("operation-location")
    if resp.status_code == 202:
        if not operation_location:
            raise RuntimeError("Azure nao retornou Operation-Location para acompanhar a analise.")
        inicio = time.time()
        while True:
            poll = requests.get(operation_location, headers={"Ocp-Apim-Subscription-Key": api_key}, timeout=30)
            payload = poll.json()
            status = _as_str(payload.get("status")).lower()
            if status == "succeeded":
                break
            if status == "failed":
                raise RuntimeError(f"Azure nao conseguiu analisar a imagem: {payload}")
            if (time.time() - inicio) > 120:
                raise RuntimeError("Azure demorou demais para concluir a analise da imagem.")
            time.sleep(1.5)

    analyze_result = payload.get("analyzeResult") if isinstance(payload, dict) else {}
    documentos = analyze_result.get("documents") if isinstance(analyze_result, dict) else []
    itens = []
    numero_nota = ""
    emitente_nome = ""
    data_emissao = ""

    if documentos:
        doc = documentos[0] if isinstance(documentos[0], dict) else {}
        campos = doc.get("fields") if isinstance(doc.get("fields"), dict) else {}
        numero_nota = _as_str(_azure_docint_value(campos.get("InvoiceId")))
        emitente_nome = _as_str(_azure_docint_value(campos.get("VendorName")))
        data_emissao = _normalizar_data_documento(_azure_docint_value(campos.get("InvoiceDate")))
        items_field = campos.get("Items") if isinstance(campos.get("Items"), dict) else {}
        value_array = items_field.get("valueArray") if isinstance(items_field, dict) else []
        for idx, raw in enumerate(value_array or [], start=1):
            value_object = raw.get("valueObject") if isinstance(raw, dict) else {}
            codigo = _as_str(_azure_docint_value(value_object.get("ProductCode") or value_object.get("ItemCode")))
            descricao = _as_str(_azure_docint_value(value_object.get("Description")))
            quantidade = _as_float_br(_azure_docint_value(value_object.get("Quantity")), _as_float(_azure_docint_value(value_object.get("Quantity")), 0.0))
            valor_unitario = _as_float_br(_azure_docint_value(value_object.get("UnitPrice")), _as_float(_azure_docint_value(value_object.get("UnitPrice")), 0.0))
            if not descricao and not codigo:
                continue
            itens.append({
                "item_seq": str(idx),
                "codigo_produto_nfe": codigo,
                "codigo_barras": "",
                "nome_produto": descricao,
                "unidade": "",
                "quantidade": quantidade,
                "valor_unitario": valor_unitario,
            })

    if not itens:
        raise ValueError("Azure analisou a imagem, mas nao retornou itens utilizaveis. Tente outra foto ou outro modelo.")

    return _aplicar_cadastro_embalagem_preview({
        "source_type": "ocr",
        "arquivo_origem": arquivo_origem or "Azure-Document-Intelligence",
        "numero_nota": numero_nota,
        "emitente_nome": emitente_nome,
        "data_emissao": data_emissao,
        "itens": itens,
        "warnings": [
            "Itens extraidos via Azure Document Intelligence. Revise os campos antes de confirmar a importacao.",
        ],
    })


def _ocr_preview_manutencao_imagem_bytes(image_bytes, arquivo_origem=""):
    ocr = None
    warnings = []
    itens = []
    local_error = ""
    try:
        ocr = _ocr_nfe_imagem_bytes(image_bytes, arquivo_origem=arquivo_origem)
        warnings.extend(ocr.get("warnings") or [])
        try:
            itens_preview = _ocr_itens_nfe_imagem_bytes(image_bytes, arquivo_origem=arquivo_origem)
            if isinstance(itens_preview, dict):
                itens = itens_preview.get("itens") if isinstance(itens_preview.get("itens"), list) else []
                warnings.extend([msg for msg in (itens_preview.get("warnings") or []) if msg])
        except Exception:
            warnings.append("Nao foi possivel identificar os itens automaticamente nessa foto inteira. Se precisar, tire outra foto focando apenas a grade dos produtos.")
    except RuntimeError as exc:
        local_error = _as_str(exc)
    except Exception:
        raise

    if ocr is None:
        azure_error = ""
        try:
            azure_preview = _azure_docint_nfe_itens_preview(image_bytes, arquivo_origem=arquivo_origem)
            return {
                "source_type": "ocr",
                "arquivo_origem": arquivo_origem or "Azure-Document-Intelligence",
                "texto_bruto": "",
                "chave_acesso": "",
                "numero_nota": _as_str(azure_preview.get("numero_nota")),
                "serie": "",
                "data_documento": _normalizar_data_documento(azure_preview.get("data_emissao") or azure_preview.get("data_documento")),
                "emitente_nome": _as_str(azure_preview.get("emitente_nome")),
                "emitente_cnpj": "",
                "valor_total": None,
                "valor_total_label": "",
                "itens": azure_preview.get("itens") if isinstance(azure_preview.get("itens"), list) else [],
                "warnings": [
                    msg for msg in (
                        [
                            "OCR local indisponivel nesta instalacao. Usando Azure Document Intelligence como fallback para a manutencao."
                        ] + list(azure_preview.get("warnings") or [])
                    ) if _as_str(msg).strip()
                ],
            }
        except Exception as exc:
            azure_error = _as_str(exc)
        detalhes = [msg for msg in (local_error, azure_error) if msg]
        raise RuntimeError(" | ".join(detalhes) or "OCR indisponivel para manutencao nesta instalacao.")

    dedup_warnings = []
    for msg in warnings:
        text = _as_str(msg).strip()
        if text and text not in dedup_warnings:
            dedup_warnings.append(text)

    return {
        "source_type": "ocr",
        "arquivo_origem": arquivo_origem,
        "texto_bruto": _as_str(ocr.get("texto_bruto")),
        "chave_acesso": _as_str(ocr.get("chave_acesso")),
        "numero_nota": _as_str(ocr.get("numero_nota")),
        "serie": _as_str(ocr.get("serie")),
        "data_documento": _normalizar_data_documento(ocr.get("data_emissao")),
        "emitente_nome": _as_str(ocr.get("emitente_nome")),
        "emitente_cnpj": _as_str(ocr.get("emitente_cnpj")),
        "valor_total": _as_float(ocr.get("valor_total"), 0.0) if ocr.get("valor_total") not in (None, "") else None,
        "valor_total_label": _as_str(ocr.get("valor_total_label")),
        "itens": itens,
        "warnings": dedup_warnings,
    }

def _ocr_preview_abastecimento_imagem_bytes(image_bytes, arquivo_origem="", combustivel_tipo=""):
    tipo_forcado = _as_str(combustivel_tipo).strip()
    tipo_forcado = _validar_combustivel_tipo(tipo_forcado) if tipo_forcado else ""

    BytesIO, Image, pytesseract = _carregar_dependencias_ocr()
    try:
        image = Image.open(BytesIO(image_bytes))
        image.load()
    except Exception as exc:
        raise ValueError("nao foi possivel abrir a imagem enviada") from exc

    try:
        candidates = _preparar_candidatos_ocr_imagem(image)
    except Exception:
        candidates = [image]

    textos = _coletar_textos_ocr_imagem(candidates, pytesseract)
    if not textos:
        raise ValueError("nenhum texto foi identificado na foto. Envie uma foto mais proxima da secao DADOS DOS PRODUTOS.")

    warnings = []
    resumo, variantes = _selecionar_resumo_combustivel_ocr_textos(textos, combustivel_tipo=tipo_forcado)
    if resumo.get("quantidade_litros") not in (None, "", 0, 0.0) and resumo.get("valor") not in (None, "", 0, 0.0):
        warnings.append(
            "Quantidade e V.Total foram extraidos diretamente da foto da secao DADOS DOS PRODUTOS."
        )
        ocorrencias = _as_int(resumo.get("itens_encontrados"), 0)
        if ocorrencias > 1:
            warnings.append(f"Quantidade e V.Total foram confirmados em {ocorrencias} leituras da mesma imagem.")
        elif len(variantes) > 1:
            warnings.append(
                "A imagem gerou mais de uma combinacao de Quantidade e V.Total. O sistema escolheu a combinacao mais recorrente."
            )

    if resumo.get("quantidade_litros") in (None, "", 0, 0.0) or resumo.get("valor") in (None, "", 0, 0.0):
        warnings.append(
            "Nao foi localizado um par confiavel de Quantidade e V.Total na secao DADOS DOS PRODUTOS. O sistema nao vai mais preencher valores aleatorios."
        )

    dedup_warnings = []
    for msg in warnings:
        text = _as_str(msg).strip()
        if text and text not in dedup_warnings:
            dedup_warnings.append(text)

    combustivel_resumo = _as_str(resumo.get("combustivel_tipo")).strip()
    if combustivel_resumo:
        combustivel_resumo = _normalizar_combustivel_tipo(combustivel_resumo)
    elif tipo_forcado:
        combustivel_resumo = tipo_forcado

    quantidade_resumo = resumo.get("quantidade_litros")
    valor_resumo = _as_float(resumo.get("valor"), 0.0) if resumo.get("valor") not in (None, "") else None

    return {
        "source_type": "ocr",
        "arquivo_origem": arquivo_origem,
        "texto_bruto": "\n\n".join(textos),
        "chave_acesso_nfe": "",
        "chave_acesso": "",
        "numero_nota": "",
        "serie": "",
        "data_emissao": "",
        "emitente_nome": "",
        "emitente_cnpj": "",
        "combustivel_tipo": combustivel_resumo,
        "valor": valor_resumo,
        "valor_total": valor_resumo,
        "valor_total_label": "",
        "quantidade_litros": _as_float(quantidade_resumo, 0.0) if quantidade_resumo not in (None, "") else None,
        "itens_encontrados": _as_int(resumo.get("itens_encontrados"), 0),
        "warnings": dedup_warnings,
    }

def _preview_nfe_estoque_requisicao():
    payload = request.form.to_dict(flat=True) if request.form else (request.get_json(silent=True) or {})
    chave_acesso_esperada = _normalizar_chave_acesso_nfe(payload.get("chave_acesso_esperada"))
    conteudo, arquivo_origem, mimetype = _ler_arquivo_nfe_requisicao()
    if not conteudo:
        raise ValueError("envie um XML ou PDF da NF-e para importar")

    tipo_arquivo = _detectar_tipo_arquivo_nfe(conteudo, arquivo_origem=arquivo_origem, mimetype=mimetype)
    if tipo_arquivo == "xml":
        xml_text = _decode_xml_bytes(conteudo)
        preview = _preview_nfe_estoque_from_xml_text(
            xml_text,
            arquivo_origem=arquivo_origem,
            chave_acesso_esperada=chave_acesso_esperada,
        )
    elif tipo_arquivo == "html":
        html_text = _decode_xml_bytes(conteudo)
        preview = _parse_nfe_portal_html(html_text, arquivo_origem=arquivo_origem)
    elif tipo_arquivo == "pdf":
        preview = _parse_nfe_pdf_bytes(conteudo, arquivo_origem=arquivo_origem)
        chave_pdf = _normalizar_chave_acesso_nfe(preview.get("chave_acesso")) or chave_acesso_esperada
        if len(chave_pdf) == 44:
            nfe_status = _nfe_status_publico()
            if nfe_status.get("pronto_dfe"):
                try:
                    preview_dfe, resultado_dfe = _preview_nfe_estoque_por_dfe(
                        chave_pdf,
                        arquivo_origem="NFeDistribuicaoDFe",
                        warnings=[
                            "PDF usado apenas como contingencia para localizar a chave. Dados oficiais carregados do XML via DF-e."
                        ],
                    )
                    preview_dfe["arquivo_origem"] = (
                        f"{_as_str(arquivo_origem) or 'PDF'} -> NFeDistribuicaoDFe"
                    )
                    if bool(resultado_dfe.get("manifestado")):
                        preview_dfe["warnings"] = (
                            preview_dfe.get("warnings") or []
                        ) + ["XML liberado apos manifestacao automatica de ciencia da operacao."]
                    preview = _normalizar_preview_nfe(preview_dfe)
                except (RuntimeError, ValueError) as exc:
                    preview["warnings"] = (preview.get("warnings") or []) + [
                        f"Falha ao buscar o XML oficial pela chave do PDF: {str(exc)}. Mantido o PDF como contingencia."
                    ]
            else:
                preview["warnings"] = (preview.get("warnings") or []) + [
                    "A chave foi localizada no PDF, mas o DF-e nao esta pronto nesta configuracao. Mantido o PDF como contingencia."
                ]
    else:
        raise ValueError("formato nao suportado. Envie um XML ou PDF da NF-e.")

    chave_preview = _normalizar_chave_acesso_nfe(preview.get("chave_acesso"))
    if tipo_arquivo != "xml" and chave_acesso_esperada:
        if chave_preview and chave_preview != chave_acesso_esperada:
            raise ValueError("a chave bipada nao confere com o arquivo da NF-e informado")
        if not chave_preview:
            preview["chave_acesso"] = chave_acesso_esperada
            preview["warnings"] = (preview.get("warnings") or []) + [
                "A chave bipada foi aplicada ao rascunho porque o arquivo nao trouxe a chave automaticamente."
            ]
    return _aplicar_cadastro_embalagem_preview(preview)

def _persistir_preview_nfe_estoque(preview):
    nfe = _normalizar_preview_nfe(preview)
    chave_xml = _normalizar_chave_acesso_nfe(nfe.get("chave_acesso"))
    if chave_xml and len(chave_xml) != 44:
        raise ValueError("a chave de acesso da NF-e precisa ter 44 digitos ou ficar vazia")

    itens_validos = []
    for idx, item in enumerate(nfe.get("itens") or [], start=1):
        if not (
            _as_str(item.get("nome_produto"))
            or _as_str(item.get("codigo_produto_nfe"))
            or _as_str(item.get("codigo_barras"))
        ):
            continue
        quantidade = _as_float(item.get("quantidade"), 0.0)
        if quantidade <= 0:
            raise ValueError(f"o item {idx} precisa ter quantidade maior que zero")
        item_norm = _normalizar_item_preview_nfe(item, idx)
        if not _as_str(item_norm.get("nome_produto")):
            item_norm["nome_produto"] = _as_str(item_norm.get("codigo_produto_nfe")) or _as_str(item_norm.get("codigo_barras")) or f"Item {idx}"
        itens_validos.append(item_norm)

    if not itens_validos:
        raise ValueError("a NF-e precisa ter pelo menos um item valido para importar")

    conn = get_conn()
    cur = conn.cursor(dictionary=True)
    try:
        try:
            _validar_nota_duplicada_estoque(
                cur,
                numero_nota=_as_str(nfe.get("numero_nota")),
                chave_acesso_nfe=chave_xml,
                emitente_nome=_as_str(nfe.get("emitente_nome")),
            )
        except ValueError as exc:
            raise ValueError(str(exc)) from exc

        conferencia_existente = None
        if chave_xml:
            cur.execute("SELECT id, status FROM estoque_conferencias WHERE chave_acesso=%s ORDER BY id DESC LIMIT 1", (chave_xml,))
            conferencia_existente = cur.fetchone()
            if conferencia_existente and _as_str(conferencia_existente.get("status")) == "consolidado":
                raise ValueError("esta NF-e ja foi consolidada no estoque")

        if conferencia_existente:
            conferencia_id = _as_int(conferencia_existente.get("id"), 0)
            cur.execute("""
                UPDATE estoque_conferencias
                SET
                    numero_nota=%s,
                    chave_acesso=%s,
                    serie=%s,
                    emitente_nome=%s,
                    emitente_cnpj=%s,
                    destinatario_nome=%s,
                    destinatario_cnpj=%s,
                    data_emissao=%s,
                    status='pendente',
                    arquivo_origem=%s,
                    confirmado_em=NULL,
                    recebido_por=''
                WHERE id=%s
            """, (
                _as_str(nfe.get("numero_nota")),
                chave_xml,
                _as_str(nfe.get("serie")),
                _as_str(nfe.get("emitente_nome")),
                _as_str(nfe.get("emitente_cnpj")),
                _as_str(nfe.get("destinatario_nome")),
                _as_str(nfe.get("destinatario_cnpj")),
                _as_str(nfe.get("data_emissao")),
                _as_str(nfe.get("arquivo_origem")),
                conferencia_id,
            ))
            cur.execute("DELETE FROM estoque_conferencia_itens WHERE conferencia_id=%s", (conferencia_id,))
        else:
            cur.execute("""
                INSERT INTO estoque_conferencias
                    (
                        numero_nota, chave_acesso, serie, emitente_nome, emitente_cnpj,
                        destinatario_nome, destinatario_cnpj, data_emissao, status, arquivo_origem
                    )
                VALUES
                    (%s, %s, %s, %s, %s, %s, %s, %s, 'pendente', %s)
            """, (
                _as_str(nfe.get("numero_nota")),
                chave_xml,
                _as_str(nfe.get("serie")),
                _as_str(nfe.get("emitente_nome")),
                _as_str(nfe.get("emitente_cnpj")),
                _as_str(nfe.get("destinatario_nome")),
                _as_str(nfe.get("destinatario_cnpj")),
                _as_str(nfe.get("data_emissao")),
                _as_str(nfe.get("arquivo_origem")),
            ))
            conferencia_id = cur.lastrowid

        produtos_criados = 0
        source_type = _as_str(nfe.get("source_type")).lower()
        origem_cadastro = "nfe_pdf" if source_type == "pdf" else ("nfe_portal" if source_type == "portal" else "nfe_xml")
        for item in itens_validos:
            produto, criado = _obter_ou_criar_produto_estoque(
                cur,
                codigo_barras=item.get("codigo_barras"),
                codigo_produto_nfe=item.get("codigo_produto_nfe"),
                nome_produto=item.get("nome_produto"),
                unidade=item.get("unidade"),
                origem_cadastro=origem_cadastro,
            )
            if criado:
                produtos_criados += 1
            cur.execute("""
                INSERT INTO estoque_conferencia_itens
                    (
                        conferencia_id, item_seq, produto_id, codigo_produto_nfe, codigo_barras,
                        nome_produto, unidade, embalagem_tipo, quantidade_embalagem, fator_embalagem, fator_inferido,
                        quantidade_nfe, quantidade_conferida, valor_unitario
                    )
                VALUES
                    (%s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s)
            """, (
                conferencia_id,
                _as_str(item.get("item_seq")),
                _as_int(produto.get("id"), 0) or None,
                _as_str(item.get("codigo_produto_nfe")),
                _normalizar_codigo_barras(item.get("codigo_barras")),
                _as_str(item.get("nome_produto")),
                _as_str(item.get("unidade")),
                _as_str(item.get("embalagem_tipo")) or _as_str(item.get("unidade")),
                _as_float(item.get("quantidade_embalagem"), _as_float(item.get("quantidade"), 0.0)),
                _as_float(item.get("fator_embalagem"), 1.0),
                1 if item.get("fator_inferido") in (True, 1, "1", "true", "True") else 0,
                _as_float(item.get("quantidade"), 0.0),
                _as_float(item.get("quantidade"), 0.0),
                _as_float(item.get("valor_unitario"), 0.0),
            ))

        conferencia = _carregar_conferencia_estoque(cur, conferencia_id)
        itens = _listar_itens_conferencia_estoque(cur, conferencia_id)
        conn.commit()
    finally:
        cur.close()
        conn.close()

    return {
        "conferencia": _estoque_conferencia_publica(conferencia),
        "itens": [_estoque_conferencia_item_publico(item) for item in itens],
        "produtos_criados": produtos_criados,
    }

def _resumir_nfe_para_abastecimento(nfe, combustivel_tipo=""):
    tipo_forcado = _as_str(combustivel_tipo).strip().lower()
    tipo_forcado = _validar_combustivel_tipo(tipo_forcado) if tipo_forcado else ""

    itens_tipados = []
    for item in nfe.get("itens") or []:
        tipo_item = _detectar_combustivel_tipo_item(item.get("nome_produto"))
        if tipo_item:
            itens_tipados.append((item, tipo_item))

    if tipo_forcado:
        selecionados = [item for item, tipo_item in itens_tipados if tipo_item == tipo_forcado]
        if not selecionados:
            raise ValueError(f"Nao foi encontrado item de {_combustivel_tipo_label(tipo_forcado).lower()} na NF-e informada.")
        tipo_final = tipo_forcado
    else:
        tipos_encontrados = sorted({tipo_item for _, tipo_item in itens_tipados})
        if not tipos_encontrados:
            raise ValueError(
                "Nao foi possivel identificar Diesel S10, Diesel 500, "
                "Gasolina, Etanol ou Arla nos itens da NF-e."
            )
        if len(tipos_encontrados) > 1:
            raise ValueError(
                "A NF-e possui mais de um tipo de combustivel. Selecione "
                "Diesel S10, Diesel 500, Gasolina, Etanol ou Arla."
            )
        tipo_final = tipos_encontrados[0]
        selecionados = [item for item, _ in itens_tipados]

    quantidade_total = 0.0
    valor_total = 0.0
    for item in selecionados:
        quantidade_total += _as_float(item.get("quantidade"), 0.0)
        valor_total += _as_float(item.get("valor_total"), 0.0)

    if quantidade_total <= 0:
        raise ValueError("A NF-e informada nao possui quantidade valida para o combustivel selecionado.")

    return {
        "combustivel_tipo": tipo_final,
        "quantidade_litros": quantidade_total,
        "valor": valor_total,
        "numero_nota": _as_str(nfe.get("numero_nota")),
        "chave_acesso_nfe": _normalizar_chave_acesso_nfe(nfe.get("chave_acesso")),
        "emitente_nome": _as_str(nfe.get("emitente_nome")),
        "itens_encontrados": len(selecionados),
    }

def _importar_nfe_abastecimento_por_xml_text(abastecimento_id, xml_text, chave_acesso_esperada="", combustivel_tipo=""):
    chave_acesso_esperada = _normalizar_chave_acesso_nfe(chave_acesso_esperada)
    nfe = _parse_nfe_xml_text(xml_text)

    conn = get_conn()
    cur = conn.cursor(dictionary=True)
    try:
        cur.execute("""
            SELECT
                a.id,
                a.veiculo_id,
                a.km,
                a.posto,
                a.status
            FROM abastecimentos a
            WHERE a.id=%s
        """, (abastecimento_id,))
        row = cur.fetchone()
        if not row:
            raise ValueError("abastecimento nao encontrado")

        status = _as_str(row.get("status")).lower()
        if status not in ("liberado", "abastecido"):
            raise ValueError("somente abastecimentos liberados ou abastecidos podem receber XML")

        combustivel_validado = _validar_combustivel_para_veiculo(
            cur,
            row.get("veiculo_id"),
            combustivel_tipo,
        )
        resumo_nfe = _resumir_nfe_para_abastecimento(
            nfe,
            combustivel_tipo=combustivel_validado,
        )
        chave_xml = _normalizar_chave_acesso_nfe(resumo_nfe.get("chave_acesso_nfe"))
        if chave_acesso_esperada and chave_xml != chave_acesso_esperada:
            raise ValueError("a chave bipada nao confere com o XML da NF-e informado")

        _validar_nota_duplicada_abastecimento(
            cur,
            numero_nota=resumo_nfe.get("numero_nota"),
            chave_acesso_nfe=chave_xml,
            exclude_id=abastecimento_id,
        )

        valor = _as_float(resumo_nfe.get("valor"), 0.0)
        quantidade_litros = _as_float(resumo_nfe.get("quantidade_litros"), 0.0)
        if valor <= 0:
            raise ValueError("o XML informado nao trouxe valor valido para o combustivel selecionado")
        if quantidade_litros <= 0:
            raise ValueError("o XML informado nao trouxe quantidade valida para o combustivel selecionado")

        posto_final = _as_str(row.get("posto")) or _as_str(resumo_nfe.get("emitente_nome"))
        cur.execute("""
            UPDATE abastecimentos
            SET
                posto = %s,
                combustivel_tipo = %s,
                valor = %s,
                quantidade_litros = %s,
                chave_acesso_nfe = %s,
                numero_nota = %s,
                emitente_nome = %s,
                status = 'abastecido',
                data_abastecimento = NOW()
            WHERE id=%s
        """, (
            posto_final,
            resumo_nfe.get("combustivel_tipo"),
            valor,
            quantidade_litros,
            chave_xml,
            resumo_nfe.get("numero_nota"),
            resumo_nfe.get("emitente_nome"),
            abastecimento_id,
        ))
        conn.commit()
    finally:
        cur.close()
        conn.close()

    return resumo_nfe

def _buscar_produto_estoque(cur, codigo_barras="", codigo_produto_nfe="", nome_produto=""):
    codigo_barras = _normalizar_codigo_barras(codigo_barras)
    codigo_produto_nfe = _as_str(codigo_produto_nfe)
    codigo_produto_norm = _codigo_produto_chave(codigo_produto_nfe)
    nome_produto = _as_str(nome_produto)
    nome_produto_norm = _produto_nome_normalizado(nome_produto)

    if codigo_barras:
        cur.execute("""
            SELECT id, codigo_barras, codigo_produto_nfe, nome_produto, unidade,
                   embalagem_tipo_padrao, fator_embalagem_padrao, origem_cadastro, criado_em, atualizado_em
            FROM estoque_produtos
            WHERE codigo_barras=%s
            ORDER BY id DESC
            LIMIT 1
        """, (codigo_barras,))
        row = cur.fetchone()
        if row:
            return row

    if codigo_produto_nfe:
        cur.execute("""
            SELECT id, codigo_barras, codigo_produto_nfe, nome_produto, grupo_estoque, produto_base_nome, unidade,
                   embalagem_tipo_padrao, fator_embalagem_padrao, origem_cadastro, criado_em, atualizado_em
            FROM estoque_produtos
            WHERE codigo_produto_nfe=%s
            ORDER BY id DESC
            LIMIT 1
        """, (codigo_produto_nfe,))
        row = cur.fetchone()
        if row:
            return row
    if codigo_produto_norm:
        cur.execute("""
            SELECT id, codigo_barras, codigo_produto_nfe, nome_produto, grupo_estoque, produto_base_nome, unidade,
                   embalagem_tipo_padrao, fator_embalagem_padrao, origem_cadastro, criado_em, atualizado_em
            FROM estoque_produtos
            WHERE TRIM(LEADING '0' FROM COALESCE(codigo_produto_nfe, ''))=%s
            ORDER BY id DESC
            LIMIT 1
        """, (codigo_produto_norm,))
        row = cur.fetchone()
        if row:
            return row

    if nome_produto:
        cur.execute("""
            SELECT id, codigo_barras, codigo_produto_nfe, nome_produto, grupo_estoque, produto_base_nome, unidade,
                   embalagem_tipo_padrao, fator_embalagem_padrao, origem_cadastro, criado_em, atualizado_em
            FROM estoque_produtos
            WHERE nome_produto=%s
            ORDER BY id DESC
            LIMIT 1
        """, (nome_produto,))
        row = cur.fetchone()
        if row:
            return row
    if nome_produto_norm:
        cur.execute("""
            SELECT id, codigo_barras, codigo_produto_nfe, nome_produto, grupo_estoque, produto_base_nome, unidade,
                   embalagem_tipo_padrao, fator_embalagem_padrao, origem_cadastro, criado_em, atualizado_em
            FROM estoque_produtos
            ORDER BY id DESC
        """)
        for row in (cur.fetchall() or []):
            if _produto_nome_normalizado(row.get("nome_produto")) == nome_produto_norm:
                return row

    return None

def _obter_ou_criar_produto_estoque(cur, codigo_barras="", codigo_produto_nfe="", nome_produto="", unidade="", origem_cadastro="manual"):
    row = _buscar_produto_estoque(
        cur,
        codigo_barras=codigo_barras,
        codigo_produto_nfe=codigo_produto_nfe,
        nome_produto=nome_produto,
    )
    if row:
        updates = []
        params = []
        codigo_barras = _normalizar_codigo_barras(codigo_barras)
        codigo_produto_nfe = _codigo_produto_nfe_saida(codigo_produto_nfe)
        unidade = _as_str(unidade)
        grupo_estoque = _estoque_grupo_inferido(nome_produto=nome_produto, codigo_produto_nfe=codigo_produto_nfe, grupo_estoque=row.get("grupo_estoque"))
        produto_base_nome = _estoque_base_nome_inferido(nome_produto=nome_produto, grupo_estoque=grupo_estoque, produto_base_nome=row.get("produto_base_nome"))
        if codigo_barras and not _as_str(row.get("codigo_barras")):
            updates.append("codigo_barras=%s")
            params.append(codigo_barras)
        if codigo_produto_nfe and not _as_str(row.get("codigo_produto_nfe")):
            updates.append("codigo_produto_nfe=%s")
            params.append(codigo_produto_nfe)
        if grupo_estoque and not _as_str(row.get("grupo_estoque")):
            updates.append("grupo_estoque=%s")
            params.append(grupo_estoque)
        if produto_base_nome and not _as_str(row.get("produto_base_nome")):
            updates.append("produto_base_nome=%s")
            params.append(produto_base_nome)
        if unidade and not _as_str(row.get("unidade")):
            updates.append("unidade=%s")
            params.append(unidade)
        if updates:
            params.append(row.get("id"))
            cur.execute(f"UPDATE estoque_produtos SET {', '.join(updates)} WHERE id=%s", tuple(params))
            row = {
                **row,
                "codigo_barras": codigo_barras or row.get("codigo_barras"),
                "codigo_produto_nfe": codigo_produto_nfe or row.get("codigo_produto_nfe"),
                "grupo_estoque": grupo_estoque or row.get("grupo_estoque"),
                "produto_base_nome": produto_base_nome or row.get("produto_base_nome"),
                "unidade": unidade or row.get("unidade"),
            }
        return row, False

    cur.execute("""
        INSERT INTO estoque_produtos
            (codigo_barras, codigo_produto_nfe, nome_produto, grupo_estoque, produto_base_nome, unidade, embalagem_tipo_padrao, fator_embalagem_padrao, origem_cadastro)
        VALUES
            (%s, %s, %s, %s, %s, %s, %s, %s, %s)
    """, (
        _normalizar_codigo_barras(codigo_barras),
        _codigo_produto_nfe_saida(codigo_produto_nfe),
        _as_str(nome_produto),
        "",
        "",
        _as_str(unidade),
        "",
        1.0,
        _as_str(origem_cadastro) or "manual",
    ))
    produto_id = cur.lastrowid
    return {
        "id": produto_id,
        "codigo_barras": _normalizar_codigo_barras(codigo_barras),
        "codigo_produto_nfe": _codigo_produto_nfe_saida(codigo_produto_nfe),
        "nome_produto": _as_str(nome_produto),
        "grupo_estoque": "",
        "produto_base_nome": "",
        "unidade": _as_str(unidade),
        "embalagem_tipo_padrao": "",
        "fator_embalagem_padrao": 1.0,
        "origem_cadastro": _as_str(origem_cadastro) or "manual",
    }, True

def _produto_estoque_publico(row):
    meta = _estoque_produto_meta(row)
    classificacao = _estoque_classificacao_operacional({**row, **meta})
    fator_padrao = _as_float(row.get("fator_embalagem_padrao"), 1.0)
    if fator_padrao <= 0:
        fator_padrao = 1.0
    return {
        "id": _as_int(row.get("id"), 0),
        "codigo_barras": _normalizar_codigo_barras(row.get("codigo_barras")),
        "codigo_produto_nfe": _as_str(row.get("codigo_produto_nfe")),
        "nome_produto": _as_str(row.get("nome_produto")),
        "grupo_estoque": meta.get("grupo_estoque"),
        "produto_base_nome": meta.get("produto_base_nome"),
        "produto_base_key": meta.get("produto_base_key"),
        "cadastro_explicitado": 1 if meta.get("cadastro_explicitado") else 0,
        **classificacao,
        "unidade": _as_str(row.get("unidade")),
        "embalagem_tipo_padrao": _as_str(row.get("embalagem_tipo_padrao")),
        "fator_embalagem_padrao": fator_padrao,
        "origem_cadastro": _as_str(row.get("origem_cadastro")) or "manual",
        "criado_em": _fmt_dt(row.get("criado_em")),
        "atualizado_em": _fmt_dt(row.get("atualizado_em")),
    }

def _aplicar_cadastro_embalagem_preview(preview):
    preview = _normalizar_preview_nfe(preview)
    itens = preview.get("itens") or []
    if not itens:
        return preview

    conn = get_conn()
    cur = conn.cursor(dictionary=True)
    try:
        itens_final = []
        for item in itens:
            cadastro = _buscar_produto_estoque(
                cur,
                codigo_barras=item.get("codigo_barras"),
                codigo_produto_nfe=item.get("codigo_produto_nfe"),
                nome_produto=item.get("nome_produto"),
            ) or {}
            unidade = _as_str(item.get("unidade"))
            if re.fullmatch(r"\d[\d.,]*", unidade or ""):
                unidade = ""
            embalagem_padrao = _as_str(cadastro.get("embalagem_tipo_padrao"))
            fator_padrao = _as_float(cadastro.get("fator_embalagem_padrao"), 0.0)
            item_atual = dict(item or {})
            if embalagem_padrao:
                item_atual["embalagem_tipo"] = embalagem_padrao
                if not unidade:
                    item_atual["unidade"] = embalagem_padrao
            else:
                item_atual["unidade"] = unidade
            if fator_padrao > 0 and _as_float(item_atual.get("fator_embalagem"), 0.0) <= 0:
                item_atual["fator_embalagem"] = fator_padrao
                item_atual["fator_inferido"] = 0
            grupo_regra = _estoque_grupo_inferido(
                nome_produto=item_atual.get("nome_produto"),
                codigo_produto_nfe=item_atual.get("codigo_produto_nfe"),
                grupo_estoque=cadastro.get("grupo_estoque"),
            )
            apresentacao_regra = _estoque_apresentacao_normalizada(
                item_atual.get("embalagem_tipo"),
                item_atual.get("unidade"),
                item_atual.get("nome_produto"),
            )
            if apresentacao_regra in {"PCT", "FD", "CX", "CX24", "CX48"}:
                fator_regra = _fator_base_produto(
                    nome_produto=item_atual.get("nome_produto"),
                    embalagem=apresentacao_regra,
                    unidade_ref=apresentacao_regra,
                    grupo_produto=grupo_regra,
                )
                if grupo_regra in {"PET", "GFA", "AGUA"} and fator_regra > 0:
                    item_atual["fator_embalagem"] = fator_regra
                    item_atual["fator_inferido"] = 1
            itens_final.append(_normalizar_item_preview_nfe(item_atual, len(itens_final) + 1))
        preview["itens"] = itens_final
        return preview
    finally:
        cur.close()
        conn.close()

