@app.route("/api/dashboard")
def dashboard():
    _limpar_fretes_finalizados_expirados()
    conn = get_conn()
    cursor = conn.cursor(dictionary=True)
    cursor.execute("""
        SELECT status, COUNT(*) as total
        FROM fretes
        GROUP BY status
    """)
    dados = cursor.fetchall()

    resumo = {
        "chegada": 0,
        "descarregado": 0,
        "liberado": 0,
        "carregando": 0,
        "carregado": 0,
        "entregando": 0,
        "retornando": 0,
        "paradoVasio": 0,
        "paradoCarregado": 0
    }

    for row in dados:
        if row["status"] in resumo:
            resumo[row["status"]] = row["total"]

    cursor.close()
    conn.close()
    return jsonify(resumo)

def _carregar_lookup_produtos_estoque(cur):
    cur.execute("""
        SELECT
            id,
            codigo_barras,
            codigo_produto_nfe,
            nome_produto,
            grupo_estoque,
            produto_base_nome,
            unidade,
            embalagem_tipo_padrao,
            fator_embalagem_padrao,
            origem_cadastro,
            criado_em,
            atualizado_em
        FROM estoque_produtos
        ORDER BY id DESC
    """)
    rows = cur.fetchall() or []
    lookup = {
        "codigo_barras": {},
        "codigo_produto_nfe": {},
        "nome_produto": {},
    }
    for row in rows:
        codigo_barras = _normalizar_codigo_barras(row.get("codigo_barras"))
        codigo_nfe = _codigo_produto_chave(row.get("codigo_produto_nfe"))
        nome_norm = _produto_nome_normalizado(row.get("nome_produto"))
        if codigo_barras and codigo_barras not in lookup["codigo_barras"]:
            lookup["codigo_barras"][codigo_barras] = row
        if codigo_nfe and codigo_nfe not in lookup["codigo_produto_nfe"]:
            lookup["codigo_produto_nfe"][codigo_nfe] = row
        if nome_norm and nome_norm not in lookup["nome_produto"]:
            lookup["nome_produto"][nome_norm] = row
    return lookup

def _resolver_produto_lookup_estoque(lookup, codigo_barras="", codigo_produto_nfe="", nome_produto=""):
    if not isinstance(lookup, dict):
        return None
    codigo_barras_norm = _normalizar_codigo_barras(codigo_barras)
    codigo_nfe_norm = _codigo_produto_chave(codigo_produto_nfe)
    nome_norm = _produto_nome_normalizado(nome_produto)
    if codigo_barras_norm and codigo_barras_norm in lookup.get("codigo_barras", {}):
        return lookup["codigo_barras"][codigo_barras_norm]
    if codigo_nfe_norm and codigo_nfe_norm in lookup.get("codigo_produto_nfe", {}):
        return lookup["codigo_produto_nfe"][codigo_nfe_norm]
    if nome_norm and nome_norm in lookup.get("nome_produto", {}):
        return lookup["nome_produto"][nome_norm]
    return None

def _estoque_merge_row(target, aliases, row):
    meta = _estoque_produto_meta(row)
    codigo_barras = _normalizar_codigo_barras(row.get("codigo_barras"))
    codigo_produto_nfe_norm = _codigo_produto_chave(row.get("codigo_produto_nfe"))
    codigo_produto_nfe_saida = _codigo_produto_nfe_saida(codigo_produto_nfe_norm) if codigo_produto_nfe_norm else _as_str(row.get("codigo_produto_nfe"))
    nome_produto = _as_str(meta.get("produto_base_nome") or row.get("nome_produto"))
    nome_produto_norm = _produto_nome_normalizado(nome_produto) or nome_produto
    grupo_estoque = meta.get("grupo_estoque") or "OUTROS"
    produto_base_key = _as_str(meta.get("produto_base_key"))

    chaves_candidatas = []
    if produto_base_key:
        chaves_candidatas.append(f"base:{produto_base_key}")
    if codigo_produto_nfe_norm:
        chaves_candidatas.append(f"cod:{codigo_produto_nfe_norm}")
    if codigo_barras:
        chaves_candidatas.append(f"ean:{codigo_barras}")
    if nome_produto_norm:
        chaves_candidatas.append(f"nom:{nome_produto_norm}")

    chave = next((aliases[ch] for ch in chaves_candidatas if ch in aliases), None)
    if not chave:
        chave = chaves_candidatas[0] if chaves_candidatas else f"row:{len(target) + 1}"

    atual = target.setdefault(chave, {
        "produto_key": chave,
        "grupo_estoque": grupo_estoque,
        "produto_base_nome": nome_produto or "-",
        "produto_base_key": produto_base_key,
        "codigo_barras": codigo_barras,
        "codigo_produto_nfe": codigo_produto_nfe_saida,
        "codigo_produto_nfe_norm": codigo_produto_nfe_norm,
        "nome_produto": nome_produto or "-",
        "nome_produto_norm": nome_produto_norm,
        "entradas_total": 0.0,
        "saidas_total": 0.0,
        "saidas_dia": 0.0,
        "quantidade_atual": 0.0,
        "quantidade_comprometida": 0.0,
        "vendas_dia": 0.0,
        "vendas_semana": 0.0,
        "ultimo_valor": 0.0,
        "ultima_movimentacao": "",
        "fornecedores": {},
        "codigos_origem": set(),
        "embalagens_origem": set(),
        "fatores_embalagem_origem": set(),
    })
    for alias in chaves_candidatas:
        aliases[alias] = chave

    if codigo_barras and not atual.get("codigo_barras"):
        atual["codigo_barras"] = codigo_barras
    if codigo_produto_nfe_norm:
        atual["codigo_produto_nfe_norm"] = codigo_produto_nfe_norm
    if codigo_produto_nfe_saida and not atual.get("codigo_produto_nfe"):
        atual["codigo_produto_nfe"] = codigo_produto_nfe_saida
    for codigo in (codigo_produto_nfe_saida, codigo_barras):
        if codigo:
            atual.setdefault("codigos_origem", set()).add(codigo)
    embalagem_origem = _as_str(row.get("embalagem_tipo_padrao") or row.get("unidade")).upper()
    if embalagem_origem:
        atual.setdefault("embalagens_origem", set()).add(embalagem_origem)
    fator_origem = _as_float(row.get("fator_embalagem_padrao"), 0.0)
    if fator_origem > 0:
        atual.setdefault("fatores_embalagem_origem", set()).add(fator_origem)
    if grupo_estoque and not atual.get("grupo_estoque"):
        atual["grupo_estoque"] = grupo_estoque
    if produto_base_key and not atual.get("produto_base_key"):
        atual["produto_base_key"] = produto_base_key
    if nome_produto and (not atual.get("produto_base_nome") or atual.get("produto_base_nome") == "-"):
        atual["produto_base_nome"] = nome_produto
    if nome_produto and (not atual.get("nome_produto") or atual.get("nome_produto") == "-"):
        atual["nome_produto"] = nome_produto
    if nome_produto_norm and not atual.get("nome_produto_norm"):
        atual["nome_produto_norm"] = nome_produto_norm
    fornecedor = _estoque_fornecedor_publico(row)
    if fornecedor:
        fornecedor_key = (
            fornecedor.get("cnpj")
            or fornecedor.get("nome")
            or fornecedor.get("categoria")
        )
        if fornecedor_key:
            atual.setdefault("fornecedores", {})[fornecedor_key] = fornecedor
    return atual

def _estoque_fornecedor_publico(row):
    cnpj = re.sub(r"\D+", "", _as_str(row.get("fornecedor_cnpj") or row.get("emitente_cnpj") or row.get("cnpj")))
    nome = _as_str(row.get("fornecedor_nome") or row.get("emitente_nome") or row.get("nome"))
    categoria = _as_str(row.get("fornecedor_categoria") or row.get("categoria"))
    if (nome or cnpj) and not categoria:
        categoria = "outros"
    if not (nome or cnpj or categoria):
        return None
    return {
        "cnpj": cnpj,
        "nome": nome or cnpj or "Sem fornecedor",
        "categoria": categoria or "outros",
    }

def _estoque_fornecedores_lista(item):
    fornecedores = item.get("fornecedores") or {}
    if isinstance(fornecedores, dict):
        values = list(fornecedores.values())
    elif isinstance(fornecedores, list):
        values = fornecedores
    else:
        values = []
    normalizados = []
    seen = set()
    for fornecedor in values:
        if not isinstance(fornecedor, dict):
            continue
        item_publico = _estoque_fornecedor_publico(fornecedor)
        if not item_publico:
            continue
        key = item_publico.get("cnpj") or item_publico.get("nome")
        if not key or key in seen:
            continue
        seen.add(key)
        normalizados.append(item_publico)
    normalizados.sort(key=lambda row: (_as_str(row.get("categoria")), _as_str(row.get("nome"))))
    return normalizados

def _estoque_registrar_filtro_fornecedor(meta, fornecedor):
    item = _estoque_fornecedor_publico(fornecedor or {})
    if not item:
        return
    meta.setdefault("_fornecedores_map", {})[item.get("cnpj") or item.get("nome")] = item
    categoria = item.get("categoria") or "outros"
    meta.setdefault("_categorias_fornecedor", set()).add(categoria)

def _estoque_resumo_produtos_data():
    hoje = datetime.date.today()
    inicio_semana = hoje - datetime.timedelta(days=hoje.weekday())
    conn = get_conn()
    cur = conn.cursor(dictionary=True)
    linhas = {}
    aliases = {}
    meta = {
        "data_referencia": _fmt_date(hoje),
        "inicio_semana": _fmt_date(inicio_semana),
        "cargas_importadas": 0,
        "cargas_pendentes": 0,
        "cargas_baixadas": 0,
        "saidas_dia_total": 0.0,
        "vendas_dia_total": 0.0,
        "vendas_semana_total": 0.0,
        "_fornecedores_map": {},
        "_categorias_fornecedor": set(),
    }
    pending_carga_ids = set()
    baixadas_ids = set()
    try:
        produtos_lookup = _carregar_lookup_produtos_estoque(cur)
        cur.execute("""
            SELECT
                e.codigo_barras,
                e.codigo_produto_nfe,
                e.nome_produto,
                COALESCE(SUM(CASE WHEN e.tipo_movimento = 'entrada' THEN e.quantidade ELSE 0 END), 0) AS entradas_total,
                COALESCE(SUM(CASE WHEN e.tipo_movimento = 'saida' THEN e.quantidade ELSE 0 END), 0) AS saidas_total,
                COALESCE(SUM(CASE WHEN e.tipo_movimento = 'saida' AND DATE(e.data_registro) = CURDATE() THEN e.quantidade ELSE 0 END), 0) AS saidas_dia,
                COALESCE(SUM(CASE WHEN e.tipo_movimento = 'saida' THEN -e.quantidade ELSE e.quantidade END), 0) AS quantidade_atual,
                MAX(e.data_registro) AS ultima_movimentacao,
                (
                    SELECT e2.valor_unitario
                    FROM estoque_movimentos e2
                    WHERE
                        COALESCE(NULLIF(e2.codigo_barras, ''), '__') = COALESCE(NULLIF(e.codigo_barras, ''), '__')
                        AND COALESCE(NULLIF(e2.codigo_produto_nfe, ''), '__') = COALESCE(NULLIF(e.codigo_produto_nfe, ''), '__')
                        AND COALESCE(NULLIF(e2.nome_produto, ''), '__') = COALESCE(NULLIF(e.nome_produto, ''), '__')
                    ORDER BY e2.id DESC
                    LIMIT 1
                ) AS ultimo_valor,
                COALESCE(NULLIF(f.cnpj, ''), NULLIF(xi.emitente_cnpj, ''), NULLIF(c.emitente_cnpj, '')) AS fornecedor_cnpj,
                COALESCE(NULLIF(f.nome, ''), NULLIF(xi.emitente_nome, ''), NULLIF(c.emitente_nome, '')) AS fornecedor_nome,
                COALESCE(NULLIF(f.categoria, ''), CASE WHEN COALESCE(NULLIF(xi.emitente_cnpj, ''), NULLIF(c.emitente_cnpj, '')) IS NOT NULL THEN 'outros' ELSE '' END) AS fornecedor_categoria
            FROM estoque_movimentos e
            LEFT JOIN importar_xml_estoque_itens xi
                ON e.referencia_tipo='importar_xml'
               AND e.referencia_id=xi.id
            LEFT JOIN estoque_conferencias c
                ON e.referencia_tipo='conferencia_nfe'
               AND e.referencia_id=c.id
            LEFT JOIN gestor_email_fornecedores f
                ON BINARY f.cnpj = BINARY COALESCE(NULLIF(xi.emitente_cnpj, ''), NULLIF(c.emitente_cnpj, ''))
            GROUP BY
                e.codigo_barras, e.codigo_produto_nfe, e.nome_produto,
                fornecedor_cnpj, fornecedor_nome, fornecedor_categoria
        """)
        for row in (cur.fetchall() or []):
            _estoque_registrar_filtro_fornecedor(meta, row)
            cadastro = _resolver_produto_lookup_estoque(
                produtos_lookup,
                codigo_barras=row.get("codigo_barras"),
                codigo_produto_nfe=row.get("codigo_produto_nfe"),
                nome_produto=row.get("nome_produto"),
            ) or {}
            row = {
                **row,
                "grupo_estoque": cadastro.get("grupo_estoque"),
                "produto_base_nome": cadastro.get("produto_base_nome"),
                "embalagem_tipo_padrao": cadastro.get("embalagem_tipo_padrao"),
                "fator_embalagem_padrao": cadastro.get("fator_embalagem_padrao"),
            }
            item = _estoque_merge_row(linhas, aliases, row)
            item["entradas_total"] += _as_float(row.get("entradas_total"), 0.0)
            item["saidas_total"] += _as_float(row.get("saidas_total"), 0.0)
            item["saidas_dia"] += _as_float(row.get("saidas_dia"), 0.0)
            item["quantidade_atual"] += _as_float(row.get("quantidade_atual"), 0.0)
            ultima = _fmt_dt(row.get("ultima_movimentacao"))
            if ultima and ultima > _as_str(item.get("ultima_movimentacao")):
                item["ultima_movimentacao"] = ultima
                item["ultimo_valor"] = _as_float(row.get("ultimo_valor"), item.get("ultimo_valor"))
            elif not item.get("ultima_movimentacao"):
                item["ultimo_valor"] = _as_float(row.get("ultimo_valor"), item.get("ultimo_valor"))

        cur.execute("""
            SELECT
                c.id AS carga_id,
                c.nome AS carga_nome,
                c.tipo_importacao,
                c.estoque_baixado_em,
                f.status AS frete_status,
                i.codigo_produto,
                i.codigo_barras,
                i.nome_produto,
                i.quantidade_total
            FROM cargas c
            LEFT JOIN fretes f ON f.carga_id = c.id
            LEFT JOIN cargas_estoque_itens i ON i.carga_id = c.id
            WHERE c.tipo_importacao='pdf'
            ORDER BY c.id DESC, i.item_seq ASC, i.id ASC
        """)
        for row in (cur.fetchall() or []):
            carga_id = _as_int(row.get("carga_id"), 0)
            if row.get("estoque_baixado_em"):
                if carga_id > 0:
                    baixadas_ids.add(carga_id)
                continue
            status_frete = _as_str(row.get("frete_status")).lower()
            if status_frete and status_frete not in ("chegada", "descarregado", "liberado", "carregando", "carregado"):
                continue
            if carga_id > 0:
                pending_carga_ids.add(carga_id)
            if not _as_str(row.get("nome_produto")):
                continue
            cadastro = _resolver_produto_lookup_estoque(
                produtos_lookup,
                codigo_barras=row.get("codigo_barras"),
                codigo_produto_nfe=row.get("codigo_produto"),
                nome_produto=row.get("nome_produto"),
            ) or {}
            item = _estoque_merge_row(linhas, aliases, {
                "codigo_barras": row.get("codigo_barras"),
                "codigo_produto_nfe": row.get("codigo_produto"),
                "nome_produto": row.get("nome_produto"),
                "grupo_estoque": cadastro.get("grupo_estoque"),
                "produto_base_nome": cadastro.get("produto_base_nome"),
            })
            item["quantidade_comprometida"] += _as_float(row.get("quantidade_total"), 0.0)

        meta["cargas_pendentes"] = len(pending_carga_ids)
        meta["cargas_baixadas"] = len(baixadas_ids)

        cache_entry = None
        try:
            cache_entry, _source, _cfg = _vendas_obter_cache_ativo(force_refresh=False)
        except Exception:
            cache_entry = None

        cache_id = _as_str((cache_entry or {}).get("id"))
        if cache_id:
            for chave_periodo, data_inicio, data_fim in (
                ("vendas_dia", hoje, hoje),
                ("vendas_semana", inicio_semana, hoje),
            ):
                cur.execute("""
                    SELECT
                        produto,
                        COALESCE(SUM(quantidade), 0) AS quantidade
                    FROM vendas_relatorio_itens
                    WHERE import_id=%s AND data_ref BETWEEN %s AND %s
                    GROUP BY produto
                """, (cache_id, data_inicio, data_fim))
                for row in (cur.fetchall() or []):
                    produto_texto = _as_str(row.get("produto"))
                    codigo_produto = _extrair_codigo_produto_texto(produto_texto)
                    nome_produto = re.sub(r"^\s*0*[A-Z0-9]+\s*[-–]\s*", "", produto_texto, flags=re.I).strip() or produto_texto
                    cadastro = _buscar_produto_estoque(
                        cur,
                        codigo_produto_nfe=_codigo_produto_nfe_saida(codigo_produto),
                        nome_produto=nome_produto,
                    ) or {}
                    fator = _as_float(cadastro.get("fator_embalagem_padrao"), 0.0)
                    if fator <= 0:
                        fator = _fator_base_produto(
                            nome_produto=nome_produto,
                            embalagem="",
                            unidade_ref=_as_str(cadastro.get("unidade")),
                            grupo_produto=cadastro.get("grupo_estoque"),
                        )
                    quantidade_base = round(_as_float(row.get("quantidade"), 0.0) * (fator if fator > 0 else 1.0), 3)
                    item = _estoque_merge_row(linhas, aliases, {
                        "codigo_barras": cadastro.get("codigo_barras"),
                        "codigo_produto_nfe": cadastro.get("codigo_produto_nfe") or codigo_produto,
                        "nome_produto": cadastro.get("nome_produto") or nome_produto,
                        "grupo_estoque": cadastro.get("grupo_estoque"),
                        "produto_base_nome": cadastro.get("produto_base_nome"),
                    })
                    item[chave_periodo] += quantidade_base
                    meta[f"{chave_periodo}_total"] += quantidade_base
    finally:
        cur.close()
        conn.close()

    rows = []
    for item in linhas.values():
        entradas_total = round(_as_float(item.get("entradas_total"), 0.0), 3)
        saidas_total = round(_as_float(item.get("saidas_total"), 0.0), 3)
        saidas_dia = round(_as_float(item.get("saidas_dia"), 0.0), 3)
        quantidade_atual = round(_as_float(item.get("quantidade_atual"), 0.0), 3)
        quantidade_comprometida = round(_as_float(item.get("quantidade_comprometida"), 0.0), 3)
        vendas_dia = round(_as_float(item.get("vendas_dia"), 0.0), 3)
        vendas_semana = round(_as_float(item.get("vendas_semana"), 0.0), 3)
        saldo_previsto_dia = round(quantidade_atual - quantidade_comprometida - vendas_dia, 3)
        saldo_remanescente = round(quantidade_atual - quantidade_comprometida, 3)
        if not any([quantidade_atual, quantidade_comprometida, entradas_total, saidas_total, vendas_dia, vendas_semana, saidas_dia]):
            continue
        fornecedores = _estoque_fornecedores_lista(item)
        meta["saidas_dia_total"] += saidas_dia
        row_publica = {
            "grupo_estoque": _as_str(item.get("grupo_estoque")) or "OUTROS",
            "produto_base_nome": _as_str(item.get("produto_base_nome")) or _as_str(item.get("nome_produto")) or "-",
            "produto_base_key": _as_str(item.get("produto_base_key")),
            "codigo_barras": _as_str(item.get("codigo_barras")),
            "codigo_produto_nfe": _as_str(item.get("codigo_produto_nfe")),
            "codigos_origem": sorted(item.get("codigos_origem") or []),
            "itens_unificados": len(item.get("codigos_origem") or []),
            "nome_produto": _as_str(item.get("produto_base_nome") or item.get("nome_produto")) or "-",
            "entradas_total": entradas_total,
            "saidas_total": saidas_total,
            "saidas_dia": saidas_dia,
            "quantidade_atual": quantidade_atual,
            "quantidade_comprometida": quantidade_comprometida,
            "vendas_dia": vendas_dia,
            "vendas_semana": vendas_semana,
            "saldo_previsto_dia": saldo_previsto_dia,
            "saldo_remanescente": saldo_remanescente,
            "ultimo_valor": _as_float(item.get("ultimo_valor"), 0.0),
            "ultima_movimentacao": _as_str(item.get("ultima_movimentacao")),
            "fornecedores": fornecedores,
            "fornecedor_nomes": [f.get("nome") for f in fornecedores if f.get("nome")],
            "fornecedor_categorias": sorted({f.get("categoria") or "outros" for f in fornecedores}),
            "embalagem_tipo_padrao": " ".join(sorted(item.get("embalagens_origem") or [])),
            "fatores_embalagem_origem": sorted(item.get("fatores_embalagem_origem") or []),
        }
        row_publica.update(_estoque_classificacao_operacional(row_publica))
        row_publica["pallet_meta"] = _estoque_pallet_meta(row_publica)
        rows.append(row_publica)
    rows.sort(key=lambda r: (
        _estoque_grupo_ordem(r.get("grupo_estoque")),
        _produto_nome_normalizado(r.get("produto_base_nome") or r.get("nome_produto")),
        _as_str(r.get("codigo_produto_nfe")),
        _as_str(r.get("codigo_barras")),
    ))
    meta["cargas_importadas"] = max(meta["cargas_importadas"], len(pending_carga_ids | baixadas_ids))
    meta["saidas_dia_total"] = round(meta["saidas_dia_total"], 3)
    meta["fornecedores"] = sorted(
        meta.pop("_fornecedores_map", {}).values(),
        key=lambda row: (_as_str(row.get("categoria")), _as_str(row.get("nome"))),
    )
    meta["categorias_fornecedor"] = sorted(meta.pop("_categorias_fornecedor", set()))
    return {
        "rows": rows,
        "meta": meta,
    }

def _dashboard_estoque_data():
    payload = _estoque_resumo_produtos_data()
    rows = [
        row for row in payload.get("rows", [])
        if row.get("exibir_dashboard")
    ]
    meta = dict(payload.get("meta") or {})
    meta["itens_dashboard"] = len(rows)
    meta["vendas_dia_total"] = round(
        sum(_as_float(row.get("vendas_dia"), 0.0) for row in rows), 3
    )
    meta["vendas_semana_total"] = round(
        sum(_as_float(row.get("vendas_semana"), 0.0) for row in rows), 3
    )
    meta["saidas_dia_total"] = round(
        sum(_as_float(row.get("saidas_dia"), 0.0) for row in rows), 3
    )
    return {"rows": rows, "meta": meta}


_RASTREIO_SIMULACAO_ATE = datetime.date(2026, 7, 31)
_RASTREIO_SERIAL_MAX = 100000
_ESTOQUE_XML_REFERENCIA = "importar_xml"
_RASTREIO_ORIGENS_AUTOMATICAS = {
    "bootstrap_simulado",
    "bootstrap_movimento",
    "bootstrap_xml_importado",
    "bootstrap",
    "amarracao_inicial",
    "simulacao",
    "simulacao_cliente",
    "auto_entrada_fabrica",
    "auto_saida_semana",
}
_RASTREIO_ORIGEM_MANUAL = "manual_correcao"


def _rastreio_parse_data_lote(value):
    if isinstance(value, datetime.datetime):
        return value.date()
    if isinstance(value, datetime.date):
        return value
    texto = _as_str(value)
    if not texto:
        return None
    for fmt in ("%Y-%m-%d", "%d/%m/%Y", "%d-%m-%Y"):
        try:
            return datetime.datetime.strptime(texto[:10], fmt).date()
        except Exception:
            continue
    return None


def _rastreio_lote_codigo(data_lote, serial):
    if not data_lote:
        return ""
    serial = max(1, min(_RASTREIO_SERIAL_MAX, _as_int(serial, 1) or 1))
    base = f"lote{data_lote.strftime('%d')}fab{data_lote.strftime('%d%m%Y')}"
    if serial <= 1:
        return base
    return f"{base}-{str(serial).zfill(2)}"


def _rastreio_data_from_registro(value):
    if isinstance(value, datetime.datetime):
        return value.date()
    if isinstance(value, datetime.date):
        return value
    texto = _as_str(value)
    if not texto:
        return None
    for fmt, size in (
        ("%Y-%m-%d %H:%M:%S", 19),
        ("%Y-%m-%d", 10),
        ("%d/%m/%Y", 10),
        ("%d-%m-%Y", 10),
    ):
        try:
            return datetime.datetime.strptime(texto[:size], fmt).date()
        except Exception:
            continue
    return None


def _rastreio_tipo_movimento(value):
    tipo = _as_str(value).lower()
    return "saida" if tipo == "saida" else "entrada"


def _rastreio_semana_inicio(data_ref):
    if not data_ref:
        return None
    return data_ref - datetime.timedelta(days=data_ref.weekday())


def _rastreio_semana_fim(data_ref):
    inicio = _rastreio_semana_inicio(data_ref)
    return inicio + datetime.timedelta(days=6) if inicio else None


def _rastreio_adicionar_entrada_semana(entradas_por_semana, data_lote):
    data_lote = _rastreio_data_from_registro(data_lote)
    if not data_lote:
        return
    semana = _rastreio_semana_inicio(data_lote)
    if not semana:
        return
    entradas_por_semana.setdefault(semana, set()).add(data_lote)


def _rastreio_lote_data_saida(data_movimento, entradas_por_semana):
    semana = _rastreio_semana_inicio(data_movimento)
    if not semana:
        return data_movimento
    datas = sorted(entradas_por_semana.get(semana) or [])
    anteriores = [d for d in datas if d <= data_movimento]
    if anteriores:
        return anteriores[-1]
    if datas:
        return datas[0]
    return semana


def _rastreio_carregar_entradas_por_semana(cur, data_inicio=None, data_fim=None):
    entradas_por_semana = {}
    where = ["tipo_movimento='entrada'"]
    params = []
    if data_inicio:
        where.append("data_lote>=%s")
        params.append(_rastreio_semana_inicio(data_inicio) or data_inicio)
    if data_fim:
        where.append("data_lote<=%s")
        params.append(_rastreio_semana_fim(data_fim) or data_fim)
    cur.execute(
        f"""
        SELECT DISTINCT data_lote
        FROM rastreabilidade_lancamento_vinculos
        WHERE {' AND '.join(where)}
        """,
        tuple(params),
    )
    for row in cur.fetchall() or []:
        _rastreio_adicionar_entrada_semana(entradas_por_semana, row.get("data_lote"))
    return entradas_por_semana


def _rastreio_nota_key(value):
    texto = _as_str(value).upper()
    digits = re.sub(r"\D+", "", texto)
    if digits:
        return digits.lstrip("0") or "0"
    return re.sub(r"\s+", "", texto)


def _rastreio_item_combina_texto(row, termo):
    termo_norm = _produto_nome_normalizado(termo)
    if not termo_norm:
        return True
    valores = [
        row.get("nome_produto"),
        row.get("produto"),
        row.get("produto_base_nome"),
        row.get("materia_prima_nome"),
    ]
    texto_norm = _produto_nome_normalizado(" ".join(_as_str(v) for v in valores if _as_str(v)))
    if not texto_norm:
        return False
    return termo_norm in texto_norm or texto_norm in termo_norm


def _rastreio_normalizar_periodo(data_lote=None, data_inicio=None, data_fim=None):
    data_ref = _rastreio_parse_data_lote(data_lote)
    inicio = _rastreio_parse_data_lote(data_inicio)
    fim = _rastreio_parse_data_lote(data_fim)
    if data_ref and not (inicio or fim):
        inicio = data_ref
        fim = data_ref
    if inicio and fim and inicio > fim:
        inicio, fim = fim, inicio
    return inicio, fim


def _rastreio_regularizar_vinculos_automaticos(cur, data_inicio=None, data_fim=None, hoje=None, limit=200000):
    hoje = hoje or datetime.date.today()
    limite = hoje - datetime.timedelta(days=1)
    if data_inicio and data_inicio > limite:
        return {"regularizados": 0, "movimentos_lote_atualizados": 0}
    if data_fim and data_fim > limite:
        data_fim = limite

    data_expr = "DATE(COALESCE(e.data_registro, NULLIF(xi.data_emissao, ''), xi.criado_em, v.data_lote))"
    origem_placeholders = ", ".join(["%s"] * len(_RASTREIO_ORIGENS_AUTOMATICAS))
    where = [
        f"{data_expr}<=%s",
        f"""(
            COALESCE(v.vinculo_origem, '') IN ({origem_placeholders})
            OR COALESCE(v.vinculo_origem, '') LIKE %s
            OR COALESCE(v.lote_codigo, '') LIKE %s
        )""",
    ]
    params = [limite, *_RASTREIO_ORIGENS_AUTOMATICAS, "bootstrap%", "LT-%"]
    if data_inicio:
        where.append(f"{data_expr}>=%s")
        params.append(data_inicio)
    if data_fim:
        where.append(f"{data_expr}<=%s")
        params.append(data_fim)

    cur.execute(
        f"""
        SELECT
            v.id,
            v.origem_tipo,
            v.estoque_movimento_id,
            v.tipo_movimento,
            v.lote_codigo,
            v.data_lote,
            v.serial,
            v.vinculo_origem,
            {data_expr} AS data_movimento
        FROM rastreabilidade_lancamento_vinculos v
        LEFT JOIN estoque_movimentos e
            ON v.origem_tipo='estoque_movimento'
           AND v.estoque_movimento_id=e.id
        LEFT JOIN importar_xml_estoque_itens xi
            ON v.referencia_tipo='importar_xml'
           AND v.referencia_id=xi.id
        WHERE {' AND '.join(where)}
        ORDER BY {data_expr} ASC, v.id ASC
        LIMIT %s
        """,
        tuple(params + [limit]),
    )
    rows = cur.fetchall() or []
    if not rows:
        return {"regularizados": 0, "movimentos_lote_atualizados": 0}

    datas = [
        d for d in (_rastreio_data_from_registro(row.get("data_movimento")) for row in rows)
        if d
    ]
    entradas_por_semana = _rastreio_carregar_entradas_por_semana(
        cur,
        min(datas) if datas else data_inicio,
        max(datas) if datas else data_fim,
    )
    for row in rows:
        data_movimento = _rastreio_data_from_registro(row.get("data_movimento"))
        if data_movimento and _rastreio_tipo_movimento(row.get("tipo_movimento")) == "entrada":
            _rastreio_adicionar_entrada_semana(entradas_por_semana, data_movimento)

    regularizados = 0
    movimentos_lote_atualizados = 0
    for row in rows:
        data_movimento = _rastreio_data_from_registro(row.get("data_movimento"))
        if not data_movimento or data_movimento >= hoje:
            continue
        tipo = _rastreio_tipo_movimento(row.get("tipo_movimento"))
        lote_data = (
            data_movimento
            if tipo == "entrada"
            else _rastreio_lote_data_saida(data_movimento, entradas_por_semana)
        )
        serial = 1
        lote_codigo = _rastreio_lote_codigo(lote_data, serial)
        origem = "auto_entrada_fabrica" if tipo == "entrada" else "auto_saida_semana"
        if (
            _as_str(row.get("lote_codigo")) != lote_codigo
            or _rastreio_data_from_registro(row.get("data_lote")) != lote_data
            or _as_int(row.get("serial"), 0) != serial
            or _as_str(row.get("vinculo_origem")) != origem
        ):
            cur.execute(
                """
                UPDATE rastreabilidade_lancamento_vinculos
                SET lote_codigo=%s,
                    data_lote=%s,
                    serial=%s,
                    vinculo_origem=%s,
                    simulado=0,
                    atualizado_em=CURRENT_TIMESTAMP
                WHERE id=%s
                """,
                (lote_codigo, lote_data, serial, origem, _as_int(row.get("id"), 0)),
            )
            regularizados += cur.rowcount

        movimento_id = _as_int(row.get("estoque_movimento_id"), 0)
        if _as_str(row.get("origem_tipo")) == "estoque_movimento" and movimento_id > 0:
            cur.execute(
                """
                UPDATE estoque_movimentos
                SET lote_codigo=%s
                WHERE id=%s
                  AND (COALESCE(lote_codigo, '')='' OR COALESCE(lote_codigo, '') LIKE %s)
                """,
                (lote_codigo, movimento_id, "LT-%"),
            )
            movimentos_lote_atualizados += cur.rowcount

    return {
        "regularizados": regularizados,
        "movimentos_lote_atualizados": movimentos_lote_atualizados,
    }


def _rastreio_criar_amarracao_inicial(data_lote=None, data_inicio=None, data_fim=None, limit=50000):
    conn = get_conn()
    cur = conn.cursor(dictionary=True)
    lock_ok = False
    resumo = {
        "criados": 0,
        "ignorados": 0,
        "sem_data": 0,
        "limite_serial": 0,
        "movimentos": 0,
        "xml_importados": 0,
        "xml_ignorados": 0,
        "saidas_manuais": 0,
        "regularizados": 0,
        "movimentos_lote_atualizados": 0,
    }
    try:
        try:
            cur.execute("SELECT GET_LOCK(%s, %s) AS ok", ("riob_rastreabilidade_bootstrap", 5))
            lock_ok = _as_int((cur.fetchone() or {}).get("ok"), 0) == 1
        except Exception:
            lock_ok = True
        if not lock_ok:
            return {**resumo, "lock": False}

        rows = []
        periodo_inicio, periodo_fim = _rastreio_normalizar_periodo(data_lote, data_inicio, data_fim)

        where = [
            "v.id IS NULL",
            "e.id IS NOT NULL",
        ]
        params = []
        if periodo_inicio:
            where.append("DATE(e.data_registro)>=%s")
            params.append(periodo_inicio)
        if periodo_fim:
            where.append("DATE(e.data_registro)<=%s")
            params.append(periodo_fim)
        cur.execute(
            f"""
            SELECT
                e.id,
                e.codigo_barras,
                e.codigo_produto_nfe,
                e.numero_nota,
                e.nome_produto,
                e.quantidade,
                e.valor_unitario,
                e.tipo_movimento,
                e.referencia_tipo,
                e.referencia_id,
                e.data_registro
            FROM estoque_movimentos e
            LEFT JOIN rastreabilidade_lancamento_vinculos v
                ON v.origem_tipo='estoque_movimento'
               AND v.estoque_movimento_id=e.id
            WHERE {' AND '.join(where)}
            ORDER BY DATE(e.data_registro) ASC, e.data_registro ASC, e.id ASC
            LIMIT %s
            """,
            tuple(params + [limit]),
        )
        for row in cur.fetchall() or []:
            rows.append(
                {
                    "origem_tipo": "estoque_movimento",
                    "estoque_movimento_id": _as_int(row.get("id"), 0),
                    "referencia_id": _as_int(row.get("referencia_id"), 0) or None,
                    "data_registro": row.get("data_registro"),
                    "codigo_barras": row.get("codigo_barras"),
                    "codigo_produto_nfe": row.get("codigo_produto_nfe"),
                    "numero_nota": row.get("numero_nota"),
                    "nome_produto": row.get("nome_produto"),
                    "quantidade": row.get("quantidade"),
                    "valor_unitario": row.get("valor_unitario"),
                    "tipo_movimento": row.get("tipo_movimento"),
                    "referencia_tipo": row.get("referencia_tipo"),
                    "vinculo_origem": "bootstrap_movimento",
                    "simulado": 0,
                }
            )
        resumo["movimentos"] = len(rows)

        where_xml = [
            "v.id IS NULL",
            "xi.id IS NOT NULL",
            "em.id IS NULL",
        ]
        params_xml = []
        if periodo_inicio:
            where_xml.append("DATE(COALESCE(NULLIF(xi.data_emissao, ''), xi.criado_em))>=%s")
            params_xml.append(periodo_inicio)
        if periodo_fim:
            where_xml.append("DATE(COALESCE(NULLIF(xi.data_emissao, ''), xi.criado_em))<=%s")
            params_xml.append(periodo_fim)
        try:
            cur.execute(
                f"""
                SELECT
                    xi.id,
                    xi.codigo_produto,
                    xi.numero_nota,
                    xi.descricao_produto,
                    xi.quantidade,
                    xi.valor_unitario,
                    xi.tipo_movimento,
                    xi.chave_nfe,
                    xi.data_emissao,
                    xi.criado_em
                FROM importar_xml_estoque_itens xi
                LEFT JOIN rastreabilidade_lancamento_vinculos v
                    ON v.origem_tipo='importar_xml'
                   AND v.referencia_id=xi.id
                LEFT JOIN estoque_movimentos em
                    ON em.referencia_tipo=%s
                   AND em.referencia_id=xi.id
                WHERE {' AND '.join(where_xml)}
                ORDER BY DATE(COALESCE(NULLIF(xi.data_emissao, ''), xi.criado_em)) ASC, xi.id ASC
                LIMIT %s
                """,
                tuple([_ESTOQUE_XML_REFERENCIA] + params_xml + [max(0, limit - len(rows))]),
            )
            xml_rows = cur.fetchall() or []
        except Exception as exc:
            xml_rows = []
            resumo["xml_erro"] = str(exc)

        for row in xml_rows:
            tipo_xml = _as_str(row.get("tipo_movimento")).upper()
            data_xml = (
                _rastreio_data_from_registro(row.get("data_emissao"))
                or _rastreio_data_from_registro(row.get("criado_em"))
            )
            rows.append(
                {
                    "origem_tipo": "importar_xml",
                    "estoque_movimento_id": None,
                    "referencia_id": _as_int(row.get("id"), 0),
                    "data_registro": data_xml or row.get("data_emissao") or row.get("criado_em"),
                    "codigo_barras": "",
                    "codigo_produto_nfe": row.get("codigo_produto"),
                    "numero_nota": row.get("numero_nota") or row.get("chave_nfe"),
                    "nome_produto": row.get("descricao_produto"),
                    "quantidade": row.get("quantidade"),
                    "valor_unitario": row.get("valor_unitario"),
                    "tipo_movimento": "saida" if tipo_xml == "SAIDA_ESTOQUE" else "entrada",
                    "referencia_tipo": _ESTOQUE_XML_REFERENCIA,
                    "vinculo_origem": "bootstrap_xml_importado",
                    "simulado": 0,
                }
            )
        resumo["xml_importados"] = len(xml_rows)

        hoje = datetime.date.today()
        datas = sorted({
            d for d in (_rastreio_data_from_registro(row.get("data_registro")) for row in rows)
            if d
        })
        entradas_por_semana = (
            _rastreio_carregar_entradas_por_semana(
                cur,
                min(datas) if datas else periodo_inicio,
                max(datas) if datas else periodo_fim,
            )
            if rows else {}
        )
        for row in rows:
            d = _rastreio_data_from_registro(row.get("data_registro"))
            if d and _rastreio_tipo_movimento(row.get("tipo_movimento")) == "entrada":
                _rastreio_adicionar_entrada_semana(entradas_por_semana, d)

        for row in rows:
            d = _rastreio_data_from_registro(row.get("data_registro"))
            if not d:
                resumo["sem_data"] += 1
                continue
            tipo = _rastreio_tipo_movimento(row.get("tipo_movimento"))
            if tipo == "saida" and d >= hoje:
                resumo["saidas_manuais"] = _as_int(resumo.get("saidas_manuais"), 0) + 1
                continue
            lote_data = d if tipo == "entrada" else _rastreio_lote_data_saida(d, entradas_por_semana)
            serial = 1
            lote_codigo = _rastreio_lote_codigo(lote_data, serial)
            vinculo_origem = "auto_entrada_fabrica" if tipo == "entrada" else "auto_saida_semana"
            cur.execute(
                """
                INSERT IGNORE INTO rastreabilidade_lancamento_vinculos (
                    lote_codigo, data_lote, serial, origem_tipo, estoque_movimento_id,
                    tipo_movimento, numero_nota, codigo_barras, codigo_produto_nfe,
                    nome_produto, quantidade, valor_unitario, referencia_tipo,
                    referencia_id, vinculo_origem, simulado
                )
                VALUES (%s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s)
                """,
                (
                    lote_codigo,
                    lote_data,
                    serial,
                    _as_str(row.get("origem_tipo")) or "estoque_movimento",
                    _as_int(row.get("estoque_movimento_id"), 0) or None,
                    tipo,
                    _as_str(row.get("numero_nota")),
                    _normalizar_codigo_barras(row.get("codigo_barras")),
                    _as_str(row.get("codigo_produto_nfe")),
                    _as_str(row.get("nome_produto")),
                    _as_float(row.get("quantidade"), 0.0),
                    _as_float(row.get("valor_unitario"), 0.0),
                    _as_str(row.get("referencia_tipo")),
                    _as_int(row.get("referencia_id"), 0) or None,
                    vinculo_origem,
                    1 if _as_int(row.get("simulado"), 0) else 0,
                ),
            )
            if cur.rowcount:
                resumo["criados"] += 1
                movimento_id = _as_int(row.get("estoque_movimento_id"), 0)
                if _as_str(row.get("origem_tipo")) == "estoque_movimento" and movimento_id > 0:
                    cur.execute(
                        """
                        UPDATE estoque_movimentos
                        SET lote_codigo=%s
                        WHERE id=%s
                          AND (COALESCE(lote_codigo, '')='' OR COALESCE(lote_codigo, '') LIKE %s)
                        """,
                        (lote_codigo, movimento_id, "LT-%"),
                    )
            else:
                resumo["ignorados"] += 1
        regularizacao = _rastreio_regularizar_vinculos_automaticos(
            cur,
            data_inicio=periodo_inicio,
            data_fim=periodo_fim,
            hoje=hoje,
        )
        resumo.update(regularizacao)
        conn.commit()
        return resumo
    finally:
        if lock_ok:
            try:
                cur.execute("SELECT RELEASE_LOCK(%s)", ("riob_rastreabilidade_bootstrap",))
                cur.fetchone()
            except Exception:
                pass
        cur.close()
        conn.close()


def _rastreio_buscar_notas_compra(cur, data_lote, serial, sabor=""):
    cur.execute(
        """
        SELECT
            v.id,
            v.lote_codigo,
            v.serial,
            v.codigo_barras,
            v.codigo_produto_nfe,
            v.numero_nota,
            v.nome_produto,
            v.quantidade,
            v.valor_unitario,
            v.referencia_tipo,
            v.referencia_id,
            v.vinculo_origem,
            v.simulado,
            v.criado_em,
            COALESCE(NULLIF(f.cnpj, ''), NULLIF(xi.emitente_cnpj, ''), NULLIF(c.emitente_cnpj, '')) AS fornecedor_cnpj,
            COALESCE(NULLIF(f.nome, ''), NULLIF(xi.emitente_nome, ''), NULLIF(c.emitente_nome, '')) AS fornecedor_nome,
            COALESCE(NULLIF(f.categoria, ''), CASE WHEN COALESCE(NULLIF(xi.emitente_cnpj, ''), NULLIF(c.emitente_cnpj, '')) IS NOT NULL THEN 'outros' ELSE '' END) AS fornecedor_categoria
        FROM rastreabilidade_lancamento_vinculos v
        LEFT JOIN estoque_movimentos e
            ON v.origem_tipo='estoque_movimento'
           AND v.estoque_movimento_id=e.id
        LEFT JOIN importar_xml_estoque_itens xi
            ON v.referencia_tipo='importar_xml'
           AND v.referencia_id=xi.id
        LEFT JOIN estoque_conferencias c
            ON v.referencia_tipo='conferencia_nfe'
           AND v.referencia_id=c.id
        LEFT JOIN gestor_email_fornecedores f
            ON BINARY f.cnpj = BINARY COALESCE(NULLIF(xi.emitente_cnpj, ''), NULLIF(c.emitente_cnpj, ''))
        WHERE v.tipo_movimento='entrada'
          AND v.data_lote=%s
          AND v.serial=%s
        ORDER BY v.serial ASC, v.id ASC
        """,
        (data_lote, serial),
    )
    rows = cur.fetchall() or []
    if sabor:
        rows = [row for row in rows if _rastreio_item_combina_texto(row, sabor)]

    notas = []
    for row in rows:
        fornecedor = _estoque_fornecedor_publico(row) or {}
        notas.append(
            {
                "id": _as_int(row.get("id"), 0),
                "vinculo_id": _as_int(row.get("id"), 0),
                "lote_codigo": _as_str(row.get("lote_codigo")),
                "serial": _as_int(row.get("serial"), 0),
                "nota_compra": _as_str(row.get("numero_nota")) or _as_str(row.get("lote_codigo")),
                "materia_prima_nome": _as_str(row.get("nome_produto")),
                "codigo": _as_str(row.get("codigo_produto_nfe") or row.get("codigo_barras")),
                "fornecedor_nome": _as_str(fornecedor.get("nome")),
                "fornecedor_cnpj": _as_str(fornecedor.get("cnpj")),
                "fornecedor_categoria": _as_str(fornecedor.get("categoria")),
                "quantidade": round(_as_float(row.get("quantidade"), 0.0), 6),
                "valor_unitario": _as_float(row.get("valor_unitario"), 0.0),
                "data": _fmt_date(data_lote),
                "origem": _as_str(row.get("vinculo_origem")) or _as_str(row.get("referencia_tipo")) or "amarracao_inicial",
                "simulado": bool(_as_int(row.get("simulado"), 1)),
            }
        )
    return notas


def _rastreio_buscar_notas_saida(cur, data_lote, serial, sabor=""):
    notas = []
    vistos = set()

    cur.execute(
        """
        SELECT id, numero_nota, lote_codigo, data_lote, serial
        FROM rastreabilidade_lancamento_vinculos
        WHERE tipo_movimento='saida'
          AND data_lote=%s
          AND serial=%s
        """,
        (data_lote, serial),
    )
    vinculos_saida = cur.fetchall() or []
    vinculos_por_key = {}
    notas_serial_keys = set()
    for row in vinculos_saida:
        key = _rastreio_nota_key(row.get("numero_nota") or row.get("lote_codigo"))
        if not key:
            continue
        notas_serial_keys.add(key)
        vinculos_por_key.setdefault(key, row)

    if notas_serial_keys:
        semana_inicio = _rastreio_semana_inicio(data_lote) or data_lote
        semana_fim = _rastreio_semana_fim(data_lote) or data_lote
        cur.execute(
            """
            SELECT
                v.id, v.nota_key, v.chave_nfe, v.numero_nota, v.frete_id,
                v.veiculo_id, v.carga_id, v.rota_registrada, v.placa_xml,
                v.mapa_xml, v.emitente_nome, v.destinatario_nome,
                v.data_emissao, v.itens_total, v.quantidade_total,
                v.valor_total_nota, v.vinculacao_origem, v.criado_em,
                f.nome AS frete_nome,
                f.cidade AS frete_cidade,
                c.nome AS carga_nome
            FROM estoque_xml_frete_vinculos v
            LEFT JOIN fretes f ON f.id = v.frete_id
            LEFT JOIN cargas c ON c.id = v.carga_id
            WHERE DATE(COALESCE(v.data_emissao, v.criado_em)) BETWEEN %s AND %s
            ORDER BY COALESCE(v.data_emissao, DATE(v.criado_em)) ASC, v.id ASC
            """,
            (semana_inicio, semana_fim),
        )
        for row in cur.fetchall() or []:
            key = _rastreio_nota_key(row.get("numero_nota") or row.get("chave_nfe") or row.get("nota_key"))
            if key not in notas_serial_keys:
                continue
            vistos.add(key)
            vinculo = vinculos_por_key.get(key) or {}
            notas.append(
                {
                    "id": _as_int(row.get("id"), 0),
                    "vinculo_id": _as_int(vinculo.get("id"), 0),
                    "lote_codigo": _as_str(vinculo.get("lote_codigo")),
                    "serial": _as_int(vinculo.get("serial"), 0),
                    "nota_saida": _as_str(row.get("numero_nota")) or _as_str(row.get("chave_nfe")),
                    "chave_nfe": _as_str(row.get("chave_nfe")),
                    "data": _fmt_date(row.get("data_emissao")) or _fmt_date(row.get("criado_em")),
                    "transportadora": _as_str(row.get("emitente_nome")) or _as_str(row.get("frete_nome")),
                    "destinatario_nome": _as_str(row.get("destinatario_nome")),
                    "frete_id": _as_int(row.get("frete_id"), 0) or None,
                    "frete_nome": _as_str(row.get("frete_nome")),
                    "carga_id": _as_int(row.get("carga_id"), 0) or None,
                    "carga_nome": _as_str(row.get("carga_nome")),
                    "rota": _as_str(row.get("rota_registrada") or row.get("frete_cidade")),
                    "placa": _as_str(row.get("placa_xml")),
                    "mapa": _as_str(row.get("mapa_xml")),
                    "quantidade_total": round(_as_float(row.get("quantidade_total"), 0.0), 3),
                    "valor_total_nota": _as_float(row.get("valor_total_nota"), 0.0),
                    "origem": _as_str(row.get("vinculacao_origem")) or "xml_frete",
                    "simulado": False,
                }
            )

    cur.execute(
        """
        SELECT
            v.id, v.lote_codigo, v.serial, v.numero_nota, v.codigo_barras,
            v.codigo_produto_nfe, v.nome_produto, v.quantidade, v.valor_unitario,
            v.referencia_tipo, v.referencia_id, v.vinculo_origem, v.simulado, v.criado_em,
            DATE(COALESCE(e.data_registro, NULLIF(xi.data_emissao, ''), xi.criado_em, v.data_lote)) AS data_movimento
        FROM rastreabilidade_lancamento_vinculos v
        LEFT JOIN estoque_movimentos e
            ON v.origem_tipo='estoque_movimento'
           AND v.estoque_movimento_id=e.id
        LEFT JOIN importar_xml_estoque_itens xi
            ON v.referencia_tipo='importar_xml'
           AND v.referencia_id=xi.id
        WHERE v.tipo_movimento='saida'
          AND v.data_lote=%s
          AND v.serial=%s
        ORDER BY v.serial ASC, v.id ASC
        """,
        (data_lote, serial),
    )
    for row in cur.fetchall() or []:
        if sabor and not _rastreio_item_combina_texto(row, sabor):
            continue
        key = _rastreio_nota_key(row.get("numero_nota")) or _as_str(row.get("lote_codigo")) or f"vinc:{row.get('id')}"
        if key in vistos:
            continue
        vistos.add(key)
        notas.append(
            {
                "id": _as_int(row.get("id"), 0),
                "vinculo_id": _as_int(row.get("id"), 0),
                "lote_codigo": _as_str(row.get("lote_codigo")),
                "serial": _as_int(row.get("serial"), 0),
                "nota_saida": _as_str(row.get("numero_nota")) or _as_str(row.get("lote_codigo")),
                "chave_nfe": "",
                "data": _fmt_date(row.get("data_movimento")) or _fmt_date(data_lote),
                "transportadora": "Transportadora pendente",
                "destinatario_nome": "Cliente pendente",
                "frete_id": None,
                "frete_nome": "",
                "carga_id": None,
                "carga_nome": "",
                "rota": "Rota pendente",
                "placa": "",
                "mapa": "",
                "produto": _as_str(row.get("nome_produto")),
                "quantidade_total": round(_as_float(row.get("quantidade"), 0.0), 3),
                "valor_total_nota": round(
                    _as_float(row.get("quantidade"), 0.0)
                    * _as_float(row.get("valor_unitario"), 0.0),
                    2,
                ),
                "origem": _as_str(row.get("vinculo_origem")) or _as_str(row.get("referencia_tipo")) or "amarracao_inicial",
                "simulado": bool(_as_int(row.get("simulado"), 1)),
            }
        )
    return notas


def _rastreio_buscar_clientes(cur, data_lote, sabor, notas_saida):
    clientes = []
    vistos = set()
    carga_ids = sorted({_as_int(n.get("carga_id"), 0) for n in notas_saida if _as_int(n.get("carga_id"), 0) > 0})
    nota_keys = {
        _rastreio_nota_key(n.get("nota_saida"))
        for n in notas_saida
        if _rastreio_nota_key(n.get("nota_saida"))
    }

    if carga_ids:
        placeholders = ", ".join(["%s"] * len(carga_ids))
        cur.execute(
            f"""
            SELECT
                carga_id,
                cliente,
                cidade,
                rota,
                numero_nf,
                produto,
                COALESCE(SUM(quantidade), 0) AS quantidade,
                COALESCE(SUM(litro), 0) AS litros,
                COALESCE(SUM(peso), 0) AS peso,
                COALESCE(SUM(valor_venda), 0) AS valor_venda
            FROM cargas_import_linhas
            WHERE carga_id IN ({placeholders})
            GROUP BY carga_id, cliente, cidade, rota, numero_nf, produto
            ORDER BY cliente ASC, numero_nf ASC, produto ASC
            """,
            tuple(carga_ids),
        )
        for row in cur.fetchall() or []:
            if sabor and not _rastreio_item_combina_texto(row, sabor):
                continue
            key = (
                _as_str(row.get("cliente")).casefold(),
                _rastreio_nota_key(row.get("numero_nf")),
                _produto_nome_normalizado(row.get("produto")),
            )
            if key in vistos:
                continue
            vistos.add(key)
            clientes.append(
                {
                    "cliente": _as_str(row.get("cliente")) or "Sem cliente",
                    "cidade": _as_str(row.get("cidade")),
                    "rota": _as_str(row.get("rota")),
                    "nota_saida": _as_str(row.get("numero_nf")),
                    "produto": _as_str(row.get("produto")),
                    "quantidade": round(_as_float(row.get("quantidade"), 0.0), 3),
                    "litros": round(_as_float(row.get("litros"), 0.0), 3),
                    "peso": round(_as_float(row.get("peso"), 0.0), 3),
                    "valor_venda": _as_float(row.get("valor_venda"), 0.0),
                    "origem": "carga",
                    "simulado": False,
                }
            )

    cache_id = ""
    try:
        cache_entry, _source, _cfg = _vendas_obter_cache_ativo(force_refresh=False)
        cache_id = _as_str((cache_entry or {}).get("id"))
    except Exception:
        cache_id = ""

    if cache_id:
        semana_inicio = _rastreio_semana_inicio(data_lote) or data_lote
        semana_fim = _rastreio_semana_fim(data_lote) or data_lote
        cur.execute(
            """
            SELECT
                cliente,
                cidade,
                numero_nf,
                produto,
                COALESCE(SUM(quantidade), 0) AS quantidade,
                COALESCE(SUM(litros), 0) AS litros,
                COALESCE(SUM(caixas), 0) AS caixas,
                COALESCE(SUM(valor_liquido), 0) AS valor_venda
            FROM vendas_relatorio_itens
            WHERE import_id=%s
              AND data_ref BETWEEN %s AND %s
            GROUP BY cliente, cidade, numero_nf, produto
            ORDER BY cliente ASC, numero_nf ASC, produto ASC
            LIMIT 800
            """,
            (cache_id, semana_inicio, semana_fim),
        )
        for row in cur.fetchall() or []:
            nota_key = _rastreio_nota_key(row.get("numero_nf"))
            if nota_keys and nota_key not in nota_keys:
                if not (sabor and _rastreio_item_combina_texto(row, sabor)):
                    continue
            if sabor and not _rastreio_item_combina_texto(row, sabor):
                continue
            key = (
                _as_str(row.get("cliente")).casefold(),
                nota_key,
                _produto_nome_normalizado(row.get("produto")),
            )
            if key in vistos:
                continue
            vistos.add(key)
            clientes.append(
                {
                    "cliente": _as_str(row.get("cliente")) or "Sem cliente",
                    "cidade": _as_str(row.get("cidade")),
                    "rota": "",
                    "nota_saida": _as_str(row.get("numero_nf")),
                    "produto": _as_str(row.get("produto")),
                    "quantidade": round(_as_float(row.get("quantidade"), 0.0), 3),
                    "litros": round(_as_float(row.get("litros"), 0.0), 3),
                    "peso": 0.0,
                    "valor_venda": _as_float(row.get("valor_venda"), 0.0),
                    "origem": "vendas",
                    "simulado": False,
                }
            )
    return clientes


