def _rastreio_simular_clientes(data_lote, serial, sabor="", notas_saida=None):
    base = notas_saida or [
        {
            "nota_saida": f"TEMP-SAIDA-{data_lote.strftime('%d%m%y')}-{str(serial).zfill(2)}",
            "produto": sabor or "Produto do lote",
            "quantidade_total": 1.0,
            "valor_total_nota": 0.0,
            "rota": "Rota pendente",
        }
    ]
    clientes = []
    for idx, nota in enumerate(base, start=1):
        produto = _as_str(nota.get("produto")) or sabor or "Produto do lote"
        if sabor and not _rastreio_item_combina_texto({"produto": produto}, sabor):
            continue
        clientes.append(
            {
                "cliente": _as_str(nota.get("destinatario_nome")) or f"Cliente pendente {idx}",
                "cidade": "",
                "rota": _as_str(nota.get("rota")) or "Rota pendente",
                "nota_saida": _as_str(nota.get("nota_saida")),
                "produto": produto,
                "quantidade": round(_as_float(nota.get("quantidade_total"), 1.0), 3),
                "litros": 0.0,
                "peso": 0.0,
                "valor_venda": _as_float(nota.get("valor_total_nota"), 0.0),
                "origem": "amarracao_inicial",
                "simulado": True,
            }
        )
    return clientes


def _rastreio_modo_resultado(*listas):
    tem_real = False
    tem_simulado = False
    for lista in listas:
        for item in lista or []:
            if item.get("simulado"):
                tem_simulado = True
            else:
                tem_real = True
    if tem_real and tem_simulado:
        return "misto"
    if tem_real:
        return "real"
    if tem_simulado:
        return "temporario"
    return "sem_dados"


try:
    if _as_bool(os.environ.get("RB_RASTREIO_BOOTSTRAP_STARTUP", "1"), True):
        _rastreio_criar_amarracao_inicial()
except Exception as exc:
    app.logger.warning("Falha ao criar amarracao inicial de rastreabilidade: %s", exc)


_ESTOQUE_XML_LOTE_MAXIMO = 500


def _estoque_xml_dados_item(valor):
    if isinstance(valor, dict):
        return valor
    texto = _as_str(valor).strip()
    if not texto:
        return {}
    try:
        dados = json.loads(texto)
    except Exception:
        try:
            dados = ast.literal_eval(texto)
        except Exception:
            dados = {}
    return dados if isinstance(dados, dict) else {}


def _estoque_xml_placa_normalizada(valor):
    return re.sub(r"[^A-Z0-9]", "", _as_str(valor).upper())


def _estoque_xml_numero_veiculo(valor):
    match = re.search(r"\d+", _as_str(valor))
    if not match:
        return ""
    return match.group(0).lstrip("0") or "0"


def _estoque_xml_numero_caminhao_mapa(mapa):
    match = re.fullmatch(r"7(\d{2})\d{4}", _as_str(mapa).strip())
    if not match:
        return ""
    return match.group(1).lstrip("0") or "0"


def _estoque_xml_tag_local(elemento):
    return _as_str(getattr(elemento, "tag", "")).rsplit("}", 1)[-1]


def _estoque_xml_texto_tag(elemento, nome_tag):
    if elemento is None:
        return ""
    for filho in elemento.iter():
        if _estoque_xml_tag_local(filho) == nome_tag:
            return _as_str(filho.text).strip()
    return ""


def _estoque_xml_localizar_arquivo(cur, nota):
    arquivo_ids = sorted(
        arquivo_id
        for arquivo_id in (nota.get("arquivo_ids") or set())
        if _as_int(arquivo_id, 0) > 0
    )
    if not arquivo_ids:
        return ""
    placeholders = ", ".join(["%s"] * len(arquivo_ids))
    cur.execute(
        f"""
        SELECT id, nome_arquivo, caminho_relativo
        FROM importar_xml_arquivos
        WHERE id IN ({placeholders})
        ORDER BY id DESC
        """,
        tuple(arquivo_ids),
    )
    nomes = []
    for row in cur.fetchall() or []:
        for valor in (row.get("caminho_relativo"), row.get("nome_arquivo")):
            nome = os.path.basename(_as_str(valor).strip())
            if nome and nome not in nomes:
                nomes.append(nome)

    raiz_legacy = os.environ.get(
        "RB_IMPORTAR_XML_LEGACY_DIR",
        os.path.join(BASE_DIR, "ImportarXml"),
    )
    diretorios = [
        os.environ.get(
            "RB_IMPORTAR_XML_DATA_DIR",
            os.path.join(DATA_ROOT, "ImportarXml", "uploads"),
        ),
        os.path.join(raiz_legacy, "uploads_xml_homologacao"),
        os.path.join(BASE_DIR, "ImportarXml", "uploads_xml_homologacao"),
    ]
    for diretorio in diretorios:
        for nome in nomes:
            caminho = os.path.join(diretorio, nome)
            if os.path.isfile(caminho):
                return caminho
    return ""


def _estoque_xml_extrair_transporte(cur, nota):
    resultado = {
        "placa": "",
        "uf_placa": "",
        "mapa": "",
        "numero_caminhao": "",
        "modalidade_frete": "",
        "informacoes_complementares": "",
        "arquivo_xml": "",
    }
    caminho = _estoque_xml_localizar_arquivo(cur, nota)
    if not caminho:
        return resultado
    resultado["arquivo_xml"] = os.path.basename(caminho)
    try:
        raiz = ET.parse(caminho).getroot()
    except Exception:
        return resultado

    veiculo = next(
        (
            elemento
            for elemento in raiz.iter()
            if _estoque_xml_tag_local(elemento) == "veicTransp"
        ),
        None,
    )
    resultado["placa"] = _estoque_xml_placa_normalizada(
        _estoque_xml_texto_tag(veiculo, "placa")
    )
    resultado["uf_placa"] = _estoque_xml_texto_tag(veiculo, "UF").upper()
    resultado["modalidade_frete"] = next(
        (
            _as_str(elemento.text)
            for elemento in raiz.iter()
            if _estoque_xml_tag_local(elemento) == "modFrete"
        ),
        "",
    )
    inf_cpl = next(
        (
            _as_str(elemento.text)
            for elemento in raiz.iter()
            if _estoque_xml_tag_local(elemento) == "infCpl"
        ),
        "",
    )
    resultado["informacoes_complementares"] = inf_cpl
    match_mapa = re.search(r"\bMapa\s*:\s*([0-9]+)", inf_cpl, flags=re.IGNORECASE)
    resultado["mapa"] = match_mapa.group(1) if match_mapa else ""
    resultado["numero_caminhao"] = _estoque_xml_numero_caminhao_mapa(
        resultado["mapa"]
    )
    return resultado


def _estoque_xml_normalizar_texto(valor):
    texto = unicodedata.normalize("NFKD", _as_str(valor).upper())
    return " ".join(
        "".join(ch for ch in texto if not unicodedata.combining(ch)).split()
    )


def _estoque_xml_detectar_dispensa_frete(transporte):
    modalidade = _as_str(transporte.get("modalidade_frete"))
    if modalidade in {"1", "4", "9"}:
        rotulos = {
            "1": "frete por conta do destinatario",
            "4": "transporte proprio do destinatario",
            "9": "operacao sem transporte",
        }
        return {
            "dispensa_frete": True,
            "tipo_transporte": "retirada_cliente",
            "origem": "automatico_xml",
            "motivo": (
                f"XML informa {rotulos[modalidade]}; "
                "nao exige frete, rota ou veiculo da empresa."
            ),
        }

    texto = _estoque_xml_normalizar_texto(
        transporte.get("informacoes_complementares")
    )
    sem_veiculo = not (
        _estoque_xml_placa_normalizada(transporte.get("placa"))
        or _estoque_xml_numero_veiculo(transporte.get("numero_caminhao"))
    )
    padroes_cliente = (
        (r"\bRETIRADA PELO CLIENTE\b", "RETIRADA PELO CLIENTE"),
        (r"\bRETIRA CLIENTE\b", "RETIRA CLIENTE"),
        (r"\bTRANSPORTE PELO CLIENTE\b", "TRANSPORTE PELO CLIENTE"),
        (r"\bTRANSPORTE DO CLIENTE\b", "TRANSPORTE DO CLIENTE"),
        (
            r"\bVENDEDOR\s*:\s*(?:\d+\s*-\s*)?BALCAO\b",
            "VENDA DE BALCAO",
        ),
    )
    indicacao = next(
        (rotulo for padrao, rotulo in padroes_cliente if re.search(padrao, texto)),
        "",
    )
    if sem_veiculo and indicacao:
        return {
            "dispensa_frete": True,
            "tipo_transporte": "retirada_cliente",
            "origem": "automatico_xml",
            "motivo": (
                f"XML sem placa/caminhao e com indicacao '{indicacao}'; "
                "tratado como retirada ou transporte pelo cliente."
            ),
        }
    return {
        "dispensa_frete": False,
        "tipo_transporte": "",
        "origem": "",
        "motivo": "",
    }


def _estoque_xml_arquivar_card_automatico_dispensado(
    cur,
    pre_vinculo,
    nota_key,
    usuario,
):
    frete_id = _as_int(pre_vinculo.get("frete_id"), 0)
    if (
        frete_id <= 0
        or _as_str(pre_vinculo.get("origem_frete")) != "frete_criado"
    ):
        return False
    cur.execute(
        """
        SELECT COUNT(*) AS total
        FROM estoque_xml_frete_vinculos
        WHERE frete_id=%s
        """,
        (frete_id,),
    )
    if _as_int((cur.fetchone() or {}).get("total"), 0) > 0:
        return False
    cur.execute(
        """
        SELECT COUNT(*) AS total
        FROM estoque_xml_frete_pre_vinculos
        WHERE frete_id=%s AND nota_key<>%s AND status<>'dispensado'
        """,
        (frete_id, nota_key),
    )
    if _as_int((cur.fetchone() or {}).get("total"), 0) > 0:
        return False
    frete = _buscar_frete_detalhado(cur, frete_id)
    if not frete or not _as_str(frete.get("observacao")).startswith(
        "Card criado automaticamente pelo XML de saida."
    ):
        return False
    observacao = _as_str(frete.get("observacao"))
    complemento = " Arquivado porque o transporte foi realizado pelo cliente."
    if complemento.strip() not in observacao:
        observacao = f"{observacao}{complemento}"[:500]
    cur.execute(
        """
        UPDATE fretes
        SET arquivado=1, observacao=%s
        WHERE id=%s
        """,
        (observacao, frete_id),
    )
    depois = _buscar_frete_detalhado(cur, frete_id)
    _registrar_historico_frete(
        cur,
        frete_id,
        "arquivado_retirada_cliente_xml",
        usuario,
        frete,
        depois,
    )
    return True


def _estoque_xml_definir_dispensa_frete(
    cur,
    nota,
    dispensa_frete,
    origem,
    motivo,
    usuario,
    tipo_transporte="retirada_cliente",
):
    canonicos = nota.get("canonicos") or []
    base = canonicos[0] if canonicos else {}
    nota_key = _as_str(nota.get("nota_key"))
    cur.execute(
        """
        INSERT IGNORE INTO estoque_xml_frete_pre_vinculos (
            nota_key, chave_nfe, numero_nota, status, criado_em, atualizado_em
        )
        VALUES (%s, %s, %s, 'pendente', NOW(), NOW())
        """,
        (
            nota_key,
            _normalizar_chave_acesso_nfe(base.get("chave_nfe")),
            _as_str(base.get("numero_nota")),
        ),
    )
    cur.execute(
        """
        SELECT *
        FROM estoque_xml_frete_pre_vinculos
        WHERE nota_key=%s
        LIMIT 1
        FOR UPDATE
        """,
        (nota_key,),
    )
    pre_vinculo = cur.fetchone() or {}
    card_arquivado = False
    if dispensa_frete:
        card_arquivado = _estoque_xml_arquivar_card_automatico_dispensado(
            cur,
            pre_vinculo,
            nota_key,
            usuario,
        )
    cur.execute(
        """
        UPDATE estoque_xml_frete_pre_vinculos
        SET dispensa_frete=%s,
            tipo_transporte=%s,
            origem_decisao_logistica=%s,
            motivo_decisao_logistica=%s,
            usuario_decisao_logistica=%s,
            frete_id=CASE WHEN %s=1 THEN NULL ELSE frete_id END,
            veiculo_id=CASE WHEN %s=1 THEN NULL ELSE veiculo_id END,
            origem_frete=CASE WHEN %s=1 THEN 'retirada_cliente' ELSE '' END,
            origem_veiculo=CASE WHEN %s=1 THEN 'veiculo_cliente' ELSE '' END,
            status=CASE WHEN %s=1 THEN 'dispensado' ELSE 'pendente' END,
            detalhes=%s,
            atualizado_em=NOW(),
            confirmado_em=NULL
        WHERE nota_key=%s
        """,
        (
            1 if dispensa_frete else 0,
            tipo_transporte if dispensa_frete else "",
            _as_str(origem),
            _as_str(motivo)[:500],
            _as_str(usuario),
            1 if dispensa_frete else 0,
            1 if dispensa_frete else 0,
            1 if dispensa_frete else 0,
            1 if dispensa_frete else 0,
            1 if dispensa_frete else 0,
            _as_str(motivo)[:500],
            nota_key,
        ),
    )
    cur.execute(
        """
        SELECT *
        FROM estoque_xml_frete_pre_vinculos
        WHERE nota_key=%s
        LIMIT 1
        """,
        (nota_key,),
    )
    atualizado = cur.fetchone() or {}
    atualizado["card_arquivado"] = card_arquivado
    return atualizado


def _estoque_xml_resolver_veiculo(cur, transporte):
    placa_xml = _estoque_xml_placa_normalizada(transporte.get("placa"))
    numero_xml = _estoque_xml_numero_veiculo(transporte.get("numero_caminhao"))
    cur.execute(
        """
        SELECT id, nome, placa, modelo
        FROM veiculos
        ORDER BY id ASC
        """
    )
    veiculos = cur.fetchall() or []
    if placa_xml:
        for veiculo in veiculos:
            if _estoque_xml_placa_normalizada(veiculo.get("placa")) == placa_xml:
                return {
                    "veiculo_id": _as_int(veiculo.get("id"), 0),
                    "origem": "placa_xml",
                    "veiculo": veiculo,
                }
    if numero_xml:
        for veiculo in veiculos:
            if _estoque_xml_numero_veiculo(veiculo.get("nome")) == numero_xml:
                return {
                    "veiculo_id": _as_int(veiculo.get("id"), 0),
                    "origem": "mapa_xml",
                    "veiculo": veiculo,
                }
    return {
        "veiculo_id": 0,
        "origem": "nao_identificado",
        "veiculo": None,
    }


def _estoque_xml_sugerir_frete(cur, transporte, veiculo_id=0):
    placa_xml = _estoque_xml_placa_normalizada(transporte.get("placa"))
    numero_xml = _estoque_xml_numero_veiculo(transporte.get("numero_caminhao"))
    vazio = {
        "frete_id": 0,
        "confianca": "",
        "motivo": "",
        "candidatos_total": 0,
    }
    if not (placa_xml or numero_xml or _as_int(veiculo_id, 0) > 0):
        return {
            **vazio,
            "motivo": "O XML nao informou uma placa nem um mapa compativel com numero de caminhao.",
        }

    cur.execute(
        FRETE_SELECT_SQL
        + """
          WHERE COALESCE(f.arquivado, 0)=0
        """
    )
    fretes_por_id = {}
    for row in cur.fetchall() or []:
        frete = _serialize_frete_row(row)
        if frete and frete.get("id"):
            fretes_por_id[frete["id"]] = frete

    candidatos = []
    for frete in fretes_por_id.values():
        if _as_str(frete.get("status")) in {"retornando", "paradoVasio"}:
            continue
        placa_frete = _estoque_xml_placa_normalizada(frete.get("veiculo_placa"))
        numeros_frete = {
            numero
            for numero in (
                _estoque_xml_numero_veiculo(frete.get("veiculo_nome")),
                _estoque_xml_numero_veiculo(frete.get("carga_veiculo_numero")),
            )
            if numero
        }
        veiculo_confere = bool(
            _as_int(veiculo_id, 0) > 0
            and _as_int(frete.get("veiculo_id"), 0) == _as_int(veiculo_id, 0)
        )
        placa_confere = bool(placa_xml and placa_frete == placa_xml)
        numero_confere = bool(numero_xml and numero_xml in numeros_frete)
        if not (veiculo_confere or placa_confere or numero_confere):
            continue
        candidatos.append(
            {
                "frete": frete,
                "veiculo_confere": veiculo_confere,
                "placa_confere": placa_confere,
                "numero_confere": numero_confere,
            }
        )

    candidatos_placa = [item for item in candidatos if item["placa_confere"]]
    if candidatos_placa:
        candidatos = candidatos_placa
    if not candidatos:
        identificador = (
            placa_xml
            or (f"caminhao {numero_xml}" if numero_xml else "")
            or f"veiculo #{_as_int(veiculo_id, 0)}"
        )
        return {
            **vazio,
            "motivo": f"Nao existe frete ativo para {identificador}; selecione manualmente.",
        }

    pontos_status = {
        "entregando": 50,
        "carregado": 45,
        "carregando": 40,
        "liberado": 35,
        "chegada": 20,
        "descarregado": 15,
        "paradoCarregado": 10,
        "paradoVasio": 5,
        "retornando": 0,
    }
    for item in candidatos:
        frete = item["frete"]
        item["pontos"] = (
            (120 if item["veiculo_confere"] else 0)
            + (100 if item["placa_confere"] else 0)
            + (40 if item["numero_confere"] else 0)
            + pontos_status.get(_as_str(frete.get("status")), 0)
        )
    candidatos.sort(
        key=lambda item: (
            item["pontos"],
            _as_int(item["frete"].get("id"), 0),
        ),
        reverse=True,
    )
    escolhido = candidatos[0]
    frete = escolhido["frete"]
    evidencias = []
    if escolhido["veiculo_confere"]:
        evidencias.append(f"veiculo cadastrado #{_as_int(veiculo_id, 0)}")
    if escolhido["placa_confere"]:
        evidencias.append(f"placa {placa_xml}")
    if escolhido["numero_confere"]:
        evidencias.append(f"caminhao {numero_xml} pelo mapa {transporte.get('mapa')}")
    confianca = "alta" if len(candidatos) == 1 and escolhido["placa_confere"] else "media"
    evidencias_texto = " e ".join(evidencias)
    if evidencias_texto:
        evidencias_texto = evidencias_texto[0].upper() + evidencias_texto[1:]
    return {
        "frete_id": _as_int(frete.get("id"), 0),
        "confianca": confianca,
        "motivo": (
            f"{evidencias_texto} indicam o frete "
            f"#{frete.get('id')} ({_as_str(frete.get('nome'))}); "
            f"status {_as_str(frete.get('status')) or '-'}."
        ),
        "candidatos_total": len(candidatos),
    }

def _frete_cidades_lista(*valores):
    cidades = []
    vistos = set()
    for valor in valores:
        candidatos = valor if isinstance(valor, (list, tuple, set)) else [valor]
        partes = []
        for candidato in candidatos:
            partes.extend(
                re.split(r"(?:\r?\n|[;,|]|\s+-\s+)+", _as_str(candidato))
            )
        for parte in partes:
            cidade = _normalizar_nome_local(parte)
            chave = _normalizar_chave_texto(cidade)
            if cidade and chave and chave not in vistos:
                vistos.add(chave)
                cidades.append(cidade)
    return cidades


def _estoque_xml_sugerir_frete_por_cidade_rota(cur, nota, veiculo_id=0):
    canonicos = (nota or {}).get("canonicos") or []
    cidades_nota = _frete_cidades_lista(
        *[_estoque_xml_cidade_destinatario(row) for row in canonicos]
    )
    if not cidades_nota:
        return {}
    cidade_chaves = {_normalizar_chave_texto(cidade) for cidade in cidades_nota}

    cur.execute("SELECT id, nome, cidades FROM cargas_rotas WHERE ativo=1 ORDER BY id")
    rota_escolhida = None
    rota_chaves = set()
    for rota in cur.fetchall() or []:
        chaves = {
            _normalizar_chave_texto(cidade)
            for cidade in _cargas_rota_cidades_lista(rota.get("cidades"))
            if _normalizar_chave_texto(cidade)
        }
        if cidade_chaves & chaves:
            rota_escolhida = rota
            rota_chaves = chaves
            break

    cur.execute(
        """
        SELECT f.id, f.nome, f.cidade, f.veiculo_id,
               c.cidade AS carga_cidade, c.rota AS carga_rota,
               cil.carga_cidades
        FROM fretes f
        LEFT JOIN cargas c ON c.id=f.carga_id
        LEFT JOIN (
            SELECT carga_id, GROUP_CONCAT(DISTINCT cidade SEPARATOR '\n') AS carga_cidades
            FROM cargas_import_linhas
            WHERE TRIM(COALESCE(cidade, ''))<>''
            GROUP BY carga_id
        ) cil ON cil.carga_id=c.id
        WHERE COALESCE(f.arquivado, 0)=0
          AND COALESCE(f.status, '') NOT IN ('retornando', 'paradoVasio')
          AND (
              f.observacao LIKE 'Card criado automaticamente pelo XML%%'
              OR EXISTS (
                  SELECT 1 FROM estoque_xml_frete_vinculos v
                  WHERE v.frete_id=f.id
              )
              OR EXISTS (
                  SELECT 1 FROM estoque_xml_frete_pre_vinculos p
                  WHERE p.frete_id=f.id
                    AND COALESCE(p.status, '') NOT IN (
                        'cancelado', 'cancelada', 'descartado', 'descartada',
                        'ignorado', 'ignorada', 'dispensado'
                    )
              )
          )
        ORDER BY f.id ASC
        """
    )
    candidatos = []
    veiculo_id = _as_int(veiculo_id, 0)
    for frete in cur.fetchall() or []:
        veiculo_frete = _as_int(frete.get("veiculo_id"), 0)
        if veiculo_id and veiculo_frete and veiculo_id != veiculo_frete:
            continue
        cidades_frete = _frete_cidades_lista(
            frete.get("cidade"),
            frete.get("carga_cidade"),
            frete.get("carga_rota"),
            frete.get("carga_cidades"),
        )
        chaves_frete = {
            _normalizar_chave_texto(cidade)
            for cidade in cidades_frete
            if _normalizar_chave_texto(cidade)
        }
        mesma_cidade = bool(cidade_chaves & chaves_frete)
        mesma_rota = bool(rota_chaves and rota_chaves & chaves_frete)
        if not (mesma_cidade or mesma_rota):
            continue
        candidatos.append(
            {
                "frete": frete,
                "mesma_cidade": mesma_cidade,
                "mesma_rota": mesma_rota,
                "veiculo_confere": bool(veiculo_id and veiculo_frete == veiculo_id),
            }
        )
    if not candidatos:
        return {}
    candidatos.sort(
        key=lambda item: (
            1 if item["mesma_cidade"] else 0,
            1 if item["veiculo_confere"] else 0,
            -_as_int(item["frete"].get("id"), 0),
        ),
        reverse=True,
    )
    escolhido = candidatos[0]
    frete = escolhido["frete"]
    motivo = (
        f"A cidade {cidades_nota[0]} ja possui o frete #{frete.get('id')}."
        if escolhido["mesma_cidade"]
        else (
            f"A cidade {cidades_nota[0]} pertence a rota "
            f"{_as_str((rota_escolhida or {}).get('nome'))}, ja representada "
            f"pelo frete #{frete.get('id')}."
        )
    )
    return {
        "frete_id": _as_int(frete.get("id"), 0),
        "confianca": "alta",
        "motivo": motivo,
        "candidatos_total": len(candidatos),
        "origem": "cidade" if escolhido["mesma_cidade"] else "rota_registrada",
    }

def _estoque_xml_agrupar_cidades_no_frete(cur, frete_id, nota):
    frete_id = _as_int(frete_id, 0)
    if frete_id <= 0:
        return []
    cur.execute(
        """
        SELECT f.nome, f.cidade, f.veiculo_id, v.nome AS veiculo_nome
        FROM fretes f
        LEFT JOIN veiculos v ON v.id=f.veiculo_id
        WHERE f.id=%s
        LIMIT 1
        """,
        (frete_id,),
    )
    frete = cur.fetchone() or {}
    cidades = _frete_cidades_lista(
        frete.get("cidade"),
        *[
            _estoque_xml_cidade_destinatario(row)
            for row in ((nota or {}).get("canonicos") or [])
        ],
    )
    if not cidades:
        return []
    cidade_texto = " - ".join(cidades)
    nome = _montar_nome_frete_exibicao(
        cidades,
        _as_str(frete.get("veiculo_nome")),
        cidades[0],
    ) or _as_str(frete.get("nome"))
    cur.execute(
        """
        UPDATE fretes
        SET cidade=%s,
            nome=%s
        WHERE id=%s
        """,
        (cidade_texto[:255], nome[:150], frete_id),
    )
    return cidades


def _estoque_xml_criar_frete_automatico(
    cur,
    nota,
    transporte,
    veiculo_resolvido,
    usuario="sistema",
):
    canonicos = nota.get("canonicos") or []
    base = canonicos[0] if canonicos else {}
    numero_nota = _as_str(base.get("numero_nota")) or _as_str(nota.get("nota_key"))
    veiculo = veiculo_resolvido.get("veiculo") or {}
    numero_caminhao = _as_str(transporte.get("numero_caminhao"))
    identificador = (
        _as_str(veiculo.get("nome"))
        or numero_caminhao
        or _as_str(transporte.get("placa"))
    )
    nome = (
        f"NF-e {numero_nota} - Caminhao {identificador}"
        if identificador
        else f"NF-e {numero_nota} - Vincular veiculo"
    )[:150]
    cidades = [
        _estoque_xml_cidade_destinatario(row)
        for row in canonicos
    ]
    cidades = [cidade for cidade in cidades if cidade]
    cidade = ""
    if cidades:
        ocorrencias = Counter(cidades)
        cidade = sorted(
            ocorrencias,
            key=lambda item: (-ocorrencias[item], cidades.index(item), item),
        )[0]
    veiculo_id = _as_int(veiculo_resolvido.get("veiculo_id"), 0)
    equipe = _buscar_equipe_atual_veiculo(cur, veiculo_id)
    motorista_id = _as_int(equipe.get("motorista_id"), 0) or None
    ajudante_id = _as_int(equipe.get("ajudante_id"), 0) or None
    legacy_motorista_id = _resolver_motorista_legacy_id_por_colaborador(
        cur, motorista_id
    )
    legacy_ajudante_id = _resolver_motorista_legacy_id_por_colaborador(
        cur, ajudante_id
    )
    km_atual = _buscar_km_atual_veiculo(cur, veiculo_id)
    partes_observacao = [
        "Card criado automaticamente pelo XML de saida.",
        f"Placa: {_as_str(transporte.get('placa')) or '-'}.",
        f"Mapa: {_as_str(transporte.get('mapa')) or '-'}.",
    ]
    if not _as_int(veiculo_resolvido.get("veiculo_id"), 0):
        partes_observacao.append("Veiculo pendente de vinculacao no Kanban.")
    partes_observacao.append("Revise rota, motorista e demais dados.")
    observacao = " ".join(partes_observacao)
    cur.execute(
        """
        INSERT INTO fretes (
            nome, cidade, data_carga, status,
            motorista_id, entregador_id,
            colaborador_motorista_id, colaborador_entregador_id,
            veiculo_id, carga_id,
            observacao, km_atual, peso, qtd_entregas, arquivado
        )
        VALUES (
            %s, %s, %s, 'liberado',
            %s, %s, %s, %s,
            %s, NULL, %s, %s, 0, 1, 0
        )
        """,
        (
            nome,
            cidade,
            _as_date(base.get("data_emissao")) or datetime.date.today(),
            legacy_motorista_id,
            legacy_ajudante_id,
            motorista_id,
            ajudante_id,
            veiculo_id or None,
            observacao,
            km_atual,
        ),
    )
    frete_id = _as_int(cur.lastrowid, 0)
    frete = _buscar_frete_detalhado(cur, frete_id)
    historico = {
        **(frete or {}),
        "numero_nota": numero_nota,
        "chave_nfe": _normalizar_chave_acesso_nfe(base.get("chave_nfe")),
    }
    _registrar_historico_frete(
        cur,
        frete_id,
        "criado_automaticamente_xml",
        usuario,
        None,
        historico,
    )
    return frete


def _estoque_xml_preparar_vinculo(cur, nota, usuario="sistema"):
    canonicos = nota.get("canonicos") or []
    base = canonicos[0] if canonicos else {}
    nota_key = _as_str(nota.get("nota_key"))
    chave_nfe = _normalizar_chave_acesso_nfe(base.get("chave_nfe"))
    numero_nota = _as_str(base.get("numero_nota"))
    transporte = _estoque_xml_extrair_transporte(cur, nota)

    cur.execute(
        """
        INSERT IGNORE INTO estoque_xml_frete_pre_vinculos (
            nota_key, chave_nfe, numero_nota, placa_xml, mapa_xml,
            numero_caminhao_xml, status, criado_em, atualizado_em
        )
        VALUES (%s, %s, %s, %s, %s, %s, 'pendente', NOW(), NOW())
        """,
        (
            nota_key,
            chave_nfe,
            numero_nota,
            _as_str(transporte.get("placa")),
            _as_str(transporte.get("mapa")),
            _as_str(transporte.get("numero_caminhao")),
        ),
    )
    pre_vinculo_criado = bool(cur.rowcount)
    cur.execute(
        """
        SELECT *
        FROM estoque_xml_frete_pre_vinculos
        WHERE nota_key=%s
        LIMIT 1
        FOR UPDATE
        """,
        (nota_key,),
    )
    pre_vinculo = cur.fetchone() or {}
    cur.execute(
        """
        SELECT frete_id, veiculo_id
        FROM estoque_xml_frete_vinculos
        WHERE nota_key=%s
        LIMIT 1
        """,
        (nota_key,),
    )
    vinculo_final = cur.fetchone() or {}
    desvinculado_manualmente = (
        _as_str(pre_vinculo.get("origem_frete")) == "desvinculado_kanban"
        and _as_str(pre_vinculo.get("status")).lower() in {
            "cancelado",
            "desvinculado",
        }
    )
    if desvinculado_manualmente and not vinculo_final:
        return {
            "nota_key": nota_key,
            "frete_id": 0,
            "veiculo_id": 0,
            "origem_veiculo": "desvinculado_kanban",
            "origem_frete": "desvinculado_kanban",
            "status": "desvinculado",
            "dispensa_frete": False,
            "tipo_transporte": "",
            "origem_decisao_logistica": "manual",
            "motivo_decisao_logistica": (
                "Nota mantida sem vinculo por decisao manual no Kanban."
            ),
            "transporte_xml": transporte,
            "frete_sugestao": {},
            "pre_vinculo_criado": pre_vinculo_criado,
            "frete_criado": False,
            "bloqueio_vinculo_automatico": True,
        }
    decisao_automatica = _estoque_xml_detectar_dispensa_frete(transporte)
    if (
        decisao_automatica.get("dispensa_frete")
        and not _as_str(pre_vinculo.get("origem_decisao_logistica"))
        and not vinculo_final
    ):
        pre_vinculo = _estoque_xml_definir_dispensa_frete(
            cur,
            nota,
            True,
            decisao_automatica.get("origem"),
            decisao_automatica.get("motivo"),
            usuario,
            tipo_transporte=decisao_automatica.get("tipo_transporte"),
        )
    if _as_int(pre_vinculo.get("dispensa_frete"), 0):
        return {
            "nota_key": nota_key,
            "frete_id": 0,
            "veiculo_id": 0,
            "origem_veiculo": _as_str(pre_vinculo.get("origem_veiculo")),
            "origem_frete": _as_str(pre_vinculo.get("origem_frete")),
            "status": _as_str(pre_vinculo.get("status")) or "dispensado",
            "dispensa_frete": True,
            "tipo_transporte": _as_str(pre_vinculo.get("tipo_transporte")),
            "origem_decisao_logistica": _as_str(
                pre_vinculo.get("origem_decisao_logistica")
            ),
            "motivo_decisao_logistica": _as_str(
                pre_vinculo.get("motivo_decisao_logistica")
            ),
            "transporte_xml": transporte,
            "frete_sugestao": {
                "frete_id": 0,
                "confianca": "alta",
                "motivo": _as_str(
                    pre_vinculo.get("motivo_decisao_logistica")
                ),
                "candidatos_total": 0,
            },
            "pre_vinculo_criado": pre_vinculo_criado,
            "frete_criado": False,
            "card_arquivado": bool(pre_vinculo.get("card_arquivado")),
        }

    frete_id_atual = (
        _as_int(vinculo_final.get("frete_id"), 0)
        or _as_int(pre_vinculo.get("frete_id"), 0)
    )
    frete_atual = (
        _buscar_frete_detalhado(cur, frete_id_atual)
        if frete_id_atual > 0
        else None
    )

    veiculo_resolvido = _estoque_xml_resolver_veiculo(cur, transporte)
    veiculo_id_xml = _as_int(veiculo_resolvido.get("veiculo_id"), 0)
    veiculo_id_frete = _as_int((frete_atual or {}).get("veiculo_id"), 0)
    veiculo_id = (
        _as_int(vinculo_final.get("veiculo_id"), 0)
        or veiculo_id_frete
        or _as_int(pre_vinculo.get("veiculo_id"), 0)
        or veiculo_id_xml
    )
    origem_veiculo = _as_str(pre_vinculo.get("origem_veiculo"))
    if veiculo_id_frete and veiculo_id_frete != veiculo_id_xml:
        origem_veiculo = "kanban_manual"
    elif not origem_veiculo or origem_veiculo == "nao_identificado":
        origem_veiculo = _as_str(veiculo_resolvido.get("origem"))
    if frete_atual and _as_int(frete_atual.get("veiculo_id"), 0):
        origem_veiculo = origem_veiculo or "frete_existente"

    frete_criado = False
    sugestao = {}
    origem_frete = _as_str(pre_vinculo.get("origem_frete"))
    if vinculo_final and frete_atual:
        origem_frete = origem_frete or "vinculo_confirmado"
        sugestao = {
            "frete_id": _as_int(frete_atual.get("id"), 0),
            "confianca": "alta",
            "motivo": "A nota ja possui vinculo definitivo com este frete.",
            "candidatos_total": 1,
        }
    elif frete_atual:
        origem_frete = origem_frete or "pre_vinculo_existente"
        veiculo_pendente = not _as_int(frete_atual.get("veiculo_id"), 0)
        sugestao = {
            "frete_id": _as_int(frete_atual.get("id"), 0),
            "confianca": "manual" if veiculo_pendente else "alta",
            "motivo": (
                "O card foi criado automaticamente e aguarda o vinculo manual do veiculo no Kanban."
                if veiculo_pendente
                else (
                    "O card criado automaticamente ja estava preparado para esta nota."
                    if origem_frete == "frete_criado"
                    else "O frete ja estava preparado para esta nota."
                )
            ),
            "candidatos_total": 1,
        }
    else:
        sugestao = _estoque_xml_sugerir_frete_por_cidade_rota(
            cur, nota, veiculo_id
        ) or _estoque_xml_sugerir_frete(cur, transporte, veiculo_id)
        frete_id_sugerido = _as_int(sugestao.get("frete_id"), 0)
        if frete_id_sugerido > 0:
            frete_atual = _buscar_frete_detalhado(cur, frete_id_sugerido)
            origem_frete = "frete_existente"
        else:
            veiculo_resolvido = {
                **veiculo_resolvido,
                "veiculo_id": veiculo_id,
            }
            frete_atual = _estoque_xml_criar_frete_automatico(
                cur,
                nota,
                transporte,
                veiculo_resolvido,
                usuario=usuario,
            )
            frete_criado = True
            origem_frete = "frete_criado"
            sugestao = {
                "frete_id": _as_int((frete_atual or {}).get("id"), 0),
                "confianca": "alta" if veiculo_id > 0 else "manual",
                "motivo": (
                    "Foi criado um card no Kanban ja vinculado ao veiculo identificado."
                    if veiculo_id > 0
                    else "Foi criado um card aberto no Kanban para vincular o veiculo manualmente."
                ),
                "candidatos_total": 1,
            }

    frete_id = _as_int((frete_atual or {}).get("id"), 0)
    if frete_id > 0:
        _estoque_xml_agrupar_cidades_no_frete(cur, frete_id, nota)
        frete_atual = _buscar_frete_detalhado(cur, frete_id) or frete_atual
    if not veiculo_id:
        veiculo_id = _as_int((frete_atual or {}).get("veiculo_id"), 0)
    status_pre = "confirmado" if vinculo_final else "pendente"
    detalhes = _as_str(sugestao.get("motivo"))[:500]
    if vinculo_final:
        cur.execute(
            """
            UPDATE estoque_xml_frete_vinculos
            SET veiculo_id=COALESCE(veiculo_id, %s),
                placa_xml=CASE
                    WHEN TRIM(COALESCE(placa_xml, ''))='' THEN %s
                    ELSE placa_xml
                END,
                mapa_xml=CASE
                    WHEN TRIM(COALESCE(mapa_xml, ''))='' THEN %s
                    ELSE mapa_xml
                END,
                numero_caminhao_xml=CASE
                    WHEN TRIM(COALESCE(numero_caminhao_xml, ''))='' THEN %s
                    ELSE numero_caminhao_xml
                END
            WHERE nota_key=%s
            """,
            (
                veiculo_id or None,
                _as_str(transporte.get("placa")),
                _as_str(transporte.get("mapa")),
                _as_str(transporte.get("numero_caminhao")),
                nota_key,
            ),
        )
    cur.execute(
        """
        UPDATE estoque_xml_frete_pre_vinculos
        SET chave_nfe=%s,
            numero_nota=%s,
            veiculo_id=%s,
            frete_id=%s,
            placa_xml=%s,
            mapa_xml=%s,
            numero_caminhao_xml=%s,
            origem_veiculo=%s,
            origem_frete=%s,
            status=%s,
            detalhes=%s,
            atualizado_em=NOW(),
            confirmado_em=CASE
                WHEN %s='confirmado' THEN COALESCE(confirmado_em, NOW())
                ELSE confirmado_em
            END
        WHERE nota_key=%s
        """,
        (
            chave_nfe,
            numero_nota,
            veiculo_id or None,
            frete_id or None,
            _as_str(transporte.get("placa")),
            _as_str(transporte.get("mapa")),
            _as_str(transporte.get("numero_caminhao")),
            origem_veiculo,
            origem_frete,
            status_pre,
            detalhes,
            status_pre,
            nota_key,
        ),
    )
    return {
        "nota_key": nota_key,
        "frete_id": frete_id,
        "veiculo_id": veiculo_id,
        "origem_veiculo": origem_veiculo,
        "origem_frete": origem_frete,
        "status": status_pre,
        "dispensa_frete": False,
        "tipo_transporte": "",
        "origem_decisao_logistica": _as_str(
            pre_vinculo.get("origem_decisao_logistica")
        ),
        "motivo_decisao_logistica": _as_str(
            pre_vinculo.get("motivo_decisao_logistica")
        ),
        "transporte_xml": transporte,
        "frete_sugestao": sugestao,
        "pre_vinculo_criado": pre_vinculo_criado,
        "frete_criado": frete_criado,
    }


def _estoque_xml_nota_key(row):
    chave = _normalizar_chave_acesso_nfe(row.get("chave_nfe"))
    if chave:
        return chave
    return "|".join(
        [
            "sem-chave",
            _as_str(row.get("emitente_cnpj")),
            _as_str(row.get("numero_nota")),
            _as_str(row.get("serie")),
        ]
    )


def _estoque_xml_item_seq(row):
    dados = _estoque_xml_dados_item(row.get("dados_json"))
    return _as_str(dados.get("nItem") or dados.get("item_seq"))

def _estoque_xml_cidade_destinatario(row):
    dados = _estoque_xml_dados_item((row or {}).get("dados_json"))
    cab = dados.get("cab") if isinstance(dados.get("cab"), dict) else {}
    return _normalizar_nome_local(
        dados.get("destinatario_cidade")
        or dados.get("cidade_destinatario")
        or cab.get("destinatario_cidade")
    )

def _estoque_xml_emitente_fantasia(row):
    dados = _estoque_xml_dados_item((row or {}).get("dados_json"))
    cab = dados.get("cab") if isinstance(dados.get("cab"), dict) else {}
    return _as_str(
        dados.get("emitente_fantasia")
        or cab.get("emitente_fantasia")
    )

def _estoque_xml_atualizar_cidade_frete(cur, frete_id, nota_atual=None):
    frete_id = _as_int(frete_id, 0)
    if frete_id <= 0:
        return ""
    cur.execute(
        """
        SELECT DISTINCT nota_key
        FROM estoque_xml_frete_vinculos
        WHERE frete_id=%s
        """,
        (frete_id,),
    )
    notas = {
        _as_str(row.get("nota_key"))
        for row in (cur.fetchall() or [])
        if _as_str(row.get("nota_key"))
    }
    cidades = []
    for nota_key in notas:
        notas_xml = _estoque_xml_carregar_notas(cur, nota_key)
        nota = notas_xml.get(nota_key)
        canonicos = (nota or {}).get("canonicos") or []
        cidade = next(
            (
                _estoque_xml_cidade_destinatario(row)
                for row in canonicos
                if _estoque_xml_cidade_destinatario(row)
            ),
            "",
        )
        if cidade:
            cidades.append(cidade)
    canonicos_atuais = (nota_atual or {}).get("canonicos") or []
    cidade_atual = next(
        (
            _estoque_xml_cidade_destinatario(row)
            for row in canonicos_atuais
            if _estoque_xml_cidade_destinatario(row)
        ),
        "",
    )
    if cidade_atual and cidade_atual not in cidades:
        cidades.append(cidade_atual)
    if not cidades:
        return ""
    ocorrencias = Counter(cidades)
    cidade_sugerida = sorted(
        ocorrencias,
        key=lambda item: (-ocorrencias[item], cidades.index(item), item),
    )[0]
    cur.execute(
        "UPDATE fretes SET cidade=%s WHERE id=%s",
        (cidade_sugerida, frete_id),
    )
    return cidade_sugerida


def _estoque_xml_agrupar_notas(rows):
    notas = {}
    for row in rows or []:
        chave_nota = _estoque_xml_nota_key(row)
        nota = notas.setdefault(
            chave_nota,
            {
                "nota_key": chave_nota,
                "rows": [],
                "arquivo_ids": set(),
            },
        )
        nota["rows"].append(row)
        arquivo_id = _as_int(row.get("arquivo_id"), 0)
        if arquivo_id > 0:
            nota["arquivo_ids"].add(arquivo_id)

    for nota in notas.values():
        canonicos = {}
        for row in sorted(nota["rows"], key=lambda item: _as_int(item.get("id"), 0)):
            seq = _estoque_xml_item_seq(row)
            if seq:
                identidade = f"seq:{seq}"
            else:
                identidade = "|".join(
                    [
                        "item",
                        _as_str(row.get("codigo_produto")),
                        _as_str(row.get("descricao_produto")),
                        str(round(_as_float(row.get("quantidade"), 0.0), 6)),
                        str(round(_as_float(row.get("valor_unitario"), 0.0), 6)),
                        _as_str(row.get("cfop")),
                    ]
                )
            canonicos.setdefault(identidade, row)
        nota["canonicos"] = list(canonicos.values())
    return notas


def _estoque_xml_carregar_notas(cur, nota_key="", limite_linhas=0, busca=""):
    sql = """
        SELECT
            id, arquivo_id, arquivo_origem, tipo_movimento,
            padrao_detectado, motivo_classificacao, chave_nfe,
            numero_nota, serie, data_emissao, natureza_operacao,
            cfop, emitente_cnpj, emitente_nome, destinatario_cnpj,
            destinatario_nome, codigo_produto, descricao_produto,
            ncm, unidade, quantidade, valor_unitario,
            valor_total_item, valor_total_nota, criado_em, dados_json
        FROM importar_xml_estoque_itens
    """
    params = []
    where = []
    chave = _normalizar_chave_acesso_nfe(nota_key)
    if len(chave) == 44:
        where.append("chave_nfe=%s")
        params.append(chave)
    busca = _as_str(busca)
    if busca:
        termo = f"%{busca}%"
        where.append(
            """
            (
                numero_nota LIKE %s OR chave_nfe LIKE %s
                OR emitente_nome LIKE %s OR destinatario_nome LIKE %s
            )
            """
        )
        params.extend((termo, termo, termo, termo))
    if where:
        sql += " WHERE " + " AND ".join(where)
    limite_linhas = max(0, min(_as_int(limite_linhas, 0), 20000))
    sql += " ORDER BY id " + ("DESC" if limite_linhas else "ASC")
    if limite_linhas:
        sql += f" LIMIT {limite_linhas}"
    cur.execute(sql, tuple(params))
    notas = _estoque_xml_agrupar_notas(cur.fetchall() or [])
    if nota_key and nota_key in notas:
        return {nota_key: notas[nota_key]}
    return notas


def _estoque_xml_referencias_lancadas(cur, referencia_ids=None):
    ids = sorted(
        {
            _as_int(valor, 0)
            for valor in (referencia_ids or [])
            if _as_int(valor, 0) > 0
        }
    )
    filtro = ""
    params = [_ESTOQUE_XML_REFERENCIA]
    if ids:
        filtro = " AND referencia_id IN (" + ",".join(["%s"] * len(ids)) + ")"
        params.extend(ids)
    cur.execute(
        f"""
        SELECT referencia_id
        FROM estoque_movimentos
        WHERE referencia_tipo=%s AND referencia_id IS NOT NULL
        {filtro}
        """,
        tuple(params),
    )
    return {
        _as_int(row.get("referencia_id"), 0)
        for row in (cur.fetchall() or [])
        if _as_int(row.get("referencia_id"), 0) > 0
    }


def _estoque_xml_destinos_manutencao(cur, nota_keys=None):
    keys = []
    if nota_keys:
        for valor in nota_keys:
            key = _as_str(valor)
            if key and key not in keys:
                keys.append(key)

    params = []
    where = "WHERE COALESCE(status, '') NOT IN ('descartado', 'devolvido_estoque')"
    if keys:
        where += " AND nota_key IN (" + ",".join(["%s"] * len(keys)) + ")"
        params.extend(keys)

    cur.execute(
        f"""
        SELECT id, nota_key, status, manutencao_id
        FROM manutencao_xml_pre_lancamentos
        {where}
        """,
        tuple(params),
    )
    return {
        _as_str(row.get("nota_key")): row
        for row in (cur.fetchall() or [])
        if _as_str(row.get("nota_key"))
    }


def _estoque_xml_pre_lancamentos_manutencao_status(cur, nota_keys=None):
    keys = []
    if nota_keys:
        for valor in nota_keys:
            key = _as_str(valor)
            if key and key not in keys:
                keys.append(key)

    params = []
    where = ""
    if keys:
        where = "WHERE nota_key IN (" + ",".join(["%s"] * len(keys)) + ")"
        params.extend(keys)

    cur.execute(
        f"""
        SELECT id, nota_key, status, manutencao_id
        FROM manutencao_xml_pre_lancamentos
        {where}
        """,
        tuple(params),
    )
    return {
        _as_str(row.get("nota_key")): row
        for row in (cur.fetchall() or [])
        if _as_str(row.get("nota_key"))
    }


def _estoque_xml_regra_hash(*partes):
    texto = "\x1f".join(_as_str(parte) for parte in partes)
    return hashlib.sha1(texto.encode("utf-8", "ignore")).hexdigest()


def _estoque_xml_emitente_info(row):
    row = row or {}
    cnpj = re.sub(r"\D+", "", _as_str(row.get("emitente_cnpj") or row.get("cnpj")))
    nome = re.sub(r"\s+", " ", _as_str(row.get("emitente_nome") or row.get("nome"))).strip()
    if cnpj:
        chave = f"cnpj:{cnpj}"
    elif nome:
        chave = f"nome:{_normalizar_chave_texto(nome)}"
    else:
        chave = ""
    return {
        "emitente_cnpj": cnpj,
        "emitente_nome": nome,
        "emitente_chave": chave[:255],
        "emitente_hash": _estoque_xml_regra_hash(chave) if chave else "",
    }

def _estoque_xml_item_classificacao_key(row):
    return _estoque_xml_nome_produto_key(
        (row or {}).get("descricao_produto")
        or (row or {}).get("nome_produto")
    )


def _estoque_xml_carregar_regras_classificacao(cur):
    cur.execute(
        """
        SELECT id, escopo, regra_chave, regra_rotulo,
               destino_importacao, ativo
        FROM estoque_xml_classificacao_regras
        WHERE ativo=1
        ORDER BY atualizado_em DESC, id DESC
        """
    )
    return cur.fetchall() or []


def _estoque_xml_sugestao_classificacao(nota, regras):
    canonicos = (nota or {}).get("canonicos") or []
    base = canonicos[0] if canonicos else {}
    emitente_hash = _as_str(
        _estoque_xml_emitente_info(base).get("emitente_hash")
    )
    itens_keys = {
        _estoque_xml_item_classificacao_key(row)
        for row in canonicos
        if _estoque_xml_item_classificacao_key(row)
    }
    for regra in regras or []:
        escopo = _as_str(regra.get("escopo"))
        chave = _as_str(regra.get("regra_chave"))
        corresponde = (
            escopo == "empresa" and chave == emitente_hash
        ) or (
            escopo == "item" and chave in itens_keys
        )
        if corresponde:
            return {
                "regra_id": _as_int(regra.get("id"), 0),
                "escopo": escopo,
                "rotulo": _as_str(regra.get("regra_rotulo")),
                "destino": _as_str(regra.get("destino_importacao")),
            }
    return {}


def _estoque_xml_registrar_regras_classificacao(
    cur,
    notas,
    destino,
    escopo,
    usuario="",
):
    destino = _as_str(destino).lower()
    escopo = _as_str(escopo).lower()
    if destino not in {"estoque", "manutencao"}:
        raise ValueError("destino de classificacao invalido")
    if escopo not in {"empresa", "item"}:
        raise ValueError("escopo deve ser empresa ou item")
    registradas = 0
    for nota in notas or []:
        canonicos = (nota or {}).get("canonicos") or []
        base = canonicos[0] if canonicos else {}
        regras_nota = []
        if escopo == "empresa":
            info = _estoque_xml_emitente_info(base)
            chave = _as_str(info.get("emitente_hash"))
            if chave:
                regras_nota.append(
                    (chave, _as_str(info.get("emitente_nome")))
                )
        else:
            vistos = set()
            for row in canonicos:
                chave = _estoque_xml_item_classificacao_key(row)
                if chave and chave not in vistos:
                    vistos.add(chave)
                    regras_nota.append(
                        (chave, _as_str(row.get("descricao_produto")))
                    )
        for chave, rotulo in regras_nota:
            cur.execute(
                """
                INSERT INTO estoque_xml_classificacao_regras (
                    escopo, regra_chave, regra_rotulo,
                    destino_importacao, ativo, usuario_registro,
                    criado_em, atualizado_em
                )
                VALUES (%s,%s,%s,%s,1,%s,NOW(),NOW())
                ON DUPLICATE KEY UPDATE
                    regra_rotulo=VALUES(regra_rotulo),
                    destino_importacao=VALUES(destino_importacao),
                    ativo=1,
                    usuario_registro=VALUES(usuario_registro),
                    atualizado_em=NOW()
                """,
                (
                    escopo,
                    chave[:255],
                    rotulo[:255],
                    destino,
                    _as_str(usuario)[:180],
                ),
            )
            registradas += 1
    return registradas


def _estoque_xml_codigo_regra(valor):
    return _as_str(_codigo_produto_nfe_saida(valor)).strip().upper()[:120]


def _estoque_xml_nome_produto_key(valor):
    return (_produto_nome_normalizado(valor) or _normalizar_chave_texto(valor)).strip()[:180]


def _estoque_xml_embalagem_regra(*valores):
    return (
        _estoque_apresentacao_normalizada(*valores)
        or _as_str(next((valor for valor in valores if _as_str(valor)), ""))
    ).strip().upper()[:30]


def _atualizar_fornecedor_categoria_manutencao(cur, emitente_info):
    cnpj = _as_str((emitente_info or {}).get("emitente_cnpj"))
    if not cnpj:
        return False
    nome = _as_str((emitente_info or {}).get("emitente_nome"))[:255]
    try:
        cur.execute(
            """
            UPDATE gestor_email_fornecedores
            SET categoria='manutencao',
                updated_at=NOW()
            WHERE BINARY cnpj = BINARY %s
            """,
            (cnpj,),
        )
        if cur.rowcount > 0:
            return True
        cur.execute(
            """
            INSERT INTO gestor_email_fornecedores (
                cnpj, nome, categoria, ativo, origem, created_at, updated_at
            )
            VALUES (%s, %s, 'manutencao', 1, 'xml_estoque', NOW(), NOW())
            ON DUPLICATE KEY UPDATE
                nome=COALESCE(NULLIF(nome, ''), VALUES(nome)),
                categoria='manutencao',
                ativo=1,
                updated_at=NOW()
            """,
            (cnpj, nome),
        )
        return True
    except Exception:
        return False


def _registrar_regra_fornecedor_manutencao_xml(
    cur,
    dados_emitente,
    usuario="",
    motivo="",
):
    info = _estoque_xml_emitente_info(dados_emitente)
    emitente_hash = _as_str(info.get("emitente_hash"))
    if not emitente_hash:
        return False
    motivo_final = (
        _as_str(motivo)
        or "Fornecedor marcado como manutencao ao direcionar uma NF-e."
    )[:500]
    cur.execute(
        """
        INSERT INTO estoque_xml_fornecedor_regras (
            emitente_hash, emitente_chave, emitente_cnpj, emitente_nome,
            destino_importacao, motivo, usuario_registro, criado_em, atualizado_em
        )
        VALUES (%s, %s, %s, %s, 'manutencao', %s, %s, NOW(), NOW())
        ON DUPLICATE KEY UPDATE
            emitente_chave=VALUES(emitente_chave),
            emitente_cnpj=VALUES(emitente_cnpj),
            emitente_nome=VALUES(emitente_nome),
            destino_importacao='manutencao',
            motivo=VALUES(motivo),
            usuario_registro=VALUES(usuario_registro),
            atualizado_em=NOW()
        """,
        (
            emitente_hash,
            _as_str(info.get("emitente_chave"))[:255],
            _as_str(info.get("emitente_cnpj"))[:32],
            _as_str(info.get("emitente_nome"))[:255],
            motivo_final,
            _as_str(usuario)[:180],
        ),
    )
    _atualizar_fornecedor_categoria_manutencao(cur, info)
    return True


def _carregar_regras_fornecedor_manutencao_xml(cur):
    try:
        cur.execute(
            """
            SELECT emitente_hash
            FROM estoque_xml_fornecedor_regras
            WHERE destino_importacao='manutencao'
            """
        )
        return {
            _as_str(row.get("emitente_hash"))
            for row in (cur.fetchall() or [])
            if _as_str(row.get("emitente_hash"))
        }
    except Exception:
        return set()


def _registrar_regra_fator_fornecedor_xml(
    cur,
    dados_emitente,
    codigo_produto_nfe="",
    nome_produto="",
    embalagem_tipo="",
    fator_embalagem=0,
    grupo_estoque="",
    produto_base_nome="",
    usuario="",
):
    info = _estoque_xml_emitente_info(dados_emitente)
    emitente_hash = _as_str(info.get("emitente_hash"))
    fator = _as_float(fator_embalagem, 0.0)
    if not emitente_hash or fator <= 0:
        return False

    codigo = _estoque_xml_codigo_regra(codigo_produto_nfe)
    nome_key = _estoque_xml_nome_produto_key(nome_produto)
    embalagem = _estoque_xml_embalagem_regra(embalagem_tipo, nome_produto)
    if not (codigo or nome_key):
        return False
    regra_hash = _estoque_xml_regra_hash(
        emitente_hash,
        codigo,
        nome_key,
        embalagem,
    )
    cur.execute(
        """
        INSERT INTO estoque_xml_fator_regras (
            regra_hash, emitente_hash, emitente_chave, emitente_cnpj,
            emitente_nome, codigo_produto_nfe, nome_produto_key, nome_produto,
            embalagem_tipo, fator_embalagem, grupo_estoque, produto_base_nome,
            usuario_registro, criado_em, atualizado_em
        )
        VALUES (%s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, NOW(), NOW())
        ON DUPLICATE KEY UPDATE
            emitente_chave=VALUES(emitente_chave),
            emitente_cnpj=VALUES(emitente_cnpj),
            emitente_nome=VALUES(emitente_nome),
            codigo_produto_nfe=VALUES(codigo_produto_nfe),
            nome_produto_key=VALUES(nome_produto_key),
            nome_produto=VALUES(nome_produto),
            embalagem_tipo=VALUES(embalagem_tipo),
            fator_embalagem=VALUES(fator_embalagem),
            grupo_estoque=VALUES(grupo_estoque),
            produto_base_nome=VALUES(produto_base_nome),
            usuario_registro=VALUES(usuario_registro),
            atualizado_em=NOW()
        """,
        (
            regra_hash,
            emitente_hash,
            _as_str(info.get("emitente_chave"))[:255],
            _as_str(info.get("emitente_cnpj"))[:32],
            _as_str(info.get("emitente_nome"))[:255],
            codigo,
            nome_key,
            _as_str(nome_produto)[:255],
            embalagem,
            fator,
            _estoque_grupo_normalizado(grupo_estoque) or "",
            _as_str(produto_base_nome)[:255],
            _as_str(usuario)[:180],
        ),
    )
    return True


def _carregar_regras_fator_fornecedor_xml(cur, dados_emitente):
    info = _estoque_xml_emitente_info(dados_emitente)
    emitente_hash = _as_str(info.get("emitente_hash"))
    if not emitente_hash:
        return []
    try:
        cur.execute(
            """
            SELECT
                codigo_produto_nfe, nome_produto_key, nome_produto,
                embalagem_tipo, fator_embalagem, grupo_estoque,
                produto_base_nome
            FROM estoque_xml_fator_regras
            WHERE emitente_hash=%s AND fator_embalagem > 0
            ORDER BY atualizado_em DESC, id DESC
            """,
            (emitente_hash,),
        )
        return cur.fetchall() or []
    except Exception:
        return []


def _selecionar_regra_fator_xml(regras, row, item_preview):
    if not regras:
        return None
    codigo = _estoque_xml_codigo_regra(
        item_preview.get("codigo_produto_nfe") or row.get("codigo_produto")
    )
    nome_key = _estoque_xml_nome_produto_key(
        item_preview.get("nome_produto") or row.get("descricao_produto")
    )
    embalagem = _estoque_xml_embalagem_regra(
        item_preview.get("embalagem_tipo"),
        row.get("unidade"),
        item_preview.get("nome_produto"),
    )
    melhor = None
    melhor_score = 0
    for regra in regras:
        score = 0
        regra_codigo = _estoque_xml_codigo_regra(regra.get("codigo_produto_nfe"))
        regra_nome_key = _as_str(regra.get("nome_produto_key"))
        regra_embalagem = _estoque_xml_embalagem_regra(regra.get("embalagem_tipo"))
        if codigo and regra_codigo and codigo == regra_codigo:
            score += 6
        if nome_key and regra_nome_key and nome_key == regra_nome_key:
            score += 3
        if score <= 0:
            continue
        if regra_embalagem and embalagem and regra_embalagem == embalagem:
            score += 2
        elif regra_embalagem and embalagem and regra_embalagem != embalagem:
            score -= 1
        if score > melhor_score:
            melhor = regra
            melhor_score = score
    return melhor


def _aplicar_regra_fator_item_xml(item_preview, regra):
    if not regra:
        return item_preview
    fator = _as_float(regra.get("fator_embalagem"), 0.0)
    if fator <= 0:
        return item_preview
    quantidade = _as_float(item_preview.get("quantidade_embalagem"), _as_float(item_preview.get("quantidade"), 0.0))
    item = dict(item_preview or {})
    grupo = _estoque_grupo_normalizado(regra.get("grupo_estoque"))
    if grupo:
        item["grupo_estoque"] = grupo
    if _as_str(regra.get("produto_base_nome")):
        item["produto_base_nome"] = _as_str(regra.get("produto_base_nome"))
    item["embalagem_tipo"] = _as_str(regra.get("embalagem_tipo")) or item.get("embalagem_tipo") or item.get("unidade")
    item["fator_embalagem"] = fator
    item["fator_inferido"] = 0
    item["quantidade_unidades"] = quantidade * fator if quantidade > 0 else _as_float(item.get("quantidade_unidades"), 0.0)
    item["regra_fator_fornecedor"] = 1
    return item


def _aplicar_regras_fornecedor_manutencao_xml(cur, notas, referencias_lancadas, usuario=""):
    regras = _carregar_regras_fornecedor_manutencao_xml(cur)
    if not regras:
        return 0
    destinos = _estoque_xml_destinos_manutencao(cur)
    pre_lancamentos = _estoque_xml_pre_lancamentos_manutencao_status(cur)
    criados = 0
    for nota in (notas or {}).values():
        resumo = _estoque_xml_nota_publica(nota, referencias_lancadas)
        nota_key = _as_str(resumo.get("nota_key"))
        if not nota_key or destinos.get(nota_key):
            continue
        status_previo = _as_str((pre_lancamentos.get(nota_key) or {}).get("status"))
        if status_previo in {"descartado", "devolvido_estoque", "confirmado"}:
            continue
        if resumo.get("status") != "pendente" or resumo.get("tipo_movimento") != "entrada":
            continue
        info = _estoque_xml_emitente_info(resumo)
        if _as_str(info.get("emitente_hash")) not in regras:
            continue
        preview = _estoque_xml_preview(cur, nota, referencias_lancadas)
        pre_lancamento_id = _registrar_pre_lancamento_manutencao_preview(
            cur,
            preview,
            nota_key_override=nota_key,
            origem_veiculo="fornecedor_manutencao",
            motivo=(
                "Nota enviada automaticamente para manutencao porque o "
                "fornecedor foi classificado como manutencao."
            ),
        )
        if pre_lancamento_id:
            destinos[nota_key] = {"id": pre_lancamento_id, "nota_key": nota_key}
            criados += 1
    return criados


def _estoque_xml_nota_publica(nota, referencias_lancadas):
    canonicos = nota.get("canonicos") or []
    base = canonicos[0] if canonicos else {}
    total = len(canonicos)
    lancados = sum(
        1
        for row in canonicos
        if _as_int(row.get("id"), 0) in referencias_lancadas
    )
    status = "consolidado" if total > 0 and lancados == total else (
        "parcial" if lancados > 0 else "pendente"
    )
    tipo_origem = _as_str(base.get("tipo_movimento")).upper()
    tipo_movimento = "saida" if tipo_origem == "SAIDA_ESTOQUE" else "entrada"
    emitente_fantasia = _estoque_xml_emitente_fantasia(base)
    itens_preview = []
    for row in canonicos:
        nome_item = _as_str(row.get("descricao_produto"))
        if not nome_item:
            continue
        itens_preview.append(
            {
                "nome": nome_item,
                "quantidade": _as_float(row.get("quantidade"), 0.0),
                "unidade": _as_str(row.get("unidade")),
            }
        )
        if len(itens_preview) >= 4:
            break
    return {
        "nota_key": nota.get("nota_key"),
        "chave_nfe": _as_str(base.get("chave_nfe")),
        "numero_nota": _as_str(base.get("numero_nota")),
        "serie": _as_str(base.get("serie")),
        "data_emissao": _as_str(base.get("data_emissao")),
        "emitente_nome": _as_str(base.get("emitente_nome")),
        "emitente_fantasia": emitente_fantasia or _as_str(base.get("emitente_nome")),
        "emitente_cnpj": _as_str(base.get("emitente_cnpj")),
        "destinatario_nome": _as_str(base.get("destinatario_nome")),
        "destinatario_cnpj": _as_str(base.get("destinatario_cnpj")),
        "natureza_operacao": _as_str(base.get("natureza_operacao")),
        "tipo_movimento": tipo_movimento,
        "tipo_movimento_origem": tipo_origem,
        "status": status,
        "total_itens": total,
        "itens_lancados": lancados,
        "itens_pendentes": max(0, total - lancados),
        "itens_preview": itens_preview,
        "arquivos_repetidos": len(nota.get("arquivo_ids") or []),
        "valor_total_nota": _as_float(base.get("valor_total_nota"), 0.0),
        "arquivo_origem": _as_str(base.get("arquivo_origem")),
    }

def _sincronizar_dados_viagem_xml_frete(cur, frete_id, veiculo_id=0):
    frete_id = _as_int(frete_id, 0)
    if frete_id <= 0:
        return {}
    cur.execute(
        """
        SELECT f.veiculo_id, f.carga_id, f.cidade, f.nome,
               f.km_atual, f.peso, f.qtd_entregas,
               c.peso_total AS carga_peso_total,
               c.numero_entregas AS carga_numero_entregas,
               c.clientes_distintos AS carga_clientes_distintos
        FROM fretes f
        LEFT JOIN cargas c ON c.id=f.carga_id
        WHERE f.id=%s
        LIMIT 1
        """,
        (frete_id,),
    )
    frete = cur.fetchone() or {}
    if not frete:
        return {}

    veiculo_id = _as_int(veiculo_id, 0) or _as_int(frete.get("veiculo_id"), 0)
    km_veiculo = _buscar_km_atual_veiculo(cur, veiculo_id)
    cur.execute(
        """
        SELECT COUNT(DISTINCT nota_key) AS total
        FROM (
            SELECT nota_key
            FROM estoque_xml_frete_vinculos
            WHERE frete_id=%s
            UNION ALL
            SELECT nota_key
            FROM estoque_xml_frete_pre_vinculos
            WHERE frete_id=%s
              AND COALESCE(status, '') NOT IN (
                  'cancelado', 'cancelada', 'descartado', 'descartada',
                  'ignorado', 'ignorada', 'dispensado'
              )
        ) notas_frete
        """,
        (frete_id, frete_id),
    )
    total_xml = _as_int((cur.fetchone() or {}).get("total"), 0)
    resumo = _resolver_resumo_viagem_frete(
        frete.get("km_atual"),
        km_veiculo,
        frete.get("qtd_entregas"),
        total_xml,
        frete.get("peso"),
        frete.get("carga_peso_total"),
        (
            _as_int(frete.get("carga_numero_entregas"), 0)
            or _as_int(frete.get("carga_clientes_distintos"), 0)
        ),
    )
    rota = (
        _as_str(frete.get("cidade"))
        or _as_str(frete.get("nome"))
    )
    cur.execute(
        """
        UPDATE fretes
        SET veiculo_id=COALESCE(veiculo_id, %s),
            km_atual=%s,
            peso=%s,
            qtd_entregas=%s
        WHERE id=%s
        """,
        (
            veiculo_id or None,
            resumo["km_atual"],
            resumo["peso"],
            resumo["qtd_entregas"],
            frete_id,
        ),
    )
    if veiculo_id > 0:
        cur.execute(
            """
            UPDATE estoque_xml_frete_pre_vinculos
            SET veiculo_id=%s,
                origem_veiculo=CASE
                    WHEN TRIM(COALESCE(origem_veiculo, '')) IN ('', 'nao_identificado')
                    THEN 'kanban_manual'
                    ELSE origem_veiculo
                END,
                atualizado_em=NOW()
            WHERE frete_id=%s
            """,
            (veiculo_id, frete_id),
        )
        cur.execute(
            """
            UPDATE estoque_xml_frete_vinculos
            SET veiculo_id=%s,
                carga_id=COALESCE(carga_id, %s),
                rota_registrada=CASE
                    WHEN TRIM(COALESCE(rota_registrada, ''))='' THEN %s
                    ELSE rota_registrada
                END
            WHERE frete_id=%s
            """,
            (
                veiculo_id,
                _as_int(frete.get("carga_id"), 0) or None,
                rota,
                frete_id,
            ),
        )
    return {
        **resumo,
        "veiculo_id": veiculo_id or None,
        "total_xml": total_xml,
    }

def _registrar_rota_frete_arquivado(cur, frete_id):
    frete_id = _as_int(frete_id, 0)
    if frete_id <= 0:
        return {}
    cur.execute(
        """
        SELECT f.cidade, c.cidade AS carga_cidade, c.rota AS carga_rota,
               cil.carga_cidades
        FROM fretes f
        LEFT JOIN cargas c ON c.id=f.carga_id
        LEFT JOIN (
            SELECT carga_id, GROUP_CONCAT(DISTINCT cidade SEPARATOR '\n') AS carga_cidades
            FROM cargas_import_linhas
            WHERE TRIM(COALESCE(cidade, ''))<>''
            GROUP BY carga_id
        ) cil ON cil.carga_id=c.id
        WHERE f.id=%s
        LIMIT 1
        """,
        (frete_id,),
    )
    frete = cur.fetchone() or {}
    cidades = _frete_cidades_lista(
        frete.get("cidade"),
        frete.get("carga_cidade"),
        frete.get("carga_rota"),
        frete.get("carga_cidades"),
    )
    cur.execute(
        """
        SELECT nota_key
        FROM estoque_xml_frete_vinculos
        WHERE frete_id=%s
        UNION
        SELECT nota_key
        FROM estoque_xml_frete_pre_vinculos
        WHERE frete_id=%s
          AND COALESCE(status, '') NOT IN (
              'cancelado', 'cancelada', 'descartado', 'descartada',
              'ignorado', 'ignorada', 'dispensado'
          )
        """,
        (frete_id, frete_id),
    )
    for row in cur.fetchall() or []:
        nota_key = _as_str(row.get("nota_key"))
        nota = (_estoque_xml_carregar_notas(cur, nota_key) or {}).get(nota_key)
        if not nota:
            continue
        cidades = _frete_cidades_lista(
            cidades,
            *[
                _estoque_xml_cidade_destinatario(item)
                for item in (nota.get("canonicos") or [])
            ],
        )
    if len(cidades) < 2:
        return {}

    chaves = {_normalizar_chave_texto(cidade) for cidade in cidades}
    cur.execute(
        "SELECT id, nome, cidades FROM cargas_rotas WHERE ativo=1 ORDER BY id"
    )
    rota_existente = None
    for rota in cur.fetchall() or []:
        cidades_rota = _cargas_rota_cidades_lista(rota.get("cidades"))
        chaves_rota = {
            _normalizar_chave_texto(cidade)
            for cidade in cidades_rota
            if _normalizar_chave_texto(cidade)
        }
        if chaves & chaves_rota:
            rota_existente = rota
            cidades = _frete_cidades_lista(cidades_rota, cidades)
            break

    nome = " - ".join(cidades)[:220]
    cidades_texto = "\n".join(cidades)
    if rota_existente:
        cur.execute(
            """
            UPDATE cargas_rotas
            SET nome=%s, cidades=%s, ativo=1, atualizado_em=NOW()
            WHERE id=%s
            """,
            (nome, cidades_texto, _as_int(rota_existente.get("id"), 0)),
        )
        rota_id = _as_int(rota_existente.get("id"), 0)
    else:
        cur.execute(
            """
            INSERT INTO cargas_rotas (nome, cidades, ativo, criado_em, atualizado_em)
            VALUES (%s, %s, 1, NOW(), NOW())
            ON DUPLICATE KEY UPDATE
                cidades=VALUES(cidades),
                ativo=1,
                atualizado_em=NOW()
            """,
            (nome, cidades_texto),
        )
        rota_id = _as_int(cur.lastrowid, 0)
    return {"id": rota_id or None, "nome": nome, "cidades": cidades}


def _cargas_rota_cidades_lista(valor):
    partes = []
    if isinstance(valor, (list, tuple)):
        candidatos = valor
    else:
        candidatos = re.split(r"(?:\r?\n|[;,|])+", _as_str(valor))
    vistos = set()
    for item in candidatos:
        cidade = re.sub(r"\s+", " ", _as_str(item)).strip()
        if not cidade:
            continue
        chave = cidade.lower()
        if chave in vistos:
            continue
        vistos.add(chave)
        partes.append(cidade)
    return partes


def _cargas_rota_publica(row):
    row = row or {}
    cidades = _cargas_rota_cidades_lista(row.get("cidades"))
    return {
        "id": _as_int(row.get("id"), 0),
        "nome": _as_str(row.get("nome")),
        "cidades": cidades,
        "cidades_texto": "\n".join(cidades),
        "ativo": bool(_as_int(row.get("ativo"), 1)),
        "criado_em": _fmt_dt(row.get("criado_em")),
        "atualizado_em": _fmt_dt(row.get("atualizado_em")),
    }


def migrar_importacoes_xml_fretes(
    dry_run=False,
    emitente_nome_filtro="",
    criar_sem_veiculo=False,
    importado_desde=None,
):
    conn = get_conn()
    cur = conn.cursor(dictionary=True)
    resumo = {
        "notas_saida": 0,
        "pre_vinculos_criados": 0,
        "fretes_criados": 0,
        "veiculos_vinculados": 0,
        "cards_sem_veiculo": 0,
        "retiradas_cliente": 0,
        "cards_arquivados": 0,
        "simulacao": bool(dry_run),
    }
    try:
        notas = _estoque_xml_carregar_notas(cur)
        referencias_lancadas = _estoque_xml_referencias_lancadas(cur)
        for nota in notas.values():
            canonicos = nota.get("canonicos") or []
            base = canonicos[0] if canonicos else {}
            if _as_str(base.get("tipo_movimento")).upper() != "SAIDA_ESTOQUE":
                continue
            if importado_desde:
                criado_em = base.get("criado_em")
                data_importacao = (
                    criado_em.date()
                    if isinstance(criado_em, datetime.datetime)
                    else _as_date(criado_em)
                )
                if not data_importacao or data_importacao < importado_desde:
                    continue
            if emitente_nome_filtro:
                emitente = _normalizar_chave_texto(base.get("emitente_nome"))
                filtro = _normalizar_chave_texto(emitente_nome_filtro)
                if filtro not in emitente:
                    continue
            resumo["notas_saida"] += 1
            nota_key = _as_str(nota.get("nota_key"))
            cur.execute(
                """
                SELECT id
                FROM estoque_xml_frete_pre_vinculos
                WHERE nota_key=%s
                  AND frete_id IS NOT NULL
                  AND COALESCE(status, 'pendente') NOT IN (
                    'cancelado', 'cancelada',
                    'descartado', 'descartada',
                    'ignorado', 'ignorada',
                    'dispensado', 'confirmado_sem_frete'
                  )
                LIMIT 1
                """,
                (nota_key,),
            )
            pre_ativo_com_frete = cur.fetchone()
            cur.execute(
                """
                SELECT id
                FROM estoque_xml_frete_vinculos
                WHERE nota_key=%s
                LIMIT 1
                """,
                (nota_key,),
            )
            vinculo_existente = cur.fetchone()
            itens_consolidados = canonicos and all(
                _as_int(row.get("id"), 0) in referencias_lancadas
                for row in canonicos
            )
            if itens_consolidados:
                if not pre_ativo_com_frete and not vinculo_existente:
                    continue
            elif not pre_ativo_com_frete and not vinculo_existente:
                transporte = _estoque_xml_extrair_transporte(cur, nota)
                decisao_automatica = _estoque_xml_detectar_dispensa_frete(transporte)
                veiculo_resolvido = _estoque_xml_resolver_veiculo(cur, transporte)
                veiculo_id = _as_int(veiculo_resolvido.get("veiculo_id"), 0)
                sugestao = _estoque_xml_sugerir_frete(cur, transporte, veiculo_id)
                if (
                    not criar_sem_veiculo
                    and
                    not decisao_automatica.get("dispensa_frete")
                    and veiculo_id <= 0
                    and _as_int(sugestao.get("frete_id"), 0) <= 0
                ):
                    continue
            preparado = _estoque_xml_preparar_vinculo(
                cur,
                nota,
                usuario="deploy_xml",
            )
            if preparado.get("pre_vinculo_criado"):
                resumo["pre_vinculos_criados"] += 1
            if preparado.get("frete_criado"):
                resumo["fretes_criados"] += 1
            if preparado.get("dispensa_frete"):
                resumo["retiradas_cliente"] += 1
                if preparado.get("card_arquivado"):
                    resumo["cards_arquivados"] += 1
            elif _as_int(preparado.get("veiculo_id"), 0) > 0:
                resumo["veiculos_vinculados"] += 1
            else:
                resumo["cards_sem_veiculo"] += 1
        if dry_run:
            conn.rollback()
        else:
            conn.commit()
    except Exception:
        conn.rollback()
        raise
    finally:
        cur.close()
        conn.close()
    return resumo


@app.route("/api/fretes/importar-xml-saidas-white-river", methods=["POST"])
def importar_fretes_xml_saidas_white_river():
    try:
        resumo = migrar_importacoes_xml_fretes(
            dry_run=False,
            emitente_nome_filtro="BEBIDAS WHITE RIVER",
            criar_sem_veiculo=True,
            importado_desde=datetime.date.today(),
        )
        return jsonify({"ok": True, **resumo})
    except Exception as exc:
        app.logger.exception(
            "Falha ao importar fretes das NF-e de saida da White River"
        )
        return jsonify({"erro": str(exc)}), 500


def _estoque_xml_preview(cur, nota, referencias_lancadas):
    resumo = _estoque_xml_nota_publica(nota, referencias_lancadas)
    regras_fator_fornecedor = _carregar_regras_fator_fornecedor_xml(cur, resumo)
    transporte_xml = {}
    frete_sugestao = {}
    frete_id = 0
    veiculo_id = 0
    dispensa_frete = False
    pre_vinculo = {}
    if resumo.get("tipo_movimento") == "saida":
        pre_vinculo = _estoque_xml_preparar_vinculo(cur, nota)
        transporte_xml = pre_vinculo.get("transporte_xml") or {}
        frete_sugestao = pre_vinculo.get("frete_sugestao") or {}
        frete_id = _as_int(pre_vinculo.get("frete_id"), 0)
        veiculo_id = _as_int(pre_vinculo.get("veiculo_id"), 0)
        dispensa_frete = bool(pre_vinculo.get("dispensa_frete"))
    itens = []
    for idx, row in enumerate(nota.get("canonicos") or [], start=1):
        xml_item_id = _as_int(row.get("id"), 0)
        if xml_item_id in referencias_lancadas:
            continue
        item_preview = {
            "xml_item_id": xml_item_id,
            "item_seq": _estoque_xml_item_seq(row) or str(idx),
            "produto_id": 0,
            "codigo_produto_nfe": _as_str(row.get("codigo_produto")),
            "codigo_barras": "",
            "nome_produto": _as_str(row.get("descricao_produto")),
            "unidade": _as_str(row.get("unidade")),
            "embalagem_tipo": _as_str(row.get("unidade")),
            "quantidade": _as_float(row.get("quantidade"), 0.0),
            "quantidade_embalagem": _as_float(row.get("quantidade"), 0.0),
            "fator_embalagem": 1,
            "fator_inferido": 0,
            "quantidade_unidades": _as_float(row.get("quantidade"), 0.0),
            "valor_unitario": _as_float(row.get("valor_unitario"), 0.0),
            "valor_total": _as_float(row.get("valor_total_item"), 0.0),
        }
        regra_fator = _selecionar_regra_fator_xml(
            regras_fator_fornecedor,
            row,
            item_preview,
        )
        itens.append(_aplicar_regra_fator_item_xml(item_preview, regra_fator))
    repetidos = max(0, _as_int(resumo.get("arquivos_repetidos"), 0) - 1)
    warnings = [
        (
            "Esta importacao ainda nao altera o saldo. O estoque sera "
            "contabilizado somente depois da confirmacao."
        )
    ]
    if repetidos:
        warnings.append(
            f"Foram detectados {repetidos} upload(s) repetido(s) desta NF-e; "
            "somente uma copia de cada item sera considerada."
        )
    if resumo.get("tipo_movimento") == "saida":
        if dispensa_frete:
            warnings.append(
                "Saida identificada como retirada ou transporte pelo cliente. "
                "A baixa nao exigira frete, rota ou veiculo da empresa."
            )
        elif frete_id:
            warnings.append(
                "O frete foi sugerido pelos dados de transporte do XML. "
                "Revise e altere o vinculo se necessario."
            )
        else:
            warnings.append(
                "Nao foi possivel sugerir um frete ativo com seguranca; "
                "o vinculo deve ser selecionado manualmente."
            )
    return {
        "source_type": "importar_xml",
        "preview_tipo": "completo",
        "importar_xml_chave": nota.get("nota_key"),
        "frete_id": frete_id,
        "veiculo_id": veiculo_id,
        "dispensa_frete": dispensa_frete,
        "tipo_transporte": _as_str(pre_vinculo.get("tipo_transporte")),
        "decisao_logistica": {
            "origem": _as_str(
                pre_vinculo.get("origem_decisao_logistica")
            ),
            "motivo": _as_str(
                pre_vinculo.get("motivo_decisao_logistica")
            ),
        },
        "pre_vinculo_frete": {
            "origem_veiculo": _as_str(pre_vinculo.get("origem_veiculo")),
            "origem_frete": _as_str(pre_vinculo.get("origem_frete")),
            "status": _as_str(pre_vinculo.get("status")),
        },
        "transporte_xml": transporte_xml,
        "frete_sugestao": frete_sugestao,
        "tipo_movimento": resumo.get("tipo_movimento"),
        "arquivo_origem": resumo.get("arquivo_origem"),
        "numero_nota": resumo.get("numero_nota"),
        "serie": resumo.get("serie"),
        "chave_acesso": resumo.get("chave_nfe"),
        "data_emissao": _normalizar_data_documento(resumo.get("data_emissao")),
        "emitente_nome": resumo.get("emitente_nome"),
        "emitente_cnpj": resumo.get("emitente_cnpj"),
        "destinatario_nome": resumo.get("destinatario_nome"),
        "destinatario_cnpj": resumo.get("destinatario_cnpj"),
        "valor_total": resumo.get("valor_total_nota"),
        "warnings": warnings,
        "itens": itens,
    }


