@app.route("/api/estoque/produtos/<int:produto_id>/ajuste", methods=["POST"])
def ajustar_produto_estoque(produto_id):
    bloqueio = _exigir_admin_portal()
    if bloqueio:
        return bloqueio
    usuario = _usuario_ator_req()
    data = request.json or {}
    motivo = _as_str(data.get("motivo_ajuste") or data.get("motivo"))
    if not motivo:
        return jsonify({"erro": "informe o motivo do acerto de estoque"}), 400

    conn = get_conn()
    cur = conn.cursor(dictionary=True)
    try:
        produto = _carregar_produto_estoque_por_id(cur, produto_id)
        if not produto:
            return jsonify({"erro": "produto nao encontrado"}), 404

        saldo_antes = _saldo_atual_produto_estoque(
            cur,
            codigo_barras=produto.get("codigo_barras"),
            codigo_produto_nfe=produto.get("codigo_produto_nfe"),
            nome_produto=produto.get("nome_produto"),
        )
        if "quantidade_atual" in data:
            quantidade_desejada = round(_as_float(data.get("quantidade_atual"), saldo_antes), 3)
            if quantidade_desejada < 0:
                return jsonify({"erro": "a quantidade atual nao pode ser negativa"}), 400
            quantidade_ajuste = round(quantidade_desejada - saldo_antes, 3)
        else:
            quantidade_ajuste = round(_as_float(data.get("quantidade_ajuste"), 0.0), 3)
            quantidade_desejada = round(saldo_antes + quantidade_ajuste, 3)
        if abs(quantidade_ajuste) <= 0:
            return jsonify({"erro": "a quantidade informada ja corresponde ao saldo atual"}), 400
        tipo_movimento = "entrada" if quantidade_ajuste > 0 else "saida"
        quantidade_movimento = abs(round(quantidade_ajuste, 3))
        numero_nota = f"AJUSTE-{produto_id}"
        if motivo:
            numero_nota = f"{numero_nota} - {motivo[:80]}"

        cur.execute(
            """
            INSERT INTO estoque_movimentos
                (
                    codigo_barras, codigo_produto_nfe, numero_nota, nome_produto, quantidade, valor_unitario, tipo_movimento,
                    origem_setor, destino_setor, referencia_tipo, referencia_id, usuario_registro
                )
            VALUES
                (%s, %s, %s, %s, %s, %s, %s, %s, %s, 'ajuste_cadastro', %s, %s)
            """,
            (
                _normalizar_codigo_barras(produto.get("codigo_barras")),
                _codigo_produto_nfe_saida(produto.get("codigo_produto_nfe")),
                numero_nota,
                _as_str(produto.get("nome_produto")),
                quantidade_movimento,
                0.0,
                tipo_movimento,
                "Ajuste Manual",
                "Almoxarifado",
                produto_id,
                usuario,
            )
        )
        conn.commit()
    finally:
        cur.close()
        conn.close()

    saldo_depois = quantidade_desejada
    return jsonify({
        "ok": True,
        "produto": _produto_estoque_publico(produto),
        "quantidade_ajuste": round(quantidade_ajuste, 3),
        "saldo_antes": round(saldo_antes, 3),
        "saldo_depois": saldo_depois,
        "motivo_ajuste": motivo,
    })

@app.route("/api/estoque/produtos/<int:produto_id>", methods=["DELETE"])
def excluir_produto_estoque(produto_id):
    conn = get_conn()
    cur = conn.cursor(dictionary=True)
    try:
        cur.execute("SELECT id FROM estoque_produtos WHERE id=%s LIMIT 1", (produto_id,))
        row = cur.fetchone()
        if not row:
            return jsonify({"erro": "produto nao encontrado"}), 404
        cur.execute("DELETE FROM estoque_produtos WHERE id=%s", (produto_id,))
        conn.commit()
        return jsonify({"ok": True})
    finally:
        cur.close()
        conn.close()

@app.route("/api/estoque/conferencias", methods=["GET"])
def listar_conferencias_estoque():
    status_filtro = _as_str(request.args.get("status")).lower()
    conn = get_conn()
    cur = conn.cursor(dictionary=True)
    sql = """
        SELECT
            c.*,
            COUNT(i.id) AS total_itens,
            COALESCE(SUM(i.quantidade_nfe), 0) AS total_quantidade_nfe,
            COALESCE(SUM(i.quantidade_conferida), 0) AS total_quantidade_conferida
        FROM estoque_conferencias c
        LEFT JOIN estoque_conferencia_itens i ON i.conferencia_id = c.id
    """
    params = []
    if status_filtro:
        sql += " WHERE c.status=%s"
        params.append(status_filtro)
    sql += " GROUP BY c.id ORDER BY CASE WHEN c.status='pendente' THEN 0 ELSE 1 END, c.id DESC"
    cur.execute(sql, tuple(params))
    rows = cur.fetchall() or []
    cur.close()
    conn.close()
    return jsonify([_estoque_conferencia_publica(r) for r in rows])

@app.route("/api/estoque/conferencias/<int:conferencia_id>", methods=["GET"])
def detalhar_conferencia_estoque(conferencia_id):
    conn = get_conn()
    cur = conn.cursor(dictionary=True)
    conferencia = _carregar_conferencia_estoque(cur, conferencia_id)
    if not conferencia:
        cur.close()
        conn.close()
        return jsonify({"erro": "conferencia nao encontrada"}), 404
    itens = _listar_itens_conferencia_estoque(cur, conferencia_id)
    cur.close()
    conn.close()
    return jsonify({
        "conferencia": _estoque_conferencia_publica(conferencia),
        "itens": [_estoque_conferencia_item_publico(item) for item in itens],
    })

