@app.route("/api/devolucoes", methods=["GET"])
def listar_devolucoes():
    conn = get_conn()
    cursor = conn.cursor(dictionary=True)

    cursor.execute("""
    SELECT
        d.id,
        f.nome AS frete_nome,
        v.nome AS veiculo_nome,
        COALESCE(cc.nome, c.nome) AS conferente_nome,

        d.frete_id,
        d.veiculo_id,
        d.conferente_id,
        d.colaborador_conferente_id,

        d.c24, d.c48, d.pet2l, d.pet600, d.pet200,
        d.obs_c24, d.obs_c48, d.obs_pet2l, d.obs_pet600, d.obs_pet200,
        d.agua_com_gas, d.obs_agua_com_gas,
        d.agua_sem_gas, d.obs_agua_sem_gas,
        d.cx_600, d.obs_cx_600,

        d.fotos
    FROM devolucoes d
    LEFT JOIN fretes f ON d.frete_id = f.id
    LEFT JOIN veiculos v ON d.veiculo_id = v.id
    LEFT JOIN colaboradores cc ON d.colaborador_conferente_id = cc.id
    LEFT JOIN conferentes c ON d.conferente_id = c.id
    ORDER BY d.id DESC
    """)

    dados = cursor.fetchall()
    cursor.close()
    conn.close()

    for d in dados:
        fotos = _json_list_or_empty(d.get("fotos"))
        d["fotos"] = fotos
        d["tem_fotos"] = True if fotos else False

    return jsonify(dados)


def _buscar_colaborador_conferente_logado_cur(cur):
    uid = _as_int(request.headers.get("X-Usuario-Id"), 0)
    login = _normalizar_chave_texto(request.headers.get("X-Usuario-Login"))
    nome = _normalizar_chave_texto(request.headers.get("X-Usuario-Nome"))

    if uid > 0:
        cur.execute(
            """
            SELECT id
            FROM colaboradores
            WHERE usuario_id=%s AND COALESCE(is_conferente, 0)=1
            ORDER BY id ASC
            LIMIT 1
            """,
            (uid,),
        )
        row = cur.fetchone()
        if row:
            return _as_int(row.get("id"), 0) or None

    if not login and not nome:
        return None

    cur.execute(
        """
        SELECT
            c.id,
            c.nome,
            c.login,
            u.nome AS usuario_nome,
            u.login AS usuario_login
        FROM colaboradores c
        LEFT JOIN usuarios u ON u.id = c.usuario_id
        WHERE COALESCE(c.is_conferente, 0)=1
        ORDER BY c.id ASC
        """
    )
    for row in cur.fetchall() or []:
        candidatos_login = {
            _normalizar_chave_texto(row.get("login")),
            _normalizar_chave_texto(row.get("usuario_login")),
        }
        candidatos_nome = {
            _normalizar_chave_texto(row.get("nome")),
            _normalizar_chave_texto(row.get("usuario_nome")),
        }
        if login and login in candidatos_login:
            return _as_int(row.get("id"), 0) or None
        if nome and nome in candidatos_nome:
            return _as_int(row.get("id"), 0) or None
    return None


@app.route("/api/devolucoes", methods=["POST"])
def criar_devolucao():
    is_multipart = (request.content_type or "").startswith("multipart/form-data")

    if is_multipart:
        form = request.form
        files = request.files.getlist("fotos")
        data = {
            "frete_id": form.get("frete_id"),
            "veiculo_id": form.get("veiculo_id"),
            "colaborador_conferente_id": form.get("colaborador_conferente_id"),
            "conferente_id": form.get("conferente_id"),
            "c24": _as_int(form.get("c24"), 0),
            "c48": _as_int(form.get("c48"), 0),
            "pet2l": _as_int(form.get("pet2l"), 0),
            "pet600": _as_int(form.get("pet600"), 0),
            "pet200": _as_int(form.get("pet200"), 0),
            "obs_c24": _as_str(form.get("obs_c24")),
            "obs_c48": _as_str(form.get("obs_c48")),
            "obs_pet2l": _as_str(form.get("obs_pet2l")),
            "obs_pet600": _as_str(form.get("obs_pet600")),
            "obs_pet200": _as_str(form.get("obs_pet200")),
            "agua_com_gas": _as_int(form.get("agua_com_gas"), 0),
            "obs_agua_com_gas": _as_str(form.get("obs_agua_com_gas")),
            "agua_sem_gas": _as_int(form.get("agua_sem_gas"), 0),
            "obs_agua_sem_gas": _as_str(form.get("obs_agua_sem_gas")),
            "cx_600": _as_int(form.get("cx_600"), 0),
            "obs_cx_600": _as_str(form.get("obs_cx_600")),
        }
    else:
        data = request.json or {}
        files = []

    colaborador_conferente_id = _as_int(data.get("colaborador_conferente_id"), 0) or None
    conferente_id = None if colaborador_conferente_id else _as_int(data.get("conferente_id"), 0) or None
    conn = get_conn()
    cursor = conn.cursor(dictionary=True)
    if not (conferente_id or colaborador_conferente_id):
        colaborador_conferente_id = _buscar_colaborador_conferente_logado_cur(cursor)
    if not data.get("frete_id") or not (conferente_id or colaborador_conferente_id):
        cursor.close()
        conn.close()
        return jsonify({"erro": "frete_id e conferente_id ou colaborador_conferente_id são obrigatórios"}), 400

    cursor.execute("""
    INSERT INTO devolucoes
    (frete_id, veiculo_id, conferente_id, colaborador_conferente_id,
     c24, c48, pet2l, pet600, pet200,
     obs_c24, obs_c48, obs_pet2l, obs_pet600, obs_pet200,
     agua_com_gas, obs_agua_com_gas, agua_sem_gas, obs_agua_sem_gas, cx_600, obs_cx_600,
     fotos)
    VALUES (%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s)
    """, (
        data.get("frete_id"),
        data.get("veiculo_id"),
        conferente_id,
        colaborador_conferente_id,
        data.get("c24"),
        data.get("c48"),
        data.get("pet2l"),
        data.get("pet600"),
        data.get("pet200"),
        data.get("obs_c24"),
        data.get("obs_c48"),
        data.get("obs_pet2l"),
        data.get("obs_pet600"),
        data.get("obs_pet200"),
        data.get("agua_com_gas"),
        data.get("obs_agua_com_gas"),
        data.get("agua_sem_gas"),
        data.get("obs_agua_sem_gas"),
        data.get("cx_600"),
        data.get("obs_cx_600"),
        None
    ))
    devolucao_id = cursor.lastrowid

    fotos_rel = _save_devolucao_files(devolucao_id, files)
    if fotos_rel:
        cursor.execute(
            "UPDATE devolucoes SET fotos=%s WHERE id=%s",
            (json.dumps(fotos_rel), devolucao_id)
        )

    conn.commit()
    cursor.close()
    conn.close()

    return jsonify({"ok": True, "id": devolucao_id, "fotos": fotos_rel})

# =========================================================
# (6) FRETES
# =========================================================
@app.route("/api/fretes", methods=["POST"])
def criar_frete():
    data = request.json or {}
    usuario = _usuario_ator_req()
    nome = _as_str(data.get("nome"))
    if not nome:
        return jsonify({"erro": "nome do frete e obrigatorio"}), 400
    cidade = _as_str(data.get("cidade"))
    data_carga = _as_date(data.get("data_carga")) or datetime.date.today()
    colaborador_motorista_id = _as_int(data.get("colaborador_motorista_id"), 0) or _as_int(data.get("motorista_id"), 0) or None
    colaborador_entregador_id = _as_int(data.get("colaborador_entregador_id"), 0) or _as_int(data.get("entregador_id"), 0) or colaborador_motorista_id
    motorista_id = colaborador_motorista_id
    entregador_id = colaborador_entregador_id
    veiculo_id = _as_int(data.get("veiculo_id"), 0) or None
    carga_id = _as_int(data.get("carga_id"), 0) or None
    observacao = _as_str(data.get("observacao"))
    lote_manual = _normalizar_lotes_frete(data.get("lote_manual"))
    km_atual = _as_int(data.get("km_atual"), 0)
    peso = _as_float(data.get("peso"), 0.0)
    qtd_entregas = _as_int(data.get("qtd_entregas"), 0)

    conn = get_conn()
    cursor = conn.cursor(dictionary=True)
    if not veiculo_id and carga_id:
        cursor.execute("SELECT veiculo_numero FROM cargas WHERE id=%s", (carga_id,))
        carga_ref = cursor.fetchone() or {}
        veiculo_id = _resolver_veiculo_id_por_numero(cursor, carga_ref.get("veiculo_numero"))
    if veiculo_id and not colaborador_motorista_id:
        equipe_atual = _buscar_equipe_atual_veiculo(cursor, veiculo_id)
        colaborador_motorista_id = (
            _as_int(equipe_atual.get("motorista_id"), 0) or None
        )
        colaborador_entregador_id = (
            _as_int(equipe_atual.get("ajudante_id"), 0) or None
        )
        motorista_id = colaborador_motorista_id
        entregador_id = colaborador_entregador_id
    legacy_motorista_id = _resolver_motorista_legacy_id_por_colaborador(cursor, colaborador_motorista_id)
    legacy_entregador_id = _resolver_motorista_legacy_id_por_colaborador(cursor, colaborador_entregador_id)
    erro_equipe = _validar_colaboradores_frete(cursor, motorista_id, entregador_id)
    if erro_equipe:
        cursor.close()
        conn.close()
        return jsonify({"erro": erro_equipe}), 400
    erro_escala = _validar_duplicidade_escala_frete(cursor, None, "liberado", motorista_id, entregador_id)
    if erro_escala:
        cursor.close()
        conn.close()
        return jsonify({"erro": erro_escala}), 400

    if veiculo_id and km_atual <= 0:
        km_atual = _buscar_km_atual_veiculo(cursor, veiculo_id)

    cursor.execute(
        """
        INSERT INTO fretes
            (nome, cidade, data_carga, status, motorista_id, entregador_id, colaborador_motorista_id, colaborador_entregador_id, veiculo_id, carga_id, observacao, lote_manual, km_atual, peso, qtd_entregas, arquivado)
        VALUES
            (%s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s)
        """,
        (nome, cidade, data_carga, "liberado", legacy_motorista_id, legacy_entregador_id, colaborador_motorista_id, colaborador_entregador_id, veiculo_id, carga_id, observacao, lote_manual, km_atual, peso, qtd_entregas, 0)
    )
    frete_id = cursor.lastrowid
    if veiculo_id and km_atual > 0:
        cursor.execute(
            """
            UPDATE veiculos
            SET km_atual = CASE
                WHEN km_atual IS NULL OR km_atual < %s THEN %s
                ELSE km_atual
            END
            WHERE id = %s
            """,
            (km_atual, km_atual, veiculo_id)
        )
    frete = _buscar_frete_detalhado(cursor, frete_id)
    _registrar_historico_frete(cursor, frete_id, "criado", usuario, None, frete)
    conn.commit()
    cursor.close()
    conn.close()
    return jsonify({"ok": True, "id": frete_id, "frete": frete})


def _erro_unificacao_fretes(origem, destino):
    if not origem or not destino:
        return "Card de origem ou destino nao encontrado."
    if _as_int(origem.get("id"), 0) == _as_int(destino.get("id"), 0):
        return "Selecione outro card como destino."
    if _as_bool(origem.get("arquivado"), False) or _as_bool(destino.get("arquivado"), False):
        return "Cards arquivados nao podem ser unificados."
    veiculo_origem = _as_int(origem.get("veiculo_id"), 0)
    veiculo_destino = _as_int(destino.get("veiculo_id"), 0)
    if not veiculo_origem or not veiculo_destino:
        return "Os dois cards precisam ter um caminhao definido para serem unificados."
    if veiculo_origem != veiculo_destino:
        return "Somente cards do mesmo caminhao podem ser unificados."
    return ""


def _ids_vinculos_frete(cur, frete_id):
    consultas = {
        "vendas_diario": "SELECT id FROM vendas_diario_kanban WHERE frete_id=%s",
        "notas_saida": "SELECT id FROM estoque_xml_frete_vinculos WHERE frete_id=%s",
        "notas_pendentes": "SELECT id FROM estoque_xml_frete_pre_vinculos WHERE frete_id=%s",
        "notas_sugeridas": "SELECT id FROM estoque_xml_frete_vinculos WHERE frete_sugerido_id=%s",
        "devolucoes": "SELECT id FROM devolucoes WHERE frete_id=%s",
        "movimentos_estoque": """
            SELECT id FROM estoque_movimentos
            WHERE referencia_id=%s
              AND LOWER(TRIM(COALESCE(referencia_tipo,'')))='frete'
        """,
    }
    vinculos = {}
    for chave, sql in consultas.items():
        cur.execute(sql, (frete_id,))
        vinculos[chave] = [
            _as_int(row.get("id"), 0)
            for row in (cur.fetchall() or [])
            if _as_int(row.get("id"), 0) > 0
        ]
    return vinculos


def _ids_vinculos_unificacao_legada(cur, unificacao, origem_antes):
    destino_id = _as_int(unificacao.get("frete_destino_id"), 0)
    origem_id = _as_int(unificacao.get("frete_origem_id"), 0)
    criado_em = unificacao.get("criado_em")
    observacao = _as_str(origem_antes.get("observacao"))
    vendas_ids = sorted({
        _as_int(valor, 0)
        for valor in re.findall(r"Vendas\s+Diario\s+card\s*#(\d+)", observacao, flags=re.IGNORECASE)
        if _as_int(valor, 0) > 0
    })
    mapas = sorted({
        _as_str(valor)
        for valor in re.findall(r"Mapa\s*:\s*([A-Za-z0-9._/-]+)", observacao, flags=re.IGNORECASE)
        if _as_str(valor)
    })
    nota_keys = set()
    cur.execute(
        """
        SELECT dados_antes_json, dados_depois_json
        FROM fretes_historico
        WHERE frete_id=%s
          AND criado_em<=%s
          AND acao IN ('nota_saida_vinculada','nota_saida_pre_vinculada')
        """,
        (origem_id, criado_em),
    )
    for historico in cur.fetchall() or []:
        for campo in ("dados_antes_json", "dados_depois_json"):
            try:
                dados = json.loads(historico.get(campo) or "{}")
            except Exception:
                dados = {}
            nota_key = _as_str(dados.get("nota_key"))
            if nota_key:
                nota_keys.add(nota_key)

    vinculos = {
        "vendas_diario": [],
        "notas_saida": [],
        "notas_pendentes": [],
        "notas_sugeridas": [],
        "devolucoes": [],
        "movimentos_estoque": [],
    }
    if vendas_ids:
        placeholders = ",".join(["%s"] * len(vendas_ids))
        cur.execute(
            f"SELECT id FROM vendas_diario_kanban WHERE frete_id=%s AND id IN ({placeholders})",
            (destino_id, *vendas_ids),
        )
        vinculos["vendas_diario"] = [_as_int(row.get("id"), 0) for row in (cur.fetchall() or [])]

    filtros = []
    valores_filtros = []
    if nota_keys:
        filtros.append(f"nota_key IN ({','.join(['%s'] * len(nota_keys))})")
        valores_filtros.extend(sorted(nota_keys))
    if mapas:
        filtros.append(f"mapa_xml IN ({','.join(['%s'] * len(mapas))})")
        valores_filtros.extend(mapas)
    filtros_pre = list(filtros)
    valores_pre = list(valores_filtros)
    carga_origem_id = _as_int(origem_antes.get("carga_id"), 0)
    try:
        destino_antes = json.loads(unificacao.get("destino_antes_json") or "{}")
    except Exception:
        destino_antes = {}
    if carga_origem_id and carga_origem_id != _as_int(destino_antes.get("carga_id"), 0):
        filtros.append("carga_id=%s")
        valores_filtros.append(carga_origem_id)
    if filtros:
        cur.execute(
            f"SELECT id FROM estoque_xml_frete_vinculos WHERE frete_id=%s AND ({' OR '.join(filtros)})",
            (destino_id, *valores_filtros),
        )
        vinculos["notas_saida"] = [_as_int(row.get("id"), 0) for row in (cur.fetchall() or [])]
        cur.execute(
            f"SELECT id FROM estoque_xml_frete_vinculos WHERE frete_sugerido_id=%s AND ({' OR '.join(filtros)})",
            (destino_id, *valores_filtros),
        )
        vinculos["notas_sugeridas"] = [_as_int(row.get("id"), 0) for row in (cur.fetchall() or [])]
    if filtros_pre:
        cur.execute(
            f"SELECT id FROM estoque_xml_frete_pre_vinculos WHERE frete_id=%s AND ({' OR '.join(filtros_pre)})",
            (destino_id, *valores_pre),
        )
        vinculos["notas_pendentes"] = [_as_int(row.get("id"), 0) for row in (cur.fetchall() or [])]
    return vinculos


def _atualizar_vinculos_desagrupamento(cur, vinculos, destino_id, origem_id):
    operacoes = {
        "vendas_diario": ("vendas_diario_kanban", "frete_id", "atualizado_em=NOW()"),
        "notas_saida": ("estoque_xml_frete_vinculos", "frete_id", ""),
        "notas_pendentes": ("estoque_xml_frete_pre_vinculos", "frete_id", "atualizado_em=NOW()"),
        "notas_sugeridas": ("estoque_xml_frete_vinculos", "frete_sugerido_id", ""),
        "devolucoes": ("devolucoes", "frete_id", ""),
        "movimentos_estoque": ("estoque_movimentos", "referencia_id", ""),
    }
    contagens = {}
    for chave, (tabela, campo, extra) in operacoes.items():
        ids = sorted({_as_int(item, 0) for item in (vinculos.get(chave) or []) if _as_int(item, 0) > 0})
        if not ids:
            contagens[chave] = 0
            continue
        placeholders = ",".join(["%s"] * len(ids))
        complemento = f", {extra}" if extra else ""
        cur.execute(
            f"UPDATE {tabela} SET {campo}=%s{complemento} WHERE {campo}=%s AND id IN ({placeholders})",
            (origem_id, destino_id, *ids),
        )
        contagens[chave] = max(0, cur.rowcount)
    return contagens


def _restaurar_snapshot_frete(cur, frete_id, snapshot):
    cur.execute(
        """
        UPDATE fretes
        SET nome=%s, cidade=%s, data_carga=%s, status=%s,
            motorista_id=%s, entregador_id=%s,
            colaborador_motorista_id=%s, colaborador_entregador_id=%s,
            veiculo_id=%s, carga_id=%s, observacao=%s, lote_manual=%s,
            km_atual=%s, peso=%s, qtd_entregas=%s,
            finalizado_em=%s, arquivado=%s, updated_at=NOW()
        WHERE id=%s
        """,
        (
            _as_str(snapshot.get("nome")),
            _as_str(snapshot.get("cidade")),
            snapshot.get("data_carga") or None,
            _as_str(snapshot.get("status")) or "liberado",
            _as_int(snapshot.get("motorista_id"), 0) or None,
            _as_int(snapshot.get("entregador_id"), 0) or None,
            _as_int(snapshot.get("colaborador_motorista_id"), 0) or None,
            _as_int(snapshot.get("colaborador_entregador_id"), 0) or None,
            _as_int(snapshot.get("veiculo_id"), 0) or None,
            _as_int(snapshot.get("carga_id"), 0) or None,
            _as_str(snapshot.get("observacao")),
            _normalizar_lotes_frete(snapshot.get("lote_manual")),
            _as_int(snapshot.get("km_atual"), 0),
            _as_float(snapshot.get("peso"), 0),
            _as_int(snapshot.get("qtd_entregas"), 0),
            snapshot.get("finalizado_em") or None,
            1 if _as_bool(snapshot.get("arquivado"), False) else 0,
            frete_id,
        ),
    )


@app.route("/api/fretes/<int:id>/unificar", methods=["POST"])
def unificar_frete(id):
    data = request.get_json(silent=True) or {}
    destino_id = _as_int(data.get("destino_frete_id"), 0)
    if destino_id <= 0 or destino_id == id:
        return jsonify({"erro": "Selecione outro card como destino."}), 400

    usuario = _usuario_ator_req()
    conn = get_conn()
    cursor = conn.cursor(dictionary=True)
    try:
        cursor.execute(
            "SELECT id FROM fretes WHERE id IN (%s,%s) ORDER BY id FOR UPDATE",
            (id, destino_id),
        )
        if len(cursor.fetchall() or []) != 2:
            conn.rollback()
            return jsonify({"erro": "Card de origem ou destino nao encontrado."}), 404

        origem = _buscar_frete_detalhado(cursor, id)
        destino = _buscar_frete_detalhado(cursor, destino_id)
        erro = _erro_unificacao_fretes(origem, destino)
        if erro:
            conn.rollback()
            return jsonify({"erro": erro}), 409

        vinculos = _ids_vinculos_frete(cursor, id)
        cursor.execute(
            """
            INSERT INTO fretes_unificacoes (
                frete_origem_id, frete_destino_id, usuario,
                origem_antes_json, destino_antes_json, vinculos_json, status
            ) VALUES (%s,%s,%s,%s,%s,%s,'ativo')
            """,
            (
                id,
                destino_id,
                usuario,
                json.dumps(origem, ensure_ascii=False),
                json.dumps(destino, ensure_ascii=False),
                json.dumps(vinculos, ensure_ascii=False),
            ),
        )
        unificacao_id = _as_int(cursor.lastrowid, 0)

        contagens = {}
        transferencias = (
            ("vendas_diario", "UPDATE vendas_diario_kanban SET frete_id=%s, atualizado_em=NOW() WHERE frete_id=%s"),
            ("notas_saida", "UPDATE estoque_xml_frete_vinculos SET frete_id=%s WHERE frete_id=%s"),
            ("notas_pendentes", "UPDATE estoque_xml_frete_pre_vinculos SET frete_id=%s, atualizado_em=NOW() WHERE frete_id=%s"),
            ("devolucoes", "UPDATE devolucoes SET frete_id=%s WHERE frete_id=%s"),
        )
        for chave, sql in transferencias:
            cursor.execute(sql, (destino_id, id))
            contagens[chave] = max(0, cursor.rowcount)
        cursor.execute(
            "UPDATE estoque_xml_frete_vinculos SET frete_sugerido_id=%s WHERE frete_sugerido_id=%s",
            (destino_id, id),
        )
        cursor.execute(
            """
            UPDATE estoque_movimentos
            SET referencia_id=%s
            WHERE referencia_id=%s AND LOWER(TRIM(COALESCE(referencia_tipo,'')))='frete'
            """,
            (destino_id, id),
        )
        contagens["movimentos_estoque"] = max(0, cursor.rowcount)

        cidades = _frete_cidades_lista(destino.get("cidade"), origem.get("cidade"))
        cidade = " - ".join(cidades)[:180]
        lotes = _normalizar_lotes_frete(
            ", ".join(filter(None, [destino.get("lote_manual"), origem.get("lote_manual")]))
        )
        observacoes = [_as_str(destino.get("observacao"))]
        observacao_origem = _as_str(origem.get("observacao"))
        if observacao_origem and observacao_origem not in observacoes:
            observacoes.append(f"Card #{id}: {observacao_origem}")
        observacao = "\n".join(filter(None, observacoes))

        cursor.execute(
            """
            SELECT COALESCE(SUM(peso_total),0) AS peso,
                   COALESCE(SUM(qtd_entregas),0) AS entregas
            FROM vendas_diario_kanban
            WHERE frete_id=%s
            """,
            (destino_id,),
        )
        resumo_vendas = cursor.fetchone() or {}
        peso = max(
            _as_float(destino.get("peso"), 0) + _as_float(origem.get("peso"), 0),
            _as_float(resumo_vendas.get("peso"), 0),
        )
        entregas = max(
            _as_int(destino.get("qtd_entregas"), 0) + _as_int(origem.get("qtd_entregas"), 0),
            _as_int(resumo_vendas.get("entregas"), 0),
        )
        cursor.execute(
            """
            UPDATE fretes
            SET cidade=%s,
                veiculo_id=COALESCE(veiculo_id,%s),
                motorista_id=COALESCE(motorista_id,%s),
                entregador_id=COALESCE(entregador_id,%s),
                colaborador_motorista_id=COALESCE(colaborador_motorista_id,%s),
                colaborador_entregador_id=COALESCE(colaborador_entregador_id,%s),
                carga_id=COALESCE(carga_id,%s),
                lote_manual=%s, observacao=%s, peso=%s, qtd_entregas=%s,
                updated_at=NOW()
            WHERE id=%s
            """,
            (
                cidade,
                _as_int(origem.get("veiculo_id"), 0) or None,
                _as_int(origem.get("motorista_id"), 0) or None,
                _as_int(origem.get("entregador_id"), 0) or None,
                _as_int(origem.get("colaborador_motorista_id"), 0) or None,
                _as_int(origem.get("colaborador_entregador_id"), 0) or None,
                _as_int(origem.get("carga_id"), 0) or None,
                lotes, observacao, peso, entregas, destino_id,
            ),
        )
        cursor.execute(
            """
            UPDATE fretes
            SET arquivado=1,
                observacao=CONCAT_WS('\n',NULLIF(observacao,''),%s),
                updated_at=NOW()
            WHERE id=%s
            """,
            (f"Card unificado manualmente ao frete #{destino_id}.", id),
        )

        _sincronizar_dados_viagem_xml_frete(
            cursor,
            destino_id,
            _as_int(destino.get("veiculo_id"), 0) or _as_int(origem.get("veiculo_id"), 0),
        )
        depois_destino = _buscar_frete_detalhado(cursor, destino_id)
        depois_origem = _buscar_frete_detalhado(cursor, id)
        _registrar_historico_frete(
            cursor,
            destino_id,
            "unificado_destino",
            usuario,
            destino,
            {**(depois_destino or {}), "frete_origem_id": id, "frete_origem_nome": origem.get("nome")},
        )
        historico_origem_id = _registrar_historico_frete(
            cursor,
            id,
            "unificado_origem",
            usuario,
            origem,
            {**(depois_origem or {}), "frete_destino_id": destino_id, "frete_destino_nome": destino.get("nome")},
        )
        cursor.execute(
            "UPDATE fretes_unificacoes SET historico_origem_id=%s WHERE id=%s",
            (historico_origem_id, unificacao_id),
        )
        conn.commit()
        return jsonify({
            "ok": True,
            "unificacao_id": unificacao_id,
            "frete_origem_id": id,
            "frete_destino_id": destino_id,
            "frete": depois_destino,
            "transferidos": contagens,
        })
    except Exception:
        conn.rollback()
        raise
    finally:
        cursor.close()
        conn.close()


@app.route("/api/fretes/<int:id>/desagrupar", methods=["POST"])
def desagrupar_frete(id):
    usuario = _usuario_ator_req()
    conn = get_conn()
    cursor = conn.cursor(dictionary=True)
    try:
        cursor.execute(
            """
            SELECT *
            FROM fretes_unificacoes
            WHERE frete_destino_id=%s AND status='ativo'
            ORDER BY id DESC
            LIMIT 1
            FOR UPDATE
            """,
            (id,),
        )
        unificacao = cursor.fetchone()
        if not unificacao:
            conn.rollback()
            return jsonify({"erro": "Este card nao possui unificacao ativa para desfazer."}), 409

        origem_id = _as_int(unificacao.get("frete_origem_id"), 0)
        cursor.execute(
            "SELECT id FROM fretes WHERE id IN (%s,%s) ORDER BY id FOR UPDATE",
            (origem_id, id),
        )
        if len(cursor.fetchall() or []) != 2:
            conn.rollback()
            return jsonify({"erro": "Card de origem ou destino nao encontrado."}), 404

        origem_atual = _buscar_frete_detalhado(cursor, origem_id)
        destino_atual = _buscar_frete_detalhado(cursor, id)
        if not origem_atual or not destino_atual:
            conn.rollback()
            return jsonify({"erro": "Card de origem ou destino nao encontrado."}), 404
        if not origem_atual.get("arquivado"):
            conn.rollback()
            return jsonify({"erro": "O card de origem ja esta ativo; a unificacao nao pode ser desfeita novamente."}), 409

        try:
            origem_antes = json.loads(unificacao.get("origem_antes_json") or "{}")
            destino_antes = json.loads(unificacao.get("destino_antes_json") or "{}")
            vinculos = json.loads(unificacao.get("vinculos_json") or "{}")
        except Exception:
            conn.rollback()
            return jsonify({"erro": "O historico desta unificacao esta incompleto."}), 409
        if not origem_antes or not destino_antes:
            conn.rollback()
            return jsonify({"erro": "O historico desta unificacao esta incompleto."}), 409

        legado = not isinstance(vinculos, dict) or "vendas_diario" not in vinculos
        if legado:
            vinculos = _ids_vinculos_unificacao_legada(cursor, unificacao, origem_antes)
        transferidos = _atualizar_vinculos_desagrupamento(cursor, vinculos, id, origem_id)

        _restaurar_snapshot_frete(cursor, id, destino_antes)
        origem_antes["arquivado"] = False
        _restaurar_snapshot_frete(cursor, origem_id, origem_antes)

        cursor.execute(
            """
            UPDATE fretes_unificacoes
            SET status='desfeito', desfeito_em=NOW(), desfeito_por=%s
            WHERE id=%s AND status='ativo'
            """,
            (usuario, unificacao.get("id")),
        )
        depois_destino = _buscar_frete_detalhado(cursor, id)
        depois_origem = _buscar_frete_detalhado(cursor, origem_id)
        _registrar_historico_frete(
            cursor,
            id,
            "desagrupado_destino",
            usuario,
            destino_atual,
            {**(depois_destino or {}), "frete_origem_id": origem_id},
        )
        _registrar_historico_frete(
            cursor,
            origem_id,
            "desagrupado_origem",
            usuario,
            origem_atual,
            {**(depois_origem or {}), "frete_destino_id": id},
        )
        conn.commit()
        return jsonify({
            "ok": True,
            "unificacao_id": _as_int(unificacao.get("id"), 0),
            "frete_origem_id": origem_id,
            "frete_destino_id": id,
            "frete_origem": depois_origem,
            "frete_destino": depois_destino,
            "restaurados": transferidos,
            "legado": legado,
        })
    except Exception:
        conn.rollback()
        raise
    finally:
        cursor.close()
        conn.close()


@app.route("/api/fretes/<int:id>", methods=["DELETE"])
def deletar_frete(id):
    usuario = _usuario_ator_req()
    conn = get_conn()
    cursor = conn.cursor(dictionary=True)
    frete = _buscar_frete_detalhado(cursor, id)
    if not frete:
        cursor.close()
        conn.close()
        return jsonify({"erro": "frete nao encontrado"}), 404

    cursor.execute(
        "SELECT COUNT(*) AS total FROM estoque_xml_frete_vinculos WHERE frete_id=%s",
        (id,),
    )
    total_notas = _as_int((cursor.fetchone() or {}).get("total"), 0)
    if total_notas > 0:
        cursor.close()
        conn.close()
        return jsonify(
            {
                "erro": (
                    f"este frete possui {total_notas} nota(s) de saida vinculada(s) "
                    "e nao pode ser excluido"
                )
            }
        ), 409

    cursor.execute("DELETE FROM fretes_historico WHERE frete_id=%s", (id,))
    cursor.execute("DELETE FROM fretes WHERE id=%s", (id,))
    descricao = f"frete id={id} nome={_as_str(frete.get('nome'))} status={_as_str(frete.get('status'))}"
    _registrar_log_exclusao(cursor, usuario, "fretes", id, descricao)
    conn.commit()
    cursor.close()
    conn.close()
    return jsonify({"ok": True})

@app.route("/api/fretes/<int:id>", methods=["PUT", "PATCH"])
def atualizar_frete(id):
    data = request.json or {}
    usuario = _usuario_ator_req()
    conn = get_conn()
    cursor = conn.cursor(dictionary=True)
    antes = _buscar_frete_detalhado(cursor, id)
    if not antes:
        cursor.close()
        conn.close()
        return jsonify({"erro": "frete nao encontrado"}), 404

    nome = _as_str(data.get("nome")) if ("nome" in data and data.get("nome") is not None) else _as_str(antes.get("nome"))
    cidade = _as_str(data.get("cidade")) if ("cidade" in data and data.get("cidade") is not None) else _as_str(antes.get("cidade"))
    data_carga = (
        _as_date(data.get("data_carga"))
        if "data_carga" in data else _as_date(antes.get("data_carga"))
    )
    status = _as_str(data.get("status")) if ("status" in data and data.get("status") is not None) else _as_str(antes.get("status"))
    if "arquivado" in data:
        arquivado = 1 if _as_bool(data.get("arquivado"), False) else 0
    else:
        arquivado = _as_int(antes.get("arquivado"), 0) or 0
    solicitou_arquivamento = (
        arquivado == 1
        and _as_int(antes.get("arquivado"), 0) == 0
    )
    if solicitou_arquivamento and not bool(antes.get("pode_arquivar_manual")):
        cursor.close()
        conn.close()
        return jsonify(
            {
                "erro": (
                    "o card so pode ser arquivado manualmente depois de "
                    f"{FRETE_ARQUIVO_MANUAL_HORAS} horas no status retornando"
                )
            }
        ), 409
    colaborador_motorista_id = (
        _as_int(data.get("colaborador_motorista_id"), 0) or _as_int(data.get("motorista_id"), 0) or None
        if "colaborador_motorista_id" in data else (_as_int(antes.get("colaborador_motorista_id"), 0) or None)
    )
    colaborador_entregador_id = (
        _as_int(data.get("colaborador_entregador_id"), 0) or _as_int(data.get("entregador_id"), 0) or None
        if "colaborador_entregador_id" in data else (_as_int(antes.get("colaborador_entregador_id"), 0) or None)
    )
    if colaborador_entregador_id is None and colaborador_motorista_id:
        colaborador_entregador_id = colaborador_motorista_id
    motorista_id = colaborador_motorista_id
    entregador_id = colaborador_entregador_id
    veiculo_id = (
        _as_int(data.get("veiculo_id"), 0) or None
        if "veiculo_id" in data else (_as_int(antes.get("veiculo_id"), 0) or None)
    )
    carga_id = (
        _as_int(data.get("carga_id"), 0) or None
        if "carga_id" in data else (_as_int(antes.get("carga_id"), 0) or None)
    )
    observacao = _as_str(data.get("observacao")) if ("observacao" in data and data.get("observacao") is not None) else _as_str(antes.get("observacao"))
    lote_manual = _normalizar_lotes_frete(data.get("lote_manual")) if ("lote_manual" in data and data.get("lote_manual") is not None) else _normalizar_lotes_frete(antes.get("lote_manual"))
    km_atual = _as_int(data.get("km_atual"), 0) if ("km_atual" in data and data.get("km_atual") is not None) else _as_int(antes.get("km_atual"), 0)
    peso = _as_float(data.get("peso"), 0.0) if ("peso" in data and data.get("peso") is not None) else _as_float(antes.get("peso"), 0.0)
    qtd_entregas = _as_int(data.get("qtd_entregas"), 0) if ("qtd_entregas" in data and data.get("qtd_entregas") is not None) else _as_int(antes.get("qtd_entregas"), 0)
    if veiculo_id and km_atual <= 0:
        km_atual = _buscar_km_atual_veiculo(cursor, veiculo_id)

    if not nome:
        cursor.close()
        conn.close()
        return jsonify({"erro": "nome do frete e obrigatorio"}), 400

    if not veiculo_id and carga_id:
        cursor.execute("SELECT veiculo_numero FROM cargas WHERE id=%s", (carga_id,))
        carga_ref = cursor.fetchone() or {}
        veiculo_id = _resolver_veiculo_id_por_numero(cursor, carga_ref.get("veiculo_numero"))

    comparacao_antes = {
        "nome": _as_str(antes.get("nome")),
        "cidade": _as_str(antes.get("cidade")),
        "data_carga": _as_str(antes.get("data_carga")),
        "status": _as_str(antes.get("status")),
        "arquivado": _as_int(antes.get("arquivado"), 0),
        "motorista_id": _as_int(antes.get("motorista_id"), 0) or None,
        "entregador_id": _as_int(antes.get("entregador_id"), 0) or None,
        "colaborador_motorista_id": _as_int(antes.get("colaborador_motorista_id"), 0) or None,
        "colaborador_entregador_id": _as_int(antes.get("colaborador_entregador_id"), 0) or None,
        "veiculo_id": _as_int(antes.get("veiculo_id"), 0) or None,
        "carga_id": _as_int(antes.get("carga_id"), 0) or None,
        "observacao": _as_str(antes.get("observacao")),
        "lote_manual": _normalizar_lotes_frete(antes.get("lote_manual")),
        "km_atual": _as_int(antes.get("km_atual"), 0),
        "peso": _as_float(antes.get("peso"), 0.0),
        "qtd_entregas": _as_int(antes.get("qtd_entregas"), 0),
    }
    comparacao_depois = {
        "nome": nome,
        "cidade": cidade,
        "data_carga": _fmt_date(data_carga),
        "status": status,
        "arquivado": arquivado,
        "motorista_id": motorista_id,
        "entregador_id": entregador_id,
        "colaborador_motorista_id": colaborador_motorista_id,
        "colaborador_entregador_id": colaborador_entregador_id,
        "veiculo_id": veiculo_id,
        "carga_id": carga_id,
        "observacao": observacao,
        "lote_manual": lote_manual,
        "km_atual": km_atual,
        "peso": peso,
        "qtd_entregas": qtd_entregas,
    }

    legacy_motorista_id = _resolver_motorista_legacy_id_por_colaborador(
        cursor,
        colaborador_motorista_id,
        _as_int(antes.get("motorista_id"), 0) if colaborador_motorista_id == (_as_int(antes.get("colaborador_motorista_id"), 0) or None) else None,
    )
    legacy_entregador_id = _resolver_motorista_legacy_id_por_colaborador(
        cursor,
        colaborador_entregador_id,
        _as_int(antes.get("entregador_id"), 0) if colaborador_entregador_id == (_as_int(antes.get("colaborador_entregador_id"), 0) or None) else None,
    )

    escala_keys = {
        "status",
        "motorista_id",
        "entregador_id",
        "colaborador_motorista_id",
        "colaborador_entregador_id",
    }
    precisa_validar_escala = any(comparacao_antes.get(key) != comparacao_depois.get(key) for key in escala_keys)
    precisa_validar_equipe = precisa_validar_escala or comparacao_antes.get("veiculo_id") != comparacao_depois.get("veiculo_id")

    if precisa_validar_equipe:
        erro_equipe = _validar_colaboradores_frete(cursor, motorista_id, entregador_id)
        if erro_equipe:
            cursor.close()
            conn.close()
            return jsonify({"erro": erro_equipe}), 400

    if precisa_validar_escala:
        erro_escala = _validar_duplicidade_escala_frete(cursor, id, status, motorista_id, entregador_id)
        if erro_escala:
            cursor.close()
            conn.close()
            return jsonify({"erro": erro_escala}), 400

    if comparacao_antes == comparacao_depois:
        cursor.close()
        conn.close()
        return jsonify({"ok": True, "frete": antes})

    cursor.execute("""
        UPDATE fretes
        SET
          nome = %s,
          cidade = %s,
          data_carga = %s,
          finalizado_em = CASE
            WHEN %s = 'retornando' AND finalizado_em IS NULL THEN NOW()
            WHEN %s <> 'retornando' THEN NULL
            ELSE finalizado_em
          END,
          status = %s,
          arquivado = %s,
          motorista_id = %s,
          entregador_id = %s,
          colaborador_motorista_id = %s,
          colaborador_entregador_id = %s,
          veiculo_id = %s,
          carga_id = %s,
          observacao = %s,
          lote_manual = %s,
          km_atual = %s,
          peso = %s,
          qtd_entregas = %s
        WHERE id = %s
    """, (
        nome,
        cidade,
        data_carga,
        status,
        status,
        status,
        arquivado,
        legacy_motorista_id,
        legacy_entregador_id,
        colaborador_motorista_id,
        colaborador_entregador_id,
        veiculo_id,
        carga_id,
        observacao,
        lote_manual,
        km_atual,
        peso,
        qtd_entregas,
        id
    ))

    veiculo_id_num = _as_int(veiculo_id, 0)
    km_atual_num = _as_int(km_atual, 0)
    if veiculo_id_num > 0 and km_atual_num > 0:
        cursor.execute(
            """
            UPDATE veiculos
            SET km_atual = CASE
                WHEN km_atual IS NULL OR km_atual < %s THEN %s
                ELSE km_atual
            END
            WHERE id = %s
            """,
            (km_atual_num, km_atual_num, veiculo_id_num)
        )

    _sincronizar_dados_viagem_xml_frete(cursor, id, veiculo_id_num)
    if solicitou_arquivamento:
        _registrar_rota_frete_arquivado(cursor, id)
    depois = _buscar_frete_detalhado(cursor, id)
    estoque_baixa = _sincronizar_baixa_estoque_frete(cursor, antes, depois, usuario=usuario)
    _registrar_historico_frete(cursor, id, "atualizado", usuario, antes, depois)
    conn.commit()
    cursor.close()
    conn.close()
    return jsonify({"ok": True, "frete": depois, "estoque_baixa": estoque_baixa})

