def _coletar_relatorios_comissao(filtro_cod=0, filtro_entregador=""):
    filtro_cod = _as_int(filtro_cod, 0)
    filtro_entregador = _as_str(filtro_entregador).upper()
    if filtro_cod > 0:
        filtro_entregador = ""
    conn = get_conn()
    cur = conn.cursor(dictionary=True)
    cur.execute("""
        SELECT
            id, cod_vendedor, motorista, entregador, rota, usina,
            data_faturamento, data_saida, data_chegada,
            v_gf, d_gf, icms_gf, v_pet, d_pet, icms_pet, v_agua, d_agua,
            gf_600, gf_200, gf_300, dev_gf, pet_2l, pet_600, dev_pet,
            agua_vol, dev_agua, total_pedidos, acucar_qtd, t_acucar,
            pct_vend_gf, pct_vend_pet, pct_vend_agua,
            pct_ent_gf, pct_ent_pet, pct_ent_agua, taxa_ent_acucar
        FROM comissao_lancamentos
    """)
    lancamentos = cur.fetchall() or []

    cur.execute("""
        SELECT codigo, nome, funcao, pct_gf, pct_pet, pct_agua
        FROM comissao_cadastros
        WHERE ativo = 1
    """)
    cad_rows = cur.fetchall() or []
    cur.close()
    conn.close()

    vend_cad = {}
    ent_cad = {}
    for c in cad_rows:
        f = _as_str(c.get("funcao")).lower()
        if f == "vendedor":
            vend_cad[_as_int(c.get("codigo"), 0)] = c
        elif f == "entregador":
            ent_cad[_as_str(c.get("nome")).upper()] = c

    total_vendedores = {}
    total_entregadores = {}
    ranking_faixas = {}
    total_refugo = {}
    total_acucar = {}
    lancamentos_detalhados = []
    resumo = {
        "total_lancamentos": 0,
        "total_entregas": 0,
        "fretes_ate_5": 0,
        "fretes_acima_5": 0,
        "base_vendedor_total": 0.0,
        "comissao_vendedor_total": 0.0,
        "comissao_entregador_total": 0.0,
        "volume_entregador_total": 0.0,
        "devolucao_total": 0.0,
        "percentual_devolucao": 0.0,
    }

    for r in lancamentos:
        cod = _as_int(r.get("cod_vendedor"), 0)
        ent_nome = _as_str(r.get("entregador"))
        if filtro_cod > 0 and cod != filtro_cod:
            continue
        if filtro_entregador and _as_str(ent_nome).upper() != filtro_entregador:
            continue

        calc = _calc_comissao_lancamento(r)
        qtd_entregas = max(0, _as_int(r.get("total_pedidos"), 0))
        faixa_entregas = "acima_5" if qtd_entregas > 5 else "ate_5"
        resumo["total_lancamentos"] += 1
        resumo["total_entregas"] += qtd_entregas
        resumo[f"fretes_{faixa_entregas}"] += 1
        resumo["base_vendedor_total"] += calc["base_vendedor_total"]

        cad_v = vend_cad.get(cod)
        pct_v_gf = _as_float(cad_v.get("pct_gf"), _as_float(r.get("pct_vend_gf"), 0.01)) if cad_v else _as_float(r.get("pct_vend_gf"), 0.01)
        pct_v_pet = _as_float(cad_v.get("pct_pet"), _as_float(r.get("pct_vend_pet"), 0.01)) if cad_v else _as_float(r.get("pct_vend_pet"), 0.01)
        pct_v_agua = _as_float(cad_v.get("pct_agua"), _as_float(r.get("pct_vend_agua"), 0.03)) if cad_v else _as_float(r.get("pct_vend_agua"), 0.03)
        com_v = (calc["base_gf"] * pct_v_gf) + (calc["base_pet"] * pct_v_pet) + (calc["base_agua"] * pct_v_agua)
        resumo["comissao_vendedor_total"] += com_v

        if cod > 0:
            key_v = cod
            if key_v not in total_vendedores:
                total_vendedores[key_v] = {
                    "codigo": cod,
                    "nome": _as_str(cad_v.get("nome")) if cad_v else "",
                    "pct_gf": pct_v_gf,
                    "pct_pet": pct_v_pet,
                    "pct_agua": pct_v_agua,
                    "base_gf": 0.0,
                    "base_pet": 0.0,
                    "base_agua": 0.0,
                    "comissao_gf": 0.0,
                    "comissao_pet": 0.0,
                    "comissao_agua": 0.0,
                    "base_total": 0.0,
                    "comissao_total": 0.0,
                }
            total_vendedores[key_v]["base_gf"] += calc["base_gf"]
            total_vendedores[key_v]["base_pet"] += calc["base_pet"]
            total_vendedores[key_v]["base_agua"] += calc["base_agua"]
            total_vendedores[key_v]["comissao_gf"] += calc["base_gf"] * pct_v_gf
            total_vendedores[key_v]["comissao_pet"] += calc["base_pet"] * pct_v_pet
            total_vendedores[key_v]["comissao_agua"] += calc["base_agua"] * pct_v_agua
            total_vendedores[key_v]["base_total"] += calc["base_vendedor_total"]
            total_vendedores[key_v]["comissao_total"] += com_v

        cad_e = ent_cad.get(_as_str(ent_nome).upper())
        pct_e_gf = _as_float(cad_e.get("pct_gf"), _as_float(r.get("pct_ent_gf"), 0.08)) if cad_e else _as_float(r.get("pct_ent_gf"), 0.08)
        pct_e_pet = _as_float(cad_e.get("pct_pet"), _as_float(r.get("pct_ent_pet"), 0.06)) if cad_e else _as_float(r.get("pct_ent_pet"), 0.06)
        pct_e_agua = _as_float(cad_e.get("pct_agua"), _as_float(r.get("pct_ent_agua"), 0.06)) if cad_e else _as_float(r.get("pct_ent_agua"), 0.06)
        taxa_acucar = _as_float(r.get("taxa_ent_acucar"), 0.0)
        if taxa_acucar <= 0:
            taxa_acucar = _as_float(r.get("t_acucar"), 0.0)
        com_e = (calc["base_ent_gf"] * pct_e_gf) + (calc["base_ent_pet"] * pct_e_pet) + (calc["base_ent_agua"] * pct_e_agua) + (calc["base_ent_acucar"] * taxa_acucar)
        resumo["comissao_entregador_total"] += com_e

        lancamentos_detalhados.append({
            "id": _as_int(r.get("id"), 0),
            "cod_vendedor": cod,
            "vendedor": _as_str(cad_v.get("nome")) if cad_v else "",
            "entregador": ent_nome,
            "rota": _as_str(r.get("rota")),
            "usina": _as_str(r.get("usina")),
            "data_faturamento": _fmt_date(r.get("data_faturamento")),
            "data_saida": _fmt_date(r.get("data_saida")),
            "data_chegada": _fmt_date(r.get("data_chegada")),
            "total_pedidos": qtd_entregas,
            "base_gf": calc["base_gf"],
            "base_pet": calc["base_pet"],
            "base_agua": calc["base_agua"],
            "pct_vend_gf": pct_v_gf,
            "pct_vend_pet": pct_v_pet,
            "pct_vend_agua": pct_v_agua,
            "comissao_vend_gf": calc["base_gf"] * pct_v_gf,
            "comissao_vend_pet": calc["base_pet"] * pct_v_pet,
            "comissao_vend_agua": calc["base_agua"] * pct_v_agua,
            "comissao_vendedor": com_v,
            "gf_600": _as_float(r.get("gf_600"), 0.0),
            "gf_200": _as_float(r.get("gf_200"), 0.0),
            "gf_300": _as_float(r.get("gf_300"), 0.0),
            "dev_gf": _as_float(r.get("dev_gf"), 0.0),
            "pet_2l": _as_float(r.get("pet_2l"), 0.0),
            "pet_600": _as_float(r.get("pet_600"), 0.0),
            "dev_pet": _as_float(r.get("dev_pet"), 0.0),
            "agua_vol": _as_float(r.get("agua_vol"), 0.0),
            "dev_agua": _as_float(r.get("dev_agua"), 0.0),
            "base_ent_gf": calc["base_ent_gf"],
            "base_ent_pet": calc["base_ent_pet"],
            "base_ent_agua": calc["base_ent_agua"],
            "pct_ent_gf": pct_e_gf,
            "pct_ent_pet": pct_e_pet,
            "pct_ent_agua": pct_e_agua,
            "comissao_ent_gf": calc["base_ent_gf"] * pct_e_gf,
            "comissao_ent_pet": calc["base_ent_pet"] * pct_e_pet,
            "comissao_ent_agua": calc["base_ent_agua"] * pct_e_agua,
            "volume_entregador": calc["base_ent_gf"] + calc["base_ent_pet"] + calc["base_ent_agua"],
            "volume_bruto_entregador": (
                _as_float(r.get("gf_600"), 0.0) + _as_float(r.get("gf_200"), 0.0) +
                _as_float(r.get("gf_300"), 0.0) + _as_float(r.get("pet_2l"), 0.0) +
                _as_float(r.get("pet_600"), 0.0) + _as_float(r.get("agua_vol"), 0.0)
            ),
            "devolucao_entregador": (
                _as_float(r.get("dev_gf"), 0.0) + _as_float(r.get("dev_pet"), 0.0) +
                _as_float(r.get("dev_agua"), 0.0)
            ),
            "percentual_devolucao": (
                (
                    _as_float(r.get("dev_gf"), 0.0) + _as_float(r.get("dev_pet"), 0.0) +
                    _as_float(r.get("dev_agua"), 0.0)
                ) / (
                    _as_float(r.get("gf_600"), 0.0) + _as_float(r.get("gf_200"), 0.0) +
                    _as_float(r.get("gf_300"), 0.0) + _as_float(r.get("pet_2l"), 0.0) +
                    _as_float(r.get("pet_600"), 0.0) + _as_float(r.get("agua_vol"), 0.0)
                ) * 100
                if (
                    _as_float(r.get("gf_600"), 0.0) + _as_float(r.get("gf_200"), 0.0) +
                    _as_float(r.get("gf_300"), 0.0) + _as_float(r.get("pet_2l"), 0.0) +
                    _as_float(r.get("pet_600"), 0.0) + _as_float(r.get("agua_vol"), 0.0)
                ) > 0 else 0.0
            ),
            "comissao_entregador": com_e,
        })

        key_e = _as_str(ent_nome)
        if key_e:
            bruto_gf = _as_float(r.get("gf_600"), 0.0) + _as_float(r.get("gf_200"), 0.0) + _as_float(r.get("gf_300"), 0.0)
            bruto_pet = _as_float(r.get("pet_2l"), 0.0) + _as_float(r.get("pet_600"), 0.0)
            bruto_agua = _as_float(r.get("agua_vol"), 0.0)
            dev_gf = _as_float(r.get("dev_gf"), 0.0)
            dev_pet = _as_float(r.get("dev_pet"), 0.0)
            dev_agua = _as_float(r.get("dev_agua"), 0.0)
            if key_e not in total_entregadores:
                total_entregadores[key_e] = {
                    "nome": key_e,
                    "pct_gf": pct_e_gf,
                    "pct_pet": pct_e_pet,
                    "pct_agua": pct_e_agua,
                    "volume_gf": 0.0,
                    "volume_pet": 0.0,
                    "volume_agua": 0.0,
                    "volume_acucar": 0.0,
                    "comissao_gf": 0.0,
                    "comissao_pet": 0.0,
                    "comissao_agua": 0.0,
                    "comissao_acucar": 0.0,
                    "total_entregas": 0,
                    "volume_total": 0.0,
                    "volume_bruto_total": 0.0,
                    "devolucao_total": 0.0,
                    "percentual_devolucao": 0.0,
                    "comissao_total": 0.0,
                }
            total_e = total_entregadores[key_e]
            total_e["volume_gf"] += calc["base_ent_gf"]
            total_e["volume_pet"] += calc["base_ent_pet"]
            total_e["volume_agua"] += calc["base_ent_agua"]
            total_e["volume_acucar"] += calc["base_ent_acucar"]
            total_e["comissao_gf"] += calc["base_ent_gf"] * pct_e_gf
            total_e["comissao_pet"] += calc["base_ent_pet"] * pct_e_pet
            total_e["comissao_agua"] += calc["base_ent_agua"] * pct_e_agua
            total_e["comissao_acucar"] += calc["base_ent_acucar"] * taxa_acucar
            total_e["total_entregas"] += qtd_entregas
            # Igual ao TOTAL da planilha: GF + PET + ADQ. Açúcar é demonstrado
            # separadamente e participa da comissão, mas não do total de volumes.
            total_e["volume_total"] += calc["base_ent_gf"] + calc["base_ent_pet"] + calc["base_ent_agua"]
            total_e["volume_bruto_total"] += bruto_gf + bruto_pet + bruto_agua
            total_e["devolucao_total"] += dev_gf + dev_pet + dev_agua
            total_e["comissao_total"] += com_e

            key_ranking = (faixa_entregas, key_e)
            if key_ranking not in ranking_faixas:
                ranking_faixas[key_ranking] = {
                    "nome": key_e,
                    "faixa_entregas": faixa_entregas,
                    "faixa_entregas_label": "Acima de 5 entregas" if faixa_entregas == "acima_5" else "Até 5 entregas",
                    "qtd_fretes": 0,
                    "total_entregas": 0,
                    "volume_bruto_total": 0.0,
                    "devolucao_total": 0.0,
                    "percentual_devolucao": 0.0,
                }
            faixa_e = ranking_faixas[key_ranking]
            faixa_e["qtd_fretes"] += 1
            faixa_e["total_entregas"] += qtd_entregas
            faixa_e["volume_bruto_total"] += bruto_gf + bruto_pet + bruto_agua
            faixa_e["devolucao_total"] += dev_gf + dev_pet + dev_agua

            if key_e not in total_refugo:
                total_refugo[key_e] = {
                    "entregador": key_e,
                    "volume_gf": 0.0,
                    "volume_pet": 0.0,
                    "volume_agua": 0.0,
                    "dev_gf": 0.0,
                    "dev_pet": 0.0,
                    "dev_agua": 0.0,
                }
            refugo = total_refugo[key_e]
            refugo["volume_gf"] += bruto_gf
            refugo["volume_pet"] += bruto_pet
            refugo["volume_agua"] += bruto_agua
            refugo["dev_gf"] += dev_gf
            refugo["dev_pet"] += dev_pet
            refugo["dev_agua"] += dev_agua
            resumo["volume_entregador_total"] += bruto_gf + bruto_pet + bruto_agua
            resumo["devolucao_total"] += dev_gf + dev_pet + dev_agua

        key_u = _as_str(r.get("usina")) or "SEM USINA"
        if key_u not in total_acucar:
            total_acucar[key_u] = {"usina": key_u, "qtd": 0.0, "comissao": 0.0}
        qtd_ac = _as_float(r.get("acucar_qtd"), 0.0)
        total_acucar[key_u]["qtd"] += qtd_ac
        total_acucar[key_u]["comissao"] += qtd_ac * taxa_acucar

    resumo["percentual_devolucao"] = (
        resumo["devolucao_total"] / resumo["volume_entregador_total"] * 100
        if resumo["volume_entregador_total"] > 0 else 0.0
    )
    for item in total_entregadores.values():
        item["percentual_devolucao"] = (
            item["devolucao_total"] / item["volume_bruto_total"] * 100
            if item["volume_bruto_total"] > 0 else 0.0
        )
    for item in ranking_faixas.values():
        item["percentual_devolucao"] = (
            item["devolucao_total"] / item["volume_bruto_total"] * 100
            if item["volume_bruto_total"] > 0 else 0.0
        )
    for item in total_refugo.values():
        item["pct_dev_gf"] = item["dev_gf"] / item["volume_gf"] * 100 if item["volume_gf"] > 0 else 0.0
        item["pct_dev_pet"] = item["dev_pet"] / item["volume_pet"] * 100 if item["volume_pet"] > 0 else 0.0
        item["pct_dev_agua"] = item["dev_agua"] / item["volume_agua"] * 100 if item["volume_agua"] > 0 else 0.0
        volume_total = item["volume_gf"] + item["volume_pet"] + item["volume_agua"]
        devolucao_total = item["dev_gf"] + item["dev_pet"] + item["dev_agua"]
        item["pct_dev_total"] = devolucao_total / volume_total * 100 if volume_total > 0 else 0.0

    ranking_devolucoes = sorted(
        (
            dict(item)
            for item in ranking_faixas.values()
            if _as_float(item.get("volume_bruto_total"), 0.0) > 0
        ),
        key=lambda item: (
            0 if item.get("faixa_entregas") == "acima_5" else 1,
            _as_float(item.get("percentual_devolucao"), 0.0),
            -_as_float(item.get("volume_bruto_total"), 0.0),
            _as_str(item.get("nome")),
        ),
    )
    posicoes_por_faixa = {}
    for item in ranking_devolucoes:
        faixa = item["faixa_entregas"]
        posicoes_por_faixa[faixa] = posicoes_por_faixa.get(faixa, 0) + 1
        item["posicao"] = posicoes_por_faixa[faixa]

    return {
        "tipo_relatorio": "vendedor" if filtro_cod > 0 else ("entregador" if filtro_entregador else "geral"),
        "resumo_geral": resumo,
        "total_vendedores": sorted(total_vendedores.values(), key=lambda x: (x["codigo"], x["nome"])),
        "total_entregadores": sorted(total_entregadores.values(), key=lambda x: x["nome"]),
        "total_refugo": sorted(total_refugo.values(), key=lambda x: x["entregador"]),
        "total_acucar": sorted(total_acucar.values(), key=lambda x: x["usina"]),
        "lancamentos": sorted(
            lancamentos_detalhados,
            key=lambda x: (x.get("data_chegada") or "", x.get("id") or 0),
        ),
        "ranking_devolucoes": ranking_devolucoes,
    }

def _build_relatorio_comissao_pdf(rel, filtro_cod=0, filtro_entregador=""):
    filtro_cod = _as_int(filtro_cod, 0)
    filtro_entregador = "" if filtro_cod > 0 else _as_str(filtro_entregador)
    somente_vendedor = filtro_cod > 0
    somente_entregador = bool(filtro_entregador)
    stamp = datetime.datetime.now().strftime("%Y%m%d_%H%M%S")
    arquivo = os.path.join("/tmp", f"relatorio_comissao_{stamp}.pdf")
    doc = SimpleDocTemplate(
        arquivo,
        topMargin=24,
        leftMargin=36,
        rightMargin=36,
        bottomMargin=36
    )
    styles = getSampleStyleSheet()
    elementos = []

    logo_cell = ""
    logo_path = os.path.join(BASE_DIR, "logo.png")
    if os.path.isfile(logo_path):
        try:
            logo_cell = Image(logo_path, width=64, height=64)
        except Exception:
            logo_cell = ""

    dados_empresa = [
        Paragraph("<b>Bebidas Rio Branco</b>", styles["Heading3"]),
        Paragraph("CNPJ: 20.984.401/0001-30", styles["Normal"]),
        Paragraph("Rua Joao Nelson Arcipretti, 278 - Centro, Astorga - PR, 86730-000", styles["Normal"]),
        Paragraph("Site: refrigeranteriobranco.com.br", styles["Normal"]),
        Paragraph("E-mail: contato@refrigeranteriobranco.com.br", styles["Normal"]),
    ]
    cabecalho = Table([[logo_cell, dados_empresa]], colWidths=[72, 390])
    cabecalho.setStyle(TableStyle([
        ("VALIGN", (0, 0), (-1, -1), "TOP"),
        ("LEFTPADDING", (0, 0), (-1, -1), 0),
        ("RIGHTPADDING", (0, 0), (-1, -1), 0),
        ("TOPPADDING", (0, 0), (-1, -1), 0),
        ("BOTTOMPADDING", (0, 0), (-1, -1), 0),
        ("LINEBELOW", (0, 0), (-1, 0), 0.8, colors.black),
    ]))
    elementos.append(cabecalho)
    elementos.append(Spacer(1, 12))
    titulo_relatorio = "Relatorio de Comissao do Vendedor" if somente_vendedor else "Relatorio de Comissao do Entregador"
    elementos.append(Paragraph(titulo_relatorio, styles["Heading2"]))
    elementos.append(Spacer(1, 8))

    filtro_txt = "Todos"
    if somente_vendedor:
        filtro_txt = f"Vendedor codigo {filtro_cod}"
    elif somente_entregador:
        filtro_txt = f"Entregador {filtro_entregador}"
    elementos.append(Paragraph(f"Filtro aplicado: {filtro_txt}", styles["Normal"]))
    elementos.append(Paragraph(f"Emitido em: {datetime.datetime.now().strftime('%d/%m/%Y %H:%M:%S')}", styles["Normal"]))
    elementos.append(Spacer(1, 10))

    r = rel.get("resumo_geral", {}) or {}
    elementos.append(Paragraph(f"Total de lancamentos: {_as_int(r.get('total_lancamentos'), 0)}", styles["Normal"]))
    if somente_vendedor:
        elementos.append(Paragraph(f"Base vendedor total: R$ {_as_float(r.get('base_vendedor_total'), 0.0):.2f}", styles["Normal"]))
        elementos.append(Paragraph(f"Comissao vendedor total: R$ {_as_float(r.get('comissao_vendedor_total'), 0.0):.2f}", styles["Normal"]))
    if somente_entregador:
        elementos.append(Paragraph(f"Comissao entregador total: R$ {_as_float(r.get('comissao_entregador_total'), 0.0):.2f}", styles["Normal"]))
        elementos.append(Paragraph(f"Quantidade de entregas: {_as_int(r.get('total_entregas'), 0)}", styles["Normal"]))
        elementos.append(Paragraph(
            "Devolucao geral: "
            f"{_as_float(r.get('devolucao_total'), 0.0):.2f} / "
            f"{_as_float(r.get('volume_entregador_total'), 0.0):.2f} volumes = "
            f"{_as_float(r.get('percentual_devolucao'), 0.0):.2f}%",
            styles["Normal"],
        ))
    elementos.append(Spacer(1, 8))
    elementos.append(Paragraph("<b>Etapas de calculo</b>", styles["Normal"]))
    if somente_vendedor:
        elementos.append(Paragraph(
            "Base da categoria = vendas - devolucoes - ICMS "
            "(Agua: vendas - devolucoes). Comissao = base x percentual cadastrado.",
            styles["Normal"],
        ))
    if somente_entregador:
        elementos.append(Paragraph(
            "Volume liquido = volumes carregados - devolucoes. "
            "Comissao = volume liquido x percentual cadastrado. "
            "Percentual de devolucao = devolucoes / volumes carregados x 100.",
            styles["Normal"],
        ))
    elementos.append(Spacer(1, 12))

    tv = rel.get("total_vendedores", []) or []
    if tv and somente_vendedor:
        elementos.append(Paragraph("Totais por Vendedor", styles["Heading4"]))
        dados = [["Cod", "Nome", "GF: base x %", "PET: base x %", "Agua: base x %", "Comissao"]]
        for x in tv[:80]:
            dados.append([
                str(_as_int(x.get("codigo"), 0)),
                _as_str(x.get("nome"))[:25],
                f"{_as_float(x.get('base_gf'),0.0):.2f} x {_as_float(x.get('pct_gf'),0.0)*100:.2f}%",
                f"{_as_float(x.get('base_pet'),0.0):.2f} x {_as_float(x.get('pct_pet'),0.0)*100:.2f}%",
                f"{_as_float(x.get('base_agua'),0.0):.2f} x {_as_float(x.get('pct_agua'),0.0)*100:.2f}%",
                f"R$ {_as_float(x.get('comissao_total'),0.0):.2f}",
            ])
        t = Table(dados, colWidths=[32, 108, 82, 82, 82, 76])
        t.setStyle(TableStyle([
            ("GRID", (0, 0), (-1, -1), 0.25, colors.grey),
            ("BACKGROUND", (0, 0), (-1, 0), colors.lightgrey),
            ("FONTSIZE", (0, 0), (-1, -1), 8),
        ]))
        elementos.append(t)
        elementos.append(Spacer(1, 12))

    te = rel.get("total_entregadores", []) or []
    if te and somente_entregador:
        x = te[0]
        elementos.append(Paragraph(f"Totais - {_as_str(x.get('nome'))}", styles["Heading4"]))
        dados = [
            ["", "Volumes", "Percentual", "Comissao"],
            ["GF", f"{_as_float(x.get('volume_gf'),0):.2f}", f"{_as_float(x.get('pct_gf'),0)*100:.2f}%", f"R$ {_as_float(x.get('comissao_gf'),0):.2f}"],
            ["PET", f"{_as_float(x.get('volume_pet'),0):.2f}", f"{_as_float(x.get('pct_pet'),0)*100:.2f}%", f"R$ {_as_float(x.get('comissao_pet'),0):.2f}"],
            ["ADQ", f"{_as_float(x.get('volume_agua'),0):.2f}", f"{_as_float(x.get('pct_agua'),0)*100:.2f}%", f"R$ {_as_float(x.get('comissao_agua'),0):.2f}"],
            ["ACUCAR", f"{_as_float(x.get('volume_acucar'),0):.2f}", "-", f"R$ {_as_float(x.get('comissao_acucar'),0):.2f}"],
            ["TOTAL", f"{_as_float(x.get('volume_total'),0):.2f}", "", f"R$ {_as_float(x.get('comissao_total'),0):.2f}"],
        ]
        t = Table(dados, colWidths=[100, 110, 100, 130])
        t.setStyle(TableStyle([
            ("GRID", (0, 0), (-1, -1), 0.25, colors.grey),
            ("BACKGROUND", (0, 0), (-1, 0), colors.lightgrey),
            ("FONTNAME", (0, -1), (-1, -1), "Helvetica-Bold"),
            ("FONTSIZE", (0, 0), (-1, -1), 8),
        ]))
        elementos.append(t)

    detalhes = rel.get("lancamentos", []) or []
    if detalhes:
        elementos.append(Spacer(1, 12))
        elementos.append(Paragraph(f"Lancamentos ({len(detalhes)})", styles["Heading4"]))
        if somente_vendedor:
            dados = [["ID", "Rota", "Chegada", "GF: base x %", "PET: base x %", "Agua: base x %", "Total"]]
            for x in detalhes:
                dados.append([
                    str(_as_int(x.get("id"), 0)),
                    _as_str(x.get("rota"))[:18],
                    _as_str(x.get("data_chegada")) or "-",
                    f"{_as_float(x.get('base_gf'),0):.2f} x {_as_float(x.get('pct_vend_gf'),0)*100:.2f}%",
                    f"{_as_float(x.get('base_pet'),0):.2f} x {_as_float(x.get('pct_vend_pet'),0)*100:.2f}%",
                    f"{_as_float(x.get('base_agua'),0):.2f} x {_as_float(x.get('pct_vend_agua'),0)*100:.2f}%",
                    f"R$ {_as_float(x.get('comissao_vendedor'),0):.2f}",
                ])
            larguras = [26, 82, 56, 78, 78, 78, 64]
        else:
            dados = [["ID", "Rota", "Entregas", "Chegada", "GF liq. x %", "PET liq. x %", "Agua x %", "% Dev.", "Total"]]
            for x in detalhes:
                dados.append([
                    str(_as_int(x.get("id"), 0)),
                    _as_str(x.get("rota"))[:18],
                    str(_as_int(x.get("total_pedidos"), 0)),
                    _as_str(x.get("data_chegada")) or "-",
                    f"{_as_float(x.get('base_ent_gf'),0):.2f} x {_as_float(x.get('pct_ent_gf'),0)*100:.2f}%",
                    f"{_as_float(x.get('base_ent_pet'),0):.2f} x {_as_float(x.get('pct_ent_pet'),0)*100:.2f}%",
                    f"{_as_float(x.get('base_ent_agua'),0):.2f} x {_as_float(x.get('pct_ent_agua'),0)*100:.2f}%",
                    f"{_as_float(x.get('percentual_devolucao'),0):.2f}%",
                    f"R$ {_as_float(x.get('comissao_entregador'),0):.2f}",
                ])
            larguras = [22, 57, 43, 47, 61, 61, 61, 46, 62]
        t = Table(dados, colWidths=larguras, repeatRows=1)
        t.setStyle(TableStyle([
            ("GRID", (0, 0), (-1, -1), 0.25, colors.grey),
            ("BACKGROUND", (0, 0), (-1, 0), colors.lightgrey),
            ("FONTSIZE", (0, 0), (-1, -1), 7),
        ]))
        elementos.append(t)

    doc.build(elementos)
    return arquivo


def _abastecimento_critico_data_hora(valor):
    data = _abastecimento_xml_data(valor)
    if data:
        return data.strftime("%d/%m/%Y %H:%M:%S")
    return _as_str(valor) or "-"


def _coletar_abastecimentos_criticos(cur, filtros=None):
    filtros = filtros or {}
    where = [
        "LOWER(COALESCE(v.status, '')) = 'pendente'",
        """(
            LOWER(COALESCE(v.vinculacao_origem, '')) = 'placa_similar'
            OR TRIM(COALESCE(v.placa_xml, '')) = ''
            OR LOWER(COALESCE(v.motivo, '')) LIKE '%km do xml incompativel%'
        )""",
    ]
    params = []
    data_expr = (
        "COALESCE(DATE(LEFT(x.data_emissao, 10)), DATE(v.atualizado_em))"
    )
    if filtros.get("data_inicio"):
        where.append(f"{data_expr} >= %s")
        params.append(filtros["data_inicio"])
    if filtros.get("data_fim"):
        where.append(f"{data_expr} <= %s")
        params.append(filtros["data_fim"])

    cur.execute(
        f"""
        SELECT
            v.id,
            v.chave_nfe,
            v.placa_xml,
            v.vinculacao_origem,
            v.motivo,
            v.atualizado_em,
            x.posto_nome,
            x.data_emissao,
            x.km_final,
            x.valor_produto,
            x.valor_total,
            vei.nome AS veiculo_nome,
            vei.placa AS veiculo_placa,
            vei.km_atual AS veiculo_km_atual
        FROM abastecimento_xml_vinculos v
        LEFT JOIN importar_xml_abastecimentos x
            ON x.id = v.importar_xml_abastecimento_id
        LEFT JOIN veiculos vei
            ON vei.id = v.veiculo_id
        WHERE {" AND ".join(where)}
        ORDER BY
            COALESCE(NULLIF(TRIM(x.posto_nome), ''), 'Posto não informado'),
            COALESCE(x.data_emissao, v.atualizado_em) DESC,
            v.id DESC
        """,
        tuple(params),
    )
    categorias = {
        "placas_similares": [],
        "sem_placa": [],
        "km_incompativel": [],
    }
    for row in cur.fetchall() or []:
        item = {
            **row,
            "posto": _as_str(row.get("posto_nome")) or "Posto não informado",
            "chave_xml": _normalizar_chave_acesso_nfe(
                row.get("chave_nfe")
            ),
            "valor": _abastecimento_xml_valor(row),
            "data_hora": _abastecimento_critico_data_hora(
                row.get("data_emissao") or row.get("atualizado_em")
            ),
        }
        placa_xml = _abastecimento_xml_placa_normalizada(
            row.get("placa_xml")
        )
        origem = _as_str(row.get("vinculacao_origem")).lower()
        motivo = _as_str(row.get("motivo")).lower()
        if origem == "placa_similar":
            categorias["placas_similares"].append(item)
        if not placa_xml or "xml sem placa" in motivo:
            categorias["sem_placa"].append(item)
        if "km do xml incompativel" in motivo:
            categorias["km_incompativel"].append(item)
    return categorias


def _agrupar_abastecimentos_criticos_por_posto(rows):
    grupos = defaultdict(list)
    for row in rows or []:
        grupos[_as_str(row.get("posto")) or "Posto não informado"].append(
            row
        )
    return [
        (posto, grupos[posto])
        for posto in sorted(
            grupos,
            key=lambda valor: _normalizar_nome_local(valor),
        )
    ]


def _build_abastecimentos_criticos_pdf(categorias, filtros=None):
    filtros = filtros or {}
    stamp = datetime.datetime.now().strftime("%Y%m%d_%H%M%S")
    arquivo = os.path.join(
        "/tmp",
        f"abastecimentos_criticos_{stamp}.pdf",
    )
    doc = SimpleDocTemplate(
        arquivo,
        pagesize=landscape(A4),
        topMargin=92,
        leftMargin=24,
        rightMargin=24,
        bottomMargin=38,
        title="Relatório crítico de abastecimentos",
        author="Bebidas Rio Branco",
    )
    styles = getSampleStyleSheet()
    body_style = styles["BodyText"].clone("AbastecimentosCriticosBody")
    body_style.fontSize = 7.5
    body_style.leading = 9
    posto_style = styles["Heading3"].clone("AbastecimentosCriticosPosto")
    posto_style.fontSize = 10
    posto_style.leading = 12
    posto_style.textColor = colors.HexColor("#1f4e78")
    posto_style.spaceBefore = 5
    posto_style.spaceAfter = 4
    emissao = datetime.datetime.now().strftime("%d/%m/%Y %H:%M:%S")

    def cabecalho_rodape(canvas, doc_obj):
        canvas.saveState()
        largura_pagina, altura_pagina = doc_obj.pagesize
        logo_path = os.path.join(BASE_DIR, "logo.png")
        if os.path.isfile(logo_path):
            try:
                canvas.drawImage(
                    logo_path,
                    doc_obj.leftMargin,
                    altura_pagina - 75,
                    width=52,
                    height=52,
                    preserveAspectRatio=True,
                    mask="auto",
                )
            except Exception:
                pass
        texto_x = doc_obj.leftMargin + 62
        canvas.setFillColor(colors.HexColor("#1f2937"))
        canvas.setFont("Helvetica-Bold", 11)
        canvas.drawString(texto_x, altura_pagina - 34, "Bebidas Rio Branco")
        canvas.setFont("Helvetica", 7)
        canvas.drawString(
            texto_x,
            altura_pagina - 46,
            "CNPJ: 20.984.401/0001-30",
        )
        canvas.drawString(
            texto_x,
            altura_pagina - 57,
            "Rua João Nelson Arcipretti, 278 - Centro, Astorga - PR",
        )
        canvas.drawString(
            texto_x,
            altura_pagina - 68,
            "refrigeranteriobranco.com.br | contato@refrigeranteriobranco.com.br",
        )
        canvas.setStrokeColor(colors.HexColor("#1f4e78"))
        canvas.setLineWidth(0.8)
        canvas.line(
            doc_obj.leftMargin,
            altura_pagina - 79,
            largura_pagina - doc_obj.rightMargin,
            altura_pagina - 79,
        )

        canvas.setStrokeColor(colors.HexColor("#cbd5e1"))
        canvas.line(
            doc_obj.leftMargin,
            28,
            largura_pagina - doc_obj.rightMargin,
            28,
        )
        canvas.setFillColor(colors.HexColor("#475569"))
        canvas.setFont("Helvetica", 7)
        canvas.drawString(
            doc_obj.leftMargin,
            17,
            "Bebidas Rio Branco - Gestão de Frota",
        )
        canvas.drawRightString(
            largura_pagina - doc_obj.rightMargin,
            17,
            f"Página {doc_obj.page} | Emitido em {emissao}",
        )
        canvas.restoreState()

    def tabela(colunas, larguras, registros, montar_linha):
        dados = [
            [
                Paragraph(f"<b>{_pdf_escape(coluna)}</b>", body_style)
                for coluna in colunas
            ]
        ]
        for registro in registros:
            dados.append(
                [
                    Paragraph(_pdf_escape(valor), body_style)
                    for valor in montar_linha(registro)
                ]
            )
        table = Table(
            dados,
            repeatRows=1,
            colWidths=larguras,
            hAlign="LEFT",
        )
        table.setStyle(
            TableStyle(
                [
                    (
                        "BACKGROUND",
                        (0, 0),
                        (-1, 0),
                        colors.HexColor("#5b9bd5"),
                    ),
                    ("TEXTCOLOR", (0, 0), (-1, 0), colors.white),
                    ("FONTNAME", (0, 0), (-1, 0), "Helvetica-Bold"),
                    (
                        "GRID",
                        (0, 0),
                        (-1, -1),
                        0.35,
                        colors.HexColor("#cbd5e1"),
                    ),
                    ("VALIGN", (0, 0), (-1, -1), "TOP"),
                    ("LEFTPADDING", (0, 0), (-1, -1), 4),
                    ("RIGHTPADDING", (0, 0), (-1, -1), 4),
                    ("TOPPADDING", (0, 0), (-1, -1), 4),
                    ("BOTTOMPADDING", (0, 0), (-1, -1), 4),
                    (
                        "ROWBACKGROUNDS",
                        (0, 1),
                        (-1, -1),
                        [colors.white, colors.HexColor("#eef5fb")],
                    ),
                ]
            )
        )
        return table

    def contagem_label(quantidade):
        return f"{quantidade} registro" if quantidade == 1 else f"{quantidade} registros"

    secoes = [
        (
            "Placas similares",
            categorias.get("placas_similares") or [],
            [
                "Placa digitada no XML",
                "Placa similar cadastrada",
                "Número do veículo",
                "Data e hora",
            ],
            [190, 190, 150, 160],
            lambda row: [
                _as_str(row.get("placa_xml")) or "-",
                _as_str(row.get("veiculo_placa")) or "-",
                _as_str(row.get("veiculo_nome")) or "-",
                row.get("data_hora") or "-",
            ],
        ),
        (
            "Registros sem placa",
            categorias.get("sem_placa") or [],
            ["Chave do XML", "Valor", "Data e hora"],
            [430, 120, 160],
            lambda row: [
                _as_str(row.get("chave_xml")) or "-",
                _fmt_money_br(row.get("valor")),
                row.get("data_hora") or "-",
            ],
        ),
        (
            "Registros com KM incompatível",
            categorias.get("km_incompativel") or [],
            [
                "Placa",
                "Número do veículo",
                "KM do XML",
                "KM atual",
                "Chave do XML",
                "Valor",
                "Data e hora",
            ],
            [72, 88, 70, 75, 245, 80, 110],
            lambda row: [
                _as_str(row.get("placa_xml")) or "-",
                _as_str(row.get("veiculo_nome")) or "-",
                str(_as_int(row.get("km_final"), 0)),
                str(_as_int(row.get("veiculo_km_atual"), 0)),
                _as_str(row.get("chave_xml")) or "-",
                _fmt_money_br(row.get("valor")),
                row.get("data_hora") or "-",
            ],
        ),
    ]

    elementos = []
    filtros_resumo = filtros.get("resumo") or ["Período: todos"]
    for indice, (
        titulo,
        registros,
        colunas,
        larguras,
        montar_linha,
    ) in enumerate(secoes):
        if indice:
            elementos.append(PageBreak())
        elementos.append(
            Paragraph(
                f"Relatório crítico de abastecimentos - {_pdf_escape(titulo)}",
                styles["Heading2"],
            )
        )
        elementos.append(
            Paragraph(
                _pdf_escape(
                    " | ".join(
                        [
                            *filtros_resumo,
                            f"Total: {contagem_label(len(registros))}",
                        ]
                    )
                ),
                styles["Normal"],
            )
        )
        elementos.append(Spacer(1, 10))
        grupos = _agrupar_abastecimentos_criticos_por_posto(registros)
        if not grupos:
            elementos.append(
                Paragraph(
                    "Nenhum registro crítico encontrado no período.",
                    styles["Normal"],
                )
            )
            continue
        for posto, registros_posto in grupos:
            elementos.append(
                Paragraph(
                    (
                        f"Posto: {_pdf_escape(posto)} "
                        f"({contagem_label(len(registros_posto))})"
                    ),
                    posto_style,
                )
            )
            elementos.append(
                tabela(
                    colunas,
                    larguras,
                    registros_posto,
                    montar_linha,
                )
            )
            elementos.append(Spacer(1, 8))

    doc.build(
        elementos,
        onFirstPage=cabecalho_rodape,
        onLaterPages=cabecalho_rodape,
    )
    return arquivo

def _vendas_config_defaults():
    return {
        "habilitado": True,
        "source_type": "csv_relatorios_dir",
        "csv_dir": VENDAS_RELATORIOS_DIR,
        "active_cache_id": "",
        "updated_at": None,
    }

def _vendas_config_publico(data=None):
    base = _vendas_config_defaults()
    if isinstance(data, dict):
        base.update({
            "habilitado": _as_bool(data.get("habilitado"), True),
            "source_type": _as_str(data.get("source_type")).lower() or "csv_relatorios_dir",
            "csv_dir": _as_str(data.get("csv_dir")) or VENDAS_RELATORIOS_DIR,
            "active_cache_id": _as_str(data.get("active_cache_id")),
            "updated_at": _fmt_dt(data.get("updated_at")),
        })
    if base["source_type"] != "csv_relatorios_dir":
        base["source_type"] = "csv_relatorios_dir"
    return base

def _carregar_vendas_config():
    return _vendas_config_publico(_load_json_file(VENDAS_CONFIG_FILE, {}))

def _persistir_vendas_config(data):
    cfg = _vendas_config_publico(data or {})
    cfg["updated_at"] = _fmt_dt(datetime.datetime.now())
    _save_json_file(VENDAS_CONFIG_FILE, cfg)
    return _carregar_vendas_config()

def _vendas_db_row_to_entry(row):
    item = dict(row or {})
    return {
        "id": _as_str(item.get("id")),
        "source_type": _as_str(item.get("source_type")),
        "source_path": _as_str(item.get("source_path")),
        "source_name": _as_str(item.get("source_name")) or os.path.basename(_as_str(item.get("source_path"))),
        "source_size": _as_int(item.get("source_size"), 0),
        "source_mtime": _fmt_dt(item.get("source_mtime")),
        "source_signature": _as_str(item.get("source_signature")),
        "cache_path": "",
        "cache_exists": True,
        "rows_importadas": _as_int(item.get("rows_importadas"), 0),
        "importado_em": _fmt_dt(item.get("importado_em")),
        "updated_at": _fmt_dt(item.get("updated_at")),
        "status": _as_str(item.get("status")) or "pronto",
        "active": _as_bool(item.get("ativo"), False),
    }

