def _vendas_db_find_import(source_signature="", source_path=""):
    source_signature = _as_str(source_signature)
    source_path = _as_str(source_path)
    source_path_abs = os.path.abspath(source_path) if source_path else ""
    if not source_signature and not source_path_abs:
        return None
    conn = None
    cur = None
    try:
        conn = get_conn()
        cur = conn.cursor(dictionary=True)
        if source_signature:
            cur.execute("""
                SELECT id, source_type, source_path, source_name, source_size, source_mtime,
                       source_signature, rows_importadas, status, ativo,
                       bonificacoes_cache_json, variacao_preco_cache_json,
                       dashboard_vendas_json, dashboard_vendas_painel_json,
                       importado_em, updated_at
                FROM vendas_relatorios_importados
                WHERE source_signature=%s
                ORDER BY importado_em DESC
                LIMIT 1
            """, (source_signature,))
            row = cur.fetchone()
            if row:
                return _vendas_db_row_to_entry(row)
            return None
        if source_path_abs:
            cur.execute("""
                SELECT id, source_type, source_path, source_name, source_size, source_mtime,
                       source_signature, rows_importadas, status, ativo,
                       bonificacoes_cache_json, variacao_preco_cache_json,
                       dashboard_vendas_json, dashboard_vendas_painel_json,
                       importado_em, updated_at
                FROM vendas_relatorios_importados
                WHERE source_path=%s
                ORDER BY importado_em DESC
                LIMIT 1
            """, (source_path_abs,))
            row = cur.fetchone()
            if row:
                return _vendas_db_row_to_entry(row)
        return None
    finally:
        try:
            if cur:
                cur.close()
        except Exception:
            pass
        try:
            if conn:
                conn.close()
        except Exception:
            pass

