    if not cache_id or not campo:
        return None
    if campo not in {
        "bonificacoes_cache_json",
        "variacao_preco_cache_json",
        "mix_embalagens_cache_json",
        "dashboard_vendas_json",
        "dashboard_vendas_painel_json",
    }:
        return None
    conn = None
    cur = None
    raw = None
    try:
        conn = get_conn()
        cur = conn.cursor()
        cur.execute(
            f"SELECT {campo} FROM vendas_relatorios_importados WHERE id=%s LIMIT 1",
            (_as_str(cache_id),),
        )
        row = cur.fetchone()
        raw = row[0] if row else None
    finally:
        try:
            if cur:
                cur.close()
        except Exception:
            pass
        try:
            if conn:
                conn.close()
        except Exception:
            pass
    if not raw:
        return None
    try:
        payload = json.loads(raw)
    except Exception:
        return None
    return payload if isinstance(payload, dict) else None

